required_pkgs <- c(
  "shiny","shinydashboard","DBI","RSQLite","dplyr","DT","jsonlite","lubridate",
  "openxlsx","ggplot2","plotly","fs","digest","zip","shinyWidgets","shinyFiles","scales","htmltools"
)
missing <- required_pkgs[!vapply(required_pkgs, requireNamespace, logical(1), quietly = TRUE)]
if (length(missing)) {
  repos <- getOption("repos")
  if (is.null(repos) || !("CRAN" %in% names(repos)) || identical(repos[["CRAN"]], "@CRAN@") || !nzchar(repos[["CRAN"]])) {
    options(repos = c(CRAN = "https://cloud.r-project.org"))
  }
  message("Installing required packages: ", paste(missing, collapse = ", "))
  tryCatch(
    install.packages(missing, lib = startup_r_lib, dependencies = TRUE),
    error = function(e) {
      stop(
        "Unable to install required packages automatically: ", e$message, "\n",
        "Please run install.packages(c(", paste0("'", missing, "'", collapse = ", "), ")) and restart the app."
      )
    }
  )
  missing <- required_pkgs[!vapply(required_pkgs, requireNamespace, logical(1), quietly = TRUE)]
  if (length(missing)) {
    stop(
      "Required packages are still missing after installation attempt:\n",
      paste0("install.packages(c(", paste0("'", missing, "'", collapse = ", "), "))")
    )
  }
}

