refresh_drive_package_flags <- function() {
  has_googledrive <<- requireNamespace("googledrive", quietly = TRUE)
  has_gargle <<- requireNamespace("gargle", quietly = TRUE)
  has_future <<- requireNamespace("future", quietly = TRUE)
  invisible(c(
    googledrive = has_googledrive,
    gargle = has_gargle,
    future = has_future
  ))
}

ensure_drive_packages_installed <- function() {
  missing_drive <- drive_optional_pkgs[!vapply(drive_optional_pkgs, requireNamespace, logical(1), quietly = TRUE)]
  if (length(missing_drive) == 0) {
    refresh_drive_package_flags()
    return(invisible(TRUE))
  }
  repos <- getOption("repos")
  if (is.null(repos) || !("CRAN" %in% names(repos)) || identical(repos[["CRAN"]], "@CRAN@") || !nzchar(repos[["CRAN"]])) {
    options(repos = c(CRAN = "https://cloud.r-project.org"))
  }
  tryCatch(
    install.packages(missing_drive, lib = startup_r_lib, dependencies = TRUE),
    error = function(e) {
      stop("Unable to install Google Drive backup packages automatically: ", e$message, call. = FALSE)
    }
  )
  refresh_drive_package_flags()
  still_missing <- drive_optional_pkgs[!vapply(drive_optional_pkgs, requireNamespace, logical(1), quietly = TRUE)]
  if (length(still_missing) > 0) {
    stop(
      "Google Drive backup packages are still missing after the automatic installation attempt: ",
      paste(still_missing, collapse = ", "),
      call. = FALSE
    )
  }
  invisible(TRUE)
}

