normalize_json_payload <- function(x) {
  if (is.null(x)) return(NULL)
  if (inherits(x, c("POSIXct", "POSIXt", "Date"))) {
    return(as.character(x))
  }
  if (is.data.frame(x)) return(x)
  if (is.list(x)) {
    return(lapply(x, normalize_json_payload))
  }
  if (is.atomic(x) && length(x) > 1 && !is.null(names(x)) && any(nzchar(names(x)))) {
    payload <- as.list(x)
    names(payload) <- names(x)
    return(lapply(payload, normalize_json_payload))
  }
  x
}

json_stringify <- function(payload, auto_unbox = TRUE, null = "null", pretty = FALSE) {
  jsonlite::toJSON(
    normalize_json_payload(payload),
    auto_unbox = auto_unbox,
    null = null,
    pretty = pretty
  )
}

append_app_runtime_log <- function(level = "INFO", message, detail = list()) {
  dir_create(logs_dir, recurse = TRUE)
  detail_text <- ""
  if (length(detail) > 0) {
    detail_text <- tryCatch(
      json_stringify(detail, auto_unbox = TRUE, null = "null"),
      error = function(e) ""
    )
  }
  line <- paste0(
    "[", format(Sys.time(), "%Y-%m-%d %H:%M:%S"), "] ",
    "[", toupper(as.character(level %||% "INFO")), "] ",
    as.character(message %||% ""),
    if (nzchar(detail_text)) paste0(" ", detail_text) else "",
    "\n"
  )
  cat(line, file = app_runtime_log_file, append = TRUE)
  invisible(line)
}

is_transient_db_error <- function(error_text) {
  msg <- tolower(trimws(as.character(error_text %||% "")))
  if (!nzchar(msg)) return(FALSE)
  any(grepl(
    c(
      "database is locked",
      "database table is locked",
      "sqlite_busy",
      "database schema is locked",
      "locking protocol",
      "resource temporarily unavailable",
      "disk i/o error",
      "cannot commit transaction"
    ),
    msg,
    fixed = TRUE
  ))
}

retry_db_call <- function(expr, op_name = "database operation", retries = 5L, base_delay = 0.15) {
  last_error <- NULL
  for (attempt in seq_len(max(1L, as.integer(retries)))) {
    result <- tryCatch(list(ok = TRUE, value = force(expr)), error = function(e) list(ok = FALSE, error = e))
    if (isTRUE(result$ok)) return(result$value)
    last_error <- result$error
    if (!is_transient_db_error(last_error$message) || attempt >= retries) break
    Sys.sleep(base_delay * attempt + stats::runif(1, min = 0, max = 0.05))
  }
  stop(last_error)
}

connect_db <- function(busy_timeout_ms = 60000L, retries = 5L, base_delay = 0.2) {
  dir_create(dirname(db_file), recurse = TRUE)
  busy_timeout_ms <- suppressWarnings(as.integer(busy_timeout_ms %||% 60000L))
  if (is.na(busy_timeout_ms) || busy_timeout_ms < 0L) busy_timeout_ms <- 60000L
  retries <- max(1L, suppressWarnings(as.integer(retries %||% 5L)))
  if (is.na(retries)) retries <- 5L
  base_delay <- suppressWarnings(as.numeric(base_delay %||% 0.2))
  if (!is.finite(base_delay) || base_delay < 0) base_delay <- 0.2
  con <- retry_db_call(
    DBI::dbConnect(RSQLite::SQLite(), db_file, synchronous = NULL),
    op_name = "dbConnect",
    retries = retries,
    base_delay = base_delay
  )
  suppressWarnings(try(dbExecute(con, "PRAGMA journal_mode = WAL;"), silent = TRUE))
  suppressWarnings(try(dbExecute(con, "PRAGMA synchronous = NORMAL;"), silent = TRUE))
  suppressWarnings(try(dbExecute(con, "PRAGMA temp_store = MEMORY;"), silent = TRUE))
  suppressWarnings(try(dbExecute(con, sprintf("PRAGMA busy_timeout = %d;", busy_timeout_ms)), silent = TRUE))
  suppressWarnings(try(dbExecute(con, "PRAGMA cache_size = -20000;"), silent = TRUE))
  suppressWarnings(try(dbExecute(con, "PRAGMA wal_autocheckpoint = 1000;"), silent = TRUE))
  suppressWarnings(try(dbExecute(con, "PRAGMA journal_size_limit = 67108864;"), silent = TRUE))
  suppressWarnings(try(dbExecute(con, "PRAGMA foreign_keys = ON;"), silent = TRUE))
  con
}

connect_db_for_login <- function() {
  connect_db(busy_timeout_ms = 1500L, retries = 2L, base_delay = 0.05)
}

dbGetQuery <- function(conn, statement, ..., params = NULL, immediate = NULL) {
  retry_db_call(
    if (is.null(params)) {
      DBI::dbGetQuery(conn, statement, ..., immediate = immediate)
    } else {
      DBI::dbGetQuery(conn, statement, ..., params = params, immediate = immediate)
    },
    op_name = "dbGetQuery"
  )
}

dbExecute <- function(conn, statement, ..., params = NULL, immediate = NULL) {
  retry_db_call(
    if (is.null(params)) {
      DBI::dbExecute(conn, statement, ..., immediate = immediate)
    } else {
      DBI::dbExecute(conn, statement, ..., params = params, immediate = immediate)
    },
    op_name = "dbExecute"
  )
}

dbWriteTable <- function(conn, name, value, ..., append = FALSE, overwrite = FALSE, row.names = FALSE, temporary = FALSE) {
  retry_db_call(
    DBI::dbWriteTable(
      conn,
      name = name,
      value = value,
      ...,
      append = append,
      overwrite = overwrite,
      row.names = row.names,
      temporary = temporary
    ),
    op_name = "dbWriteTable"
  )
}

