currency_symbol <- function(code = NULL) {
  c <- (code %||% get_currency())
  switch(
    as.character(c),
    KES = "KES ",
    USD = "$",
    GBP = "\u00A3",
    EUR = "\u20AC",
    paste0(c, " ")
  )
}

format_currency <- function(x) {
  # x: numeric
  # returns formatted string with currency symbol/label only.
  # numeric formatting is identical to scales::dollar but with our symbol
  prefix <- currency_symbol()
  # keep two decimals and comma thousands separator
  scales::dollar(x, prefix = prefix, big.mark = ",", largest_with_cents = Inf)
}

project_status_choices <- c("Not Started", "In Progress", "Paused", "Ended")

normalize_project_status <- function(x) {
  value <- trimws(as.character(x %||% ""))
  if (!nzchar(value)) return("In Progress")
  key <- tolower(value)
  if (key %in% c("not started", "not_started", "not-started", "pending", "planned")) return("Not Started")
  if (key %in% c("in progress", "in_progress", "progress", "active", "ongoing")) return("In Progress")
  if (key %in% c("paused", "pause", "on hold", "on-hold", "hold")) return("Paused")
  if (key %in% c("ended", "end", "complete", "completed", "closed", "finished")) return("Ended")
  "In Progress"
}

split_team_members <- function(x) {
