project_access_key_space <- local({
  key_grid <- expand.grid(LETTERS, LETTERS, LETTERS, stringsAsFactors = FALSE)
  keys <- apply(key_grid, 1, paste0, collapse = "")
  keys <- keys[vapply(strsplit(keys, "", fixed = TRUE), function(chars) length(unique(chars)) == 3L, logical(1))]
  function() keys
})

normalize_project_access_key <- function(x) {
  value <- toupper(gsub("[^A-Za-z]", "", trimws(as.character(x %||% ""))))
  if (!nzchar(value) || nchar(value) != 3) return("")
  chars <- strsplit(value, "", fixed = TRUE)[[1]]
  if (length(unique(chars)) != 3L) return("")
  value
}

generate_unique_project_access_key <- function(con = NULL, exclude_project_id = NULL, used_keys = NULL) {
  close_con <- FALSE
  if (is.null(used_keys)) {
    if (is.null(con)) {
      con <- connect_db()
      close_con <- TRUE
    }
    if (isTRUE(close_con)) {
      on.exit({
        if (DBI::dbIsValid(con)) dbDisconnect(con)
      }, add = TRUE)
    }
    sql <- "SELECT access_key FROM projects"
    params <- list()
    if (!is.null(exclude_project_id) && nzchar(as.character(exclude_project_id %||% ""))) {
      sql <- paste0(sql, " WHERE id <> ?")
      params <- list(as.character(exclude_project_id))
    }
    existing <- if (length(params) == 0) {
      dbGetQuery(con, paste0(sql, ";"))
    } else {
      dbGetQuery(con, paste0(sql, ";"), params = params)
    }
    used_keys <- unique(Filter(nzchar, vapply(existing$access_key %||% character(), normalize_project_access_key, character(1))))
  } else {
    used_keys <- unique(Filter(nzchar, vapply(used_keys, normalize_project_access_key, character(1))))
  }
  available <- setdiff(project_access_key_space(), used_keys)
  if (length(available) == 0) stop("No remaining project Access Keys are available.")
  sample(available, 1)
}

prepare_projects_access_keys_for_restore <- function(projects_df, con, exclude_project_ids = character()) {
  if (is.null(projects_df) || nrow(projects_df) == 0) return(projects_df)
  if (!("access_key" %in% names(projects_df))) projects_df$access_key <- ""
  exclude_project_ids <- unique(as.character(exclude_project_ids %||% character()))
  exclude_project_ids <- exclude_project_ids[nzchar(exclude_project_ids)]
  sql <- "SELECT access_key FROM projects"
  params <- list()
  if (length(exclude_project_ids) > 0) {
    sql <- paste0(sql, " WHERE id NOT IN (", paste(rep("?", length(exclude_project_ids)), collapse = ", "), ")")
    params <- as.list(exclude_project_ids)
  }
  existing <- if (length(params) == 0) {
    dbGetQuery(con, paste0(sql, ";"))
  } else {
    dbGetQuery(con, paste0(sql, ";"), params = params)
  }
  used_keys <- unique(Filter(nzchar, vapply(existing$access_key %||% character(), normalize_project_access_key, character(1))))
  for (i in seq_len(nrow(projects_df))) {
    access_key <- normalize_project_access_key(projects_df$access_key[[i]] %||% "")
    if (!nzchar(access_key) || access_key %in% used_keys) {
      access_key <- generate_unique_project_access_key(used_keys = used_keys)
    }
    projects_df$access_key[[i]] <- access_key
    used_keys <- unique(c(used_keys, access_key))
  }
  projects_df
}

as_db_scalar <- function(value, field_name = "value", default = "") {
  if (is.null(value) || length(value) == 0) return(default)
  if (is.list(value) && !is.data.frame(value)) {
    value <- unlist(value, recursive = TRUE, use.names = FALSE)
  }
  if (inherits(value, "Date") || inherits(value, "POSIXt")) {
    value <- as.character(value)
  }
  if (length(value) == 0) return(default)
  if (length(value) > 1) {
    stop(sprintf("%s must be a single value.", field_name))
  }
  value[[1]]
}

schema_runtime_cache <- local({
  env <- new.env(parent = emptyenv())
  env$flags <- list()
  env
})

schema_cache_enabled <- function(key) {
  isTRUE(schema_runtime_cache$flags[[as.character(key %||% "")]])
}

mark_schema_cache_enabled <- function(key) {
  schema_runtime_cache$flags[[as.character(key %||% "")]] <- TRUE
  invisible(TRUE)
}

ensure_schema_once <- function(key, expr) {
  cache_key <- as.character(key %||% "")
  if (nzchar(cache_key) && schema_cache_enabled(cache_key)) return(invisible(TRUE))
  force(expr)
  if (nzchar(cache_key)) mark_schema_cache_enabled(cache_key)
  invisible(TRUE)
}

safe_file_size <- function(path) {
  info <- tryCatch(file_info(path), error = function(e) NULL)
  if (is.null(info) || !"size" %in% names(info) || length(info$size) == 0 || is.na(info$size[[1]])) return(0)
  as.numeric(info$size[[1]])
}

copy_file_checked <- function(src, dest, overwrite = TRUE) {
  src <- as.character(src %||% "")
  dest <- as.character(dest %||% "")
  if (!nzchar(src) || !file_exists(src)) stop("Source file could not be found.")
  if (!nzchar(dest)) stop("Destination file path is required.")
  dir_create(dirname(dest), recurse = TRUE)
  ok <- tryCatch(file.copy(src, dest, overwrite = overwrite), error = function(e) FALSE)
  if (!isTRUE(ok) || !file_exists(dest)) stop("File copy failed.")
  normalizePath(dest, winslash = "/", mustWork = FALSE)
}

delete_files_quietly <- function(paths) {
  paths <- unique(as.character(paths %||% character()))
  paths <- paths[nzchar(paths) & file_exists(paths)]
  if (length(paths) == 0) return(invisible(TRUE))
  try(file_delete(paths), silent = TRUE)
  invisible(TRUE)
}

