normalize_datetime_storage <- function(value, field_name = "date/time", default = "", tz = default_email_schedule_timezone()) {
  value <- trimws(as.character(as_db_scalar(value, field_name = field_name, default = default) %||% ""))
  if (!nzchar(value)) return("")
  tz <- normalize_timezone_value(tz, field_name = paste(field_name, "time zone"))
  parsed <- suppressWarnings(lubridate::ymd_hms(value, tz = tz, quiet = TRUE))
  if (is.na(parsed)) parsed <- suppressWarnings(lubridate::ymd_hm(value, tz = tz, quiet = TRUE))
  if (is.na(parsed)) parsed <- suppressWarnings(as.POSIXct(value, tz = tz))
  if (is.na(parsed)) stop(sprintf("%s must be a valid date and time.", field_name))
  format(lubridate::with_tz(parsed, tzone = tz), "%Y-%m-%d %H:%M:%S")
}

format_datetime_display <- function(value, tz = default_email_schedule_timezone()) {
  value <- trimws(as.character(value %||% ""))
  if (!nzchar(value)) return("-")
  tz <- normalize_timezone_value(tz, field_name = "Display time zone")
  parsed <- suppressWarnings(lubridate::ymd_hms(value, tz = tz, quiet = TRUE))
  if (is.na(parsed)) parsed <- suppressWarnings(lubridate::ymd_hm(value, tz = tz, quiet = TRUE))
  if (is.na(parsed)) return(value)
  format(lubridate::with_tz(parsed, tzone = tz), "%Y-%m-%d %H:%M")
}

compose_scheduled_datetime <- function(date_value, time_value, tz = email_schedule_timezone()) {
  date_part <- trimws(as.character(as_db_scalar(date_value, field_name = "Scheduled date", default = "")))
  time_part <- trimws(as.character(as_db_scalar(time_value, field_name = "Scheduled time", default = "")))
  if (!nzchar(date_part)) stop("Scheduled date is required.")
  if (!nzchar(time_part)) stop("Scheduled time is required.")
  normalize_datetime_storage(paste(date_part, time_part), field_name = "Scheduled date/time", tz = tz)
}

default_email_schedule_time <- function() {
  now_posix <- time_in_timezone(email_schedule_timezone()) + 3600
  format(now_posix, "%H:%M")
}

split_scheduled_datetime <- function(value, tz = email_schedule_timezone()) {
  normalized <- normalize_datetime_storage(value, field_name = "Scheduled date/time", default = "", tz = tz)
  if (!nzchar(normalized)) {
    current_date <- format(time_in_timezone(tz), "%Y-%m-%d")
    return(list(date = current_date, time = default_email_schedule_time()))
  }
  time_part <- substr(normalized, 12, 19)
  time_part <- sub(":00$", "", time_part)
  list(
    date = substr(normalized, 1, 10),
    time = time_part
  )
}

