    Sys.getenv("CHROMOTE_CHROME", unset = ""),
    unname(Sys.which(c("chrome", "chrome.exe", "msedge", "msedge.exe", "chromium", "chromium.exe"))),
    "C:/Program Files/Google/Chrome/Application/chrome.exe",
    "C:/Program Files (x86)/Google/Chrome/Application/chrome.exe",
    "C:/Program Files/Microsoft/Edge/Application/msedge.exe",
    "C:/Program Files (x86)/Microsoft/Edge/Application/msedge.exe"
  ))
  hits <- candidates[nzchar(candidates) & file.exists(candidates)]
  if (length(hits) == 0) return("")
  normalizePath(hits[[1]], winslash = "/", mustWork = FALSE)
}

