uuid <- function(prefix = "id") paste0(prefix, "-", digest::digest(runif(1)), "-", as.integer(Sys.time()))
now <- function() as.character(Sys.time())

default_email_schedule_timezone <- function() {
  env_tz <- trimws(as.character(Sys.getenv("BUDGET_APP_TIMEZONE", unset = "") %||% ""))
  tz <- if (nzchar(env_tz)) env_tz else trimws(as.character(Sys.timezone() %||% ""))
  if (!nzchar(tz)) tz <- "Africa/Nairobi"
  if (!(tz %in% OlsonNames())) tz <- "Africa/Nairobi"
  tz
}

normalize_timezone_value <- function(value, field_name = "Time zone", default = default_email_schedule_timezone()) {
  tz <- trimws(as.character(as_db_scalar(value, field_name = field_name, default = default) %||% ""))
  if (!nzchar(tz)) tz <- default
  if (!nzchar(tz)) tz <- "Africa/Nairobi"
  if (!(tz %in% OlsonNames())) stop(sprintf("%s must be a valid IANA time zone such as Africa/Nairobi or UTC.", field_name))
  tz
}

email_schedule_timezone <- function() {
  normalize_timezone_value(get_setting("email_schedule_timezone") %||% default_email_schedule_timezone(), field_name = "Email schedule time zone")
}

time_in_timezone <- function(tz = default_email_schedule_timezone()) {
  lubridate::with_tz(Sys.time(), tzone = normalize_timezone_value(tz))
}

time_string_in_timezone <- function(tz = default_email_schedule_timezone()) {
  format(time_in_timezone(tz), "%Y-%m-%d %H:%M:%S")
}

scheduled_email_now <- function() {
  time_string_in_timezone(email_schedule_timezone())
}

sanitize_filename <- function(x) {
  if (is.null(x)) return("unnamed")
  x <- as.character(x)
  x2 <- gsub("[^[:alnum:]_ \\-]", "", x)
  x3 <- gsub("\\s+", "_", x2)
  x4 <- gsub("^_+|_+$", "", x3)
  if (nzchar(x4)) x4 else "unnamed"
}

