format_file_size_text <- function(bytes) {
  value <- suppressWarnings(as.numeric(bytes %||% 0))
  if (is.na(value)) return("0 B")
  if (value < 1024) return(paste0(max(0, round(value)), " B"))
  if (value < 1024^2) return(paste0(round(value / 1024, 1), " KB"))
  if (value < 1024^3) return(paste0(round(value / (1024^2), 1), " MB"))
  paste0(round(value / (1024^3), 1), " GB")
}

format_bytes <- function(bytes) {
  format_file_size_text(bytes)
}

ensure_table_columns <- function(con, table_name, column_defs) {
  info <- dbGetQuery(con, sprintf("PRAGMA table_info(%s);", table_name))
  existing_cols <- info$name %||% character()
  missing_cols <- setdiff(names(column_defs), existing_cols)
  if (length(missing_cols) > 0) {
    for (col_name in missing_cols) {
      dbExecute(con, sprintf("ALTER TABLE %s ADD COLUMN %s %s;", table_name, col_name, column_defs[[col_name]]))
    }
    info <- dbGetQuery(con, sprintf("PRAGMA table_info(%s);", table_name))
    existing_cols <- info$name %||% character()
    still_missing <- setdiff(names(column_defs), existing_cols)
    if (length(still_missing) > 0) {
      stop(sprintf("Missing required columns in %s: %s", table_name, paste(still_missing, collapse = ", ")))
    }
  }
  invisible(existing_cols)
}

ensure_projects_schema <- function(con) {
  ensure_schema_once("projects_schema", {
    ensure_table_columns(con, "projects", c(
      workbook_path = "TEXT DEFAULT ''",
      status = "TEXT DEFAULT 'In Progress'",
      principal_investigator = "TEXT DEFAULT ''",
      team_members = "TEXT DEFAULT ''",
      access_key = "TEXT DEFAULT ''"
    ))
    try(dbExecute(con, "UPDATE projects SET access_key = '' WHERE access_key IS NULL;"), silent = TRUE)
    try(dbExecute(con, "UPDATE projects SET status = 'In Progress' WHERE status IS NULL OR TRIM(status) = '' OR LOWER(TRIM(status)) IN ('active','in progress','in_progress','progress','ongoing');"), silent = TRUE)
    try(dbExecute(con, "UPDATE projects SET status = 'Not Started' WHERE LOWER(TRIM(status)) IN ('not started','not_started','not-started','pending','planned');"), silent = TRUE)
    try(dbExecute(con, "UPDATE projects SET status = 'Paused' WHERE LOWER(TRIM(status)) IN ('paused','pause','on hold','on-hold','hold');"), silent = TRUE)
    try(dbExecute(con, "UPDATE projects SET status = 'Ended' WHERE LOWER(TRIM(status)) IN ('ended','end','complete','completed','closed','finished');"), silent = TRUE)
    project_rows <- dbGetQuery(con, "SELECT id, access_key FROM projects ORDER BY created_at, id;")
    if (nrow(project_rows) > 0) {
      used_keys <- character()
      for (i in seq_len(nrow(project_rows))) {
        project_id <- as.character(project_rows$id[[i]] %||% "")
        current_key <- normalize_project_access_key(project_rows$access_key[[i]] %||% "")
        if (!nzchar(current_key) || current_key %in% used_keys) {
          current_key <- generate_unique_project_access_key(used_keys = used_keys)
        }
        used_keys <- unique(c(used_keys, current_key))
        if (!identical(as.character(project_rows$access_key[[i]] %||% ""), current_key)) {
          dbExecute(
            con,
            "UPDATE projects SET access_key = ?, updated_at = ? WHERE id = ?;",
            params = list(current_key, now(), project_id)
          )
        }
      }
    }
    try(dbExecute(con, "CREATE UNIQUE INDEX IF NOT EXISTS idx_projects_access_key_unique ON projects(access_key);"), silent = TRUE)
  })
  invisible(TRUE)
}

