ensure_email_packages_installed <- function() {
  missing_email <- email_optional_pkgs[!vapply(email_optional_pkgs, requireNamespace, logical(1), quietly = TRUE)]
  if (length(missing_email) == 0) {
    refresh_email_package_flags()
    return(invisible(TRUE))
  }
  repos <- getOption("repos")
  if (is.null(repos) || !("CRAN" %in% names(repos)) || identical(repos[["CRAN"]], "@CRAN@") || !nzchar(repos[["CRAN"]])) {
    options(repos = c(CRAN = "https://cloud.r-project.org"))
  }
  tryCatch(
    install.packages(missing_email, lib = startup_r_lib, dependencies = TRUE),
    error = function(e) {
      stop("Unable to install scheduled email packages automatically: ", e$message, call. = FALSE)
    }
  )
  refresh_email_package_flags()
  still_missing <- email_optional_pkgs[!vapply(email_optional_pkgs, requireNamespace, logical(1), quietly = TRUE)]
  if (length(still_missing) > 0) {
    stop(
      "Scheduled email packages are still missing after the automatic installation attempt: ",
      paste(still_missing, collapse = ", "),
      call. = FALSE
    )
  }
  invisible(TRUE)
}

