default_expense_category_seed <- function(nowt = as.character(Sys.time())) {
  defaults <- data.frame(
    main = c(
      "Personnel Costs",
      "Laboratory Supplies",
      "Lab Supplies",
      "Research Equipment",
      "Animal Care",
      "Animal Purchase",
      "Surgery",
      "Sampling",
      "Field Operations",
      "Travel",
      "Per Diem",
      "Conference Charges",
      "Fuel Cost",
      "Training & Workshops",
      "Data & IT",
      "Compliance & Regulatory",
      "Dissemination",
      "Administrative Costs",
      "Stationery",
      "Airtime",
      "Tent Hire",
      "Chairs Hire",
      "Monitoring & Evaluation (M&E)",
      "Miscellaneous / Contingency"
    ),
    sub = c(
      "Research assistants salaries;Laboratory technologists;Field officers allowances;Data analysts fees;Principal investigator allowances;Intern and student stipends",
      "Reagents and chemicals;Media and buffers;ELISA / PCR / extraction kits;Pipette tips;Tubes and consumables;PPE (gloves, masks, coats)",
      "Reagents and chemicals;Media and buffers;Test kits;Pipette tips;Tubes and consumables;PPE (gloves, masks, coats)",
      "Equipment purchase;Equipment calibration;Equipment servicing and maintenance;Spare parts;Instrument accessories",
      "Animal procurement;Feed and nutrition;Veterinary drugs;Vaccination;Cage maintenance;Bedding materials;Animal welfare inspections",
      "Small laboratory animals;Large animals;Animal transport;Holding and acclimatization",
      "Surgical consumables;Anesthesia and analgesia;Sterilization supplies;Post-operative care",
      "Sample collection kits;Vacutainers and swabs;Cold-chain consumables;Sample transport",
      "Field travel;Sample collection materials;Community engagement costs;Permits and access fees;Per diems;Accommodation;Air tickets;Local transport;Fuel;Vehicle hire and maintenance",
      "Per diems;Accommodation;Air tickets;Local transport;Fuel;Vehicle hire and maintenance",
      "Field per diem;Conference per diem;Daily subsistence allowance",
      "Conference registration;Abstract submission;Conference materials",
      "Field fuel;Generator fuel;Vehicle fuel",
      "Training materials;Workshop venue hire;Facilitator fees;Participant allowances",
      "Software licenses;Data analysis tools;Cloud storage;Internet services;Bioinformatics services",
      "Ethical review fees;Research permits;Biosafety approvals;Regulatory inspections",
      "Publication fees;Printing and report production;Stakeholder meetings;Policy dissemination;Conference registration fees",
      "Office stationery;Publication;Printing and photocopying;Utilities;Office rent;Security and cleaning services;Bank charges",
      "Printing and photocopying;Paper and notebooks;Pens and markers;Binding materials",
      "Phone airtime;Data bundles;Internet bundles",
      "Tent rental;Tent setup and transport",
      "Chair rental;Chair transport and setup",
      "Monitoring visits;Evaluation consultancy;External audits;Reporting tools",
      "Emergency expenses;Unforeseen costs;Miscellaneous"
    ),
    stringsAsFactors = FALSE
  )
  rows <- data.frame(id = character(), main = character(), sub = character(), created_at = character(), stringsAsFactors = FALSE)
  for (i in seq_len(nrow(defaults))) {
    subs <- as.character(defaults$sub[[i]] %||% "")
    if (nzchar(subs)) {
      svec <- strsplit(subs, ";", fixed = TRUE)[[1]]
      for (s in svec) {
        rows <- rbind(rows, data.frame(
          id = uuid("cat"),
          main = as.character(defaults$main[[i]]),
          sub = trimws(s),
          created_at = nowt,
          stringsAsFactors = FALSE
        ))
      }
    } else {
      rows <- rbind(rows, data.frame(
        id = uuid("cat"),
        main = as.character(defaults$main[[i]]),
        sub = "",
        created_at = nowt,
        stringsAsFactors = FALSE
      ))
    }
  }
  rows
}

ensure_default_expense_categories <- function(con) {
  seed_rows <- default_expense_category_seed(now())
  existing_rows <- tryCatch(
    dbGetQuery(con, "SELECT main, sub FROM categories;"),
    error = function(e) data.frame(main = character(), sub = character(), stringsAsFactors = FALSE)
  )
  if (nrow(existing_rows) == 0) {
    dbWriteTable(con, "categories", seed_rows, append = TRUE, row.names = FALSE)
    return(invisible(TRUE))
  }
  normalize_key <- function(main, sub) paste0(tolower(trimws(as.character(main %||% ""))), "||", tolower(trimws(as.character(sub %||% ""))))
  existing_keys <- normalize_key(existing_rows$main, existing_rows$sub)
  seed_keys <- normalize_key(seed_rows$main, seed_rows$sub)
  missing_rows <- seed_rows[!(seed_keys %in% existing_keys), , drop = FALSE]
  if (nrow(missing_rows) > 0) {
    dbWriteTable(con, "categories", missing_rows, append = TRUE, row.names = FALSE)
  }
  invisible(TRUE)
}

init_db <- function() {
  con <- connect_db(); on.exit(dbDisconnect(con))
