  ensure_core_query_indices(con)
  # Seed settings if empty (include admin password hash)
  existing <- dbGetQuery(con, "SELECT COUNT(*) as n FROM settings;")$n
  if (existing == 0) {
    nowt <- as.character(Sys.time())
    seed <- data.frame(
      key = c(
        "date_format","auto_save_interval_sec","export_folder","backup_folder","excel_password",
