      ),
      value = c(
        "YYYY-MM-DD","30", internal_exports_dir, internal_backups_dir, "", "CONFIDENTIAL","Light","false","true",
        digest::digest("admin", algo = "sha256"), "KES","false","","","Budget App Backups","","300",
        "31st March 2026",
        "false","","","","587","","","true","false","60", default_email_schedule_timezone(),"15","60"
      ),
      updated_at = rep(nowt, 31),
      stringsAsFactors = FALSE
    )
    dbWriteTable(con, "settings", seed, append = TRUE, row.names = FALSE)
  } else {
    # ensure admin_password_hash exists (back-compat)
    res <- dbGetQuery(con, "SELECT value FROM settings WHERE key = 'admin_password_hash' LIMIT 1;")
    if (nrow(res) == 0) {
      dbExecute(con, "INSERT INTO settings(key,value,updated_at) VALUES (?,?,?);", params = list("admin_password_hash", digest::digest("admin", algo = "sha256"), now()))
    }
  }
  ensure_app_setting_keys(con, c(
    currency = "KES",
    drive_backup_enabled = "false",
    drive_account_email = "",
    drive_connected_email = "",
    drive_root_folder_name = "Budget App Backups",
    drive_root_folder_id = "",
    drive_sync_interval_sec = "300",
    progress_report_as_at_date = "31st March 2026",
    email_delivery_enabled = "false",
    email_from_name = "",
    email_from_address = "",
    email_smtp_host = "",
    email_smtp_port = "587",
    email_smtp_username = "",
    email_smtp_password = "",
    email_smtp_use_ssl = "true",
    email_smtp_insecure_tls = "false",
    email_scheduler_interval_sec = "60",
    email_schedule_timezone = default_email_schedule_timezone(),
    email_smtp_connect_timeout_sec = "15",
    email_smtp_total_timeout_sec = "60"
  ))
  
  ensure_default_expense_categories(con)
  
  # Ensure legacy DBs have new columns if created earlier
  info <- dbGetQuery(con, "PRAGMA table_info(expenses);")
  cols <- info$name
  if (!("category_main" %in% cols)) {
    try(dbExecute(con, "ALTER TABLE expenses ADD COLUMN category_main TEXT DEFAULT '';", silent = TRUE), silent = TRUE)
  }
  if (!("category_sub" %in% cols)) {
    try(dbExecute(con, "ALTER TABLE expenses ADD COLUMN category_sub TEXT DEFAULT '';", silent = TRUE), silent = TRUE)
  }
  
  # Ensure legacy projects table has required columns
  try(ensure_projects_schema(con), silent = TRUE)
  
  # Ensure legacy DBs have expense_breakdowns table (migration safety)
  # If table does not exist, create it (non-destructive)
  br_info <- tryCatch(dbGetQuery(con, "PRAGMA table_info(expense_breakdowns);"), error = function(e) NULL)
  if (is.null(br_info) || nrow(br_info) == 0) {
    try(dbExecute(con, "
      CREATE TABLE IF NOT EXISTS expense_breakdowns (
        id TEXT PRIMARY KEY,
        expense_id TEXT,
        label TEXT,
        amount REAL,
        created_at TEXT
      );
    "), silent = TRUE)
  }

  audit_info <- dbGetQuery(con, "PRAGMA table_info(audit);")
  if (!("workspace_id" %in% audit_info$name)) {
    try(dbExecute(con, "ALTER TABLE audit ADD COLUMN workspace_id TEXT;"), silent = TRUE)
  }

  backups_info <- dbGetQuery(con, "PRAGMA table_info(backups);")
  if (!("workspace_id" %in% backups_info$name)) {
    try(dbExecute(con, "ALTER TABLE backups ADD COLUMN workspace_id TEXT;"), silent = TRUE)
  }

  try(ensure_project_reports_schema(con), silent = TRUE)
  try(ensure_drive_sync_schema(con), silent = TRUE)
  try(ensure_communications_schema(con), silent = TRUE)
}
init_db()

# Settings helpers
settings_runtime_cache <- local({
  env <- new.env(parent = emptyenv())
  env$values <- NULL
  env
})

read_settings_map <- function(force = FALSE, con = NULL) {
  if (!isTRUE(force) && !is.null(settings_runtime_cache$values) && is.list(settings_runtime_cache$values)) {
    return(settings_runtime_cache$values)
  }
  close_con <- FALSE
  if (is.null(con)) {
    con <- connect_db()
    close_con <- TRUE
  }
  if (isTRUE(close_con)) on.exit(dbDisconnect(con), add = TRUE)
  rows <- dbGetQuery(con, "SELECT key, value FROM settings;")
  values <- stats::setNames(as.list(as.character(rows$value %||% character())), as.character(rows$key %||% character()))
  settings_runtime_cache$values <- values
  values
}

invalidate_settings_runtime_cache <- function() {
  settings_runtime_cache$values <- NULL
  invisible(TRUE)
}

get_setting <- function(key) {
  values <- read_settings_map()
  values[[as.character(key %||% "")]]
}

set_settings_batch <- function(values, audit_action = "update_settings", detail = list(), user = "local_user") {
  tryCatch({
    if (is.null(values) || length(values) == 0) return(TRUE)
    keys <- names(values)
    if (is.null(keys) || any(!nzchar(keys))) stop("Settings batch requires named values.")
    con <- connect_db()
    on.exit({
      if (DBI::dbIsValid(con)) dbDisconnect(con)
    }, add = TRUE)
    timestamp <- now()
    DBI::dbWithTransaction(con, {
      for (key in keys) {
        dbExecute(con, "
          INSERT INTO settings(key,value,updated_at) VALUES (?,?,?)
          ON CONFLICT(key) DO UPDATE SET value=excluded.value, updated_at=excluded.updated_at;
        ", params = list(as.character(key), as.character(values[[key]] %||% ""), timestamp))
      }
    })
    cache_values <- read_settings_map(force = FALSE, con = con)
    for (key in keys) {
      cache_values[[as.character(key)]] <- as.character(values[[key]] %||% "")
    }
    settings_runtime_cache$values <- cache_values
    audit_detail <- c(
      list(keys = unname(keys), key_count = length(keys)),
      if (is.list(detail)) detail else list(detail = detail)
    )
    try(log_audit(user = user, module = "Settings", action = audit_action, target_table = "settings", target_id = paste(keys, collapse = ","), detail = audit_detail, workspace_id = NA_character_, trigger_sync = FALSE), silent = TRUE)
    TRUE
  }, error = function(e) {
    message("set_settings_batch error: ", e$message)
    FALSE
  })
}

set_setting <- function(key, value) {
  set_settings_batch(stats::setNames(list(value), as.character(key)), audit_action = "update_setting", detail = list(value = value))
}

# Helper: verify admin password (hashed)
check_admin_password <- function(password_plain) {
  con <- connect_db_for_login()
  on.exit({
    if (DBI::dbIsValid(con)) dbDisconnect(con)
  }, add = TRUE)
  values <- read_settings_map(force = TRUE, con = con)
  hash <- values[["admin_password_hash"]] %||% digest::digest("admin", algo = "sha256")
  identical(digest::digest(as.character(password_plain), algo = "sha256"), as.character(hash))
}

