append_drive_sync_log <- function(level = "INFO", message, project_id = "", detail = list()) {
  dir_create(logs_dir, recurse = TRUE)
  detail_text <- ""
  if (length(detail) > 0) {
    detail_text <- tryCatch(
      json_stringify(detail, auto_unbox = TRUE),
      error = function(e) ""
    )
  }
  line <- paste0(
    "[", format(Sys.time(), "%Y-%m-%d %H:%M:%S"), "] ",
    "[", toupper(as.character(level %||% "INFO")), "]",
    if (nzchar(as.character(project_id %||% ""))) paste0(" [", as.character(project_id), "]") else "",
    " ", as.character(message %||% ""),
    if (nzchar(detail_text)) paste0(" ", detail_text) else "",
    "\n"
  )
  cat(line, file = drive_sync_log_file, append = TRUE)
  invisible(line)
}

append_scheduled_email_log <- function(level = "INFO", message, email_id = "", project_id = "", detail = list()) {
  dir_create(logs_dir, recurse = TRUE)
  detail_text <- ""
  if (length(detail) > 0) {
    detail_text <- tryCatch(
      json_stringify(detail, auto_unbox = TRUE),
      error = function(e) ""
    )
  }
  line <- paste0(
    "[", format(Sys.time(), "%Y-%m-%d %H:%M:%S"), "] ",
    "[", toupper(as.character(level %||% "INFO")), "]",
    if (nzchar(as.character(project_id %||% ""))) paste0(" [project:", as.character(project_id), "]") else "",
    if (nzchar(as.character(email_id %||% ""))) paste0(" [email:", as.character(email_id), "]") else "",
    " ", as.character(message %||% ""),
    if (nzchar(detail_text)) paste0(" ", detail_text) else "",
    "\n"
  )
  cat(line, file = scheduled_email_log_path, append = TRUE)
  invisible(line)
}

r_string_literal <- function(x) {
  jsonlite::toJSON(as.character(x %||% ""), auto_unbox = TRUE, null = "null")
}

write_json_atomic <- function(path, payload) {
  dir_create(path_dir(path), recurse = TRUE)
  temp_path <- paste0(path, ".tmp")
  writeLines(
    json_stringify(payload, auto_unbox = TRUE, null = "null", pretty = TRUE),
    con = temp_path,
    useBytes = TRUE
  )
  file_move(temp_path, path)
  invisible(path)
}

read_json_safe <- function(path, default = NULL) {
  if (!nzchar(as.character(path %||% "")) || !file_exists(path)) return(default)
  tryCatch(jsonlite::fromJSON(path, simplifyVector = TRUE), error = function(e) default)
}

launch_detached_rscript <- function(expr, log_path, reason = "worker", wd = startup_app_root) {
  rscript_bin <- Sys.which("Rscript")
  if (!nzchar(rscript_bin)) rscript_bin <- file.path(R.home("bin"), "Rscript")
  if (!nzchar(rscript_bin) || !file_exists(rscript_bin)) {
    append_background_scheduler_log("ERROR", "Unable to locate Rscript for detached worker launch.", detail = list(reason = reason))
    return(FALSE)
  }
  dir_create(path_dir(log_path), recurse = TRUE)
  tryCatch({
    if (has_processx) {
      proc <- processx::process$new(
        command = rscript_bin,
        args = c("-e", expr),
        wd = wd,
        stdout = log_path,
        stderr = log_path,
        cleanup = FALSE,
        cleanup_tree = FALSE,
        supervise = FALSE
      )
      on.exit({
        rm(proc)
        invisible(gc(FALSE))
      }, add = TRUE)
      Sys.sleep(0.2)
      exit_status <- tryCatch(proc$get_exit_status(), error = function(e) NULL)
      is_alive <- tryCatch(proc$is_alive(), error = function(e) FALSE)
      return(isTRUE(is_alive) || is.null(exit_status) || identical(exit_status, 0L))
    }

    if (.Platform$OS.type == "windows") {
      cmd <- sprintf('cmd /c start "" /B "%s" -e %s', rscript_bin, shQuote(expr))
      shell(cmd, wait = FALSE)
      return(TRUE)
    }

    cmd <- paste(
      "cd", shQuote(wd), "&&",
      "nohup",
      shQuote(rscript_bin),
      "-e",
      shQuote(expr),
      ">>",
      shQuote(log_path),
      "2>&1 </dev/null &"
    )
    system2("sh", c("-c", cmd), wait = FALSE)
    TRUE
  }, error = function(e) {
    append_background_scheduler_log("ERROR", paste0("Detached worker launch failed: ", e$message), detail = list(reason = reason))
    FALSE
  })
}

