resolve_email_smtp_transport_use_ssl <- function(settings) {
  requested_ssl <- isTRUE(settings$smtp_use_ssl)
  if (!requested_ssl) return(FALSE)
  TRUE
}

resolve_email_smtp_username <- function(settings) {
  username <- trimws(as.character(settings$smtp_username %||% ""))
  from_address <- trimws(as.character(settings$from_address %||% ""))
  smtp_host <- tolower(trimws(as.character(settings$smtp_host %||% "")))
  if (!nzchar(username)) return(from_address)
  if (nzchar(from_address) && grepl("gmail", smtp_host, fixed = TRUE) && !grepl("@", username, fixed = TRUE)) {
    return(from_address)
  }
  username
}

resolve_email_smtp_password <- function(settings) {
  password <- trimws(as.character(settings$smtp_password %||% ""))
  smtp_host <- tolower(trimws(as.character(settings$smtp_host %||% "")))
  if (nzchar(password) && grepl("gmail", smtp_host, fixed = TRUE)) {
    password <- gsub("\\s+", "", password, perl = TRUE)
  }
  password
}

contextualize_email_send_error <- function(error_text, settings, attempt_count = 1L) {
  text <- trimws(as.character(error_text %||% "Unknown email delivery error"))
  smtp_host <- trimws(as.character(settings$smtp_host %||% ""))
  auth_user <- resolve_email_smtp_username(settings)
  transport <- email_smtp_transport_label(settings)
  guidance <- character()
  if (grepl("Login denied", text, fixed = TRUE) && grepl("gmail", tolower(smtp_host), fixed = TRUE)) {
    guidance <- c(guidance, "Gmail rejected the SMTP credentials. Verify the sender email address and current Gmail App Password saved in Settings.")
  }
  if (grepl("MAIL failed:\\s*530", text, ignore.case = TRUE) && grepl("gmail", tolower(smtp_host), fixed = TRUE)) {
    guidance <- c(guidance, "Gmail rejected the MAIL command before accepting the message. Confirm STARTTLS-compatible SMTP on port 587 and valid Gmail App Password authentication.")
  }
  detail <- c(
    text,
    if (nzchar(auth_user)) paste0("SMTP auth user: ", auth_user) else NULL,
    if (nzchar(transport)) paste0("Transport: ", transport) else NULL,
    guidance,
    paste0("(after ", as.integer(attempt_count %||% 1L), " attempts)")
  )
  paste(detail[nzchar(detail)], collapse = " | ")
}

email_smtp_transport_label <- function(settings) {
  port <- suppressWarnings(as.integer(settings$smtp_port %||% 0L))
  if (identical(port, 587L) && isTRUE(settings$smtp_use_ssl)) return("STARTTLS-compatible SMTP (port 587)")
  if (identical(port, 465L)) return("Implicit SSL/TLS SMTP (port 465)")
  if (isTRUE(settings$smtp_use_ssl)) return("SSL/TLS-enabled SMTP")
  "Standard SMTP"
}

describe_email_send_error <- function(error) {
  messages <- character()
  append_message <- function(text) {
    text <- trimws(as.character(text %||% ""))
    if (nzchar(text) && !(text %in% messages)) messages <<- c(messages, text)
  }
  walk_condition <- function(cond) {
    if (is.null(cond)) return(invisible(NULL))
    append_message(conditionMessage(cond))
    if (!is.null(cond$message)) append_message(cond$message)
    if (!is.null(cond$error)) append_message(cond$error)
    parent <- NULL
    if (!is.null(cond$parent)) {
      parent <- cond$parent
    } else {
      parent <- attr(cond, "parent", exact = TRUE)
    }
    if (!is.null(parent) && !identical(parent, cond)) walk_condition(parent)
    invisible(NULL)
  }
  walk_condition(error)
  if (length(messages) == 0) "Unknown email delivery error" else paste(messages, collapse = " | ")
}

email_delivery_status <- function(settings = get_email_delivery_settings()) {
  refresh_email_package_flags()
  if (!isTRUE(settings$enabled)) {
    return(list(ok = FALSE, reason = "Scheduled email delivery is disabled.", settings = settings))
  }
  if (!has_emayili) {
    return(list(ok = FALSE, reason = "Install the optional R package 'emayili' to enable scheduled email delivery.", settings = settings))
  }
  if (!nzchar(settings$from_address)) {
    return(list(ok = FALSE, reason = "Sender email address is required.", settings = settings))
  }
  if (!nzchar(settings$smtp_host)) {
    return(list(ok = FALSE, reason = "SMTP host is required.", settings = settings))
  }
  if (is.na(settings$smtp_port) || settings$smtp_port <= 0) {
    return(list(ok = FALSE, reason = "SMTP port must be a valid positive number.", settings = settings))
  }
  if (!nzchar(resolve_email_smtp_username(settings))) {
    return(list(ok = FALSE, reason = "SMTP username is required.", settings = settings))
  }
  if (!nzchar(settings$smtp_password)) {
    return(list(ok = FALSE, reason = "SMTP password is required.", settings = settings))
  }
  list(ok = TRUE, reason = "Scheduled email delivery is ready.", settings = settings)
}

