email_logo_storage_prefix <- "email-logo"
email_logo_cid <- "budget-app-logo"

email_logo_asset_path <- function() {
  if (!dir_exists(email_branding_dir)) return("")
  candidates <- tryCatch(
    dir_ls(email_branding_dir, type = "file", recurse = FALSE),
    error = function(e) character()
  )
  candidates <- as.character(candidates)
  if (length(candidates) == 0) return("")
  keep <- basename(candidates)
  keep <- candidates[startsWith(tolower(keep), paste0(email_logo_storage_prefix, "."))]
  if (length(keep) == 0) return("")
  normalizePath(keep[[1]], winslash = "/", mustWork = FALSE)
}

email_logo_asset_label <- function() {
  path <- email_logo_asset_path()
  if (!nzchar(path)) return("Not configured")
  basename(path)
}

email_logo_content_type <- function(path = email_logo_asset_path()) {
  ext <- tolower(tools::file_ext(as.character(path %||% "")))
  switch(
    ext,
    png = "image/png",
    jpg = "image/jpeg",
    jpeg = "image/jpeg",
    webp = "image/webp",
    gif = "image/gif",
    ""
  )
}

store_email_logo_asset <- function(upload_path) {
  upload_path <- as.character(upload_path %||% "")
  if (!nzchar(upload_path) || !file_exists(upload_path)) stop("Uploaded email logo file was not found.")
  ext <- tolower(tools::file_ext(upload_path))
  allowed <- c("png", "jpg", "jpeg", "webp", "gif")
  if (!(ext %in% allowed)) {
    stop("Email logo must be a PNG, JPG, JPEG, WEBP, or GIF image.")
  }
  dir_create(email_branding_dir, recurse = TRUE)
  existing <- tryCatch(dir_ls(email_branding_dir, type = "file", recurse = FALSE), error = function(e) character())
  existing <- as.character(existing)
  if (length(existing) > 0) {
    stale <- existing[startsWith(tolower(basename(existing)), paste0(email_logo_storage_prefix, "."))]
    if (length(stale) > 0) try(file_delete(stale), silent = TRUE)
  }
  target <- file.path(email_branding_dir, paste0(email_logo_storage_prefix, ".", ext))
  file_copy(upload_path, target, overwrite = TRUE)
  normalizePath(target, winslash = "/", mustWork = FALSE)
}

