drive_sync_status <- function(settings = get_drive_sync_settings()) {
  if (!isTRUE(settings$enabled)) {
    return(list(ok = FALSE, reason = "Google Drive backup is disabled.", settings = settings))
  }
  if (identical(settings$backend, "filesystem")) {
    root_dir <- settings$root_folder_id
    if (!nzchar(root_dir)) root_dir <- file.path(data_dir, "drive-mock")
    return(list(
      ok = TRUE,
      reason = "filesystem backend ready",
      settings = modifyList(settings, list(root_folder_id = normalizePath(root_dir, winslash = "/", mustWork = FALSE)))
    ))
  }
  refresh_drive_package_flags()
  if (!has_googledrive || !has_gargle) {
    return(list(ok = FALSE, reason = "Install the optional R packages 'googledrive' and 'gargle' to enable Google Drive backups.", settings = settings))
  }
  if (isTRUE(settings$has_service_account) && file_exists(settings$service_account_path)) {
    if (!nzchar(settings$connected_email %||% "")) {
      return(list(
        ok = FALSE,
        reason = "Google Drive service account JSON is uploaded but not connected yet. Click Connect Google Drive to validate the credential and prepare the root backup folder.",
        settings = settings
      ))
    }
    if (!nzchar(settings$root_folder_name)) settings$root_folder_name <- "Budget App Backups"
    if (!nzchar(settings$root_folder_id)) {
      return(list(
        ok = FALSE,
        reason = paste(
          "Google Drive service account credential is stored, but no Shared Drive root folder ID is configured yet.",
          "Paste the folder ID of a folder inside a Google Shared Drive into Settings and click Connect Google Drive again."
        ),
        settings = settings
      ))
    }
    return(list(ok = TRUE, reason = "Google Drive service account credentials ready.", settings = settings))
  }
  if (!nzchar(settings$account_email)) {
    return(list(ok = FALSE, reason = "Google account email is required for Drive backup.", settings = settings))
  }
  if (!identical(tolower(settings$account_email), tolower(settings$connected_email %||% ""))) {
    return(list(ok = FALSE, reason = "Google Drive needs to be reconnected for the configured account email.", settings = settings))
  }
  if (!drive_has_cached_token()) {
    return(list(ok = FALSE, reason = "Google Drive is not connected yet. Use the admin settings to connect the configured account.", settings = settings))
  }
  if (!nzchar(settings$root_folder_name)) settings$root_folder_name <- "Budget App Backups"
  list(ok = TRUE, reason = "google_drive backend ready", settings = settings)
}

format_drive_error <- function(e) {
  msg <- conditionMessage(e)
  if (grepl("storagequotaexceeded|service accounts do not have storage quota", msg, ignore.case = TRUE)) {
    return(paste(
      "Google Drive service accounts cannot store backups in personal My Drive because they do not have storage quota.",
      "Create a folder inside a Google Shared Drive, add the service account as a Content manager or Manager, paste that folder ID into Settings, then click Connect Google Drive again."
    ))
  }
  if (grepl("non-interactive session|can't get google credentials", msg, ignore.case = TRUE)) {
    return(paste(
      "This hosted session cannot launch browser-based Google OAuth.",
      "Upload a Google service account JSON in Settings and click Connect Google Drive again, or reconnect using a previously created OAuth token cache."
    ))
  }
  if (grepl("insufficient|403|PERMISSION_DENIED", msg, ignore.case = TRUE)) {
    paste0(
      "Google Drive permission is insufficient. Click Connect Google Drive again and approve Drive file access. Details: ",
      msg
    )
  } else {
    msg
  }
}

drive_authenticate_interactive <- function(email) {
  ensure_drive_packages_installed()
  email <- trimws(as.character(email %||% ""))
  dir_create(drive_token_cache_dir, recurse = TRUE)
  options(googledrive_quiet = TRUE)
  if (drive_has_service_account()) {
    tryCatch({
      googledrive::drive_auth(
        path = drive_service_account_path,
        cache = FALSE,
        scopes = googledrive::drive_scopes("drive")
      )
      connected_email <- read_drive_service_account_email(drive_service_account_path)
      if (!nzchar(connected_email)) connected_email <- email
      if (!nzchar(connected_email)) connected_email <- "service-account"
      return(list(ok = TRUE, mode = "service_account", connected_email = connected_email))
    }, error = function(e) {
      stop(format_drive_error(e), call. = FALSE)
    })
  }
  if (!nzchar(email)) stop("Google account email is required unless a Google service account JSON is uploaded.")
  if (drive_has_cached_token()) {
    tryCatch({
      options(gargle_oauth_email = email)
      googledrive::drive_auth(
        email = email,
        cache = drive_token_cache_dir,
        scopes = googledrive::drive_scopes("drive"),
        use_oob = FALSE
      )
      googledrive::drive_user()
      return(list(ok = TRUE, mode = "cached_oauth", connected_email = email))
    }, error = function(e) {
      clear_drive_cached_tokens()
      stop(format_drive_error(e), call. = FALSE)
    })
  }
  if (!interactive()) {
    stop(
      paste(
        "This server session is non-interactive.",
        "For hosted Ubuntu/Shiny deployment, upload a Google service account JSON in Settings or deploy a previously-created OAuth token cache.",
        "Interactive browser OAuth cannot be started safely from the server process."
      ),
      call. = FALSE
    )
  }
  options(gargle_oauth_email = email)
  googledrive::drive_auth(
    email = email,
    cache = drive_token_cache_dir,
    scopes = googledrive::drive_scopes("drive"),
    use_oob = gargle::gargle_oob_default()
  )
  tryCatch({
    googledrive::drive_user()
    list(ok = TRUE, mode = "interactive_oauth", connected_email = email)
  }, error = function(e) {
    clear_drive_cached_tokens()
    stop(format_drive_error(e), call. = FALSE)
  })
}

