    final_folder_id <- if (!is.null(folder_id) && nzchar(as.character(folder_id))) as.character(folder_id) else as.character(current$drive_folder_id[[1]] %||% "")
    dbExecute(
      con,
      "UPDATE projects SET drive_folder_id = ?, drive_last_synced_at = ?, drive_sync_error = ?, drive_pending_sync = ? WHERE id = ?;",
      params = list(final_folder_id, if (isTRUE(success)) now() else "", as.character(error_message %||% ""), if (isTRUE(success)) 0L else 1L, as.character(project_id))
    )
    TRUE
  }, error = function(e) {
    append_drive_sync_log("ERROR", paste0("Unable to update Drive sync state: ", e$message), project_id = project_id)
    FALSE
  })
