acquire_drive_sync_lease <- function(lock_key = "google_drive_backup", ttl_sec = 900L) {
  con <- connect_db()
  on.exit(dbDisconnect(con), add = TRUE)
  ensure_drive_sync_schema(con)
  lease_token <- uuid("drivelease")
  now_epoch <- as.numeric(Sys.time())
  acquired <- DBI::dbWithTransaction(con, {
    existing <- dbGetQuery(con, "SELECT * FROM sync_locks WHERE lock_key = ? LIMIT 1;", params = list(lock_key))
    if (nrow(existing) == 0) {
      dbExecute(
        con,
        "INSERT INTO sync_locks(lock_key, lease_token, locked_until, started_at, finished_at, last_success_at, last_error, updated_at) VALUES (?,?,?,?,?,?,?,?);",
        params = list(lock_key, lease_token, now_epoch + as.numeric(ttl_sec), now(), "", "", "", now())
      )
      TRUE
    } else {
      locked_until <- suppressWarnings(as.numeric(existing$locked_until[[1]] %||% 0))
      if (is.na(locked_until) || locked_until <= now_epoch) {
        dbExecute(
          con,
          "UPDATE sync_locks SET lease_token = ?, locked_until = ?, started_at = ?, finished_at = '', updated_at = ?, last_error = '' WHERE lock_key = ?;",
          params = list(lease_token, now_epoch + as.numeric(ttl_sec), now(), now(), lock_key)
        )
        TRUE
      } else {
        FALSE
      }
    }
  })
  acquired <- isTRUE(acquired)
  list(acquired = acquired, token = if (acquired) lease_token else "", lock_key = lock_key)
}

heartbeat_drive_sync_lease <- function(lease_token, extend_sec = 900L) {
  if (is.null(lease_token) || !nzchar(as.character(lease_token))) return(invisible(FALSE))
