build_project_report_supporting_doc_row <- function(project_id, uploaded_row, report_id = "", submission_type = "supporting", uploaded_by_role = "Public Submitter", uploaded_by_name = "") {
  src_path <- as.character(uploaded_row$datapath[[1]] %||% "")
  if (!nzchar(src_path) || !file_exists(src_path)) stop("Uploaded supporting file could not be found.")
  original_filename <- as.character(uploaded_row$name[[1]] %||% basename(src_path))
  upload_size <- suppressWarnings(as.numeric(uploaded_row$size[[1]] %||% safe_file_size(src_path)))
  if (!is.na(upload_size) && upload_size > max_upload_request_bytes) {
    stop("Uploaded file exceeds the supported size limit for this server.")
  }
  ext <- tolower(fs::path_ext(original_filename))
  stem <- sanitize_filename(tools::file_path_sans_ext(original_filename))
  if (!nzchar(stem)) stem <- "supporting_file"
  doc_id <- uuid("psd")
  stored_filename <- paste0(doc_id, "__", stem, if (nzchar(ext)) paste0(".", ext) else "")
  dest_dir <- project_report_supporting_doc_storage_dir(project_id)
  dest_path <- file.path(dest_dir, stored_filename)
  dest_path <- copy_file_checked(src_path, dest_path, overwrite = TRUE)
  mime_type <- trimws(as.character(uploaded_row$type[[1]] %||% ""))
  if (!nzchar(mime_type)) mime_type <- guess_email_attachment_content_type(original_filename)
  data.frame(
    id = doc_id,
    project_id = as.character(project_id %||% ""),
    project_code = as.character(project_id %||% ""),
    report_id = as.character(report_id %||% ""),
    submission_type = as.character(submission_type %||% "supporting"),
    title = tools::file_path_sans_ext(original_filename),
    original_filename = original_filename,
    stored_filename = stored_filename,
    file_ext = ext,
    mime_type = mime_type,
    filepath = dest_path,
    size = safe_file_size(dest_path),
    checksum = file_checksum(dest_path),
    uploaded_by_role = as.character(uploaded_by_role %||% "Public Submitter"),
    uploaded_by_name = as.character(uploaded_by_name %||% ""),
    status = "active",
    is_trashed = 0L,
    deleted_at = "",
    created_at = now(),
    updated_at = now(),
    stringsAsFactors = FALSE
  )
}

save_project_report_supporting_docs <- function(project_id, uploaded_files, report_id = "", submission_type = "supporting", uploaded_by_role = "Public Submitter", uploaded_by_name = "") {
  project_id <- as.character(project_id %||% "")
  report_id <- as.character(report_id %||% "")
  if (!nzchar(project_id)) stop("Project Code is required for supporting files.")
  if (!is.data.frame(uploaded_files) || nrow(uploaded_files) == 0) return(data.frame())
  project <- lookup_project_by_code(project_id)
  if (nrow(project) != 1) stop("Invalid Project Code. No active project found.")
  con <- connect_db(); on.exit(dbDisconnect(con), add = TRUE)
  ensure_project_report_supporting_docs_schema(con)
  existing <- dbGetQuery(
    con,
    "SELECT * FROM project_report_supporting_docs WHERE project_id = ? AND COALESCE(is_trashed,0) = 0;",
    params = list(project_id)
  )
  rows <- list()
  copied_paths <- character()
  for (i in seq_len(nrow(uploaded_files))) {
    row <- build_project_report_supporting_doc_row(
      project_id = project_id,
      uploaded_row = uploaded_files[i, , drop = FALSE],
      report_id = report_id,
      submission_type = submission_type,
      uploaded_by_role = uploaded_by_role,
      uploaded_by_name = uploaded_by_name
    )
    already_exists <- nrow(existing) > 0 &&
      any(
        as.character(existing$original_filename %||% "") == as.character(row$original_filename[[1]]) &
          as.character(existing$checksum %||% "") == as.character(row$checksum[[1]]) &
          as.character(existing$report_id %||% "") == as.character(row$report_id[[1]] %||% "")
      )
    if (already_exists) {
      try(if (file_exists(as.character(row$filepath[[1]] %||% ""))) file_delete(as.character(row$filepath[[1]])), silent = TRUE)
      next
    }
    rows[[length(rows) + 1]] <- row
    copied_paths <- c(copied_paths, as.character(row$filepath[[1]] %||% ""))
  }
  if (length(rows) == 0) return(data.frame())
  out <- do.call(rbind, rows)
  tryCatch({
    dbWriteTable(con, "project_report_supporting_docs", out, append = TRUE, row.names = FALSE)
    try(mark_drive_project_dirty(project_id), silent = TRUE)
    try(log_audit(
      module = "Report Submission",
      action = "upload_supporting_files",
      target_table = "project_report_supporting_docs",
      target_id = paste(as.character(out$id), collapse = ","),
      detail = list(project_id = project_id, report_id = report_id, submission_type = submission_type, files = as.character(out$original_filename)),
      workspace_id = project_id,
      trigger_sync = FALSE
    ), silent = TRUE)
    out
  }, error = function(e) {
    stale <- copied_paths[nzchar(copied_paths) & file_exists(copied_paths)]
    if (length(stale) > 0) try(file_delete(stale), silent = TRUE)
    stop(e$message)
  })
}

load_project_report_supporting_docs <- function(project_id = NULL, report_id = NULL, include_trashed = FALSE) {
  con <- connect_db(); on.exit(dbDisconnect(con), add = TRUE)
  ensure_project_report_supporting_docs_schema(con)
  where <- character()
  params <- list()
  project_id <- as.character(project_id %||% "")
  report_id <- as.character(report_id %||% "")
  if (nzchar(project_id)) {
    where <- c(where, "project_id = ?")
    params <- c(params, list(project_id))
  }
  if (nzchar(report_id)) {
    where <- c(where, "report_id = ?")
    params <- c(params, list(report_id))
  }
  if (!isTRUE(include_trashed)) {
    where <- c(where, "COALESCE(is_trashed,0) = 0")
  }
  sql <- "SELECT * FROM project_report_supporting_docs"
  if (length(where) > 0) {
    sql <- paste(sql, "WHERE", paste(where, collapse = " AND "))
  }
  sql <- paste0(sql, " ORDER BY COALESCE(is_trashed,0), updated_at DESC, created_at DESC, original_filename;")
  if (length(params) > 0) {
    dbGetQuery(con, sql, params = params)
  } else {
    dbGetQuery(con, sql)
  }
}

