restore_project_report_supporting_doc <- function(doc_id) {
  doc <- get_project_report_supporting_doc_by_id(doc_id, include_trashed = TRUE)
  if (nrow(doc) != 1) return(FALSE)
  isTRUE(restore_file_manager_items(
    paste0("doc::", as.character(doc_id)),
    acting_user = "Administrator",
    acting_role = "Administrator"
  ))
}

file_preview_data_uri <- function(path, mime_type = "application/octet-stream") {
  path <- as.character(path %||% "")
  if (!nzchar(path) || !file_exists(path)) stop("Preview file could not be found.")
  file_size <- safe_file_size(path)
  if (file_size > inline_preview_max_bytes) {
    stop(sprintf(
      "Inline preview is limited to files up to %s on this server.",
      format_file_size_text(inline_preview_max_bytes)
    ))
  }
  raw_bytes <- readBin(path, what = "raw", n = as.integer(file_size))
  paste0("data:", mime_type, ";base64,", jsonlite::base64_enc(raw_bytes))
}

extract_xml_plain_text <- function(lines) {
  text <- paste(lines, collapse = " ")
  text <- gsub("</w:p>|</a:p>", "\n", text, ignore.case = TRUE)
  text <- gsub("<[^>]+>", " ", text)
  text <- gsub("&amp;", "&", text, fixed = TRUE)
  text <- gsub("&lt;", "<", text, fixed = TRUE)
  text <- gsub("&gt;", ">", text, fixed = TRUE)
  text <- gsub("[ \t]+", " ", text)
  text <- gsub("\n\\s+", "\n", text)
  trimws(text)
}

extract_docx_preview_text <- function(path) {
  listing <- tryCatch(unzip(path, list = TRUE), error = function(e) data.frame())
  if (nrow(listing) == 0 || !("Name" %in% names(listing)) || !("word/document.xml" %in% listing$Name)) return("")
  con <- unz(path, "word/document.xml", open = "rb")
  on.exit(try(close(con), silent = TRUE), add = TRUE)
  extract_xml_plain_text(readLines(con, warn = FALSE, encoding = "UTF-8"))
}

extract_pptx_preview_text <- function(path) {
  listing <- tryCatch(unzip(path, list = TRUE), error = function(e) data.frame())
  if (nrow(listing) == 0 || !("Name" %in% names(listing))) return("")
  slide_names <- grep("^ppt/slides/slide[0-9]+\\.xml$", listing$Name, value = TRUE)
  if (length(slide_names) == 0) return("")
  slide_text <- vapply(slide_names, function(name) {
    con <- unz(path, name, open = "rb")
    on.exit(try(close(con), silent = TRUE), add = TRUE)
    paste0("Slide ", gsub("^ppt/slides/slide|\\.xml$", "", name), "\n", extract_xml_plain_text(readLines(con, warn = FALSE, encoding = "UTF-8")))
  }, character(1))
  paste(slide_text[nzchar(trimws(slide_text))], collapse = "\n\n")
}

project_supporting_doc_preview_content <- function(doc_row) {
  path <- as.character(doc_row$filepath[[1]] %||% "")
  ext <- tolower(as.character(doc_row$file_ext[[1]] %||% fs::path_ext(path)))
  mime_type <- as.character(doc_row$mime_type[[1]] %||% guess_email_attachment_content_type(path))
  file_size <- safe_file_size(path)
  if (!nzchar(path) || !file_exists(path)) {
    return(tags$div(class = "alert alert-warning", "The stored file could not be found on disk."))
  }
  preview_size_notice <- function(limit_bytes, label = "inline preview") {
    tags$div(
      class = "alert alert-info",
      paste0(
        "This file is ",
        format_file_size_text(file_size),
        ". For server stability, ",
        label,
        " is limited to files up to ",
        format_file_size_text(limit_bytes),
        ". Use Download to open the full file."
      )
    )
  }
  if (identical(ext, "pdf")) {
    if (file_size > inline_preview_max_bytes) return(preview_size_notice(inline_preview_max_bytes))
    return(tags$iframe(src = file_preview_data_uri(path, if (nzchar(mime_type)) mime_type else "application/pdf"), style = "width:100%; height:75vh; border:1px solid #dbe7f3; border-radius:8px;"))
  }
  if (ext %in% c("png", "jpg", "jpeg", "gif", "webp")) {
    if (file_size > inline_preview_max_bytes) return(preview_size_notice(inline_preview_max_bytes))
    return(tags$img(src = file_preview_data_uri(path, if (nzchar(mime_type)) mime_type else paste0("image/", ext)), style = "max-width:100%; max-height:75vh; display:block; margin:0 auto; border-radius:8px;"))
  }
  if (ext %in% c("txt", "csv", "log", "md")) {
    lines <- tryCatch(readLines(path, warn = FALSE, encoding = "UTF-8", n = 400), error = function(e) character())
    return(tags$pre(style = "white-space:pre-wrap; max-height:75vh; overflow:auto; background:#f8fafc; padding:16px; border:1px solid #dbe7f3; border-radius:8px;", paste(lines, collapse = "\n")))
  }
  if (ext %in% c("xlsx", "xls")) {
    if (file_size > structured_preview_extract_max_bytes) return(preview_size_notice(structured_preview_extract_max_bytes, label = "spreadsheet preview"))
    preview_df <- tryCatch(openxlsx::read.xlsx(path, sheet = 1, rows = 1:50, detectDates = TRUE), error = function(e) data.frame(`Preview` = paste("Preview unavailable:", e$message), check.names = FALSE))
    if (nrow(preview_df) == 0 && ncol(preview_df) == 0) preview_df <- data.frame(Message = "The spreadsheet is empty.", check.names = FALSE)
    return(tagList(
      tags$div(class = "settings-hint", "Showing up to the first 50 rows from the first worksheet."),
      tags$div(
        style = "max-height:75vh; overflow:auto; border:1px solid #dbe7f3; border-radius:8px;",
        tags$table(
          class = "table table-bordered table-striped",
          tags$thead(tags$tr(lapply(names(preview_df), tags$th))),
          tags$tbody(lapply(seq_len(nrow(preview_df)), function(i) {
            tags$tr(lapply(preview_df[i, , drop = FALSE], function(value) tags$td(as.character(value %||% ""))))
          }))
        )
      )
    ))
  }
  if (identical(ext, "docx")) {
    if (file_size > structured_preview_extract_max_bytes) return(preview_size_notice(structured_preview_extract_max_bytes, label = "document preview"))
    text <- extract_docx_preview_text(path)
    if (!nzchar(text)) text <- "Readable preview is unavailable for this Word document. Use Download to open the full file."
    return(tags$pre(style = "white-space:pre-wrap; max-height:75vh; overflow:auto; background:#f8fafc; padding:16px; border:1px solid #dbe7f3; border-radius:8px;", text))
  }
  if (identical(ext, "pptx")) {
    if (file_size > structured_preview_extract_max_bytes) return(preview_size_notice(structured_preview_extract_max_bytes, label = "PowerPoint preview"))
    text <- extract_pptx_preview_text(path)
    if (!nzchar(text)) text <- "Direct slide rendering is unavailable in this environment. Use Download to open the PowerPoint file."
    return(tags$pre(style = "white-space:pre-wrap; max-height:75vh; overflow:auto; background:#f8fafc; padding:16px; border:1px solid #dbe7f3; border-radius:8px;", text))
  }
  if (ext %in% c("doc", "ppt")) {
    return(tags$div(class = "alert alert-info", paste0("A direct in-app preview is not available for .", ext, " files in this environment. Use Download to open the file.")))
  }
  tags$div(class = "alert alert-info", "No in-app preview is available for this file type. Use Download to open the file.")
}

