archive_item_location_label <- function(file_location = "active", is_trashed = 0L, archive_group_name = "", deleted_from_location = "") {
  is_deleted <- suppressWarnings(as.integer(is_trashed %||% 0L)) == 1L
  file_location <- normalize_file_location(file_location)
  if (is_deleted) {
    origin <- trimws(as.character(deleted_from_location %||% ""))
    if (identical(origin, "archive") && nzchar(trimws(as.character(archive_group_name %||% "")))) {
      return(paste0("Recycle Bin (from Archive: ", as.character(archive_group_name), ")"))
    }
    if (identical(origin, "archive")) return("Recycle Bin (from Archive)")
    return("Recycle Bin (from Active Files)")
  }
  if (identical(file_location, "archive")) {
    if (nzchar(trimws(as.character(archive_group_name %||% "")))) {
      return(paste0("Archive: ", as.character(archive_group_name)))
    }
    return("Archive")
  }
  "Active Files"
}

load_archive_groups <- function(search_text = "", sort_by = "updated_desc") {
  con <- connect_db(); on.exit(dbDisconnect(con), add = TRUE)
  ensure_archive_schema(con)
  search_text <- trimws(as.character(search_text %||% ""))
  where <- character()
  params <- list()
  if (nzchar(search_text)) {
    where <- c(where, "LOWER(name) LIKE ?")
    params <- c(params, list(paste0("%", tolower(search_text), "%")))
  }
  sql <- "
    SELECT
      g.*,
      COALESCE(r.report_count, 0) + COALESCE(d.doc_count, 0) AS file_count
    FROM archive_groups g
    LEFT JOIN (
      SELECT archive_group_id, COUNT(*) AS report_count
      FROM project_reports
      WHERE LOWER(COALESCE(file_location, 'active')) = 'archive' AND COALESCE(is_trashed,0) = 0
      GROUP BY archive_group_id
    ) r ON r.archive_group_id = g.id
    LEFT JOIN (
      SELECT archive_group_id, COUNT(*) AS doc_count
      FROM project_report_supporting_docs
      WHERE LOWER(COALESCE(file_location, 'active')) = 'archive' AND COALESCE(is_trashed,0) = 0
      GROUP BY archive_group_id
    ) d ON d.archive_group_id = g.id
  "
  if (length(where) > 0) sql <- paste(sql, "WHERE", paste(where, collapse = " AND "))
  order_sql <- switch(
    as.character(sort_by %||% "updated_desc"),
    name_asc = "ORDER BY LOWER(name) ASC, updated_at DESC",
    name_desc = "ORDER BY LOWER(name) DESC, updated_at DESC",
    count_desc = "ORDER BY file_count DESC, LOWER(name) ASC",
    count_asc = "ORDER BY file_count ASC, LOWER(name) ASC",
    "ORDER BY updated_at DESC, LOWER(name) ASC"
  )
  sql <- paste(sql, order_sql, ";")
  out <- if (length(params) > 0) dbGetQuery(con, sql, params = params) else dbGetQuery(con, sql)
  if (!is.data.frame(out) || nrow(out) == 0) {
    return(data.frame(
      id = character(),
      name = character(),
      description = character(),
      created_at = character(),
      updated_at = character(),
      created_by = character(),
      created_by_role = character(),
      file_count = integer(),
      stringsAsFactors = FALSE
    ))
  }
  if (!("file_count" %in% names(out))) out$file_count <- integer(nrow(out))
  out$file_count <- suppressWarnings(as.integer(out$file_count %||% integer(nrow(out))))
  out
}

