}

create_archive_group <- function(name, description = "", created_by = "Administrator", created_by_role = "Administrator") {
  tryCatch({
    group_name <- trimws(as.character(name %||% ""))
    if (!nzchar(group_name)) stop("Archive Group name is required.")
    description <- trimws(as.character(description %||% ""))
    con <- connect_db(); on.exit(dbDisconnect(con), add = TRUE)
    ensure_archive_schema(con)
    existing <- dbGetQuery(con, "SELECT id FROM archive_groups WHERE LOWER(name) = LOWER(?) LIMIT 1;", params = list(group_name))
    if (nrow(existing) > 0) stop("Archive Group name already exists.")
    rec <- data.frame(
      id = uuid("archgrp"),
      name = group_name,
      description = description,
      created_at = now(),
      updated_at = now(),
      created_by = as.character(created_by %||% "Administrator"),
      created_by_role = as.character(created_by_role %||% "Administrator"),
      stringsAsFactors = FALSE
    )
    dbWriteTable(con, "archive_groups", rec, append = TRUE, row.names = FALSE)
    try(log_audit(
      module = "File Manager",
      action = "create_archive_group",
      target_table = "archive_groups",
      target_id = rec$id,
      detail = list(group_name = rec$name, created_by = rec$created_by),
      workspace_id = NA_character_,
      trigger_sync = FALSE
    ), silent = TRUE)
    rec
  }, error = function(e) {
    attr(FALSE, "error") <- as.character(e$message %||% "Failed to create Archive Group.")
    FALSE
  })
}

rename_archive_group <- function(archive_group_id, new_name, acting_user = "Administrator", acting_role = "Administrator") {
  tryCatch({
    archive_group_id <- as.character(archive_group_id %||% "")
    group_name <- trimws(as.character(new_name %||% ""))
    if (!nzchar(archive_group_id)) stop("Select an Archive Group first.")
    if (!nzchar(group_name)) stop("Archive Group name is required.")
    con <- connect_db(); on.exit(dbDisconnect(con), add = TRUE)
    ensure_archive_schema(con)
    ensure_project_reports_schema(con)
    ensure_project_report_supporting_docs_schema(con)
    group_row <- dbGetQuery(con, "SELECT * FROM archive_groups WHERE id = ? LIMIT 1;", params = list(archive_group_id))
    if (nrow(group_row) != 1) stop("Archive Group not found.")
    existing <- dbGetQuery(con, "SELECT id FROM archive_groups WHERE LOWER(name) = LOWER(?) AND id <> ? LIMIT 1;", params = list(group_name, archive_group_id))
    if (nrow(existing) > 0) stop("Archive Group name already exists.")
    dbBegin(con)
    committed <- FALSE
    on.exit(if (!committed) try(dbRollback(con), silent = TRUE), add = TRUE)
    dbExecute(con, "UPDATE archive_groups SET name = ?, updated_at = ? WHERE id = ?;", params = list(group_name, now(), archive_group_id))
    dbExecute(con, "UPDATE project_reports SET archive_group_name = ?, updated_at = ? WHERE archive_group_id = ?;", params = list(group_name, now(), archive_group_id))
    dbExecute(con, "UPDATE project_report_supporting_docs SET archive_group_name = ?, updated_at = ? WHERE archive_group_id = ?;", params = list(group_name, now(), archive_group_id))
    dbExecute(con, "UPDATE project_reports SET deleted_from_archive_group_name = ?, updated_at = ? WHERE deleted_from_archive_group_id = ?;", params = list(group_name, now(), archive_group_id))
    dbExecute(con, "UPDATE project_report_supporting_docs SET deleted_from_archive_group_name = ?, updated_at = ? WHERE deleted_from_archive_group_id = ?;", params = list(group_name, now(), archive_group_id))
    dbCommit(con)
    committed <- TRUE
    try(log_audit(
      user = as.character(acting_user %||% "Administrator"),
      module = "File Manager",
      action = "rename_archive_group",
      target_table = "archive_groups",
      target_id = archive_group_id,
      detail = list(group_name = group_name, acting_role = acting_role),
      workspace_id = NA_character_,
      trigger_sync = FALSE
    ), silent = TRUE)
    TRUE
  }, error = function(e) {
    attr(FALSE, "error") <- as.character(e$message %||% "Failed to rename Archive Group.")
    FALSE
  })
}

delete_archive_group_if_empty <- function(archive_group_id, acting_user = "Administrator", acting_role = "Administrator") {
  tryCatch({
    archive_group_id <- as.character(archive_group_id %||% "")
    if (!nzchar(archive_group_id)) stop("Select an Archive Group first.")
    con <- connect_db(); on.exit(dbDisconnect(con), add = TRUE)
    ensure_archive_schema(con)
    count_row <- dbGetQuery(con, "
      SELECT
        COALESCE(r.report_count, 0) + COALESCE(d.doc_count, 0) AS file_count,
        COALESCE(rr.recycle_report_count, 0) + COALESCE(rd.recycle_doc_count, 0) AS recycle_file_count
      FROM archive_groups g
      LEFT JOIN (
        SELECT archive_group_id, COUNT(*) AS report_count
        FROM project_reports
        WHERE archive_group_id = ? AND LOWER(COALESCE(file_location, 'active')) = 'archive' AND COALESCE(is_trashed,0) = 0
      ) r ON 1 = 1
      LEFT JOIN (
        SELECT archive_group_id, COUNT(*) AS doc_count
        FROM project_report_supporting_docs
        WHERE archive_group_id = ? AND LOWER(COALESCE(file_location, 'active')) = 'archive' AND COALESCE(is_trashed,0) = 0
      ) d ON 1 = 1
      LEFT JOIN (
        SELECT deleted_from_archive_group_id, COUNT(*) AS recycle_report_count
        FROM project_reports
        WHERE deleted_from_archive_group_id = ? AND LOWER(COALESCE(deleted_from_location, '')) = 'archive' AND COALESCE(is_trashed,0) = 1
      ) rr ON 1 = 1
      LEFT JOIN (
        SELECT deleted_from_archive_group_id, COUNT(*) AS recycle_doc_count
        FROM project_report_supporting_docs
        WHERE deleted_from_archive_group_id = ? AND LOWER(COALESCE(deleted_from_location, '')) = 'archive' AND COALESCE(is_trashed,0) = 1
      ) rd ON 1 = 1
      WHERE g.id = ?
      LIMIT 1;
    ", params = list(archive_group_id, archive_group_id, archive_group_id, archive_group_id, archive_group_id))
    if (nrow(count_row) != 1) stop("Archive Group not found.")
    if (suppressWarnings(as.integer(count_row$file_count[[1]] %||% 0L)) > 0L) {
      stop("Archive Group is not empty and cannot be deleted.")
    }
    if (suppressWarnings(as.integer(count_row$recycle_file_count[[1]] %||% 0L)) > 0L) {
      stop("Archive Group still has deleted files in the Recycle Bin. Restore or permanently delete those files before deleting this Archive Group.")
    }
    group_row <- dbGetQuery(con, "SELECT * FROM archive_groups WHERE id = ? LIMIT 1;", params = list(archive_group_id))
    dbExecute(con, "DELETE FROM archive_groups WHERE id = ?;", params = list(archive_group_id))
    try(log_audit(
      user = as.character(acting_user %||% "Administrator"),
      module = "File Manager",
      action = "delete_archive_group",
      target_table = "archive_groups",
      target_id = archive_group_id,
      detail = list(group_name = as.character(group_row$name[[1]] %||% ""), acting_role = acting_role),
      workspace_id = NA_character_,
      trigger_sync = FALSE
    ), silent = TRUE)
    TRUE
  }, error = function(e) {
    attr(FALSE, "error") <- as.character(e$message %||% "Failed to delete Archive Group.")
    FALSE
  })
}

upsert_archive_groups_restore <- function(con, archive_groups_restore) {
  ensure_archive_schema(con)
  if (is.null(archive_groups_restore) || !is.data.frame(archive_groups_restore) || nrow(archive_groups_restore) == 0) return(invisible(TRUE))
  archive_groups_restore <- align_restore_table(con, "archive_groups", archive_groups_restore)
  for (i in seq_len(nrow(archive_groups_restore))) {
    row <- archive_groups_restore[i, , drop = FALSE]
    group_id <- as.character(row$id[[1]] %||% "")
    group_name <- trimws(as.character(row$name[[1]] %||% ""))
    if (!nzchar(group_id) || !nzchar(group_name)) next
    existing_by_id <- dbGetQuery(con, "SELECT id FROM archive_groups WHERE id = ? LIMIT 1;", params = list(group_id))
    existing_by_name <- dbGetQuery(con, "SELECT id FROM archive_groups WHERE LOWER(name) = LOWER(?) LIMIT 1;", params = list(group_name))
    if (nrow(existing_by_id) == 1) {
      dbExecute(con, "UPDATE archive_groups SET name = ?, description = ?, updated_at = ?, created_at = ?, created_by = ?, created_by_role = ? WHERE id = ?;",
        params = list(
          group_name,
          as.character(row$description[[1]] %||% ""),
          as.character(row$updated_at[[1]] %||% now()),
          as.character(row$created_at[[1]] %||% now()),
          as.character(row$created_by[[1]] %||% "Administrator"),
          as.character(row$created_by_role[[1]] %||% "Administrator"),
          group_id
        )
      )
    } else if (nrow(existing_by_name) == 1) {
      dbExecute(con, "UPDATE archive_groups SET id = ?, description = ?, updated_at = ?, created_at = ?, created_by = ?, created_by_role = ? WHERE id = ?;",
        params = list(
          group_id,
          as.character(row$description[[1]] %||% ""),
          as.character(row$updated_at[[1]] %||% now()),
          as.character(row$created_at[[1]] %||% now()),
          as.character(row$created_by[[1]] %||% "Administrator"),
          as.character(row$created_by_role[[1]] %||% "Administrator"),
          as.character(existing_by_name$id[[1]] %||% "")
        )
      )
    } else {
      dbWriteTable(con, "archive_groups", row, append = TRUE, row.names = FALSE)
    }
  }
  invisible(TRUE)
}

load_file_manager_registry <- function(project_id = NULL, include_trashed = TRUE, include_archived = TRUE) {
  con <- connect_db(); on.exit(dbDisconnect(con), add = TRUE)
  ensure_project_reports_schema(con)
  ensure_project_report_supporting_docs_schema(con)
  ensure_archive_schema(con)
  project_id <- as.character(project_id %||% "")

  report_where <- c("r.status IN ('draft','submitted')")
  report_params <- list()
  if (nzchar(project_id)) {
    report_where <- c(report_where, "r.project_id = ?")
    report_params <- c(report_params, list(project_id))
  }
  if (!isTRUE(include_trashed)) {
    report_where <- c(report_where, "COALESCE(r.is_trashed,0) = 0")
  }
  if (!isTRUE(include_archived)) {
    report_where <- c(report_where, "LOWER(COALESCE(r.file_location,'active')) <> 'archive'")
  }
  report_sql <- paste0(
    "SELECT r.*, COALESCE(NULLIF(r.project_title,''), p.name, '') AS project_title_resolved, ",
    "COALESCE(NULLIF(r.principal_investigator,''), p.principal_investigator, '') AS principal_investigator_resolved ",
    "FROM project_reports r LEFT JOIN projects p ON p.id = r.project_id ",
    "WHERE ", paste(report_where, collapse = " AND "),
    " ORDER BY COALESCE(r.is_trashed,0), r.updated_at DESC;"
  )
  report_rows <- if (length(report_params) > 0) dbGetQuery(con, report_sql, params = report_params) else dbGetQuery(con, report_sql)

  doc_where <- character()
  doc_params <- list()
  if (nzchar(project_id)) {
    doc_where <- c(doc_where, "d.project_id = ?")
    doc_params <- c(doc_params, list(project_id))
  }
  if (!isTRUE(include_trashed)) {
    doc_where <- c(doc_where, "COALESCE(d.is_trashed,0) = 0")
  }
  if (!isTRUE(include_archived)) {
    doc_where <- c(doc_where, "LOWER(COALESCE(d.file_location,'active')) <> 'archive'")
  }
  doc_sql <- paste0(
    "SELECT d.*, COALESCE(p.name, '') AS project_title_resolved, COALESCE(p.principal_investigator, '') AS principal_investigator_resolved ",
    "FROM project_report_supporting_docs d LEFT JOIN projects p ON p.id = d.project_id ",
    if (length(doc_where) > 0) paste0("WHERE ", paste(doc_where, collapse = " AND ")) else "",
    " ORDER BY COALESCE(d.is_trashed,0), d.updated_at DESC, d.created_at DESC;"
  )
  doc_rows <- if (length(doc_params) > 0) dbGetQuery(con, doc_sql, params = doc_params) else dbGetQuery(con, doc_sql)

  out <- data.frame()

  if (is.data.frame(report_rows) && nrow(report_rows) > 0) {
    report_rows$project_title_resolved <- as.character(report_rows$project_title_resolved %||% "")
    report_rows$principal_investigator_resolved <- as.character(report_rows$principal_investigator_resolved %||% "")
    report_df <- do.call(rbind, lapply(seq_len(nrow(report_rows)), function(i) {
      row <- report_rows[i, , drop = FALSE]
      file_path <- as.character(row$docx_path[[1]] %||% "")
      stored_name <- if (nzchar(file_path)) basename(file_path) else paste0(as.character(row$id[[1]] %||% ""), ".docx")
      prepared_by <- trimws(as.character(row$prepared_by[[1]] %||% ""))
      data.frame(
        file_key = paste0("report::", as.character(row$id[[1]] %||% "")),
        source_type = "report",
        source_table = "project_reports",
        source_id = as.character(row$id[[1]] %||% ""),
        project_id = as.character(row$project_id[[1]] %||% ""),
        project_code = as.character(row$project_code[[1]] %||% row$project_id[[1]] %||% ""),
        project_title = as.character(row$project_title_resolved[[1]] %||% row$project_title[[1]] %||% ""),
        principal_investigator = as.character(row$principal_investigator_resolved[[1]] %||% row$principal_investigator[[1]] %||% ""),
        display_name = project_report_display_name(row),
        original_filename = project_report_docx_filename(row),
        stored_filename = stored_name,
        file_ext = "docx",
        mime_type = "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
        file_path = file_path,
        size = safe_file_size(file_path),
        upload_date = as.character(row$created_at[[1]] %||% ""),
        uploaded_by_role = "Report Submission",
        uploaded_by_name = prepared_by,
        uploaded_by = if (nzchar(prepared_by)) paste0("Report Submission | ", prepared_by) else "Report Submission",
        last_modified = as.character(row$updated_at[[1]] %||% ""),
        submission_type = "structured_report",
        report_link = as.character(row$id[[1]] %||% ""),
        status = as.character(row$status[[1]] %||% ""),
        is_trashed = suppressWarnings(as.integer(row$is_trashed[[1]] %||% 0L)),
        deleted_at = as.character(row$submitted_at[[1]] %||% ""),
        file_location = normalize_file_location(row$file_location[[1]] %||% "active"),
        archive_group_id = as.character(row$archive_group_id[[1]] %||% ""),
        archive_group_name = as.character(row$archive_group_name[[1]] %||% ""),
        archived_at = as.character(row$archived_at[[1]] %||% ""),
        archived_by = as.character(row$archived_by[[1]] %||% ""),
        archived_by_role = as.character(row$archived_by_role[[1]] %||% ""),
        deleted_from_location = as.character(row$deleted_from_location[[1]] %||% ""),
        deleted_from_archive_group_id = as.character(row$deleted_from_archive_group_id[[1]] %||% ""),
        deleted_from_archive_group_name = as.character(row$deleted_from_archive_group_name[[1]] %||% ""),
        stringsAsFactors = FALSE
      )
    }))
    out <- rbind(out, report_df)
  }

  if (is.data.frame(doc_rows) && nrow(doc_rows) > 0) {
    doc_rows$project_title_resolved <- as.character(doc_rows$project_title_resolved %||% "")
    doc_rows$principal_investigator_resolved <- as.character(doc_rows$principal_investigator_resolved %||% "")
    doc_df <- do.call(rbind, lapply(seq_len(nrow(doc_rows)), function(i) {
      row <- doc_rows[i, , drop = FALSE]
      ext <- tolower(as.character(row$file_ext[[1]] %||% fs::path_ext(as.character(row$original_filename[[1]] %||% row$stored_filename[[1]] %||% ""))))
      uploaded_by_name <- trimws(as.character(row$uploaded_by_name[[1]] %||% ""))
      uploaded_by_role <- trimws(as.character(row$uploaded_by_role[[1]] %||% "Public Submitter"))
      data.frame(
        file_key = paste0("doc::", as.character(row$id[[1]] %||% "")),
        source_type = "supporting_doc",
        source_table = "project_report_supporting_docs",
        source_id = as.character(row$id[[1]] %||% ""),
        project_id = as.character(row$project_id[[1]] %||% ""),
        project_code = as.character(row$project_code[[1]] %||% row$project_id[[1]] %||% ""),
        project_title = as.character(row$project_title_resolved[[1]] %||% ""),
        principal_investigator = as.character(row$principal_investigator_resolved[[1]] %||% ""),
        display_name = project_report_supporting_doc_display_name(row),
        original_filename = as.character(row$original_filename[[1]] %||% row$stored_filename[[1]] %||% ""),
        stored_filename = as.character(row$stored_filename[[1]] %||% basename(as.character(row$filepath[[1]] %||% ""))),
        file_ext = ext,
        mime_type = as.character(row$mime_type[[1]] %||% ""),
        file_path = as.character(row$filepath[[1]] %||% ""),
        size = suppressWarnings(as.numeric(row$size[[1]] %||% safe_file_size(as.character(row$filepath[[1]] %||% "")))),
        upload_date = as.character(row$created_at[[1]] %||% ""),
        uploaded_by_role = uploaded_by_role,
        uploaded_by_name = uploaded_by_name,
        uploaded_by = if (nzchar(uploaded_by_name)) paste0(uploaded_by_role, " | ", uploaded_by_name) else uploaded_by_role,
        last_modified = as.character(row$updated_at[[1]] %||% ""),
        submission_type = as.character(row$submission_type[[1]] %||% ""),
        report_link = as.character(row$report_id[[1]] %||% ""),
        status = as.character(row$status[[1]] %||% "active"),
        is_trashed = suppressWarnings(as.integer(row$is_trashed[[1]] %||% 0L)),
        deleted_at = as.character(row$deleted_at[[1]] %||% ""),
        file_location = normalize_file_location(row$file_location[[1]] %||% "active"),
        archive_group_id = as.character(row$archive_group_id[[1]] %||% ""),
        archive_group_name = as.character(row$archive_group_name[[1]] %||% ""),
        archived_at = as.character(row$archived_at[[1]] %||% ""),
        archived_by = as.character(row$archived_by[[1]] %||% ""),
        archived_by_role = as.character(row$archived_by_role[[1]] %||% ""),
        deleted_from_location = as.character(row$deleted_from_location[[1]] %||% ""),
        deleted_from_archive_group_id = as.character(row$deleted_from_archive_group_id[[1]] %||% ""),
        deleted_from_archive_group_name = as.character(row$deleted_from_archive_group_name[[1]] %||% ""),
        stringsAsFactors = FALSE
      )
    }))
    out <- rbind(out, doc_df)
  }

  if (!is.data.frame(out) || nrow(out) == 0) return(data.frame())
  out$size_label <- vapply(out$size %||% 0, format_file_size_text, character(1))
  out$source_label <- vapply(seq_len(nrow(out)), function(i) archive_item_source_label(out$source_type[[i]], out$submission_type[[i]]), character(1))
  out$location_label <- vapply(seq_len(nrow(out)), function(i) {
    archive_item_location_label(
      file_location = out$file_location[[i]],
      is_trashed = out$is_trashed[[i]],
      archive_group_name = out$archive_group_name[[i]],
      deleted_from_location = out$deleted_from_location[[i]]
    )
  }, character(1))
  out
}

get_file_manager_item_by_key <- function(file_key, include_trashed = TRUE) {
  file_key <- as.character(file_key %||% "")
  if (!nzchar(file_key)) return(data.frame())
  item <- load_file_manager_registry(include_trashed = include_trashed, include_archived = TRUE)
  if (!is.data.frame(item) || nrow(item) == 0) return(data.frame())
  item[item$file_key == file_key, , drop = FALSE]
}

file_manager_item_download_name <- function(item_row) {
  if (is.null(item_row) || !is.data.frame(item_row) || nrow(item_row) != 1) return("project_file")
  if (identical(as.character(item_row$source_type[[1]] %||% ""), "report")) {
    return(as.character(item_row$original_filename[[1]] %||% "RPT--project_report.docx"))
  }
  as.character(item_row$display_name[[1]] %||% item_row$original_filename[[1]] %||% "project_file")
}

file_manager_item_preview_ui <- function(item_row) {
  if (is.null(item_row) || !is.data.frame(item_row) || nrow(item_row) != 1) {
    return(tags$div(class = "alert alert-warning", "The selected file record could not be loaded."))
  }
  if (identical(as.character(item_row$source_type[[1]] %||% ""), "report")) {
    report_row <- get_project_report_by_id(as.character(item_row$source_id[[1]] %||% ""), include_trashed = TRUE)
    if (nrow(report_row) == 1) return(project_report_view_ui(report_row))
    return(tags$div(class = "alert alert-warning", "The report record could not be loaded."))
  }
  doc_row <- get_project_report_supporting_doc_by_id(as.character(item_row$source_id[[1]] %||% ""), include_trashed = TRUE)
  if (nrow(doc_row) == 1) return(project_supporting_doc_preview_ui(doc_row))
  tags$div(class = "alert alert-warning", "The file record could not be loaded.")
}

show_file_manager_item_preview_modal <- function(item_row) {
  if (is.null(item_row) || !is.data.frame(item_row) || nrow(item_row) != 1) return(invisible(FALSE))
  showModal(modalDialog(
    title = paste0("File Preview: ", as.character(item_row$display_name[[1]] %||% item_row$original_filename[[1]] %||% "Project File")),
    size = "l",
    easyClose = TRUE,
    file_manager_item_preview_ui(item_row),
    footer = tagList(
      downloadButton("download_file_manager_item", "Download"),
      tags$button(type = "button", class = "btn btn-default", onclick = "window.print();", "Print"),
      modalButton("Close")
    )
  ))
  invisible(TRUE)
}

resolve_archive_group_target <- function(archive_group_id = "", archive_group_name = "", create_if_missing = FALSE, created_by = "Administrator", created_by_role = "Administrator") {
  archive_group_id <- trimws(as.character(archive_group_id %||% ""))
  archive_group_name <- trimws(as.character(archive_group_name %||% ""))
  if (nzchar(archive_group_id)) {
    group_row <- get_archive_group_by_id(archive_group_id)
    if (nrow(group_row) != 1) stop("Selected Archive Group was not found.")
    return(group_row[1, c("id", "name"), drop = FALSE])
  }
  if (!nzchar(archive_group_name)) stop("Archive Group is required.")
  existing <- load_archive_groups(search_text = archive_group_name, sort_by = "name_asc")
  existing <- existing[tolower(as.character(existing$name %||% "")) == tolower(archive_group_name), , drop = FALSE]
  if (nrow(existing) == 1) return(existing[1, c("id", "name"), drop = FALSE])
  if (!isTRUE(create_if_missing)) stop("Archive Group was not found.")
  created <- create_archive_group(archive_group_name, created_by = created_by, created_by_role = created_by_role)
  if (!is.data.frame(created) || nrow(created) != 1) stop(attr(created, "error") %||% "Failed to create Archive Group.")
  created[1, c("id", "name"), drop = FALSE]
}

move_file_manager_items_to_archive <- function(file_keys, archive_group_id = "", archive_group_name = "", create_group = FALSE, acting_user = "Administrator", acting_role = "Administrator") {
  tryCatch({
    file_keys <- unique(as.character(file_keys %||% character()))
    file_keys <- file_keys[nzchar(file_keys)]
    if (length(file_keys) == 0) stop("Select at least one file.")
    target_group <- resolve_archive_group_target(archive_group_id = archive_group_id, archive_group_name = archive_group_name, create_if_missing = create_group, created_by = acting_user, created_by_role = acting_role)
    items <- load_file_manager_registry(include_trashed = TRUE, include_archived = TRUE)
    items <- items[items$file_key %in% file_keys, , drop = FALSE]
    if (nrow(items) == 0) stop("Selected files were not found.")
    items <- items[suppressWarnings(as.integer(items$is_trashed %||% 0L)) == 0L, , drop = FALSE]
    if (nrow(items) == 0) stop("Selected files are already in the Recycle Bin.")
    con <- connect_db(); on.exit(dbDisconnect(con), add = TRUE)
    ensure_project_reports_schema(con)
    ensure_project_report_supporting_docs_schema(con)
    now_value <- now()
    dbBegin(con)
    committed <- FALSE
    on.exit(if (!committed) try(dbRollback(con), silent = TRUE), add = TRUE)
    report_ids <- as.character(items$source_id[items$source_type == "report"] %||% character())
    doc_ids <- as.character(items$source_id[items$source_type == "supporting_doc"] %||% character())
    if (length(report_ids) > 0) {
      sql <- paste0("UPDATE project_reports SET file_location = 'archive', archive_group_id = ?, archive_group_name = ?, archived_at = ?, archived_by = ?, archived_by_role = ?, updated_at = ? WHERE id IN (", paste(rep("?", length(report_ids)), collapse = ", "), ");")
      dbExecute(con, sql, params = c(list(as.character(target_group$id[[1]]), as.character(target_group$name[[1]]), now_value, acting_user, acting_role, now_value), as.list(report_ids)))
    }
    if (length(doc_ids) > 0) {
      sql <- paste0("UPDATE project_report_supporting_docs SET file_location = 'archive', archive_group_id = ?, archive_group_name = ?, archived_at = ?, archived_by = ?, archived_by_role = ?, updated_at = ? WHERE id IN (", paste(rep("?", length(doc_ids)), collapse = ", "), ");")
      dbExecute(con, sql, params = c(list(as.character(target_group$id[[1]]), as.character(target_group$name[[1]]), now_value, acting_user, acting_role, now_value), as.list(doc_ids)))
    }
    dbCommit(con)
    committed <- TRUE
    project_ids <- unique(as.character(items$project_id %||% character()))
    for (project_id in project_ids[nzchar(project_ids)]) try(mark_drive_project_dirty(project_id), silent = TRUE)
    for (i in seq_len(nrow(items))) {
      try(log_audit(
        user = acting_user,
        module = "File Manager",
        action = "archive_file",
        target_table = as.character(items$source_table[[i]] %||% ""),
        target_id = as.character(items$source_id[[i]] %||% ""),
        detail = list(
          project_id = as.character(items$project_id[[i]] %||% ""),
          project_code = as.character(items$project_code[[i]] %||% ""),
          file = as.character(items$display_name[[i]] %||% ""),
          archive_group = as.character(target_group$name[[1]] %||% "")
        ),
        workspace_id = as.character(items$project_id[[i]] %||% ""),
        trigger_sync = FALSE
      ), silent = TRUE)
    }
    TRUE
  }, error = function(e) {
    attr(FALSE, "error") <- as.character(e$message %||% "Failed to archive selected files.")
    FALSE
  })
}

