        target_id = as.character(items$source_id[[i]] %||% ""),
        detail = list(
          project_id = as.character(items$project_id[[i]] %||% ""),
          project_code = as.character(items$project_code[[i]] %||% ""),
          file = as.character(items$display_name[[i]] %||% ""),
