}

soft_delete_file_manager_items <- function(file_keys, acting_user = "Administrator", acting_role = "Administrator") {
  tryCatch({
    file_keys <- unique(as.character(file_keys %||% character()))
    file_keys <- file_keys[nzchar(file_keys)]
    if (length(file_keys) == 0) stop("Select at least one file.")
    items <- load_file_manager_registry(include_trashed = TRUE, include_archived = TRUE)
    items <- items[items$file_key %in% file_keys, , drop = FALSE]
    if (nrow(items) == 0) stop("Selected files were not found.")
    items <- items[suppressWarnings(as.integer(items$is_trashed %||% 0L)) == 0L, , drop = FALSE]
    if (nrow(items) == 0) stop("Selected files are already in the Recycle Bin.")
    con <- connect_db(); on.exit(dbDisconnect(con), add = TRUE)
    ensure_project_reports_schema(con)
    ensure_project_report_supporting_docs_schema(con)
    now_value <- now()
    dbBegin(con)
    committed <- FALSE
    on.exit(if (!committed) try(dbRollback(con), silent = TRUE), add = TRUE)
    report_rows <- items[items$source_type == "report", , drop = FALSE]
    doc_rows <- items[items$source_type == "supporting_doc", , drop = FALSE]
    if (nrow(report_rows) > 0) {
      for (i in seq_len(nrow(report_rows))) {
        row <- report_rows[i, , drop = FALSE]
        dbExecute(con, "
          UPDATE project_reports
          SET is_trashed = 1,
              updated_at = ?,
              file_location = ?,
              deleted_from_location = ?,
              deleted_from_archive_group_id = ?,
              deleted_from_archive_group_name = ?
          WHERE id = ?;
        ", params = list(
          now_value,
          as.character(row$file_location[[1]] %||% "active"),
          if (identical(as.character(row$file_location[[1]] %||% "active"), "archive")) "archive" else "active",
          as.character(row$archive_group_id[[1]] %||% ""),
          as.character(row$archive_group_name[[1]] %||% ""),
          as.character(row$source_id[[1]] %||% "")
        ))
      }
    }
    if (nrow(doc_rows) > 0) {
      for (i in seq_len(nrow(doc_rows))) {
        row <- doc_rows[i, , drop = FALSE]
        dbExecute(con, "
          UPDATE project_report_supporting_docs
          SET is_trashed = 1,
              deleted_at = ?,
              updated_at = ?,
              file_location = ?,
              deleted_from_location = ?,
              deleted_from_archive_group_id = ?,
              deleted_from_archive_group_name = ?
          WHERE id = ?;
        ", params = list(
          now_value,
          now_value,
          as.character(row$file_location[[1]] %||% "active"),
          if (identical(as.character(row$file_location[[1]] %||% "active"), "archive")) "archive" else "active",
          as.character(row$archive_group_id[[1]] %||% ""),
          as.character(row$archive_group_name[[1]] %||% ""),
          as.character(row$source_id[[1]] %||% "")
        ))
      }
    }
    dbCommit(con)
    committed <- TRUE
    project_ids <- unique(as.character(items$project_id %||% character()))
    for (project_id in project_ids[nzchar(project_ids)]) try(mark_drive_project_dirty(project_id), silent = TRUE)
    for (i in seq_len(nrow(items))) {
      try(log_audit(
        user = acting_user,
        module = "File Manager",
        action = "move_to_recycle_bin",
        target_table = as.character(items$source_table[[i]] %||% ""),
        target_id = as.character(items$source_id[[i]] %||% ""),
        detail = list(
          project_id = as.character(items$project_id[[i]] %||% ""),
          project_code = as.character(items$project_code[[i]] %||% ""),
          file = as.character(items$display_name[[i]] %||% ""),
          from_location = as.character(items$file_location[[i]] %||% "active")
        ),
        workspace_id = as.character(items$project_id[[i]] %||% ""),
        trigger_sync = FALSE
      ), silent = TRUE)
    }
    TRUE
  }, error = function(e) {
    attr(FALSE, "error") <- as.character(e$message %||% "Failed to move selected files to the Recycle Bin.")
    FALSE
  })
}

ensure_archive_group_restore_target <- function(con, archive_group_id = "", archive_group_name = "", acting_user = "Administrator", acting_role = "Administrator") {
  ensure_archive_schema(con)
  archive_group_id <- trimws(as.character(archive_group_id %||% ""))
  archive_group_name <- trimws(as.character(archive_group_name %||% ""))
  if (nzchar(archive_group_id)) {
    existing_by_id <- dbGetQuery(con, "SELECT id, name FROM archive_groups WHERE id = ? LIMIT 1;", params = list(archive_group_id))
    if (nrow(existing_by_id) == 1) return(existing_by_id[1, c("id", "name"), drop = FALSE])
  }
  if (nzchar(archive_group_name)) {
    existing_by_name <- dbGetQuery(con, "SELECT id, name FROM archive_groups WHERE LOWER(name) = LOWER(?) LIMIT 1;", params = list(archive_group_name))
    if (nrow(existing_by_name) == 1) return(existing_by_name[1, c("id", "name"), drop = FALSE])
  }
  if (!nzchar(archive_group_name)) stop("The previous Archive Group could not be resolved for restore.")
  restore_row <- data.frame(
    id = if (nzchar(archive_group_id)) archive_group_id else uuid("archgrp"),
    name = archive_group_name,
    description = "Restored automatically for File Manager recovery.",
    created_at = now(),
    updated_at = now(),
    created_by = as.character(acting_user %||% "Administrator"),
    created_by_role = as.character(acting_role %||% "Administrator"),
    stringsAsFactors = FALSE
  )
  dbWriteTable(con, "archive_groups", restore_row, append = TRUE, row.names = FALSE)
  restore_row[, c("id", "name"), drop = FALSE]
}

restore_file_manager_items <- function(file_keys, acting_user = "Administrator", acting_role = "Administrator") {
  tryCatch({
    file_keys <- unique(as.character(file_keys %||% character()))
    file_keys <- file_keys[nzchar(file_keys)]
    if (length(file_keys) == 0) stop("Select at least one file.")
    items <- load_file_manager_registry(include_trashed = TRUE, include_archived = TRUE)
    items <- items[items$file_key %in% file_keys, , drop = FALSE]
    if (nrow(items) == 0) stop("Selected files were not found.")
    items <- items[suppressWarnings(as.integer(items$is_trashed %||% 0L)) == 1L, , drop = FALSE]
    if (nrow(items) == 0) stop("Selected files are not in the Recycle Bin.")
    con <- connect_db(); on.exit(dbDisconnect(con), add = TRUE)
    ensure_project_reports_schema(con)
    ensure_project_report_supporting_docs_schema(con)
    now_value <- now()
    dbBegin(con)
    committed <- FALSE
    on.exit(if (!committed) try(dbRollback(con), silent = TRUE), add = TRUE)
    for (i in seq_len(nrow(items))) {
      row <- items[i, , drop = FALSE]
      restore_location <- if (identical(as.character(row$deleted_from_location[[1]] %||% ""), "archive")) "archive" else "active"
      restore_group_id <- if (identical(restore_location, "archive")) as.character(row$deleted_from_archive_group_id[[1]] %||% row$archive_group_id[[1]] %||% "") else ""
      restore_group_name <- if (identical(restore_location, "archive")) as.character(row$deleted_from_archive_group_name[[1]] %||% row$archive_group_name[[1]] %||% "") else ""
      if (identical(restore_location, "archive")) {
        restore_target <- ensure_archive_group_restore_target(
          con,
          archive_group_id = restore_group_id,
          archive_group_name = restore_group_name,
          acting_user = acting_user,
          acting_role = acting_role
        )
        restore_group_id <- as.character(restore_target$id[[1]] %||% "")
        restore_group_name <- as.character(restore_target$name[[1]] %||% "")
      }
      if (identical(as.character(row$source_type[[1]] %||% ""), "report")) {
        dbExecute(con, "
          UPDATE project_reports
          SET is_trashed = 0,
              updated_at = ?,
              file_location = ?,
              archive_group_id = ?,
              archive_group_name = ?,
              deleted_from_location = '',
              deleted_from_archive_group_id = '',
              deleted_from_archive_group_name = ''
          WHERE id = ?;
        ", params = list(now_value, restore_location, restore_group_id, restore_group_name, as.character(row$source_id[[1]] %||% "")))
      } else {
        dbExecute(con, "
          UPDATE project_report_supporting_docs
          SET is_trashed = 0,
              deleted_at = '',
              updated_at = ?,
              file_location = ?,
              archive_group_id = ?,
              archive_group_name = ?,
              deleted_from_location = '',
              deleted_from_archive_group_id = '',
              deleted_from_archive_group_name = ''
          WHERE id = ?;
        ", params = list(now_value, restore_location, restore_group_id, restore_group_name, as.character(row$source_id[[1]] %||% "")))
      }
    }
    dbCommit(con)
    committed <- TRUE
    project_ids <- unique(as.character(items$project_id %||% character()))
    for (project_id in project_ids[nzchar(project_ids)]) try(mark_drive_project_dirty(project_id), silent = TRUE)
    for (i in seq_len(nrow(items))) {
      try(log_audit(
        user = acting_user,
        module = "File Manager",
        action = "restore_file",
        target_table = as.character(items$source_table[[i]] %||% ""),
        target_id = as.character(items$source_id[[i]] %||% ""),
        detail = list(
          project_id = as.character(items$project_id[[i]] %||% ""),
          project_code = as.character(items$project_code[[i]] %||% ""),
          file = as.character(items$display_name[[i]] %||% ""),
          restore_to = if (identical(as.character(items$deleted_from_location[[i]] %||% ""), "archive")) as.character(items$deleted_from_archive_group_name[[i]] %||% "Archive") else "Active Files"
        ),
        workspace_id = as.character(items$project_id[[i]] %||% ""),
        trigger_sync = FALSE
      ), silent = TRUE)
    }
    TRUE
  }, error = function(e) {
    attr(FALSE, "error") <- as.character(e$message %||% "Failed to restore selected files.")
    FALSE
  })
}

permanently_delete_file_manager_items <- function(file_keys, acting_user = "Administrator", acting_role = "Administrator") {
  tryCatch({
    file_keys <- unique(as.character(file_keys %||% character()))
    file_keys <- file_keys[nzchar(file_keys)]
    if (length(file_keys) == 0) stop("Select at least one file.")
    items <- load_file_manager_registry(include_trashed = TRUE, include_archived = TRUE)
    items <- items[items$file_key %in% file_keys, , drop = FALSE]
    if (nrow(items) == 0) stop("Selected files were not found.")
    con <- connect_db(); on.exit(dbDisconnect(con), add = TRUE)
    ensure_project_reports_schema(con)
    ensure_project_report_supporting_docs_schema(con)
    dbBegin(con)
    committed <- FALSE
    on.exit(if (!committed) try(dbRollback(con), silent = TRUE), add = TRUE)
    for (i in seq_len(nrow(items))) {
      row <- items[i, , drop = FALSE]
      file_path <- as.character(row$file_path[[1]] %||% "")
      if (identical(as.character(row$source_type[[1]] %||% ""), "report")) {
        dbExecute(con, "DELETE FROM project_reports WHERE id = ?;", params = list(as.character(row$source_id[[1]] %||% "")))
      } else {
        dbExecute(con, "DELETE FROM project_report_supporting_docs WHERE id = ?;", params = list(as.character(row$source_id[[1]] %||% "")))
      }
      if (nzchar(file_path) && file_exists(file_path)) delete_files_quietly(file_path)
    }
    dbCommit(con)
    committed <- TRUE
    project_ids <- unique(as.character(items$project_id %||% character()))
    for (project_id in project_ids[nzchar(project_ids)]) try(mark_drive_project_dirty(project_id), silent = TRUE)
    for (i in seq_len(nrow(items))) {
      try(log_audit(
        user = acting_user,
        module = "File Manager",
        action = "permanent_delete_file",
        target_table = as.character(items$source_table[[i]] %||% ""),
        target_id = as.character(items$source_id[[i]] %||% ""),
        detail = list(
          project_id = as.character(items$project_id[[i]] %||% ""),
          project_code = as.character(items$project_code[[i]] %||% ""),
          file = as.character(items$display_name[[i]] %||% ""),
          acting_role = acting_role
        ),
        workspace_id = as.character(items$project_id[[i]] %||% ""),
        trigger_sync = FALSE
      ), silent = TRUE)
    }
    TRUE
  }, error = function(e) {
    attr(FALSE, "error") <- as.character(e$message %||% "Failed to permanently delete selected files.")
    FALSE
  })
}

build_file_manager_zip <- function(items, zip_prefix = "project_files", top_folder = "", group_by_archive = FALSE) {
  if (is.null(items) || !is.data.frame(items) || nrow(items) == 0) stop("No files were selected.")
  items <- items[nzchar(as.character(items$file_path %||% "")) & file_exists(as.character(items$file_path %||% "")), , drop = FALSE]
  if (nrow(items) == 0) stop("No physical files were found for the selected records.")
  stage_dir <- file.path(tempdir(), paste0("file_bundle_", digest::digest(paste(zip_prefix, Sys.time(), Sys.getpid(), nrow(items), sep = "_"))))
  dir_create(stage_dir, recurse = TRUE)
  top_folder_name <- sanitize_filename(as.character(top_folder %||% ""))
  for (i in seq_len(nrow(items))) {
    row <- items[i, , drop = FALSE]
    project_part <- sanitize_filename(as.character(row$project_code[[1]] %||% row$project_id[[1]] %||% "project"))
    file_name <- sanitize_filename(file_manager_item_download_name(row))
    if (!nzchar(file_name)) file_name <- paste0("file_", i)
    source_folder <- if (identical(as.character(row$source_type[[1]] %||% ""), "report")) "reports" else "files"
    rel_parts <- c()
    if (nzchar(top_folder_name)) rel_parts <- c(rel_parts, top_folder_name)
    if (exists("group_by_archive", inherits = FALSE) && isTRUE(group_by_archive)) {
      archive_part <- sanitize_filename(as.character(row$archive_group_name[[1]] %||% ""))
      if (nzchar(archive_part)) rel_parts <- c(rel_parts, archive_part)
    }
    rel_parts <- c(rel_parts, project_part, source_folder, file_name)
    rel_name <- do.call(file.path, as.list(rel_parts))
    dest <- file.path(stage_dir, rel_name)
    dir_create(dirname(dest), recurse = TRUE)
    copy_file_checked(as.character(row$file_path[[1]] %||% ""), dest, overwrite = TRUE)
  }
  zip_path <- file.path(tempdir(), paste0(sanitize_filename(zip_prefix), "_", format(Sys.time(), "%Y%m%d_%H%M%S"), ".zip"))
  zip::zipr(zipfile = zip_path, files = dir_ls(stage_dir, recurse = TRUE, type = "file"), root = stage_dir)
  zip_path
}

log_file_manager_download_action <- function(items, action = "download_file_bundle", acting_user = "Administrator", acting_role = "Administrator", bundle_name = "", archive_group = "") {
  if (is.null(items) || !is.data.frame(items) || nrow(items) == 0) return(invisible(FALSE))
  item_count <- nrow(items)
  project_ids <- unique(as.character(items$project_id %||% character()))
  project_codes <- unique(as.character(items$project_code %||% character()))
  project_titles <- unique(as.character(items$project_title %||% character()))
  workspace_id <- if (length(project_ids[nzchar(project_ids)]) == 1) project_ids[nzchar(project_ids)][[1]] else NA_character_
  target_table <- if (item_count == 1) as.character(items$source_table[[1]] %||% "file_manager") else "file_manager_bundle"
  target_id <- if (item_count == 1) as.character(items$source_id[[1]] %||% "") else as.character(bundle_name %||% action)
  detail <- list(
    acting_role = as.character(acting_role %||% "Administrator"),
    item_count = item_count,
    bundle_name = as.character(bundle_name %||% ""),
    archive_group = as.character(archive_group %||% ""),
    file_names = unique(as.character(head(items$display_name %||% character(), 10))),
    project_codes = project_codes[nzchar(project_codes)],
    project_titles = project_titles[nzchar(project_titles)]
  )
  try(log_audit(
    user = as.character(acting_user %||% "Administrator"),
    module = "File Manager",
    action = as.character(action %||% "download_file_bundle"),
    target_table = target_table,
    target_id = target_id,
    detail = detail,
    workspace_id = workspace_id,
    trigger_sync = FALSE
  ), silent = TRUE)
  invisible(TRUE)
}

write_minimal_docx <- function(output_file, title, sections) {
  dir_create(dirname(output_file), recurse = TRUE)
  stage_dir <- file.path(tempdir(), paste0("docx_stage_", digest::digest(paste(output_file, Sys.time(), Sys.getpid()))))
  dir_create(file.path(stage_dir, "_rels"), recurse = TRUE)
  dir_create(file.path(stage_dir, "word"), recurse = TRUE)
  on.exit(if (dir_exists(stage_dir)) try(dir_delete(stage_dir), silent = TRUE), add = TRUE)

  xml_text <- function(x) {
    x <- as.character(x %||% "")
    x <- gsub("&", "&amp;", x, fixed = TRUE)
    x <- gsub("<", "&lt;", x, fixed = TRUE)
    x <- gsub(">", "&gt;", x, fixed = TRUE)
    x
  }
  paragraph <- function(text, bold = FALSE) {
    text <- xml_text(text)
    rpr <- if (isTRUE(bold)) "<w:rPr><w:b/></w:rPr>" else ""
    paste0("<w:p><w:r>", rpr, "<w:t xml:space=\"preserve\">", text, "</w:t></w:r></w:p>")
  }
  section_paragraphs <- c(paragraph(title, bold = TRUE), paragraph(paste0("Generated: ", now())))
  for (section_name in names(sections)) {
    section_paragraphs <- c(section_paragraphs, paragraph(""), paragraph(section_name, bold = TRUE))
    values <- sections[[section_name]]
    if (length(values) == 0) {
      section_paragraphs <- c(section_paragraphs, paragraph("Not provided"))
    } else {
      for (line in values) section_paragraphs <- c(section_paragraphs, paragraph(line))
    }
  }

  content_types <- '<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/word/document.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml"/></Types>'
  rels <- '<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="word/document.xml"/></Relationships>'
  doc_xml <- paste0(
    '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>',
    '<w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main"><w:body>',
    paste(section_paragraphs, collapse = ""),
    '<w:sectPr><w:pgSz w:w="12240" w:h="15840"/><w:pgMar w:top="1440" w:right="1440" w:bottom="1440" w:left="1440"/></w:sectPr>',
    '</w:body></w:document>'
  )
  writeLines(content_types, file.path(stage_dir, "[Content_Types].xml"), useBytes = TRUE)
  writeLines(rels, file.path(stage_dir, "_rels", ".rels"), useBytes = TRUE)
  writeLines(doc_xml, file.path(stage_dir, "word", "document.xml"), useBytes = TRUE)
  output_file <- normalizePath(output_file, winslash = "/", mustWork = FALSE)
  if (file_exists(output_file)) file_delete(output_file)
  old_wd <- getwd()
  on.exit(setwd(old_wd), add = TRUE)
  setwd(stage_dir)
  zip::zipr(zipfile = output_file, files = c("[Content_Types].xml", "_rels/.rels", "word/document.xml"), mode = "mirror")
  normalizePath(output_file, winslash = "/", mustWork = FALSE)
}

lookup_project_by_code <- function(project_code) {
  code <- trimws(as.character(project_code %||% ""))
  if (!nzchar(code)) return(data.frame())
  con <- connect_db(); on.exit(dbDisconnect(con), add = TRUE)
  try(ensure_projects_schema(con), silent = TRUE)
  dbGetQuery(con, "SELECT * FROM projects WHERE id = ? AND COALESCE(is_trashed,0) = 0 LIMIT 1;", params = list(code))
}

get_project_report_by_id <- function(report_id, include_trashed = FALSE) {
  report_id <- as.character(report_id %||% "")
  if (!nzchar(report_id)) return(data.frame())
  con <- connect_db(); on.exit(dbDisconnect(con), add = TRUE)
  ensure_project_reports_schema(con)
  if (isTRUE(include_trashed)) {
    dbGetQuery(con, "SELECT * FROM project_reports WHERE id = ? LIMIT 1;", params = list(report_id))
  } else {
    dbGetQuery(con, "SELECT * FROM project_reports WHERE id = ? AND COALESCE(is_trashed,0) = 0 LIMIT 1;", params = list(report_id))
  }
}

get_latest_project_report_draft <- function(project_id) {
  project_id <- as.character(project_id %||% "")
  if (!nzchar(project_id)) return(data.frame())
  con <- connect_db(); on.exit(dbDisconnect(con), add = TRUE)
  ensure_project_reports_schema(con)
  dbGetQuery(con, "SELECT * FROM project_reports WHERE project_id = ? AND status = 'draft' AND COALESCE(is_trashed,0) = 0 ORDER BY updated_at DESC LIMIT 1;", params = list(project_id))
}

load_project_reports_for_file_manager <- function(project_id = NULL, include_trashed = FALSE) {
  con <- connect_db(); on.exit(dbDisconnect(con), add = TRUE)
  ensure_project_reports_schema(con)
  project_id <- as.character(project_id %||% "")
  where <- c("status IN ('draft','submitted')")
  params <- list()
  if (nzchar(project_id)) {
    where <- c(where, "project_id = ?")
    params <- c(params, list(project_id))
  }
  if (!isTRUE(include_trashed)) {
    where <- c(where, "COALESCE(is_trashed,0) = 0")
  }
  sql <- paste0("SELECT * FROM project_reports WHERE ", paste(where, collapse = " AND "), " ORDER BY COALESCE(is_trashed,0), updated_at DESC, project_title, project_code;")
  if (length(params) > 0) {
    dbGetQuery(con, sql, params = params)
  } else {
    dbGetQuery(con, sql)
  }
}

soft_delete_project_report <- function(report_id) {
  report <- get_project_report_by_id(report_id, include_trashed = FALSE)
  if (nrow(report) != 1) return(FALSE)
  isTRUE(soft_delete_file_manager_items(
    paste0("report::", as.character(report_id)),
    acting_user = "Administrator",
    acting_role = "Administrator"
  ))
}

restore_project_report <- function(report_id) {
  report <- get_project_report_by_id(report_id, include_trashed = TRUE)
  if (nrow(report) != 1) return(FALSE)
  ok <- isTRUE(restore_file_manager_items(
    paste0("report::", as.character(report_id)),
    acting_user = "Administrator",
    acting_role = "Administrator"
  ))
  if (isTRUE(ok)) {
    try(write_project_report_docx(as.character(report_id)), silent = TRUE)
  }
  ok
}

