project_progress_report_funding_awarded <- "29th May, 2025 (All grants were awarded this date)"

project_report_scalar <- function(report_row, field, default = "") {
  if (is.null(report_row) || nrow(report_row) == 0 || !(field %in% names(report_row))) return(default)
  value <- report_row[[field]][[1]] %||% default
  value <- as.character(value %||% default)
  if (is.na(value)) default else value
}

project_progress_report_as_at_date <- function() {
  value <- tryCatch(get_setting("progress_report_as_at_date") %||% project_progress_report_default_as_at_date, error = function(e) project_progress_report_default_as_at_date)
  value <- trimws(as.character(value %||% project_progress_report_default_as_at_date))
  if (nzchar(value)) value else project_progress_report_default_as_at_date
}

project_progress_report_title <- function(as_at_date = NULL) {
  date_value <- trimws(as.character(as_at_date %||% project_progress_report_as_at_date()))
  if (!nzchar(date_value)) date_value <- project_progress_report_default_as_at_date
  paste(project_progress_report_title_prefix, date_value)
}

  progress_report_workspace_script <- function() {
    tags$script(HTML("
    setTimeout(function() {
      if (window.budgetTrackerEnhanceReportWorkspace) window.budgetTrackerEnhanceReportWorkspace();
    }, 0);
    setTimeout(function() {
      if (window.budgetTrackerEnhanceReportWorkspace) window.budgetTrackerEnhanceReportWorkspace();
    }, 150);
    setTimeout(function() {
      try {
        var modal = document.querySelector('.progress-report-modal');
        if (!modal || modal.dataset.reportCloseBound) return;
        modal.dataset.reportCloseBound = '1';
        if (window.jQuery) {
          window.jQuery(modal).on('hidden.bs.modal', function() {
            if (window.budgetTrackerSetReportSubmissionMode) window.budgetTrackerSetReportSubmissionMode(false);
            if (window.Shiny) Shiny.setInputValue('report_submission_modal_closed', Date.now(), {priority: 'event'});
          });
        }
      } catch (e) {}
    }, 0);
  "))
}

project_report_form_rows <- function(report_row) {
  leader <- project_report_scalar(report_row, "project_team_leader", project_report_scalar(report_row, "principal_investigator", ""))
  members <- project_report_scalar(report_row, "team_members", "")
  grant_code <- project_report_scalar(report_row, "grant_code", project_report_scalar(report_row, "project_code", ""))
  funding_date <- project_report_scalar(report_row, "date_funding_awarded", project_progress_report_funding_awarded)
  if (!nzchar(trimws(funding_date))) funding_date <- project_progress_report_funding_awarded

  list(
    list(number = "", item = "Item", description = c("Description"), header = TRUE),
    list(number = "1", item = "Project team leader", description = c(leader), auto = TRUE),
    list(number = "2", item = "Other project team members", description = c(members), auto = TRUE),
    list(number = "3", item = "Project Title (Final project title as approved by ethical committee)", description = c(project_report_scalar(report_row, "form_project_title", ""))),
    list(number = "4", item = "Project objectives", description = c(project_report_scalar(report_row, "project_objectives", ""))),
    list(number = "", item = "Nature of project (field based only, lab-based only or both)", description = c(project_report_scalar(report_row, "nature_of_project", ""))),
    list(number = "", item = "Date funding awarded", description = c(funding_date), auto = TRUE),
    list(number = "5", item = "Grant code", description = c(grant_code), auto = TRUE),
    list(number = "6", item = "Ethical approval number (if not approved, indicate so and state status and challenges if any)", description = c(project_report_scalar(report_row, "ethical_approval_number", ""))),
    list(number = "7", item = "NACOSTI approval number (if not approved, indicate so and state status and challenges if any)", description = c(project_report_scalar(report_row, "nacosti_approval_number", ""))),
    list(number = "8", item = "Please indicated any other approval provided", description = c(project_report_scalar(report_row, "other_approval_provided", ""))),
    list(number = "9", item = "Date project commenced (if you have not started work, please indicate so and give details on challenges encountered. Also state when you will commence work)", description = c(project_report_scalar(report_row, "date_project_commenced", ""))),
    list(number = "10", item = c("Progress report:", "Indicate activities already done", "Indicate pending activities"), description = c("Indicate activities already done", project_report_scalar(report_row, "progress_activities_done", ""), "Indicate pending activities", project_report_scalar(report_row, "progress_pending_activities", ""))),
    list(number = "11", item = "Completion date (Indicate projected date for completion of the project)", description = c(project_report_scalar(report_row, "completion_date", ""))),
    list(number = "12", item = "Any other comment (are you on track on your project? Are there challenges that may make your project difficult to complete? How can the Director of Research & Product Development help you to complete your research)", description = c(project_report_scalar(report_row, "other_comment", "")))
  )
}

build_project_report_sections <- function(report_row) {
  rows <- project_report_form_rows(report_row)
  body_rows <- rows[!vapply(rows, function(x) isTRUE(x$header), logical(1))]
  section_lines <- unlist(lapply(body_rows, function(row) {
    item <- paste(row$item, collapse = " / ")
    value <- paste(row$description[nzchar(trimws(as.character(row$description)))], collapse = " / ")
    paste0(if (nzchar(row$number)) paste0(row$number, ". ") else "", item, ": ", value)
  }), use.names = FALSE)
  stats::setNames(list(section_lines), project_progress_report_title())
}

write_progress_report_docx <- function(output_file, report_row) {
  dir_create(dirname(output_file), recurse = TRUE)
  stage_dir <- file.path(tempdir(), paste0("docx_stage_", digest::digest(paste(output_file, Sys.time(), Sys.getpid()))))
  dir_create(file.path(stage_dir, "_rels"), recurse = TRUE)
  dir_create(file.path(stage_dir, "word"), recurse = TRUE)
  on.exit(if (dir_exists(stage_dir)) try(dir_delete(stage_dir), silent = TRUE), add = TRUE)

  xml_text <- function(x) {
    x <- as.character(x %||% "")
    x <- gsub("&", "&amp;", x, fixed = TRUE)
    x <- gsub("<", "&lt;", x, fixed = TRUE)
    x <- gsub(">", "&gt;", x, fixed = TRUE)
    x
  }
  paragraph <- function(text, bold = FALSE, align = "left") {
    text <- xml_text(text)
    jc <- if (!identical(align, "left")) paste0('<w:pPr><w:jc w:val="', align, '"/></w:pPr>') else ""
    rpr <- if (isTRUE(bold)) "<w:rPr><w:b/></w:rPr>" else ""
    paste0("<w:p>", jc, "<w:r>", rpr, "<w:t xml:space=\"preserve\">", text, "</w:t></w:r></w:p>")
  }
  cell <- function(lines, bold = FALSE, width = 3000) {
    lines <- as.character(lines %||% "")
    if (length(lines) == 0) lines <- ""
    lines[is.na(lines)] <- ""
    lines <- unlist(strsplit(lines, "\n", fixed = TRUE), use.names = FALSE)
    if (length(lines) == 0) lines <- ""
    paste0(
      '<w:tc><w:tcPr><w:tcW w:w="', width, '" w:type="dxa"/></w:tcPr>',
      paste(vapply(lines, paragraph, character(1), bold = bold), collapse = ""),
      '</w:tc>'
    )
  }
  row_xml <- function(row) {
    is_header <- isTRUE(row$header)
    paste0(
      "<w:tr>",
      cell(row$number, bold = is_header, width = 900),
      cell(row$item, bold = TRUE, width = 4700),
      cell(row$description, bold = is_header, width = 6400),
      "</w:tr>"
    )
  }
  table_xml <- paste0(
    '<w:tbl><w:tblPr><w:tblStyle w:val="TableGrid"/><w:tblW w:w="0" w:type="auto"/><w:tblBorders><w:top w:val="single" w:sz="4" w:space="0" w:color="666666"/><w:left w:val="single" w:sz="4" w:space="0" w:color="666666"/><w:bottom w:val="single" w:sz="4" w:space="0" w:color="666666"/><w:right w:val="single" w:sz="4" w:space="0" w:color="666666"/><w:insideH w:val="single" w:sz="4" w:space="0" w:color="666666"/><w:insideV w:val="single" w:sz="4" w:space="0" w:color="666666"/></w:tblBorders></w:tblPr>',
    paste(vapply(project_report_form_rows(report_row), row_xml, character(1)), collapse = ""),
    '</w:tbl>'
  )

  content_types <- '<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/word/document.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml"/></Types>'
  rels <- '<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="word/document.xml"/></Relationships>'
  doc_xml <- paste0(
    '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>',
    '<w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main"><w:body>',
    paragraph(project_progress_report_title(), bold = TRUE, align = "center"),
    paragraph(paste0("Generated: ", now())),
    table_xml,
    '<w:sectPr><w:pgSz w:w="12240" w:h="15840"/><w:pgMar w:top="1440" w:right="900" w:bottom="1440" w:left="900"/></w:sectPr>',
    '</w:body></w:document>'
  )
  writeLines(content_types, file.path(stage_dir, "[Content_Types].xml"), useBytes = TRUE)
  writeLines(rels, file.path(stage_dir, "_rels", ".rels"), useBytes = TRUE)
  writeLines(doc_xml, file.path(stage_dir, "word", "document.xml"), useBytes = TRUE)
  output_file <- normalizePath(output_file, winslash = "/", mustWork = FALSE)
  if (file_exists(output_file)) file_delete(output_file)
  old_wd <- getwd()
  on.exit(setwd(old_wd), add = TRUE)
  setwd(stage_dir)
  zip::zipr(zipfile = output_file, files = c("[Content_Types].xml", "_rels/.rels", "word/document.xml"), mode = "mirror")
  normalizePath(output_file, winslash = "/", mustWork = FALSE)
}

write_project_report_docx <- function(report_id) {
  report <- get_project_report_by_id(report_id)
  if (nrow(report) != 1) stop("Report record not found.")
  project_id <- as.character(report$project_id[[1]] %||% "")
  if (!nzchar(project_id)) stop("Report has no Project ID.")
  target_dir <- file.path(project_reports_dir, project_id)
  dir_create(target_dir, recurse = TRUE)
  output_file <- file.path(target_dir, project_report_docx_filename(report))
  docx_path <- write_progress_report_docx(output_file, report)
  con <- connect_db(); on.exit(dbDisconnect(con), add = TRUE)
  ensure_project_reports_schema(con)
  dbExecute(con, "UPDATE project_reports SET docx_path = ?, updated_at = ? WHERE id = ?;", params = list(docx_path, now(), report_id))
  docx_path
}

ensure_project_report_docx_file <- function(report_id) {
  report <- get_project_report_by_id(report_id)
  if (nrow(report) != 1) stop("Report record not found.")
  expected_name <- project_report_docx_filename(report)
  path <- as.character(report$docx_path[[1]] %||% "")
  if (!nzchar(path) || !file_exists(path) || !identical(basename(path), expected_name)) {
    path <- write_project_report_docx(as.character(report_id))
  }
  normalizePath(path, winslash = "/", mustWork = FALSE)
}

save_project_report_submission <- function(project_code, status = "draft", values = list(), report_id = NULL) {
  status <- normalize_project_report_status(status)
  project <- lookup_project_by_code(project_code)
  if (nrow(project) != 1) stop("Invalid Project Code. No active project matches the entered code.")
  project_id <- as.character(project$id[[1]])
  report_id <- as.character(report_id %||% "")
  existing <- if (nzchar(report_id)) get_project_report_by_id(report_id) else data.frame()
  if (nrow(existing) == 1 && !identical(as.character(existing$project_id[[1]]), project_id)) stop("Draft does not belong to the entered Project Code.")
  if (nrow(existing) == 1 && identical(as.character(existing$status[[1]]), "submitted")) stop("Submitted reports cannot be edited.")
  if (!nzchar(report_id) || nrow(existing) != 1) report_id <- uuid("prpt")

  pi_value <- trimws(as.character(values$project_team_leader %||% project$principal_investigator[[1]] %||% ""))
  if (!nzchar(pi_value)) pi_value <- as.character(project$principal_investigator[[1]] %||% "")
  team_members_value <- normalize_team_members_text(values$team_members %||% project$team_members[[1]] %||% "")
  grant_code_value <- project_id
  nowt <- now()
  created_at <- if (nrow(existing) == 1 && nzchar(as.character(existing$created_at[[1]] %||% ""))) as.character(existing$created_at[[1]]) else nowt
  submitted_at <- if (identical(status, "submitted")) nowt else if (nrow(existing) == 1) as.character(existing$submitted_at[[1]] %||% "") else ""
  form_payload <- c(values, list(project_team_leader = pi_value, team_members = team_members_value, grant_code = grant_code_value, date_funding_awarded = project_progress_report_funding_awarded))
  form_data <- jsonlite::toJSON(form_payload, auto_unbox = TRUE, null = "null")
  rec <- data.frame(
    id = report_id,
    project_id = project_id,
    project_code = project_id,
    project_title = as.character(project$name[[1]] %||% ""),
    principal_investigator = pi_value,
    project_team_leader = pi_value,
    team_members = team_members_value,
    status = status,
    report_title = project_progress_report_title(),
    reporting_period = "",
    prepared_by = "",
    summary = as.character(values$project_objectives %||% ""),
    progress = paste(c(as.character(values$progress_activities_done %||% ""), as.character(values$progress_pending_activities %||% "")), collapse = "\n"),
    challenges = as.character(values$other_comment %||% ""),
    next_steps = as.character(values$completion_date %||% ""),
    form_project_title = as.character(values$form_project_title %||% ""),
    project_objectives = as.character(values$project_objectives %||% ""),
    nature_of_project = as.character(values$nature_of_project %||% ""),
    date_funding_awarded = project_progress_report_funding_awarded,
    grant_code = grant_code_value,
    ethical_approval_number = as.character(values$ethical_approval_number %||% ""),
    nacosti_approval_number = as.character(values$nacosti_approval_number %||% ""),
    other_approval_provided = as.character(values$other_approval_provided %||% ""),
    date_project_commenced = as.character(values$date_project_commenced %||% ""),
    progress_activities_done = as.character(values$progress_activities_done %||% ""),
    progress_pending_activities = as.character(values$progress_pending_activities %||% ""),
    completion_date = as.character(values$completion_date %||% ""),
    other_comment = as.character(values$other_comment %||% ""),
    form_data = as.character(form_data),
    docx_path = if (nrow(existing) == 1) as.character(existing$docx_path[[1]] %||% "") else "",
    created_at = created_at,
    updated_at = nowt,
    submitted_at = submitted_at,
    is_trashed = 0,
    stringsAsFactors = FALSE
  )

  con <- connect_db(); on.exit(dbDisconnect(con), add = TRUE)
  ensure_project_reports_schema(con)
  DBI::dbWithTransaction(con, {
    dbExecute(con, "DELETE FROM project_reports WHERE id = ?;", params = list(report_id))
    dbWriteTable(con, "project_reports", rec, append = TRUE, row.names = FALSE)
  })
  docx_path <- write_project_report_docx(report_id)
  try(mark_drive_project_dirty(project_id), silent = TRUE)
  try(log_audit(module = "Report Submission", action = if (identical(status, "submitted")) "submit" else "save_draft", target_table = "project_reports", target_id = report_id, detail = list(project_id = project_id, status = status, docx_path = docx_path), workspace_id = project_id, trigger_sync = FALSE), silent = TRUE)
  get_project_report_by_id(report_id)
}

project_report_view_ui <- function(report_row) {
  if (is.null(report_row) || nrow(report_row) != 1) return(tags$p("Report not found."))
  rows <- project_report_form_rows(report_row)
  body_rows <- rows[!vapply(rows, function(x) isTRUE(x$header), logical(1))]
  cell_lines <- function(lines) {
    lines <- as.character(lines %||% "")
    lines[is.na(lines)] <- ""
    tags$div(class = "progress-report-view-value", lapply(lines, function(line) tags$p(style = "margin:0 0 6px;", if (nzchar(trimws(line))) line else "Not provided")))
  }
  progress_subpart_view <- function(title, value) {
    value <- as.character(value %||% "")
    tags$div(
      class = "progress-report-view-subfield",
      tags$div(class = "progress-report-view-subfield-title", title),
      tags$div(class = "progress-report-view-subfield-content", if (nzchar(trimws(value))) value else "Not provided")
    )
  }
  description_cell <- function(row) {
    if (identical(as.character(row$number %||% ""), "10")) {
      return(tags$div(
        class = "progress-report-view-progress",
        progress_subpart_view("(i) Indicate activities already done", project_report_scalar(report_row, "progress_activities_done", "")),
        progress_subpart_view("(ii) Indicate pending activities", project_report_scalar(report_row, "progress_pending_activities", ""))
      ))
    }
    cell_lines(row$description)
  }
  tagList(
    tags$div(
      class = "progress-report-workspace progress-report-view-workspace",
      tags$div(
        class = "progress-report-workspace-header",
        tags$h3(class = "progress-report-workspace-title", project_progress_report_title()),
        tags$div(
          class = "progress-report-workspace-meta",
          tags$div(tags$strong("Report: "), project_report_display_name(report_row)),
          tags$div(tags$strong("Status: "), toupper(as.character(report_row$status[[1]] %||% "draft"))),
          tags$div(tags$strong("Project Code: "), as.character(report_row$project_code[[1]] %||% report_row$project_id[[1]] %||% ""))
        )
      ),
      tags$div(
        class = "progress-report-table-wrap",
        tags$table(
          class = "table table-bordered table-condensed progress-report-preview-table",
          tags$colgroup(
            tags$col(class = "progress-report-item-col"),
            tags$col(class = "progress-report-description-col")
          ),
          tags$thead(tags$tr(tags$th("Item"), tags$th("Description"))),
          tags$tbody(lapply(body_rows, function(row) {
            tags$tr(
              tags$td(class = "progress-report-item", cell_lines(row$item)),
              tags$td(class = "progress-report-description", description_cell(row))
            )
          }))
        )
      )
    )
    , progress_report_workspace_script()
  )
}

write_project_drive_snapshots <- function(project_id, snapshot_root) {
  dir_create(snapshot_root, recurse = TRUE)
  scoped <- load_app_data(project_id)
  project_row <- scoped$projects %>% filter(id == project_id) %>% slice_head(n = 1)

  active_expenses <- scoped$expenses %>% filter(is_trashed == 0)
  active_expense_ids <- as.character(active_expenses$id %||% character())
  active_attachments <- if (nrow(scoped$attachments) > 0) scoped$attachments %>% filter(expense_id %in% active_expense_ids) else scoped$attachments
  active_breakdowns <- if (nrow(scoped$breakdowns) > 0) scoped$breakdowns %>% filter(expense_id %in% active_expense_ids) else scoped$breakdowns
  latest_exports <- if (nrow(scoped$exports_meta) > 0) {
    scoped$exports_meta %>% arrange(desc(created_at))
  } else scoped$exports_meta
  active_contacts <- if (!is.null(scoped$project_contacts) && nrow(scoped$project_contacts) > 0) {
    scoped$project_contacts %>% filter(project_id == project_id) %>% filter(is.na(is_trashed) | as.integer(is_trashed) == 0L)
  } else scoped$project_contacts
  scheduled_emails <- if (!is.null(scoped$scheduled_emails) && nrow(scoped$scheduled_emails) > 0) {
    scoped$scheduled_emails %>% filter(project_id == project_id)
  } else scoped$scheduled_emails
  scheduled_email_ids <- as.character(scheduled_emails$id %||% character())
  scheduled_email_recipients <- if (!is.null(scoped$scheduled_email_recipients) && nrow(scoped$scheduled_email_recipients) > 0) {
    scoped$scheduled_email_recipients %>% filter(project_id == project_id, email_id %in% scheduled_email_ids)
  } else scoped$scheduled_email_recipients
  scheduled_email_attachments <- if (!is.null(scoped$scheduled_email_attachments) && nrow(scoped$scheduled_email_attachments) > 0) {
    scoped$scheduled_email_attachments %>% filter(project_id == project_id, email_id %in% scheduled_email_ids)
  } else scoped$scheduled_email_attachments
  project_reports_snapshot <- scoped$project_reports
  if (!is.null(project_reports_snapshot) && nrow(project_reports_snapshot) > 0) {
    project_reports_snapshot <- project_reports_snapshot[as.character(project_reports_snapshot$project_id) == project_id, , drop = FALSE]
  }
  supporting_docs_snapshot <- scoped$project_report_supporting_docs
  if (!is.null(supporting_docs_snapshot) && nrow(supporting_docs_snapshot) > 0) {
    supporting_docs_snapshot <- supporting_docs_snapshot[as.character(supporting_docs_snapshot$project_id) == project_id, , drop = FALSE]
  }
  archive_groups_snapshot <- scoped$archive_groups %||% data.frame()

  write.csv(project_row, file.path(snapshot_root, "project.csv"), row.names = FALSE, na = "")
  write.csv(active_expenses, file.path(snapshot_root, "expenses.csv"), row.names = FALSE, na = "")
  write.csv(active_attachments, file.path(snapshot_root, "attachments.csv"), row.names = FALSE, na = "")
  write.csv(active_breakdowns, file.path(snapshot_root, "expense_breakdowns.csv"), row.names = FALSE, na = "")
  write.csv(latest_exports, file.path(snapshot_root, "exports_meta.csv"), row.names = FALSE, na = "")
  write.csv(project_reports_snapshot, file.path(snapshot_root, "project_reports.csv"), row.names = FALSE, na = "")
  write.csv(supporting_docs_snapshot, file.path(snapshot_root, "project_report_supporting_docs.csv"), row.names = FALSE, na = "")
  write.csv(archive_groups_snapshot, file.path(snapshot_root, "archive_groups.csv"), row.names = FALSE, na = "")
  write.csv(active_contacts, file.path(snapshot_root, "project_contacts.csv"), row.names = FALSE, na = "")
  write.csv(scheduled_emails, file.path(snapshot_root, "scheduled_emails.csv"), row.names = FALSE, na = "")
  write.csv(scheduled_email_recipients, file.path(snapshot_root, "scheduled_email_recipients.csv"), row.names = FALSE, na = "")
  write.csv(scheduled_email_attachments, file.path(snapshot_root, "scheduled_email_attachments.csv"), row.names = FALSE, na = "")
  jsonlite::write_json(
    list(
      generated_at = now(),
      project_id = project_id,
      project_name = as.character(project_row$name[[1]] %||% ""),
      totals = list(
        budget_total = sum(as.numeric(project_row$budget_total), na.rm = TRUE),
        spent_total = sum(as.numeric(active_expenses$amount), na.rm = TRUE)
      )
    ),
    path = file.path(snapshot_root, "project_snapshot.json"),
    auto_unbox = TRUE,
    pretty = TRUE
  )

  files <- c(
    project_csv = file.path(snapshot_root, "project.csv"),
    expenses_csv = file.path(snapshot_root, "expenses.csv"),
    attachments_csv = file.path(snapshot_root, "attachments.csv"),
    breakdowns_csv = file.path(snapshot_root, "expense_breakdowns.csv"),
    exports_csv = file.path(snapshot_root, "exports_meta.csv"),
    project_reports_csv = file.path(snapshot_root, "project_reports.csv"),
    project_report_supporting_docs_csv = file.path(snapshot_root, "project_report_supporting_docs.csv"),
    archive_groups_csv = file.path(snapshot_root, "archive_groups.csv"),
    project_contacts_csv = file.path(snapshot_root, "project_contacts.csv"),
    scheduled_emails_csv = file.path(snapshot_root, "scheduled_emails.csv"),
    scheduled_email_recipients_csv = file.path(snapshot_root, "scheduled_email_recipients.csv"),
    scheduled_email_attachments_csv = file.path(snapshot_root, "scheduled_email_attachments.csv"),
    snapshot_json = file.path(snapshot_root, "project_snapshot.json")
  )
  data.frame(
    local_key = c("snapshot::project_csv", "snapshot::expenses_csv", "snapshot::attachments_csv", "snapshot::breakdowns_csv", "snapshot::exports_csv", "snapshot::project_reports_csv", "snapshot::project_report_supporting_docs_csv", "snapshot::archive_groups_csv", "snapshot::project_contacts_csv", "snapshot::scheduled_emails_csv", "snapshot::scheduled_email_recipients_csv", "snapshot::scheduled_email_attachments_csv", "snapshot::project_snapshot"),
    remote_path = c(
      "snapshots/project.csv",
      "snapshots/expenses.csv",
      "snapshots/attachments.csv",
      "snapshots/expense_breakdowns.csv",
      "snapshots/exports_meta.csv",
      "snapshots/project_reports.csv",
      "snapshots/project_report_supporting_docs.csv",
      "snapshots/archive_groups.csv",
      "snapshots/project_contacts.csv",
      "snapshots/scheduled_emails.csv",
      "snapshots/scheduled_email_recipients.csv",
      "snapshots/scheduled_email_attachments.csv",
      "snapshots/project_snapshot.json"
    ),
    local_path = unname(files),
    stringsAsFactors = FALSE
  )
}

collect_project_drive_sync_items <- function(project_row) {
  project_id <- as.character(project_row$id[[1]] %||% "")
  if (!nzchar(project_id)) return(data.frame())
  scoped <- load_app_data(project_id)
  items <- data.frame(local_key = character(), remote_path = character(), local_path = character(), checksum = character(), stringsAsFactors = FALSE)

  workbook_path <- as.character(project_row$workbook_path[[1]] %||% "")
  if (nzchar(workbook_path) && file.exists(workbook_path)) {
    items <- rbind(items, data.frame(
      local_key = "workbook::project_workbook",
      remote_path = "workbooks/project_workbook.xlsx",
      local_path = normalizePath(workbook_path, winslash = "/", mustWork = FALSE),
      checksum = file_checksum(workbook_path),
      stringsAsFactors = FALSE
    ))
  }

  latest_reports <- scoped$exports_meta %>%
    filter(type %in% c("excel", "html", "pdf")) %>%
    arrange(desc(created_at))
  if (nrow(latest_reports) > 0) {
    for (report_type in c("excel", "html", "pdf")) {
      subset_rows <- latest_reports %>% filter(type == report_type) %>% slice_head(n = 1)
      if (nrow(subset_rows) == 1) {
        local_path <- as.character(subset_rows$filepath[[1]] %||% "")
        if (nzchar(local_path) && file.exists(local_path)) {
          remote_name <- switch(
            report_type,
            excel = "reports/latest_report.xlsx",
            html = "reports/latest_report.html",
            pdf = "reports/latest_report.pdf",
            paste0("reports/latest_report_", report_type)
          )
          items <- rbind(items, data.frame(
            local_key = paste0("report::", report_type),
            remote_path = remote_name,
            local_path = normalizePath(local_path, winslash = "/", mustWork = FALSE),
            checksum = file_checksum(local_path),
            stringsAsFactors = FALSE
          ))
        }
      }
    }
  }

  project_reports <- scoped$project_reports
  if (!is.null(project_reports) && nrow(project_reports) > 0) {
    if ("project_id" %in% names(project_reports)) project_reports <- project_reports[as.character(project_reports$project_id) == project_id, , drop = FALSE]
    for (i in seq_len(nrow(project_reports))) {
      report_row <- project_reports[i, , drop = FALSE]
      report_id <- as.character(report_row$id[[1]] %||% "")
      local_path <- as.character(report_row$docx_path[[1]] %||% "")
      if (nzchar(report_id) && nzchar(local_path) && file.exists(local_path) && identical(tolower(fs::path_ext(local_path)), "docx")) {
        items <- rbind(items, data.frame(
          local_key = paste0("project_report::", report_id),
          remote_path = project_report_remote_path(report_row),
          local_path = normalizePath(local_path, winslash = "/", mustWork = FALSE),
          checksum = file_checksum(local_path),
          stringsAsFactors = FALSE
        ))
      }
    }
  }

  supporting_docs <- scoped$project_report_supporting_docs
  if (!is.null(supporting_docs) && nrow(supporting_docs) > 0) {
    if ("project_id" %in% names(supporting_docs)) supporting_docs <- supporting_docs[as.character(supporting_docs$project_id) == project_id, , drop = FALSE]
    for (i in seq_len(nrow(supporting_docs))) {
      doc_row <- supporting_docs[i, , drop = FALSE]
      doc_id <- as.character(doc_row$id[[1]] %||% "")
      local_path <- as.character(doc_row$filepath[[1]] %||% "")
      if (nzchar(doc_id) && nzchar(local_path) && file.exists(local_path)) {
        items <- rbind(items, data.frame(
          local_key = paste0("project_supporting_doc::", doc_id),
          remote_path = project_report_supporting_doc_remote_path(doc_row),
          local_path = normalizePath(local_path, winslash = "/", mustWork = FALSE),
          checksum = file_checksum(local_path),
          stringsAsFactors = FALSE
        ))
      }
    }
  }

  scheduled_email_attachments <- scoped$scheduled_email_attachments
  if (!is.null(scheduled_email_attachments) && nrow(scheduled_email_attachments) > 0) {
    if ("project_id" %in% names(scheduled_email_attachments)) {
      scheduled_email_attachments <- scheduled_email_attachments[as.character(scheduled_email_attachments$project_id) == project_id, , drop = FALSE]
    }
    for (i in seq_len(nrow(scheduled_email_attachments))) {
      attachment_row <- scheduled_email_attachments[i, , drop = FALSE]
      attachment_id <- as.character(attachment_row$id[[1]] %||% "")
      local_path <- as.character(attachment_row$filepath[[1]] %||% "")
      if (nzchar(attachment_id) && nzchar(local_path) && file.exists(local_path)) {
        items <- rbind(items, data.frame(
          local_key = paste0("communication_attachment::", attachment_id),
          remote_path = scheduled_email_attachment_remote_path(attachment_row),
          local_path = normalizePath(local_path, winslash = "/", mustWork = FALSE),
          checksum = file_checksum(local_path),
          stringsAsFactors = FALSE
        ))
      }
    }
  }

  active_expenses <- scoped$expenses %>% filter(is_trashed == 0)
  active_expense_ids <- as.character(active_expenses$id %||% character())
  active_attachments <- if (nrow(scoped$attachments) > 0) scoped$attachments %>% filter(expense_id %in% active_expense_ids) else scoped$attachments
  if (nrow(active_attachments) > 0) {
    for (i in seq_len(nrow(active_attachments))) {
      att <- active_attachments[i, , drop = FALSE]
      local_path <- as.character(att$filepath[[1]] %||% "")
      if (nzchar(local_path) && file.exists(local_path)) {
        items <- rbind(items, data.frame(
          local_key = paste0("attachment::", as.character(att$id[[1]])),
          remote_path = file.path("attachments", build_drive_attachment_name(att)),
          local_path = normalizePath(local_path, winslash = "/", mustWork = FALSE),
          checksum = file_checksum(local_path),
          stringsAsFactors = FALSE
        ))
      }
    }
  }

  snapshot_root <- file.path(tempdir(), "budget_drive_snapshots", project_id)
  snapshot_items <- write_project_drive_snapshots(project_id, snapshot_root)
  if (nrow(snapshot_items) > 0) {
    snapshot_items$checksum <- vapply(snapshot_items$local_path, file_checksum, character(1))
    items <- rbind(items, snapshot_items[, c("local_key", "remote_path", "local_path", "checksum")])
  }

  items <- items[file.exists(items$local_path), , drop = FALSE]
  items$remote_path <- gsub("\\\\", "/", items$remote_path)
  items$local_key <- as.character(items$local_key)
  items$local_path <- as.character(items$local_path)
  items$checksum <- as.character(items$checksum)
  items
}

drive_backend_authenticate <- function(settings) {
  if (identical(settings$backend, "filesystem")) return(invisible(TRUE))
  options(googledrive_quiet = TRUE)
  if (isTRUE(settings$has_service_account) && file_exists(settings$service_account_path)) {
    googledrive::drive_auth(path = settings$service_account_path, cache = FALSE, scopes = googledrive::drive_scopes("drive"))
    return(invisible(TRUE))
  }
  options(gargle_oauth_email = settings$account_email %||% "")
  googledrive::drive_auth(email = settings$account_email, cache = settings$token_cache_dir, scopes = googledrive::drive_scopes("drive"), use_oob = FALSE)
  invisible(TRUE)
}

drive_backend_item_exists <- function(item_id, settings) {
  if (!nzchar(as.character(item_id %||% ""))) return(FALSE)
  if (identical(settings$backend, "filesystem")) {
    return(dir_exists(item_id) || file_exists(item_id))
  }
  res <- tryCatch(googledrive::drive_get(id = googledrive::as_id(item_id)), error = function(e) NULL)
  !is.null(res) && nrow(res) >= 1
}

drive_backend_ensure_child_folder <- function(parent_id, name, settings) {
  if (identical(settings$backend, "filesystem")) {
    dir_create(parent_id, recurse = TRUE)
    target <- file.path(parent_id, name)
    dir_create(target, recurse = TRUE)
    return(normalizePath(target, winslash = "/", mustWork = FALSE))
  }
  folders <- tryCatch(
    googledrive::drive_ls(path = googledrive::as_id(parent_id), type = "folder"),
    error = function(e) NULL
  )
  if (!is.null(folders) && nrow(folders) > 0) {
    exact <- folders[folders$name == name, , drop = FALSE]
    if (nrow(exact) > 1) {
      try(googledrive::drive_trash(exact[-1, , drop = FALSE]), silent = TRUE)
      exact <- exact[1, , drop = FALSE]
    }
    if (nrow(exact) == 1) return(as.character(exact$id[[1]]))
  }
  created <- googledrive::drive_mkdir(name = name, path = googledrive::as_id(parent_id))
  as.character(created$id[[1]])
}

drive_backend_get_item_name <- function(item_id, settings) {
  if (!nzchar(as.character(item_id %||% ""))) return("")
  if (identical(settings$backend, "filesystem")) {
    return(basename(as.character(item_id)))
  }
  res <- tryCatch(googledrive::drive_get(id = googledrive::as_id(item_id)), error = function(e) NULL)
  if (is.null(res) || nrow(res) == 0) return("")
  as.character(res$name[[1]] %||% "")
}

drive_backend_rename_item <- function(item_id, name, settings) {
  if (!nzchar(as.character(item_id %||% ""))) return("")
  if (identical(settings$backend, "filesystem")) {
    current_path <- as.character(item_id)
    target_path <- file.path(dirname(current_path), name)
    if (!identical(normalizePath(current_path, winslash = "/", mustWork = FALSE), normalizePath(target_path, winslash = "/", mustWork = FALSE))) {
      if (!dir_exists(target_path) && !file_exists(target_path)) {
        file_move(current_path, target_path)
        current_path <- target_path
      }
    }
    return(normalizePath(current_path, winslash = "/", mustWork = FALSE))
  }
  res <- googledrive::drive_get(id = googledrive::as_id(item_id))
  if (nrow(res) == 0) stop("Drive item not found for rename.")
  renamed <- googledrive::drive_rename(res, name = name)
  as.character(renamed$id[[1]])
}

drive_backend_upload_file <- function(local_path, parent_id, name, settings, existing_id = "") {
  if (identical(settings$backend, "filesystem")) {
    dir_create(parent_id, recurse = TRUE)
    dest <- file.path(parent_id, name)
    dest <- copy_file_checked(local_path, dest, overwrite = TRUE)
    return(list(id = dest, name = basename(dest)))
  }
  children <- tryCatch(googledrive::drive_ls(path = googledrive::as_id(parent_id)), error = function(e) NULL)
  target <- NULL
  if (!is.null(children) && nrow(children) > 0) {
    exact <- children[children$name == name, , drop = FALSE]
    if (nrow(exact) > 1) {
      if (nzchar(existing_id) && any(as.character(exact$id) == as.character(existing_id))) {
        keep_idx <- which(as.character(exact$id) == as.character(existing_id))[1]
      } else {
        keep_idx <- 1
      }
      extras <- exact[-keep_idx, , drop = FALSE]
      if (nrow(extras) > 0) try(googledrive::drive_trash(extras), silent = TRUE)
      exact <- exact[keep_idx, , drop = FALSE]
    }
    if (nrow(exact) == 1) {
      target <- exact
    }
  }
  if (!is.null(target) && nrow(target) == 1) {
    uploaded <- googledrive::drive_update(target, media = local_path)
  } else {
    uploaded <- googledrive::drive_upload(media = local_path, path = googledrive::as_id(parent_id), name = name)
  }
  list(id = as.character(uploaded$id[[1]]), name = as.character(uploaded$name[[1]]))
}

drive_backend_remove_file <- function(file_id, settings) {
  if (!nzchar(as.character(file_id %||% ""))) return(invisible(TRUE))
  if (identical(settings$backend, "filesystem")) {
    if (file_exists(file_id)) try(file_delete(file_id), silent = TRUE)
    return(invisible(TRUE))
  }
  try(googledrive::drive_trash(googledrive::as_id(file_id)), silent = TRUE)
  invisible(TRUE)
}

ensure_drive_root_folder <- function(settings) {
  if (identical(settings$backend, "filesystem")) {
    root_dir <- settings$root_folder_id
    if (!nzchar(root_dir)) root_dir <- file.path(data_dir, "drive-mock")
    dir_create(root_dir, recurse = TRUE)
    root_dir <- normalizePath(root_dir, winslash = "/", mustWork = FALSE)
    if (!identical(settings$root_folder_id %||% "", root_dir)) {
      try(set_setting("drive_root_folder_id", root_dir), silent = TRUE)
      settings$root_folder_id <- root_dir
    }
    return(root_dir)
  }

  stored_root <- as.character(settings$root_folder_id %||% "")
  if (nzchar(stored_root) && drive_backend_item_exists(stored_root, settings)) {
    current_name <- drive_backend_get_item_name(stored_root, settings)
    if (nzchar(current_name) && !identical(current_name, settings$root_folder_name)) {
      stored_root <- drive_backend_rename_item(stored_root, settings$root_folder_name, settings)
      try(set_setting("drive_root_folder_id", stored_root), silent = TRUE)
    }
    return(stored_root)
  }

  root_children <- tryCatch(googledrive::drive_ls(path = NULL, type = "folder"), error = function(e) NULL)
  if (!is.null(root_children) && nrow(root_children) > 0) {
    exact <- root_children[root_children$name == settings$root_folder_name, , drop = FALSE]
    if (nrow(exact) > 1) {
      exact <- exact[1, , drop = FALSE]
    }
    if (nrow(exact) == 1) {
      root_id <- as.character(exact$id[[1]])
      try(set_setting("drive_root_folder_id", root_id), silent = TRUE)
      return(root_id)
    }
  }

  created <- googledrive::drive_mkdir(name = settings$root_folder_name, path = NULL)
  root_id <- as.character(created$id[[1]])
  try(set_setting("drive_root_folder_id", root_id), silent = TRUE)
  root_id
}

ensure_project_drive_folder <- function(project_row, settings) {
  project_id <- as.character(project_row$id[[1]] %||% "")
  folder_name <- drive_sync_project_folder_name(project_row)
  root_id <- ensure_drive_root_folder(settings)
  folder_id <- as.character(project_row$drive_folder_id[[1]] %||% "")
  if (nzchar(folder_id) && drive_backend_item_exists(folder_id, settings)) {
    current_name <- drive_backend_get_item_name(folder_id, settings)
    if (nzchar(current_name) && !identical(current_name, folder_name)) {
      folder_id <- drive_backend_rename_item(folder_id, folder_name, settings)
    }
  } else {
    folder_id <- drive_backend_ensure_child_folder(root_id, folder_name, settings)
  }
  update_project_drive_sync_state(project_id, folder_id = folder_id, success = FALSE, error_message = as.character(project_row$drive_sync_error[[1]] %||% ""))
  folder_id
}

ensure_drive_folder_path <- function(project_folder_id, remote_path, settings) {
  rel_parts <- strsplit(gsub("\\\\", "/", as.character(remote_path %||% "")), "/", fixed = TRUE)[[1]]
  rel_parts <- rel_parts[nzchar(rel_parts)]
  if (length(rel_parts) <= 1) return(list(folder_id = project_folder_id, filename = if (length(rel_parts) == 1) rel_parts[[1]] else ""))
  current_folder <- project_folder_id
  for (folder_name in rel_parts[-length(rel_parts)]) {
    current_folder <- drive_backend_ensure_child_folder(current_folder, folder_name, settings)
  }
  list(folder_id = current_folder, filename = rel_parts[[length(rel_parts)]])
}

drive_sync_project_files <- function(project_row, settings, lease_token = "") {
  project_id <- as.character(project_row$id[[1]] %||% "")
  folder_id <- ensure_project_drive_folder(project_row, settings)
  items <- collect_project_drive_sync_items(project_row)
  existing_map <- get_drive_file_map(project_id)
  active_keys <- character()

  if (nrow(items) > 0) {
    for (i in seq_len(nrow(items))) {
      if (nzchar(lease_token)) heartbeat_drive_sync_lease(lease_token)
      item <- items[i, , drop = FALSE]
      active_keys <- c(active_keys, item$local_key[[1]])
      mapped <- existing_map[existing_map$local_key == item$local_key[[1]], , drop = FALSE]
      mapped_checksum <- if (nrow(mapped) == 1) as.character(mapped$checksum[[1]] %||% "") else ""
      mapped_file_id <- if (nrow(mapped) == 1) as.character(mapped$drive_file_id[[1]] %||% "") else ""
      if (identical(mapped_checksum, item$checksum[[1]]) && nzchar(mapped_file_id)) next

      target <- ensure_drive_folder_path(folder_id, item$remote_path[[1]], settings)
      upload_res <- drive_backend_upload_file(
        local_path = item$local_path[[1]],
        parent_id = target$folder_id,
        name = target$filename,
        settings = settings,
        existing_id = mapped_file_id
      )
      save_drive_file_map_entry(
        project_id = project_id,
        local_key = item$local_key[[1]],
        local_path = item$local_path[[1]],
        remote_path = item$remote_path[[1]],
        remote_name = target$filename,
        drive_file_id = upload_res$id,
        checksum = item$checksum[[1]]
      )
    }
  }

  stale <- existing_map[!(existing_map$local_key %in% active_keys), , drop = FALSE]
  if (nrow(stale) > 0) {
    for (i in seq_len(nrow(stale))) {
      if (nzchar(lease_token)) heartbeat_drive_sync_lease(lease_token)
      drive_backend_remove_file(as.character(stale$drive_file_id[[i]] %||% ""), settings)
    }
    delete_drive_file_map_entries(project_id, stale$local_key)
  }

  update_project_drive_sync_state(project_id, folder_id = folder_id, success = TRUE, error_message = "")
  append_drive_sync_log("INFO", "Project Drive sync completed.", project_id = project_id, detail = list(file_count = nrow(items), folder_id = folder_id))
  try(log_audit(module = "Google Drive", action = "sync_project", target_table = "projects", target_id = project_id, detail = list(folder_id = folder_id, file_count = nrow(items)), workspace_id = project_id, trigger_sync = FALSE), silent = TRUE)
  TRUE
}

get_drive_sync_candidates <- function() {
  con <- connect_db()
  on.exit(dbDisconnect(con), add = TRUE)
  ensure_drive_sync_schema(con)
  dbGetQuery(
    con,
    "SELECT * FROM projects WHERE is_trashed = 0 AND (drive_pending_sync = 1 OR COALESCE(drive_folder_id, '') = '' OR COALESCE(drive_sync_error, '') <> '') ORDER BY updated_at ASC;"
  )
}

run_drive_sync_cycle <- function(lease_token = "", reason = "scheduled") {
  status <- drive_sync_status()
  success <- TRUE
  final_error <- ""
  on.exit({
    if (nzchar(as.character(lease_token %||% ""))) {
      release_drive_sync_lease(lease_token, success = success, error_message = final_error)
    }
  }, add = TRUE)

  if (!isTRUE(status$ok)) {
    final_error <- status$reason
    append_drive_sync_log("ERROR", status$reason, detail = list(reason = reason))
    return(FALSE)
  }

  settings <- status$settings
  append_drive_sync_log("INFO", "Starting Drive sync cycle.", detail = list(reason = reason, backend = settings$backend))

  tryCatch({
    drive_backend_authenticate(settings)
    projects <- get_drive_sync_candidates()
    if (nrow(projects) == 0) {
      append_drive_sync_log("INFO", "No Drive-sync changes detected.")
      return(TRUE)
    }
    for (i in seq_len(nrow(projects))) {
      if (nzchar(as.character(lease_token %||% ""))) heartbeat_drive_sync_lease(lease_token)
      project_row <- projects[i, , drop = FALSE]
      project_id <- as.character(project_row$id[[1]] %||% "")
      tryCatch({
        drive_sync_project_files(project_row, settings, lease_token = lease_token)
      }, error = function(e) {
        drive_error <- format_drive_error(e)
        success <<- FALSE
        final_error <<- drive_error
        update_project_drive_sync_state(project_id, folder_id = as.character(project_row$drive_folder_id[[1]] %||% ""), success = FALSE, error_message = drive_error)
        append_drive_sync_log("ERROR", paste0("Drive sync failed: ", drive_error), project_id = project_id)
        try(log_audit(module = "Google Drive", action = "sync_error", target_table = "projects", target_id = project_id, detail = list(error = drive_error), workspace_id = project_id, trigger_sync = FALSE), silent = TRUE)
      })
    }
    success
  }, error = function(e) {
    success <<- FALSE
    final_error <<- e$message
    append_drive_sync_log("ERROR", paste0("Drive sync cycle failed: ", format_drive_error(e)), detail = list(reason = reason))
    FALSE
  })
}


# ---------------------------
# Google Drive restore helpers
# ---------------------------
drive_backend_list_children <- function(parent_id, settings, type = NULL) {
  parent_id <- as.character(parent_id %||% "")
  empty <- data.frame(id = character(), name = character(), type = character(), stringsAsFactors = FALSE)
  if (!nzchar(parent_id)) return(empty)
  if (identical(settings$backend, "filesystem")) {
    if (!dir_exists(parent_id)) return(empty)
    entries <- dir_ls(parent_id, recurse = FALSE, all = FALSE)
    if (length(entries) == 0) return(empty)
    entry_type <- ifelse(dir_exists(entries), "folder", "file")
    out <- data.frame(
      id = normalizePath(as.character(entries), winslash = "/", mustWork = FALSE),
      name = basename(as.character(entries)),
      type = entry_type,
      stringsAsFactors = FALSE
    )
    if (!is.null(type) && nzchar(as.character(type))) out <- out[out$type == as.character(type), , drop = FALSE]
    return(out)
  }
  res <- tryCatch({
    if (!is.null(type) && identical(as.character(type), "folder")) {
      googledrive::drive_ls(path = googledrive::as_id(parent_id), type = "folder")
    } else {
      googledrive::drive_ls(path = googledrive::as_id(parent_id))
    }
  }, error = function(e) data.frame())
  if (is.null(res) || nrow(res) == 0) return(empty)
  data.frame(
    id = as.character(res$id),
    name = as.character(res$name),
    type = if (!is.null(type) && identical(as.character(type), "folder")) "folder" else "item",
    stringsAsFactors = FALSE
  )
}

drive_backend_find_child <- function(parent_id, name, settings, type = NULL) {
  children <- drive_backend_list_children(parent_id, settings, type = type)
  if (nrow(children) == 0) return(data.frame())
  matches <- children[children$name == as.character(name), , drop = FALSE]
  if (nrow(matches) == 0) return(data.frame())
  matches[1, , drop = FALSE]
}

drive_backend_find_remote_path <- function(project_folder_id, remote_path, settings) {
  parts <- strsplit(gsub("\\\\", "/", as.character(remote_path %||% "")), "/", fixed = TRUE)[[1]]
  parts <- parts[nzchar(parts)]
  if (length(parts) == 0) return(data.frame())
  current_id <- as.character(project_folder_id %||% "")
  if (!nzchar(current_id)) return(data.frame())
  if (length(parts) > 1) {
    for (folder_name in parts[-length(parts)]) {
      folder <- drive_backend_find_child(current_id, folder_name, settings, type = "folder")
      if (nrow(folder) == 0) return(data.frame())
      current_id <- as.character(folder$id[[1]])
    }
  }
  drive_backend_find_child(current_id, parts[[length(parts)]], settings)
}

drive_backend_download_file <- function(file_id, dest_path, settings) {
  file_id <- as.character(file_id %||% "")
  if (!nzchar(file_id)) return(FALSE)
  dir_create(dirname(dest_path), recurse = TRUE)
  if (identical(settings$backend, "filesystem")) {
    if (!file_exists(file_id)) return(FALSE)
    file_copy(file_id, dest_path, overwrite = TRUE)
  } else {
    googledrive::drive_download(googledrive::as_id(file_id), path = dest_path, overwrite = TRUE)
  }
  file_exists(dest_path)
}

drive_restore_download_remote_path <- function(project_folder_id, remote_path, dest_path, settings) {
  remote <- drive_backend_find_remote_path(project_folder_id, remote_path, settings)
  if (nrow(remote) == 0) return(list(ok = FALSE, id = "", name = basename(remote_path), path = ""))
  ok <- drive_backend_download_file(remote$id[[1]], dest_path, settings)
  list(
    ok = isTRUE(ok),
    id = as.character(remote$id[[1]]),
    name = as.character(remote$name[[1]] %||% basename(remote_path)),
    path = if (isTRUE(ok)) normalizePath(dest_path, winslash = "/", mustWork = FALSE) else ""
  )
}

read_drive_restore_csv <- function(project_folder_id, remote_path, stage_dir, settings) {
  dest <- file.path(stage_dir, gsub("/", "_", remote_path, fixed = TRUE))
  res <- drive_restore_download_remote_path(project_folder_id, remote_path, dest, settings)
  if (!isTRUE(res$ok)) return(data.frame())
  read_backup_table_csv(dest)
}

align_restore_table <- function(con, table_name, df) {
  if (is.null(df) || nrow(df) == 0) return(data.frame())
  table_cols <- dbGetQuery(con, sprintf("PRAGMA table_info(%s);", table_name))$name
  for (col in setdiff(table_cols, names(df))) df[[col]] <- ""
  df <- df[, table_cols, drop = FALSE]
  df[] <- lapply(df, function(x) {
    x <- as.character(x)
    x[is.na(x)] <- ""
    x
  })
  df
}

restore_drive_attachment_files <- function(project_folder_id, project_id, attachments_restore, settings) {
  if (is.null(attachments_restore) || nrow(attachments_restore) == 0) return(attachments_restore)
  attachments_folder <- drive_backend_find_remote_path(project_folder_id, "attachments", settings)
  attachments_children <- if (nrow(attachments_folder) == 1) drive_backend_list_children(attachments_folder$id[[1]], settings) else data.frame()
  for (i in seq_len(nrow(attachments_restore))) {
    att <- attachments_restore[i, , drop = FALSE]
    expected_name <- build_drive_attachment_name(att)
    remote <- if (nrow(attachments_children) > 0) attachments_children[attachments_children$name == expected_name, , drop = FALSE] else data.frame()
    if (nrow(remote) == 0 && nrow(attachments_children) > 0) {
      prefix <- paste0(as.character(att$id[[1]] %||% ""), "_")
      remote <- attachments_children[startsWith(attachments_children$name, prefix), , drop = FALSE]
    }
    if (nrow(remote) > 0) {
      remote <- remote[1, , drop = FALSE]
      dest <- file.path(receipts_dir, paste0("drive_restore_", project_id, "_", basename(remote$name[[1]])))
      if (drive_backend_download_file(remote$id[[1]], dest, settings)) {
        dest_abs <- normalizePath(dest, winslash = "/", mustWork = FALSE)
        attachments_restore$filepath[[i]] <- dest_abs
        attachments_restore$size[[i]] <- as.numeric(file_info(dest_abs)$size)
        attachments_restore$checksum[[i]] <- file_checksum(dest_abs)
        save_drive_file_map_entry(
          project_id = project_id,
          local_key = paste0("attachment::", as.character(att$id[[1]])),
          local_path = dest_abs,
          remote_path = file.path("attachments", as.character(remote$name[[1]])),
          remote_name = as.character(remote$name[[1]]),
          drive_file_id = as.character(remote$id[[1]]),
          checksum = file_checksum(dest_abs)
        )
      }
    }
  }
  attachments_restore
}

restore_drive_report_files <- function(project_folder_id, project_id, settings) {
  report_specs <- data.frame(
    type = c("excel", "html", "pdf"),
    remote_path = c("reports/latest_report.xlsx", "reports/latest_report.html", "reports/latest_report.pdf"),
    filename = c("latest_report.xlsx", "latest_report.html", "latest_report.pdf"),
    stringsAsFactors = FALSE
  )
  rows <- list()
  for (i in seq_len(nrow(report_specs))) {
    spec <- report_specs[i, , drop = FALSE]
    dest <- file.path(internal_exports_dir, paste0("drive_restore_", project_id, "_", spec$filename[[1]]))
    res <- drive_restore_download_remote_path(project_folder_id, spec$remote_path[[1]], dest, settings)
    if (isTRUE(res$ok)) {
      rows[[length(rows) + 1]] <- data.frame(
        id = uuid("exp"),
        filename = basename(res$path),
        filepath = res$path,
        type = spec$type[[1]],
        created_at = now(),
        criteria = project_id,
        stringsAsFactors = FALSE
      )
      save_drive_file_map_entry(
        project_id = project_id,
        local_key = paste0("report::", spec$type[[1]]),
        local_path = res$path,
        remote_path = spec$remote_path[[1]],
        remote_name = spec$filename[[1]],
        drive_file_id = res$id,
        checksum = file_checksum(res$path)
      )
    }
  }
  if (length(rows) == 0) return(data.frame())
  do.call(rbind, rows)
}

restore_drive_project_report_files <- function(project_folder_id, project_id, project_reports_restore, settings) {
  if (is.null(project_reports_restore) || nrow(project_reports_restore) == 0) return(project_reports_restore)
  if (!("id" %in% names(project_reports_restore))) return(project_reports_restore)
  if (!("docx_path" %in% names(project_reports_restore))) project_reports_restore$docx_path <- ""

  reports_folder <- drive_backend_find_remote_path(project_folder_id, "project_reports", settings)
  reports_children <- if (nrow(reports_folder) == 1) drive_backend_list_children(reports_folder$id[[1]], settings) else data.frame()
  target_dir <- file.path(project_reports_dir, project_id)
  dir_create(target_dir, recurse = TRUE)

  for (i in seq_len(nrow(project_reports_restore))) {
    report_row <- project_reports_restore[i, , drop = FALSE]
    report_id <- as.character(report_row$id[[1]] %||% "")
    expected_names <- unique(c(
      project_report_docx_filename(report_row),
      basename(as.character(report_row$docx_path[[1]] %||% ""))
    ))
    expected_names <- expected_names[nzchar(expected_names) & grepl("\\.docx$", expected_names, ignore.case = TRUE)]
    remote <- if (nrow(reports_children) > 0) reports_children[reports_children$name %in% expected_names, , drop = FALSE] else data.frame()
    if (nrow(remote) == 0 && nrow(reports_children) > 0 && nzchar(report_id)) {
      remote <- reports_children[grepl(report_id, reports_children$name, fixed = TRUE) & grepl("\\.docx$", reports_children$name, ignore.case = TRUE), , drop = FALSE]
    }
    if (nrow(remote) > 0) {
      remote <- remote[1, , drop = FALSE]
      dest <- file.path(target_dir, basename(as.character(remote$name[[1]])))
      if (drive_backend_download_file(remote$id[[1]], dest, settings)) {
        dest_abs <- normalizePath(dest, winslash = "/", mustWork = FALSE)
        project_reports_restore$docx_path[[i]] <- dest_abs
        save_drive_file_map_entry(
          project_id = project_id,
          local_key = paste0("project_report::", report_id),
          local_path = dest_abs,
          remote_path = file.path("project_reports", as.character(remote$name[[1]])),
          remote_name = as.character(remote$name[[1]]),
          drive_file_id = as.character(remote$id[[1]]),
          checksum = file_checksum(dest_abs)
        )
      }
    }
  }
  project_reports_restore
}

restore_drive_project_supporting_doc_files <- function(project_folder_id, project_id, supporting_docs_restore, settings) {
  if (is.null(supporting_docs_restore) || nrow(supporting_docs_restore) == 0) return(supporting_docs_restore)
  if (!("id" %in% names(supporting_docs_restore))) return(supporting_docs_restore)
  if (!("stored_filename" %in% names(supporting_docs_restore))) supporting_docs_restore$stored_filename <- ""
  if (!("filepath" %in% names(supporting_docs_restore))) supporting_docs_restore$filepath <- ""
  if (!("file_ext" %in% names(supporting_docs_restore))) supporting_docs_restore$file_ext <- ""
  target_dir <- project_report_supporting_doc_storage_dir(project_id)
  for (i in seq_len(nrow(supporting_docs_restore))) {
    doc_row <- supporting_docs_restore[i, , drop = FALSE]
    doc_id <- as.character(doc_row$id[[1]] %||% "")
    stored_name <- as.character(doc_row$stored_filename[[1]] %||% "")
    if (!nzchar(stored_name)) {
      original_name <- as.character(doc_row$original_filename[[1]] %||% "")
      ext <- tolower(fs::path_ext(original_name))
      stem <- sanitize_filename(tools::file_path_sans_ext(original_name))
      if (!nzchar(stem)) stem <- "supporting_file"
      stored_name <- paste0(doc_id, "__", stem, if (nzchar(ext)) paste0(".", ext) else "")
      supporting_docs_restore$stored_filename[[i]] <- stored_name
    }
    if (!nzchar(doc_id) || !nzchar(stored_name)) next
    remote_path <- project_report_supporting_doc_remote_path(data.frame(
      project_id = project_id,
      stored_filename = stored_name,
      filepath = "",
      stringsAsFactors = FALSE
    ))
    dest <- file.path(target_dir, stored_name)
    res <- drive_restore_download_remote_path(project_folder_id, remote_path, dest, settings)
    if (isTRUE(res$ok)) {
      dest_abs <- normalizePath(dest, winslash = "/", mustWork = FALSE)
      supporting_docs_restore$filepath[[i]] <- dest_abs
      supporting_docs_restore$size[[i]] <- as.numeric(file_info(dest_abs)$size)
      supporting_docs_restore$checksum[[i]] <- file_checksum(dest_abs)
      save_drive_file_map_entry(
        project_id = project_id,
        local_key = paste0("project_supporting_doc::", doc_id),
        local_path = dest_abs,
        remote_path = remote_path,
        remote_name = stored_name,
        drive_file_id = res$id,
        checksum = file_checksum(dest_abs)
      )
    }
  }
  supporting_docs_restore
}

restore_drive_scheduled_email_attachment_files <- function(project_folder_id, project_id, scheduled_email_attachments_restore, settings) {
  if (is.null(scheduled_email_attachments_restore) || nrow(scheduled_email_attachments_restore) == 0) return(scheduled_email_attachments_restore)
