  if (!("attachment_name" %in% names(scheduled_email_attachments_restore))) scheduled_email_attachments_restore$attachment_name <- ""
  if (!("filepath" %in% names(scheduled_email_attachments_restore))) scheduled_email_attachments_restore$filepath <- ""

  for (i in seq_len(nrow(scheduled_email_attachments_restore))) {
    attachment_row <- scheduled_email_attachments_restore[i, , drop = FALSE]
    email_id <- as.character(attachment_row$email_id[[1]] %||% "")
    stored_name <- as.character(attachment_row$stored_filename[[1]] %||% "")
    if (!nzchar(email_id) || !nzchar(stored_name)) next
    remote_path <- scheduled_email_attachment_remote_path(attachment_row)
    dest_dir <- scheduled_email_attachment_storage_dir(project_id, email_id)
    dest <- file.path(dest_dir, stored_name)
    res <- drive_restore_download_remote_path(project_folder_id, remote_path, dest, settings)
    if (isTRUE(res$ok)) {
      dest_abs <- normalizePath(dest, winslash = "/", mustWork = FALSE)
      scheduled_email_attachments_restore$filepath[[i]] <- dest_abs
      scheduled_email_attachments_restore$size[[i]] <- as.numeric(file_info(dest_abs)$size)
      scheduled_email_attachments_restore$checksum[[i]] <- file_checksum(dest_abs)
      save_drive_file_map_entry(
        project_id = project_id,
        local_key = paste0("communication_attachment::", as.character(attachment_row$id[[1]] %||% "")),
        local_path = dest_abs,
        remote_path = remote_path,
        remote_name = stored_name,
        drive_file_id = res$id,
        checksum = file_checksum(dest_abs)
      )
    }
  }
  scheduled_email_attachments_restore
}

restore_single_project_from_drive_folder <- function(project_folder, settings) {
  project_folder_id <- as.character(project_folder$id[[1]] %||% "")
  project_folder_name <- as.character(project_folder$name[[1]] %||% "")
  stage_dir <- file.path(tempdir(), paste0("budget_drive_restore_", digest::digest(paste(project_folder_id, Sys.getpid(), Sys.time()))))
  dir_create(stage_dir, recurse = TRUE)
  on.exit(if (dir_exists(stage_dir)) try(dir_delete(stage_dir), silent = TRUE), add = TRUE)

  projects_restore <- read_drive_restore_csv(project_folder_id, "snapshots/project.csv", stage_dir, settings)
  if (nrow(projects_restore) == 0 || !("id" %in% names(projects_restore))) {
    return(list(restored = FALSE, project_id = "", project_name = project_folder_name, reason = "Missing project snapshot"))
  }
  projects_restore <- projects_restore[1, , drop = FALSE]
  project_id <- as.character(projects_restore$id[[1]] %||% "")
  if (!nzchar(project_id)) return(list(restored = FALSE, project_id = "", project_name = project_folder_name, reason = "Project snapshot has no Project ID"))
  try(local({
    con_clear <- connect_db()
    on.exit(if (DBI::dbIsValid(con_clear)) dbDisconnect(con_clear), add = TRUE)
    ensure_drive_sync_schema(con_clear)
    dbExecute(con_clear, "DELETE FROM drive_file_map WHERE project_id = ?;", params = list(project_id))
  }), silent = TRUE)

  expenses_restore <- read_drive_restore_csv(project_folder_id, "snapshots/expenses.csv", stage_dir, settings)
  attachments_restore <- read_drive_restore_csv(project_folder_id, "snapshots/attachments.csv", stage_dir, settings)
  breakdowns_restore <- read_drive_restore_csv(project_folder_id, "snapshots/expense_breakdowns.csv", stage_dir, settings)
  project_reports_restore <- read_drive_restore_csv(project_folder_id, "snapshots/project_reports.csv", stage_dir, settings)
  project_report_supporting_docs_restore <- read_drive_restore_csv(project_folder_id, "snapshots/project_report_supporting_docs.csv", stage_dir, settings)
  archive_groups_restore <- read_drive_restore_csv(project_folder_id, "snapshots/archive_groups.csv", stage_dir, settings)
  contacts_restore <- read_drive_restore_csv(project_folder_id, "snapshots/project_contacts.csv", stage_dir, settings)
  scheduled_emails_restore <- read_drive_restore_csv(project_folder_id, "snapshots/scheduled_emails.csv", stage_dir, settings)
  scheduled_email_recipients_restore <- read_drive_restore_csv(project_folder_id, "snapshots/scheduled_email_recipients.csv", stage_dir, settings)
  scheduled_email_attachments_restore <- read_drive_restore_csv(project_folder_id, "snapshots/scheduled_email_attachments.csv", stage_dir, settings)

  if (nrow(expenses_restore) > 0 && any(as.character(expenses_restore$project_id) != project_id)) stop("Drive snapshot expense scope mismatch for project ", project_id)
  if (nrow(project_reports_restore) > 0 && "project_id" %in% names(project_reports_restore) && any(as.character(project_reports_restore$project_id) != project_id)) stop("Drive snapshot report scope mismatch for project ", project_id)
  if (nrow(project_report_supporting_docs_restore) > 0 && "project_id" %in% names(project_report_supporting_docs_restore) && any(as.character(project_report_supporting_docs_restore$project_id) != project_id)) stop("Drive snapshot uploaded file scope mismatch for project ", project_id)
  if (nrow(contacts_restore) > 0 && "project_id" %in% names(contacts_restore) && any(as.character(contacts_restore$project_id) != project_id)) stop("Drive snapshot contact scope mismatch for project ", project_id)
  if (nrow(scheduled_emails_restore) > 0 && "project_id" %in% names(scheduled_emails_restore) && any(as.character(scheduled_emails_restore$project_id) != project_id)) stop("Drive snapshot scheduled email scope mismatch for project ", project_id)
  if (nrow(scheduled_email_recipients_restore) > 0 && "project_id" %in% names(scheduled_email_recipients_restore) && any(as.character(scheduled_email_recipients_restore$project_id) != project_id)) stop("Drive snapshot scheduled email recipient scope mismatch for project ", project_id)
  if (nrow(scheduled_email_attachments_restore) > 0 && "project_id" %in% names(scheduled_email_attachments_restore) && any(as.character(scheduled_email_attachments_restore$project_id) != project_id)) stop("Drive snapshot scheduled email attachment scope mismatch for project ", project_id)

  attachments_restore <- restore_drive_attachment_files(project_folder_id, project_id, attachments_restore, settings)
  project_reports_restore <- restore_drive_project_report_files(project_folder_id, project_id, project_reports_restore, settings)
  project_report_supporting_docs_restore <- restore_drive_project_supporting_doc_files(project_folder_id, project_id, project_report_supporting_docs_restore, settings)
  scheduled_email_attachments_restore <- restore_drive_scheduled_email_attachment_files(project_folder_id, project_id, scheduled_email_attachments_restore, settings)
  if (nrow(attachments_restore) > 0 && nrow(expenses_restore) > 0 && "expense_id" %in% names(attachments_restore) && "filepath" %in% names(attachments_restore)) {
    for (expense_id in unique(as.character(attachments_restore$expense_id))) {
      idx <- which(as.character(expenses_restore$id) == expense_id)
      att_idx <- which(as.character(attachments_restore$expense_id) == expense_id & nzchar(as.character(attachments_restore$filepath)))
      if (length(idx) > 0 && length(att_idx) > 0 && "receipt_path" %in% names(expenses_restore)) {
        expenses_restore$receipt_path[[idx[[1]]]] <- as.character(attachments_restore$filepath[[att_idx[[1]]]])
      }
    }
  }

  report_rows <- restore_drive_report_files(project_folder_id, project_id, settings)
  workbook_dest <- file.path(internal_exports_dir, paste0("drive_restore_", project_id, "_project_workbook.xlsx"))
  workbook_res <- drive_restore_download_remote_path(project_folder_id, "workbooks/project_workbook.xlsx", workbook_dest, settings)
  if (isTRUE(workbook_res$ok)) projects_restore$workbook_path <- rep(workbook_res$path, nrow(projects_restore))

  projects_restore$drive_folder_id <- rep(project_folder_id, nrow(projects_restore))
  projects_restore$drive_last_synced_at <- rep(now(), nrow(projects_restore))
  projects_restore$drive_sync_error <- rep("", nrow(projects_restore))
  projects_restore$drive_pending_sync <- rep(0L, nrow(projects_restore))
  projects_restore$is_trashed <- rep(0L, nrow(projects_restore))
  if ("status" %in% names(projects_restore) && nrow(projects_restore) > 0) {
    projects_restore$status <- vapply(projects_restore$status, normalize_project_status, character(1))
  }
  if ("team_members" %in% names(projects_restore) && nrow(projects_restore) > 0) {
    projects_restore$team_members <- vapply(projects_restore$team_members, normalize_team_members_text, character(1))
  }

  con <- connect_db()
  on.exit(if (DBI::dbIsValid(con)) dbDisconnect(con), add = TRUE)
  ensure_projects_schema(con)
  ensure_expenses_schema(con)
  ensure_drive_sync_schema(con)
  ensure_project_reports_schema(con)
  ensure_project_report_supporting_docs_schema(con)
  ensure_communications_schema(con)
  ensure_archive_schema(con)
  dbBegin(con)
  committed <- FALSE
  on.exit(if (!committed) try(dbRollback(con), silent = TRUE), add = TRUE)
  dbExecute(con, "DELETE FROM attachments WHERE expense_id IN (SELECT id FROM expenses WHERE project_id = ?);", params = list(project_id))
  dbExecute(con, "DELETE FROM expense_breakdowns WHERE expense_id IN (SELECT id FROM expenses WHERE project_id = ?);", params = list(project_id))
  dbExecute(con, "DELETE FROM exports_meta WHERE criteria = ?;", params = list(project_id))
  dbExecute(con, "DELETE FROM project_reports WHERE project_id = ?;", params = list(project_id))
  dbExecute(con, "DELETE FROM project_report_supporting_docs WHERE project_id = ?;", params = list(project_id))
  dbExecute(con, "DELETE FROM scheduled_email_attachments WHERE project_id = ?;", params = list(project_id))
  dbExecute(con, "DELETE FROM scheduled_email_recipients WHERE project_id = ?;", params = list(project_id))
  dbExecute(con, "DELETE FROM scheduled_emails WHERE project_id = ?;", params = list(project_id))
  dbExecute(con, "DELETE FROM project_contacts WHERE project_id = ?;", params = list(project_id))
  dbExecute(con, "DELETE FROM expenses WHERE project_id = ?;", params = list(project_id))
  dbExecute(con, "DELETE FROM projects WHERE id = ?;", params = list(project_id))

  projects_restore <- align_restore_table(con, "projects", projects_restore)
  projects_restore <- prepare_projects_access_keys_for_restore(projects_restore, con, exclude_project_ids = as.character(project_id))
  expenses_restore <- align_restore_table(con, "expenses", expenses_restore)
  attachments_restore <- align_restore_table(con, "attachments", attachments_restore)
  breakdowns_restore <- align_restore_table(con, "expense_breakdowns", breakdowns_restore)
  report_rows <- align_restore_table(con, "exports_meta", report_rows)
  project_reports_restore <- align_restore_table(con, "project_reports", project_reports_restore)
  project_report_supporting_docs_restore <- align_restore_table(con, "project_report_supporting_docs", project_report_supporting_docs_restore)
  archive_groups_restore <- align_restore_table(con, "archive_groups", archive_groups_restore)
  contacts_restore <- align_restore_table(con, "project_contacts", contacts_restore)
  scheduled_emails_restore <- align_restore_table(con, "scheduled_emails", scheduled_emails_restore)
  scheduled_email_recipients_restore <- align_restore_table(con, "scheduled_email_recipients", scheduled_email_recipients_restore)
  scheduled_email_attachments_restore <- align_restore_table(con, "scheduled_email_attachments", scheduled_email_attachments_restore)

  upsert_archive_groups_restore(con, archive_groups_restore)

  if (nrow(projects_restore) > 0) dbWriteTable(con, "projects", projects_restore, append = TRUE, row.names = FALSE)
  if (nrow(expenses_restore) > 0) dbWriteTable(con, "expenses", expenses_restore, append = TRUE, row.names = FALSE)
  if (nrow(attachments_restore) > 0) dbWriteTable(con, "attachments", attachments_restore, append = TRUE, row.names = FALSE)
  if (nrow(breakdowns_restore) > 0) dbWriteTable(con, "expense_breakdowns", breakdowns_restore, append = TRUE, row.names = FALSE)
  if (nrow(report_rows) > 0) dbWriteTable(con, "exports_meta", report_rows, append = TRUE, row.names = FALSE)
  if (nrow(project_reports_restore) > 0) dbWriteTable(con, "project_reports", project_reports_restore, append = TRUE, row.names = FALSE)
  if (nrow(project_report_supporting_docs_restore) > 0) dbWriteTable(con, "project_report_supporting_docs", project_report_supporting_docs_restore, append = TRUE, row.names = FALSE)
  if (nrow(contacts_restore) > 0) dbWriteTable(con, "project_contacts", contacts_restore, append = TRUE, row.names = FALSE)
  if (nrow(scheduled_emails_restore) > 0) dbWriteTable(con, "scheduled_emails", scheduled_emails_restore, append = TRUE, row.names = FALSE)
  if (nrow(scheduled_email_recipients_restore) > 0) dbWriteTable(con, "scheduled_email_recipients", scheduled_email_recipients_restore, append = TRUE, row.names = FALSE)
  if (nrow(scheduled_email_attachments_restore) > 0) dbWriteTable(con, "scheduled_email_attachments", scheduled_email_attachments_restore, append = TRUE, row.names = FALSE)
  dbCommit(con)
  committed <- TRUE

  workbook_path <- try(sync_project_workbook(project_id), silent = TRUE)
  if (!inherits(workbook_path, "try-error") && !identical(workbook_path, FALSE) && nzchar(as.character(workbook_path %||% ""))) {
    workbook_remote <- drive_backend_find_remote_path(project_folder_id, "workbooks/project_workbook.xlsx", settings)
    if (nrow(workbook_remote) == 1 && file_exists(workbook_path)) {
      save_drive_file_map_entry(
        project_id = project_id,
        local_key = "workbook::project_workbook",
        local_path = normalizePath(workbook_path, winslash = "/", mustWork = FALSE),
        remote_path = "workbooks/project_workbook.xlsx",
        remote_name = "project_workbook.xlsx",
        drive_file_id = as.character(workbook_remote$id[[1]]),
        checksum = file_checksum(workbook_path)
      )
    }
  }
  update_project_drive_sync_state(project_id, folder_id = project_folder_id, success = TRUE, error_message = "")
  try(log_audit(module = "Google Drive", action = "restore_project", target_table = "projects", target_id = project_id, detail = list(folder_id = project_folder_id), workspace_id = project_id, trigger_sync = FALSE), silent = TRUE)
  list(restored = TRUE, project_id = project_id, project_name = as.character(projects_restore$name[[1]] %||% project_folder_name), reason = "")
}

restore_from_google_drive <- function() {
  status <- drive_sync_status()
  if (!isTRUE(status$ok)) stop(status$reason)
  settings <- status$settings
  drive_backend_authenticate(settings)
  root_id <- ensure_drive_root_folder(settings)
  folders <- drive_backend_list_children(root_id, settings, type = "folder")
  if (nrow(folders) == 0) {
    append_drive_sync_log("INFO", "Drive restore found no project folders.")
    return(list(restored_projects = 0L, skipped_projects = 0L, details = data.frame()))
  }
  details <- list()
  restored_count <- 0L
  skipped_count <- 0L
  for (i in seq_len(nrow(folders))) {
    folder <- folders[i, , drop = FALSE]
    res <- tryCatch(
      restore_single_project_from_drive_folder(folder, settings),
      error = function(e) list(restored = FALSE, project_id = "", project_name = as.character(folder$name[[1]] %||% ""), reason = format_drive_error(e))
    )
    if (isTRUE(res$restored)) restored_count <- restored_count + 1L else skipped_count <- skipped_count + 1L
    details[[length(details) + 1]] <- data.frame(
      project_id = as.character(res$project_id %||% ""),
      project_name = as.character(res$project_name %||% ""),
      restored = isTRUE(res$restored),
      reason = as.character(res$reason %||% ""),
      stringsAsFactors = FALSE
    )
  }
  detail_df <- if (length(details) == 0) data.frame() else do.call(rbind, details)
  append_drive_sync_log("INFO", "Drive restore completed.", detail = list(restored_projects = restored_count, skipped_projects = skipped_count))
  list(restored_projects = restored_count, skipped_projects = skipped_count, details = detail_df)
}
drive_sync_runtime <- local({
  env <- new.env(parent = emptyenv())
  env$future_job <- NULL
  env$future_lease_token <- ""
  env$plan_ready <- FALSE
  env
})

cleanup_drive_sync_future_job <- function() {
  if (is.null(drive_sync_runtime$future_job)) return(invisible(FALSE))
  if (!future::resolved(drive_sync_runtime$future_job)) return(invisible(FALSE))

  lease_token <- as.character(drive_sync_runtime$future_lease_token %||% "")
  result <- tryCatch(
    suppressWarnings(future::value(drive_sync_runtime$future_job)),
    error = function(e) e
  )

  if (inherits(result, "error")) {
    message_text <- conditionMessage(result)
    append_drive_sync_log("ERROR", paste0("Drive sync background task failed: ", message_text))
    if (nzchar(lease_token)) try(release_drive_sync_lease(lease_token, success = FALSE, error_message = message_text), silent = TRUE)
  } else if (!isTRUE(result)) {
    message_text <- "Drive sync background task exited before completing successfully."
    append_drive_sync_log("ERROR", message_text)
    if (nzchar(lease_token)) try(release_drive_sync_lease(lease_token, success = FALSE, error_message = message_text), silent = TRUE)
  }

  drive_sync_runtime$future_job <- NULL
  drive_sync_runtime$future_lease_token <- ""
  invisible(isTRUE(result))
}

ensure_drive_future_plan <- function() {
  if (!has_future) return(FALSE)
  if (isTRUE(drive_sync_runtime$plan_ready)) return(TRUE)
  ok <- tryCatch({
    future::plan(future::multisession, workers = 1L)
    TRUE
  }, error = function(e) {
    append_drive_sync_log("ERROR", paste0("Unable to configure background Drive sync worker: ", e$message))
    FALSE
  })
  drive_sync_runtime$plan_ready <- isTRUE(ok)
  ok
}

launch_background_drive_sync_once_process <- function(reason = "scheduled") {
  expr <- paste0(
    "Sys.setenv(BUDGET_APP_MODE='worker', BUDGET_APP_ROOT=", r_string_literal(app_root), ");",
    "app_env <- new.env(parent = globalenv());",
    "source(", r_string_literal(file.path(startup_app_root, "app.R")), ", local = app_env, chdir = TRUE, encoding = 'UTF-8');",
    "result <- app_env$run_background_drive_sync_once(reason = ", r_string_literal(as.character(reason %||% "scheduled")), ");",
    "quit(save = 'no', status = if (isTRUE(result)) 0L else 1L)"
  )
  launch_detached_rscript(expr, log_path = drive_sync_log_file, reason = paste0("drive_sync_once:", as.character(reason %||% "scheduled")))
}

start_drive_sync_worker <- function(reason = "scheduled") {
  settings <- get_drive_sync_settings()
  if (isTRUE(settings$enabled) && identical(settings$backend, "google_drive") && (!has_googledrive || !has_gargle)) {
    install_ok <- tryCatch({
      ensure_drive_packages_installed()
      TRUE
    }, error = function(e) {
      append_drive_sync_log("ERROR", paste0("Unable to prepare Google Drive backup packages: ", e$message), detail = list(reason = reason))
      FALSE
    })
    if (!isTRUE(install_ok)) return(FALSE)
  }
  status <- drive_sync_status(settings)
  if (!isTRUE(status$ok)) {
    if (isTRUE(status$settings$enabled)) append_drive_sync_log("ERROR", status$reason, detail = list(reason = reason))
    return(FALSE)
  }
  if (can_launch_background_scheduler()) {
    launched <- isTRUE(launch_background_drive_sync_once_process(reason = reason))
    if (launched) return(TRUE)
  }
  if (!has_future) {
    append_drive_sync_log("ERROR", "The optional 'future' package is required for background Drive sync.", detail = list(reason = reason))
    return(FALSE)
  }
  if (!isTRUE(ensure_drive_future_plan())) {
    return(FALSE)
  }
  if (!is.null(drive_sync_runtime$future_job)) {
    cleanup_drive_sync_future_job()
    if (!is.null(drive_sync_runtime$future_job)) {
      return(FALSE)
    }
  }
  lease <- acquire_drive_sync_lease(ttl_sec = max(900L, as.integer(status$settings$interval_sec) * 2L))
  if (!isTRUE(lease$acquired)) return(FALSE)
  drive_sync_runtime$future_lease_token <- as.character(lease$token %||% "")
  ok <- tryCatch({
    drive_sync_runtime$future_job <- future::future(
      {
        Sys.setenv(BUDGET_APP_MODE = "worker", BUDGET_APP_ROOT = app_root)
        original_wd <- getwd()
        on.exit(setwd(original_wd), add = TRUE)
        setwd(startup_app_root)
        app_env <- new.env(parent = globalenv())
        source(file.path(startup_app_root, "app.R"), local = app_env, chdir = TRUE, encoding = "UTF-8")
        isTRUE(app_env$run_drive_sync_cycle(lease_token = lease$token, reason = as.character(reason %||% "scheduled")))
      },
      seed = TRUE
    )
    TRUE
  }, error = function(e) {
    drive_sync_runtime$future_lease_token <- ""
    release_drive_sync_lease(lease$token, success = FALSE, error_message = e$message)
    append_drive_sync_log("ERROR", paste0("Unable to start Drive sync background task: ", e$message), detail = list(reason = reason))
    FALSE
  })
  ok
}

initialize_drive_sync_scheduler <- local({
  scheduler_started <- FALSE
  function(force = FALSE) {
    if (!identical(app_mode, "app")) return(invisible(FALSE))
    if (scheduler_started && !isTRUE(force)) return(invisible(TRUE))
    scheduler_started <<- TRUE
    schedule_next <- function() {
      delay <- get_drive_sync_settings()$interval_sec
      later::later(function() {
        try(start_drive_sync_worker("scheduled"), silent = TRUE)
        schedule_next()
      }, delay = delay)
    }
    later::later(function() {
      try(start_drive_sync_worker("startup"), silent = TRUE)
      schedule_next()
    }, delay = 5)
    invisible(TRUE)
  }
})

load_workspace_project <- function(workspace_id, include_trashed = FALSE, busy_timeout_ms = 60000L, retries = 5L, base_delay = 0.2) {
  con <- connect_db(busy_timeout_ms = busy_timeout_ms, retries = retries, base_delay = base_delay)
  on.exit(dbDisconnect(con))
  if (is.null(workspace_id) || !nzchar(as.character(workspace_id))) return(data.frame())
  sql <- "SELECT * FROM projects WHERE id = ?"
  if (!isTRUE(include_trashed)) sql <- paste0(sql, " AND is_trashed = 0")
  sql <- paste0(sql, " LIMIT 1;")
  dbGetQuery(con, sql, params = list(as.character(workspace_id)))
}

get_project_access_key <- function(project_id) {
  project_row <- load_workspace_project(project_id, include_trashed = TRUE)
  if (nrow(project_row) != 1) return("")
  normalize_project_access_key(project_row$access_key[[1]] %||% "")
}

resolve_workspace_id <- function(target_table = NA, target_id = NA, detail = list()) {
  detail_list <- detail
  if (is.character(detail_list) && length(detail_list) == 1 && nzchar(detail_list)) {
    detail_list <- tryCatch(jsonlite::fromJSON(detail_list, simplifyVector = TRUE), error = function(e) list())
  }
  if (!is.list(detail_list)) detail_list <- list()

  if (!is.null(detail_list$workspace_id) && nzchar(as.character(detail_list$workspace_id))) {
    return(as.character(detail_list$workspace_id))
  }
  if (!is.null(detail_list$project_id) && nzchar(as.character(detail_list$project_id))) {
    return(as.character(detail_list$project_id))
  }
  if (!is.na(target_table) && identical(target_table, "projects") && nzchar(as.character(target_id %||% ""))) {
    return(as.character(target_id))
  }

  con <- connect_db(); on.exit(dbDisconnect(con), add = TRUE)

  if (!is.na(target_table) && identical(target_table, "expenses") && nzchar(as.character(target_id %||% ""))) {
    res <- dbGetQuery(con, "SELECT project_id FROM expenses WHERE id = ? LIMIT 1;", params = list(target_id))
    if (nrow(res) == 1 && nzchar(as.character(res$project_id[[1]] %||% ""))) return(as.character(res$project_id[[1]]))
  }
  if (!is.na(target_table) && identical(target_table, "attachments") && nzchar(as.character(target_id %||% ""))) {
    res <- dbGetQuery(con, "
      SELECT e.project_id
      FROM attachments a
      INNER JOIN expenses e ON e.id = a.expense_id
      WHERE a.id = ? LIMIT 1;
    ", params = list(target_id))
    if (nrow(res) == 1 && nzchar(as.character(res$project_id[[1]] %||% ""))) return(as.character(res$project_id[[1]]))
  }
  if (!is.na(target_table) && identical(target_table, "exports_meta") && nzchar(as.character(target_id %||% ""))) {
    res <- dbGetQuery(con, "SELECT criteria FROM exports_meta WHERE id = ? LIMIT 1;", params = list(target_id))
    if (nrow(res) == 1 && nzchar(as.character(res$criteria[[1]] %||% ""))) return(as.character(res$criteria[[1]]))
  }
  if (!is.na(target_table) && identical(target_table, "backups") && nzchar(as.character(target_id %||% ""))) {
    res <- dbGetQuery(con, "SELECT workspace_id FROM backups WHERE id = ? LIMIT 1;", params = list(target_id))
    if (nrow(res) == 1 && nzchar(as.character(res$workspace_id[[1]] %||% ""))) return(as.character(res$workspace_id[[1]]))
  }
  if (!is.na(target_table) && identical(target_table, "project_contacts") && nzchar(as.character(target_id %||% ""))) {
    res <- dbGetQuery(con, "SELECT project_id FROM project_contacts WHERE id = ? LIMIT 1;", params = list(target_id))
    if (nrow(res) == 1 && nzchar(as.character(res$project_id[[1]] %||% ""))) return(as.character(res$project_id[[1]]))
  }
  if (!is.na(target_table) && identical(target_table, "scheduled_emails") && nzchar(as.character(target_id %||% ""))) {
    res <- dbGetQuery(con, "SELECT project_id FROM scheduled_emails WHERE id = ? LIMIT 1;", params = list(target_id))
    if (nrow(res) == 1 && nzchar(as.character(res$project_id[[1]] %||% ""))) return(as.character(res$project_id[[1]]))
  }
  if (!is.na(target_table) && identical(target_table, "scheduled_email_recipients") && nzchar(as.character(target_id %||% ""))) {
    res <- dbGetQuery(con, "SELECT project_id FROM scheduled_email_recipients WHERE id = ? LIMIT 1;", params = list(target_id))
    if (nrow(res) == 1 && nzchar(as.character(res$project_id[[1]] %||% ""))) return(as.character(res$project_id[[1]]))
  }

  NA_character_
}

# Categories helpers (persisted in data layer only; NOT exposed in Settings UI)
load_categories <- function() {
  con <- connect_db(); on.exit(dbDisconnect(con))
  cats <- dbGetQuery(con, "SELECT * FROM categories ORDER BY main, sub;")
  if (nrow(cats) == 0) return(data.frame(main=character(), sub=character(), stringsAsFactors = FALSE))
  cats
}
get_main_categories <- function() {
  cats <- load_categories()
  unique(cats$main)
}
get_subcategories <- function(main_name) {
  if (is.null(main_name) || !nzchar(main_name)) return(character(0))
  cats <- load_categories()
  subs <- cats %>% filter(.data$main == main_name) %>% pull(sub) %>% unique()
  if (length(subs) == 0) return(character(0))
  subs
}
add_category <- function(main, sub = "") {
  if (is.null(main) || !nzchar(main)) return(FALSE)
  con <- connect_db(); on.exit(dbDisconnect(con))
  entry <- data.frame(id = uuid("cat"), main = as.character(main), sub = as.character(sub %||% ""), created_at = now(), stringsAsFactors = FALSE)
  dbWriteTable(con, "categories", entry, append = TRUE, row.names = FALSE)
  log_audit(module = "Categories", action = "create", target_table = "categories", target_id = entry$id, detail = list(main = main, sub = sub))
  TRUE
}
delete_category <- function(id) {
  con <- connect_db(); on.exit(dbDisconnect(con))
  rec <- dbGetQuery(con, "SELECT * FROM categories WHERE id = ? LIMIT 1;", params = list(id))
  if (nrow(rec) == 0) return(FALSE)
  dbExecute(con, "DELETE FROM categories WHERE id = ?;", params = list(id))
  log_audit(module = "Categories", action = "delete", target_table = "categories", target_id = id, detail = list())
  TRUE
}

# ---------------------------
# Expense breakdown helpers (NEW ADDITIVE MODULE)
# - The following functions and DB table are additive.
# - They store breakdown entries linked to a parent expense.
# ---------------------------
# Create or replace breakdowns for an expense.
# entries: data.frame or list of lists with 'label' and 'amount'
create_breakdowns_for_expense <- function(expense_id, entries) {
  tryCatch({
    if (is.null(expense_id) || !nzchar(expense_id)) stop("create_breakdowns_for_expense requires expense_id")
    con <- connect_db(); on.exit(dbDisconnect(con))
    # remove existing breakdowns for this expense
    dbExecute(con, "DELETE FROM expense_breakdowns WHERE expense_id = ?;", params = list(expense_id))
    if (is.null(entries) || length(entries) == 0) return(TRUE)
    # normalize entries to data.frame
    if (is.data.frame(entries)) {
      df <- entries
      if (!("label" %in% names(df)) || !("amount" %in% names(df))) stop("entries must include label and amount")
    } else {
      # assume list of lists
      rows <- lapply(entries, function(e) {
        label <- e$label %||% e[[1]] %||% ""
        amount <- as.numeric(e$amount %||% e[[2]] %||% 0)
        data.frame(id = uuid("bkd"), expense_id = expense_id, label = as.character(label), amount = amount, created_at = now(), stringsAsFactors = FALSE)
      })
      df <- do.call(rbind, rows)
    }
    # ensure id, expense_id, label, amount, created_at present
    if (!("id" %in% names(df))) df$id <- vapply(seq_len(nrow(df)), function(i) uuid("bkd"), character(1))
    df$expense_id <- rep(as.character(expense_id), nrow(df))
    if (!("created_at" %in% names(df))) {
      df$created_at <- rep(now(), nrow(df))
    } else {
      df$created_at <- as.character(df$created_at %||% rep(now(), nrow(df)))
    }
    # write to DB
    dbWriteTable(con, "expense_breakdowns", df %>% select(id, expense_id, label, amount, created_at), append = TRUE, row.names = FALSE)
    TRUE
  }, error = function(e) {
    message("create_breakdowns_for_expense error: ", e$message); FALSE
  })
}

# Retrieve breakdowns for an expense
get_breakdowns <- function(expense_id) {
  con <- connect_db(); on.exit(dbDisconnect(con))
  if (is.null(expense_id) || !nzchar(expense_id)) return(data.frame())
  df <- dbGetQuery(con, "SELECT * FROM expense_breakdowns WHERE expense_id = ? ORDER BY created_at;", params = list(expense_id))
  df
}

# ---------------------------
# Per-project workbook sync (only that project's data)
# Modified slightly (additive) to include breakdown rows indented under each expense in the "Expenses" sheet.
# ---------------------------
sync_project_workbook <- function(project_id) {
  if (is.null(project_id) || !nzchar(as.character(project_id))) {
    message("sync_project_workbook requires a valid project_id")
    return(invisible(FALSE))
  }
  tryCatch({
    build_scope_expense_rows <- function(expense_rows) {
      expense_rows <- normalize_expenses_frame(expense_rows)
      if (nrow(expense_rows) == 0) {
        return(data.frame(
          ID = character(),
          Description = character(),
          Amount = numeric(),
          Category = character(),
          Subcategory = character(),
          Date = character(),
          Receipt = character(),
          Created = character(),
          stringsAsFactors = FALSE
        ))
      }
      expense_rows <- expense_rows %>%
        mutate(
          category_main = ifelse(
            is.na(category_main) | category_main == "",
            ifelse(is.na(category) | category == "", "Uncategorized", sub(" -.*$", "", category)),
            category_main
          ),
          category_sub = ifelse(
            is.na(category_sub) | category_sub == "",
            ifelse(grepl(" - ", category), sub("^.* - ", "", category), ""),
            category_sub
          )
        )
      combined_rows <- data.frame(
        ID = character(),
        Description = character(),
        Amount = numeric(),
        Category = character(),
        Subcategory = character(),
        Date = character(),
        Receipt = character(),
        Created = character(),
        stringsAsFactors = FALSE
      )
      for (k in seq_len(nrow(expense_rows))) {
        row <- expense_rows[k, ]
        combined_rows <- rbind(
          combined_rows,
          data.frame(
            ID = row$id,
            Description = row$description,
            Amount = row$amount,
            Category = row$category_main,
            Subcategory = row$category_sub,
            Date = row$date,
            Receipt = ifelse(row$receipt_path == "", "", "Has Receipt"),
            Created = row$created_at,
            stringsAsFactors = FALSE
          )
        )
        bks <- get_breakdowns(row$id)
        if (nrow(bks) > 0) {
          for (bi in seq_len(nrow(bks))) {
            bk <- bks[bi, ]
            combined_rows <- rbind(
              combined_rows,
              data.frame(
                ID = "",
                Description = paste0("  - ", bk$label),
                Amount = bk$amount,
                Category = "",
                Subcategory = "",
                Date = "",
                Receipt = "",
                Created = bk$created_at,
                stringsAsFactors = FALSE
              )
            )
          }
        }
      }
      combined_rows
    }

    write_scope_breakdown_sheet <- function(wb, sheet_name, expense_rows, hdr_style, money_style) {
      addWorksheet(wb, sheet_name)
      if (nrow(expense_rows) == 0) {
        writeData(wb, sheet_name, data.frame(Message = "No expenses for this financial view"), startRow = 1)
        return(invisible(TRUE))
      }
      expense_rows <- expense_rows %>%
        mutate(
          category_main = ifelse(
            is.na(category_main) | category_main == "",
            ifelse(is.na(category) | category == "", "Uncategorized", sub(" -.*$", "", category)),
            category_main
          ),
          category_sub = ifelse(
            is.na(category_sub) | category_sub == "",
            ifelse(grepl(" - ", category), sub("^.* - ", "", category), ""),
            category_sub
          )
        )
      main_totals <- expense_rows %>%
        group_by(category_main) %>%
        summarise(MainTotal = sum(amount, na.rm = TRUE), .groups = "drop") %>%
        arrange(desc(MainTotal))
      startrow <- 1
      writeData(wb, sheet_name, "Category Summary", startRow = startrow, startCol = 1)
      addStyle(wb, sheet_name, hdr_style, rows = startrow, cols = 1, gridExpand = TRUE)
      startrow <- startrow + 1
      for (i in seq_len(nrow(main_totals))) {
        mainc <- main_totals$category_main[i]
        mtotal <- main_totals$MainTotal[i]
        writeData(wb, sheet_name, c(mainc, mtotal), startRow = startrow, startCol = 1)
        addStyle(
          wb,
          sheet_name,
          createStyle(fontSize = 11, textDecoration = "bold", fgFill = "#EAF3FF"),
          rows = startrow,
          cols = 1:2,
          gridExpand = TRUE
        )
        startrow <- startrow + 1
        sub_df <- expense_rows %>%
          filter(category_main == mainc) %>%
          group_by(category_sub) %>%
          summarise(SubTotal = sum(amount, na.rm = TRUE), .groups = "drop") %>%
          arrange(desc(SubTotal))
        if (nrow(sub_df) > 0) {
          for (j in seq_len(nrow(sub_df))) {
            writeData(wb, sheet_name, c(paste0("  - ", sub_df$category_sub[j]), sub_df$SubTotal[j]), startRow = startrow, startCol = 1)
            addStyle(wb, sheet_name, createStyle(indent = 1), rows = startrow, cols = 1:2, gridExpand = TRUE)
            startrow <- startrow + 1
          }
        }
        startrow <- startrow + 1
      }
      try(addStyle(wb, sheet_name, money_style, rows = 2:startrow, cols = 2, gridExpand = TRUE), silent = TRUE)
      invisible(TRUE)
    }

    write_scope_expense_sheet <- function(wb, sheet_name, expense_rows, money_style) {
      addWorksheet(wb, sheet_name)
      combined_rows <- build_scope_expense_rows(expense_rows)
      if (nrow(combined_rows) == 0) {
        writeData(wb, sheet_name, data.frame(Message = "No expenses for this financial view"), startRow = 1)
        return(invisible(TRUE))
      }
      writeDataTable(wb, sheet_name, combined_rows, tableStyle = "TableStyleMedium9")
      try(addStyle(wb, sheet_name, money_style, rows = 2:(nrow(combined_rows) + 1), cols = 3, gridExpand = TRUE), silent = TRUE)
      try(
        writeData(
          wb,
          sheet_name,
          x = data.frame(Total = sum(as.numeric(expense_rows$amount), na.rm = TRUE)),
          startRow = nrow(combined_rows) + 3,
          startCol = 3
        ),
        silent = TRUE
      )
      invisible(TRUE)
    }

    con <- connect_db(); on.exit(dbDisconnect(con))
    ensure_projects_schema(con)
    ensure_expenses_schema(con)
    pr <- dbGetQuery(con, "SELECT * FROM projects WHERE id = ? LIMIT 1;", params = list(project_id))
    if (nrow(pr) == 0) return(invisible(FALSE))
    pr <- pr[1, ]
    ex <- dbGetQuery(con, "SELECT * FROM expenses WHERE project_id = ? AND is_trashed = 0;", params = list(project_id))
    ex <- normalize_expenses_frame(ex)
    admin_ex <- filter_expenses_by_scope(ex, expense_scope = "administrator", include_trashed = FALSE)
    scientist_ex <- filter_expenses_by_scope(ex, expense_scope = "scientist", include_trashed = FALSE)
    attachments_df <- dbGetQuery(con, "SELECT * FROM attachments WHERE expense_id IN (SELECT id FROM expenses WHERE project_id = ?);", params = list(project_id))
    related_audit <- dbGetQuery(con, "SELECT * FROM audit WHERE workspace_id = ? ORDER BY timestamp DESC LIMIT 2000;", params = list(project_id))
    
    wb <- createWorkbook()
    hdrStyle <- createStyle(fontSize = 12, textDecoration = "bold", halign = "center")
    moneyStyle <- createStyle(numFmt = "ACCOUNTING")
    
    # Summary
    addWorksheet(wb, "Summary")
    summary_df <- data.frame(
      ProjectID = pr$id,
      Name = pr$name,
      PrincipleInvestigator = ifelse(nzchar(trimws(as.character(pr$principal_investigator %||% ""))), as.character(pr$principal_investigator), "Not provided"),
      TeamMembers = format_team_members_inline(pr$team_members %||% "", empty = "Not provided"),
      Description = pr$description,
      Budget = as.numeric(pr$budget_total),
      AdminSpent = sum(as.numeric(admin_ex$amount), na.rm = TRUE),
      AdminRemaining = as.numeric(pr$budget_total) - sum(as.numeric(admin_ex$amount), na.rm = TRUE),
      ScientistSpent = sum(as.numeric(scientist_ex$amount), na.rm = TRUE),
      ScientistRemaining = as.numeric(pr$budget_total) - sum(as.numeric(scientist_ex$amount), na.rm = TRUE),
      Status = normalize_project_status(pr$status),
      Start = pr$start_date,
      End = pr$end_date,
      LastUpdate = pr$updated_at,
      stringsAsFactors = FALSE
    )
    writeData(wb, "Summary", summary_df, startRow = 1, startCol = 1)
    addStyle(wb, "Summary", hdrStyle, rows = 1, cols = 1:ncol(summary_df), gridExpand = TRUE)
    writeData(
      wb,
      "Summary",
      x = data.frame(
        Label = c(
          "Admin Total Spent",
          "Admin Remaining Balance",
          "User/Scientist Total Spent",
          "User/Scientist Remaining Balance"
        ),
        Value = c(
          summary_df$AdminSpent,
          summary_df$AdminRemaining,
          summary_df$ScientistSpent,
          summary_df$ScientistRemaining
        )
      ),
      startRow = 4,
      startCol = 1
    )
    addStyle(wb, "Summary", createStyle(fontSize = 10, textDecoration = "bold"), rows = 4:7, cols = 1, gridExpand = TRUE)
    addStyle(wb, "Summary", createStyle(fontSize = 10), rows = 4:7, cols = 2, gridExpand = TRUE)
    
    write_scope_breakdown_sheet(wb, "Admin Category Breakdown", admin_ex, hdrStyle, moneyStyle)
    write_scope_expense_sheet(wb, "Admin Expenses", admin_ex, moneyStyle)
    write_scope_breakdown_sheet(wb, "Scientist Category Breakdown", scientist_ex, hdrStyle, moneyStyle)
    write_scope_expense_sheet(wb, "Scientist Expenses", scientist_ex, moneyStyle)
    
    # Attachments
    addWorksheet(wb, "Attachments")
    if (nrow(attachments_df) > 0) {
      writeDataTable(wb, "Attachments", attachments_df %>% select(id, expense_id, filename, filepath, size, created_at))
    } else {
      writeData(wb, "Attachments", data.frame(Message = "No attachments for this project"))
    }
    
    # Audit (kept in Excel workbook but not included in PDF generation)
    addWorksheet(wb, "Audit")
    if (nrow(related_audit) > 0) {
      writeDataTable(wb, "Audit", related_audit, tableStyle = "TableStyleLight9")
    } else {
      writeData(wb, "Audit", data.frame(Message = "No audit entries for this project"), startRow = 1)
    }
    
    # Worksheet protection if requested
    pwd <- get_setting("excel_password") %||% ""
    protect_other <- tolower(as.character(get_setting("protect_other_sheets") %||% "false")) == "true"
    if (nzchar(pwd)) {
      try(protectWorksheet(wb, sheet = "Audit", protect = TRUE, password = pwd), silent = TRUE)
      if (protect_other) {
        other_sheets <- setdiff(names(wb), "Audit")
        for (s in other_sheets) try(protectWorksheet(wb, sheet = s, protect = TRUE, password = pwd), silent = TRUE)
      }
    }
    
    export_folder <- get_export_folder()
    dir_create(export_folder, recurse = TRUE)
    fname <- file.path(export_folder, paste0("project_", sanitize_filename(pr$name), "_", pr$id, ".xlsx"))
    saveWorkbook(wb, fname, overwrite = TRUE)
    fname_abs <- normalizePath(fname, winslash = "/", mustWork = FALSE)
    
    rec <- data.frame(id = uuid("exp"), filename = basename(fname_abs), filepath = fname_abs, type = "project_workbook", created_at = now(), criteria = project_id, stringsAsFactors = FALSE)
    dbWriteTable(con, "exports_meta", rec, append = TRUE, row.names = FALSE)
    try(dbExecute(con, "UPDATE projects SET workbook_path = ?, updated_at = ? WHERE id = ?;", params = list(fname_abs, now(), project_id)), silent = TRUE)
    
    log_audit(
      user = "system",
      module = "Reports",
      action = "sync_project_workbook",
      target_table = "exports_meta",
      target_id = rec$id,
      detail = list(path = fname_abs, project_id = project_id),
      workspace_id = project_id
    )
    
    invisible(fname_abs)
  }, error = function(e) {
    message("sync_project_workbook error: ", e$message)
    invisible(FALSE)
  })
}

project_workbook_sync_log_file <- file.path(logs_dir, "project_workbook_sync.log")
project_workbook_sync_queue_file <- file.path(runtime_dir, "project_workbook_sync_queue.json")

append_project_workbook_sync_log <- function(level = "INFO", message, project_id = "", detail = list()) {
  timestamp <- format(Sys.time(), "%Y-%m-%d %H:%M:%S")
  payload <- detail
  if (nzchar(as.character(project_id %||% ""))) payload$project_id <- as.character(project_id)
  suffix <- if (length(payload) > 0) paste0(" ", json_stringify(payload, auto_unbox = TRUE, null = "null")) else ""
  cat(paste0("[", timestamp, "] [", toupper(as.character(level %||% "INFO")), "] ", as.character(message %||% ""), suffix, "\n"), file = project_workbook_sync_log_file, append = TRUE)
  invisible(TRUE)
}

read_project_workbook_sync_queue <- function() {
  payload <- read_json_safe(project_workbook_sync_queue_file, default = list(project_ids = character()))
  project_ids <- as.character(payload$project_ids %||% character())
  project_ids <- unique(project_ids[nzchar(project_ids)])
  project_ids
}

write_project_workbook_sync_queue <- function(project_ids) {
  project_ids <- unique(as.character(project_ids %||% character()))
  project_ids <- project_ids[nzchar(project_ids)]
  write_json_atomic(
    project_workbook_sync_queue_file,
    list(
      project_ids = project_ids,
      updated_at = now()
    )
  )
  invisible(project_ids)
}

with_project_workbook_sync_queue_lock <- function(expr, retries = 20L, base_delay = 0.1) {
  for (attempt in seq_len(max(1L, as.integer(retries)))) {
    lease <- acquire_drive_sync_lease(lock_key = "project_workbook_sync_queue_write", ttl_sec = 30L)
    if (isTRUE(lease$acquired)) {
      success <- FALSE
      error_text <- ""
      on.exit(
        try(release_drive_sync_lease(as.character(lease$token %||% ""), success = success, error_message = error_text), silent = TRUE),
        add = TRUE
      )
      result <- tryCatch({
        value <- force(expr)
        success <<- TRUE
        value
      }, error = function(e) {
        error_text <<- as.character(e$message %||% "Workbook sync queue update failed.")
        stop(e)
      })
      return(result)
    }
    Sys.sleep(base_delay * attempt + stats::runif(1, min = 0, max = 0.05))
  }
  stop("Unable to access the workbook sync queue.")
}

enqueue_project_workbook_sync_request <- function(project_id) {
  project_id <- as.character(project_id %||% "")
  if (!nzchar(project_id)) return(character())
  with_project_workbook_sync_queue_lock({
    queue <- unique(c(read_project_workbook_sync_queue(), project_id))
    write_project_workbook_sync_queue(queue)
    queue
  })
}

pull_next_project_workbook_sync_request <- function() {
  with_project_workbook_sync_queue_lock({
    queue <- read_project_workbook_sync_queue()
    if (length(queue) == 0) return("")
    project_id <- queue[[1]]
    write_project_workbook_sync_queue(queue[-1])
    as.character(project_id %||% "")
  })
}

run_background_project_workbook_sync_queue <- function(reason = "queued") {
  lease <- acquire_drive_sync_lease(lock_key = "project_workbook_sync_queue_worker", ttl_sec = 900L)
  if (!isTRUE(lease$acquired)) return(FALSE)
  success <- TRUE
  final_error <- ""
  on.exit(
    try(release_drive_sync_lease(as.character(lease$token %||% ""), success = success, error_message = final_error), silent = TRUE),
    add = TRUE
  )
  repeat {
    heartbeat_drive_sync_lease(as.character(lease$token %||% ""), extend_sec = 900L)
    project_id <- tryCatch(pull_next_project_workbook_sync_request(), error = function(e) {
      success <<- FALSE
      final_error <<- as.character(e$message %||% "Unable to read workbook sync queue.")
      append_project_workbook_sync_log("ERROR", paste0("Workbook sync queue read failed: ", final_error))
      ""
    })
    if (!nzchar(project_id)) break
    result <- tryCatch({
      sync_path <- sync_project_workbook(project_id)
      isTRUE(!identical(sync_path, FALSE) && nzchar(as.character(sync_path %||% "")))
    }, error = function(e) {
      success <<- FALSE
      final_error <<- as.character(e$message %||% "Workbook sync failed.")
      append_project_workbook_sync_log("ERROR", paste0("Workbook sync failed: ", final_error), project_id = project_id, detail = list(reason = reason))
      FALSE
    })
    if (isTRUE(result)) {
      append_project_workbook_sync_log("INFO", "Background workbook sync completed.", project_id = project_id, detail = list(reason = reason))
    }
  }
  success
}

launch_background_project_workbook_sync_process <- function(reason = "queued") {
  expr <- paste0(
    "Sys.setenv(BUDGET_APP_MODE='worker', BUDGET_APP_ROOT=", r_string_literal(app_root), ");",
    "app_env <- new.env(parent = globalenv());",
    "source(", r_string_literal(file.path(startup_app_root, "app.R")), ", local = app_env, chdir = TRUE, encoding = 'UTF-8');",
    "result <- app_env$run_background_project_workbook_sync_queue(reason = ", r_string_literal(as.character(reason %||% "queued")), ");",
    "quit(save = 'no', status = if (isTRUE(result)) 0L else 1L)"
  )
  launch_detached_rscript(expr, log_path = project_workbook_sync_log_file, reason = paste0("project_workbook_sync:", as.character(reason %||% "queued")))
}

project_workbook_sync_runtime <- local({
  env <- new.env(parent = emptyenv())
  env$future_job <- NULL
  env$project_id <- ""
  env$queue <- character()
  env
})

cleanup_project_workbook_sync_future_job <- function() {
  if (is.null(project_workbook_sync_runtime$future_job)) return(invisible(FALSE))
  if (!future::resolved(project_workbook_sync_runtime$future_job)) return(invisible(FALSE))
  project_id <- as.character(project_workbook_sync_runtime$project_id %||% "")
  result <- tryCatch(suppressWarnings(future::value(project_workbook_sync_runtime$future_job)), error = function(e) e)
  if (inherits(result, "error")) {
    append_project_workbook_sync_log("ERROR", paste0("Background workbook sync failed: ", conditionMessage(result)), project_id = project_id)
  } else if (!isTRUE(result)) {
    append_project_workbook_sync_log("ERROR", "Background workbook sync exited before completion.", project_id = project_id)
  } else {
    append_project_workbook_sync_log("INFO", "Background workbook sync completed.", project_id = project_id)
  }
  project_workbook_sync_runtime$future_job <- NULL
  project_workbook_sync_runtime$project_id <- ""
  invisible(isTRUE(result))
}

poll_project_workbook_sync_future <- function() {
  if (is.null(project_workbook_sync_runtime$future_job)) {
    if (length(project_workbook_sync_runtime$queue) > 0) later::later(poll_project_workbook_sync_future, delay = 0.2)
    return(invisible(FALSE))
  }
  if (!future::resolved(project_workbook_sync_runtime$future_job)) {
    later::later(poll_project_workbook_sync_future, delay = 0.6)
    return(invisible(FALSE))
  }
  cleanup_project_workbook_sync_future_job()
  if (length(project_workbook_sync_runtime$queue) > 0) {
    start_next_project_workbook_sync()
  }
  invisible(TRUE)
}

start_next_project_workbook_sync <- function() {
  if (!has_future) return(FALSE)
  if (!isTRUE(ensure_drive_future_plan())) return(FALSE)
  if (!is.null(project_workbook_sync_runtime$future_job)) {
    cleanup_project_workbook_sync_future_job()
    if (!is.null(project_workbook_sync_runtime$future_job)) return(FALSE)
  }
  queue <- unique(as.character(project_workbook_sync_runtime$queue %||% character()))
  queue <- queue[nzchar(queue)]
  project_workbook_sync_runtime$queue <- queue
  if (length(queue) == 0) return(FALSE)

  project_id <- queue[[1]]
  project_workbook_sync_runtime$queue <- queue[-1]
  project_workbook_sync_runtime$project_id <- project_id
  append_project_workbook_sync_log("INFO", "Starting background workbook sync.", project_id = project_id)
  project_workbook_sync_runtime$future_job <- tryCatch(
    future::future({
      Sys.setenv(BUDGET_APP_MODE = "worker", BUDGET_APP_ROOT = app_root)
      original_wd <- getwd()
      on.exit(setwd(original_wd), add = TRUE)
      setwd(startup_app_root)
      app_env <- new.env(parent = globalenv())
      source(file.path(startup_app_root, "app.R"), local = app_env, chdir = TRUE, encoding = "UTF-8")
      result <- app_env$sync_project_workbook(project_id)
      isTRUE(!identical(result, FALSE) && !is.null(result) && nzchar(as.character(result %||% "")))
    }, seed = TRUE),
    error = function(e) {
      append_project_workbook_sync_log("ERROR", paste0("Unable to launch background workbook sync: ", e$message), project_id = project_id)
      NULL
    }
  )
  if (is.null(project_workbook_sync_runtime$future_job)) {
    project_workbook_sync_runtime$project_id <- ""
    return(FALSE)
  }
  later::later(poll_project_workbook_sync_future, delay = 0.6)
  TRUE
}

queue_project_workbook_sync <- function(project_id, reason = "queued") {
  project_id <- as.character(project_id %||% "")
  if (!nzchar(project_id)) return(FALSE)
  if (can_launch_background_scheduler()) {
    queue <- tryCatch(
      enqueue_project_workbook_sync_request(project_id),
      error = function(e) {
        append_project_workbook_sync_log("ERROR", paste0("Unable to queue workbook sync: ", e$message), project_id = project_id, detail = list(reason = reason))
        character()
      }
    )
    if (length(queue) == 0) return(FALSE)
    append_project_workbook_sync_log("INFO", "Workbook sync queued.", project_id = project_id, detail = list(reason = reason, queue_length = length(queue), delivery = "detached_process"))
    return(isTRUE(launch_background_project_workbook_sync_process(reason = reason)))
  }
  if (!has_future) return(FALSE)
  queue <- unique(c(as.character(project_workbook_sync_runtime$queue %||% character()), project_id))
  project_workbook_sync_runtime$queue <- queue[nzchar(queue)]
  append_project_workbook_sync_log("INFO", "Workbook sync queued.", project_id = project_id, detail = list(reason = reason, queue_length = length(project_workbook_sync_runtime$queue)))
  later::later(function() try(start_next_project_workbook_sync(), silent = TRUE), delay = 0)
  TRUE
}


