normalize_report_expense_scope <- function(x) {
  value <- trimws(tolower(as.character(x %||% "all")))
  if (value %in% c("admin", "administrator", "administrator_only")) return("administrator")
  if (value %in% c("scientist", "user", "user/scientist", "scientist_only")) return("scientist")
  "all"
}

normalize_expense_source_scope <- function(x) {
  value <- trimws(tolower(as.character(x %||% "")))
  if (!nzchar(value)) return("administrator")
  if (value %in% c("admin", "administrator", "administrator_only")) return("administrator")
  if (value %in% c("scientist", "user", "user/scientist", "user_scientist", "scientist_only")) return("scientist")
  value
}

expense_scope_storage_role <- function(scope = "administrator") {
  scope <- normalize_expense_source_scope(scope)
  switch(
    scope,
    administrator = "Administrator",
    scientist = "Scientist",
    "Administrator"
  )
}

