filter_expenses_by_scope <- function(expenses, expense_scope = "all", include_trashed = FALSE) {
  if (is.null(expenses) || !is.data.frame(expenses)) return(data.frame())
  expenses <- normalize_expenses_frame(expenses)
  if (!("is_trashed" %in% names(expenses))) expenses$is_trashed <- 0L
  if (!isTRUE(include_trashed)) {
    trashed <- suppressWarnings(as.integer(expenses$is_trashed %||% 0L))
    expenses <- expenses[is.na(trashed) | trashed == 0L, , drop = FALSE]
  }
  scope <- normalize_report_expense_scope(expense_scope)
  if (identical(scope, "all")) return(expenses)
  expenses[as.character(expenses$expense_source_scope %||% "") == normalize_expense_source_scope(scope), , drop = FALSE]
}

get_expenses_by_date_range <- function(project_id, start_date = NULL, end_date = NULL, expense_scope = "all") {
  con <- connect_db(); on.exit(dbDisconnect(con))
  
  if (is.null(project_id) || !nzchar(as.character(project_id))) {
    return(data.frame())
  }
  
  ensure_expenses_schema(con)
  sql <- "SELECT * FROM expenses WHERE project_id = ? AND is_trashed = 0"
  params <- list(project_id)
  scope <- normalize_report_expense_scope(expense_scope)
  scope_aliases <- expense_scope_sql_aliases(scope)
  if (length(scope_aliases) > 0) {
    placeholders <- paste(rep("?", length(scope_aliases)), collapse = ", ")
    sql <- paste0(sql, " AND LOWER(TRIM(COALESCE(created_by_role,''))) IN (", placeholders, ")")
    params <- c(params, as.list(scope_aliases))
  }
  
  # Apply date filters if both dates are provided
  if (!is.null(start_date) && !is.null(end_date)) {
    start_str <- as.character(start_date)
    end_str <- as.character(end_date)
    
    if (nzchar(start_str) && nzchar(end_str)) {
      sql <- paste0(sql, " AND date >= ? AND date <= ?")
      params <- c(params, start_str, end_str)
    }
  }
  
  sql <- paste0(sql, " ORDER BY date ASC")
  
  tryCatch({
    ex <- normalize_expenses_frame(dbGetQuery(con, sql, params = params))
    if (nrow(ex) > 0) {
      ex <- ex %>% 
        mutate(
          category_main = ifelse(is.na(category_main) | category_main == "", 
                                 (ifelse(is.na(category) | category == "", "Uncategorized", sub(" -.*$", "", category))), 
                                 category_main),
          category_sub = ifelse(is.na(category_sub) | category_sub == "", 
                                (ifelse(grepl(" - ", category), sub("^.* - ", "", category), "")), 
                                category_sub)
        )
    }
    ex
  }, error = function(e) {
    message("get_expenses_by_date_range error: ", e$message)
    data.frame()
  })
}

normalize_report_date <- function(x) {
  if (is.null(x) || length(x) == 0) return(NULL)
  candidate <- suppressWarnings(as.Date(as.character(x[[1]])))
  if (length(candidate) == 0 || is.na(candidate)) return(NULL)
  candidate
}

normalize_expense_categories <- function(ex) {
  if (is.null(ex) || nrow(ex) == 0) {
    if (is.null(ex)) ex <- data.frame(stringsAsFactors = FALSE)
    if (!("category_main" %in% names(ex))) ex$category_main <- character(0)
    if (!("category_sub" %in% names(ex))) ex$category_sub <- character(0)
    return(ex)
  }
  ex %>%
    mutate(
      category_main = ifelse(
        is.na(category_main) | category_main == "",
        ifelse(is.na(category) | category == "", "Uncategorized", sub(" -.*$", "", category)),
        category_main
      ),
      category_sub = ifelse(
        is.na(category_sub) | category_sub == "",
        ifelse(grepl(" - ", category), sub("^.* - ", "", category), ""),
        category_sub
      )
    )
}

build_report_category_summary <- function(filtered_expenses) {
  empty <- data.frame(
    MainCategory = character(),
    Subcategory = character(),
    Amount = numeric(),
    Level = character(),
    stringsAsFactors = FALSE
  )
  if (is.null(filtered_expenses) || nrow(filtered_expenses) == 0) return(empty)

  main_totals <- filtered_expenses %>%
    group_by(category_main) %>%
    summarise(Amount = sum(as.numeric(amount), na.rm = TRUE), .groups = "drop") %>%
    arrange(desc(Amount), category_main)

  rows <- list()
  for (i in seq_len(nrow(main_totals))) {
    mainc <- as.character(main_totals$category_main[i] %||% "Uncategorized")
    rows[[length(rows) + 1]] <- data.frame(
      MainCategory = mainc,
      Subcategory = "",
      Amount = as.numeric(main_totals$Amount[i]),
      Level = "main",
      stringsAsFactors = FALSE
    )

    sub_totals <- filtered_expenses %>%
      filter(category_main == mainc) %>%
      group_by(category_sub) %>%
      summarise(Amount = sum(as.numeric(amount), na.rm = TRUE), .groups = "drop") %>%
      arrange(desc(Amount), category_sub)

    for (j in seq_len(nrow(sub_totals))) {
      sub_display <- as.character(sub_totals$category_sub[j] %||% "")
      if (!nzchar(sub_display)) sub_display <- "(none)"
      rows[[length(rows) + 1]] <- data.frame(
        MainCategory = mainc,
        Subcategory = sub_display,
        Amount = as.numeric(sub_totals$Amount[j]),
        Level = "sub",
        stringsAsFactors = FALSE
      )
    }
  }

  do.call(rbind, rows)
}

build_report_detail_rows <- function(filtered_expenses) {
  empty <- data.frame(
    RowType = character(),
    MainCategory = character(),
    Subcategory = character(),
    Date = character(),
    Description = character(),
    Amount = numeric(),
    Receipt = character(),
    SourceID = character(),
    stringsAsFactors = FALSE
  )
  if (is.null(filtered_expenses) || nrow(filtered_expenses) == 0) return(empty)

  main_totals <- filtered_expenses %>%
    group_by(category_main) %>%
    summarise(Amount = sum(as.numeric(amount), na.rm = TRUE), .groups = "drop") %>%
    arrange(desc(Amount), category_main)

  rows <- list()
  for (i in seq_len(nrow(main_totals))) {
    mainc <- as.character(main_totals$category_main[i] %||% "Uncategorized")
    sub_totals <- filtered_expenses %>%
      filter(category_main == mainc) %>%
      group_by(category_sub) %>%
      summarise(Amount = sum(as.numeric(amount), na.rm = TRUE), .groups = "drop") %>%
      arrange(desc(Amount), category_sub)

    if (nrow(sub_totals) == 0) {
      sub_totals <- data.frame(category_sub = "", Amount = 0, stringsAsFactors = FALSE)
    }

    for (j in seq_len(nrow(sub_totals))) {
      raw_sub <- as.character(sub_totals$category_sub[j] %||% "")
      display_sub <- if (nzchar(raw_sub)) raw_sub else "(none)"
      items <- filtered_expenses %>%
        filter(category_main == mainc & category_sub == raw_sub) %>%
        arrange(date, created_at, description)

      if (nrow(items) == 0) next

      for (k in seq_len(nrow(items))) {
        it <- items[k, ]
        rows[[length(rows) + 1]] <- data.frame(
          RowType = "expense",
          MainCategory = mainc,
          Subcategory = display_sub,
          Date = ifelse(is.na(it$date) || it$date == "", "-", as.character(it$date)),
          Description = as.character(it$description %||% ""),
          Amount = as.numeric(it$amount %||% 0),
          Receipt = ifelse(is.na(it$receipt_path) || it$receipt_path == "", "No", "Yes"),
          SourceID = as.character(it$id),
          stringsAsFactors = FALSE
        )

        bks <- get_breakdowns(it$id)
        if (nrow(bks) > 0) {
          for (bi in seq_len(nrow(bks))) {
            bk <- bks[bi, ]
            rows[[length(rows) + 1]] <- data.frame(
              RowType = "breakdown",
              MainCategory = mainc,
              Subcategory = display_sub,
              Date = "",
              Description = paste0("  - ", as.character(bk$label %||% "")),
              Amount = as.numeric(bk$amount %||% 0),
              Receipt = "",
              SourceID = as.character(it$id),
              stringsAsFactors = FALSE
            )
          }
        }
      }
    }
  }

  do.call(rbind, rows)
}

build_report_context <- function(project_id, start_date = NULL, end_date = NULL, expense_scope = "all") {
  con <- connect_db(); on.exit(dbDisconnect(con))

  if (is.null(project_id) || !nzchar(as.character(project_id))) stop("No project selected.")
  pr <- dbGetQuery(con, "SELECT * FROM projects WHERE id = ? LIMIT 1;", params = list(project_id))
  if (nrow(pr) == 0) stop("Project not found.")
  project <- pr[1, ]
  project$status <- normalize_project_status(project$status %||% "In Progress")
  project$principal_investigator <- trimws(as.character(project$principal_investigator %||% ""))
  if (!nzchar(project$principal_investigator)) project$principal_investigator <- "Not provided"
  project$team_members <- format_team_members_inline(project$team_members %||% "", empty = "Not provided")

  start_norm <- normalize_report_date(start_date)
  end_norm <- normalize_report_date(end_date)
  is_filtered <- !is.null(start_norm) && !is.null(end_norm)
  expense_scope <- normalize_report_expense_scope(expense_scope)

  all_expenses <- normalize_expense_categories(get_expenses_by_date_range(project_id, NULL, NULL, expense_scope = expense_scope))
  filtered_expenses <- if (is_filtered) {
    normalize_expense_categories(get_expenses_by_date_range(project_id, start_norm, end_norm, expense_scope = expense_scope))
  } else {
    all_expenses
  }

  total_budget <- suppressWarnings(as.numeric(project$budget_total %||% 0))
  if (is.na(total_budget)) total_budget <- 0
  total_spent_all <- sum(suppressWarnings(as.numeric(all_expenses$amount)), na.rm = TRUE)
  total_spent_period <- sum(suppressWarnings(as.numeric(filtered_expenses$amount)), na.rm = TRUE)
  remaining_all <- total_budget - total_spent_all

  list(
    project = project,
    start_date = start_norm,
    end_date = end_norm,
    is_filtered = is_filtered,
    expense_scope = expense_scope,
    expense_scope_label = report_expense_scope_label(expense_scope),
    all_expenses = all_expenses,
    filtered_expenses = filtered_expenses,
    category_summary = build_report_category_summary(filtered_expenses),
    detail_rows = build_report_detail_rows(filtered_expenses),
    total_budget = total_budget,
    total_spent_all = total_spent_all,
    total_spent_period = total_spent_period,
    remaining_all = remaining_all
  )
}

report_total_label <- function(ctx) {
  if (isTRUE(ctx$is_filtered)) "Total Expenses for Selected Period" else "Total Expenses Recorded"
}

report_total_note <- function(ctx) {
  if (isTRUE(ctx$is_filtered)) {
    paste0(
      "Period: ", html_escape(as.character(ctx$start_date)), " to ",
      html_escape(as.character(ctx$end_date)),
      " | This total reflects only expenses within the selected date range."
    )
  } else {
    "This total reflects all recorded expenses for the project."
  }
}

excel_currency_numfmt <- function(code = NULL) {
  current <- as.character(code %||% get_currency())
  switch(
    current,
    KES = "\"KES\" #,##0.00",
    USD = "$#,##0.00",
    GBP = "\"GBP\" #,##0.00",
    EUR = "\"EUR\" #,##0.00",
    "#,##0.00"
  )
}

build_report_file_stem <- function(project_name, request_tag = NULL, prefix = "budget_report") {
  timestamp <- gsub("[^0-9]", "", format(Sys.time(), "%Y%m%d_%H%M%OS3"))
  unique_tag <- substr(digest::digest(paste(project_name, request_tag %||% uuid("req"), Sys.time(), runif(1))), 1, 10)
  paste0(prefix, "_", sanitize_filename(project_name), "_", timestamp, "_", unique_tag)
}

register_export <- function(path, type, project_id, detail = list()) {
  con <- connect_db(); on.exit(dbDisconnect(con))
  normalized_path <- normalizePath(path, winslash = "/", mustWork = FALSE)
  rec <- data.frame(
    id = uuid("exp"),
    filename = basename(normalized_path),
    filepath = normalized_path,
    type = type,
    created_at = now(),
    criteria = project_id,
    stringsAsFactors = FALSE
  )
  dbWriteTable(con, "exports_meta", rec, append = TRUE, row.names = FALSE)
  log_audit(
    module = "Reports",
    action = paste0("export_", type),
    target_table = "exports_meta",
    target_id = rec$id,
    detail = c(list(filename = basename(normalized_path), project_id = project_id), detail),
    trigger_sync = FALSE
  )
  normalized_path
}

truncate_report_text <- function(x, width) {
  x <- as.character(x %||% "")
  ifelse(nchar(x) > width, paste0(substr(x, 1, pmax(1, width - 3)), "..."), x)
}

build_pdf_report_lines <- function(ctx, generated_at) {
  lines <- c(
    paste0("Generated: ", generated_at),
    paste0("Expense Source: ", ctx$expense_scope_label),
    paste0("Project: ", ctx$project$name),
    paste0("Project ID: ", ctx$project$id),
    paste0("Project Status: ", ctx$project$status),
    paste0("Principle Investigator: ", ctx$project$principal_investigator),
    paste0("Team Members: ", ctx$project$team_members),
    paste0("Budget: ", format_currency(ctx$total_budget)),
    paste0("Spent (All Time): ", format_currency(ctx$total_spent_all)),
    paste0("Remaining: ", format_currency(ctx$remaining_all))
  )

  if (!is.null(ctx$project$start_date) && nzchar(as.character(ctx$project$start_date %||% ""))) {
    lines <- c(lines, paste0("Project Start: ", ctx$project$start_date))
  }
  if (!is.null(ctx$project$end_date) && nzchar(as.character(ctx$project$end_date %||% ""))) {
    lines <- c(lines, paste0("Project End: ", ctx$project$end_date))
  }
  if (isTRUE(ctx$is_filtered)) {
    lines <- c(lines, paste0("Report Period: ", ctx$start_date, " to ", ctx$end_date))
  }

  lines <- c(lines, "", "Category Summary", strrep("-", 92))
  if (nrow(ctx$category_summary) == 0) {
    lines <- c(lines, "No expenses found for the selected criteria.")
  } else {
    for (i in seq_len(nrow(ctx$category_summary))) {
      row <- ctx$category_summary[i, ]
      label <- if (identical(row$Level, "main")) as.character(row$MainCategory) else paste0("  - ", as.character(row$Subcategory))
      lines <- c(lines, sprintf("%-72s %18s", truncate_report_text(label, 72), format_currency(row$Amount)))
    }
  }

  lines <- c(lines, "", "Expense Details", strrep("-", 92))
  if (nrow(ctx$detail_rows) == 0) {
    lines <- c(lines, "No expenses found for the selected criteria.")
  } else {
    lines <- c(lines, sprintf("%-10s %-18s %-18s %-28s %14s", "Date", "Category", "Subcategory", "Description", "Amount"))
    lines <- c(lines, strrep("-", 92))
    for (i in seq_len(nrow(ctx$detail_rows))) {
      row <- ctx$detail_rows[i, ]
      lines <- c(lines, sprintf(
        "%-10s %-18s %-18s %-28s %14s",
        truncate_report_text(row$Date, 10),
        truncate_report_text(row$MainCategory, 18),
        truncate_report_text(row$Subcategory, 18),
        truncate_report_text(row$Description, 28),
        format_currency(row$Amount)
      ))
    }
  }

  c(lines, "", paste0(report_total_label(ctx), ": ", format_currency(ctx$total_spent_period)))
}

write_pdf_report_fallback <- function(ctx, output_file, watermark = NULL, generated_at = format(Sys.time(), "%Y-%m-%d %H:%M:%S")) {
  lines <- build_pdf_report_lines(ctx, generated_at)
  pages <- split(lines, ceiling(seq_along(lines) / 34))

  grDevices::pdf(output_file, width = 11, height = 8.5, onefile = TRUE)
  on.exit(grDevices::dev.off(), add = TRUE)

  for (page_idx in seq_along(pages)) {
    graphics::plot.new()
    graphics::par(mar = c(0.4, 0.4, 0.4, 0.4))
    graphics::rect(0.015, 0.015, 0.985, 0.985, border = "#dbe7f3", lwd = 1)
    graphics::text(0.04, 0.965, labels = "Budget Tracker Report", adj = c(0, 1), cex = 1.25, font = 2)
    graphics::text(0.96, 0.965, labels = paste0("Page ", page_idx, " of ", length(pages)), adj = c(1, 1), cex = 0.8)
    if (!is.null(watermark) && nzchar(as.character(watermark))) {
      graphics::text(0.5, 0.52, labels = as.character(watermark), cex = 4.8, col = grDevices::rgb(0.8, 0.8, 0.8, 0.12), srt = 30)
    }
    y_positions <- seq(0.92, 0.06, length.out = length(pages[[page_idx]]))
    for (i in seq_along(pages[[page_idx]])) {
      graphics::text(0.04, y_positions[i], labels = pages[[page_idx]][i], adj = c(0, 1), cex = 0.78, family = "mono")
    }
  }

  normalizePath(output_file, winslash = "/", mustWork = FALSE)
}


