# ---------------------------
# Helper: Generate HTML preview for reports (used for live preview)
# Updated to show both full project totals and period-filtered totals
# ---------------------------
generate_report_preview_html <- function(project_id, start_date = NULL, end_date = NULL, watermark = NULL, expense_scope = "all") {
  tryCatch({
    ctx <- build_report_context(project_id, start_date, end_date, expense_scope = expense_scope)
    generated_at <- format(Sys.time(), "%Y-%m-%d %H:%M:%S")

    card_template <- function(title, value, accent, bg) {
      sprintf(
        "<div class='budget-metric-card' style='background:%s;border:1px solid #e6eef8;border-left:4px solid %s;padding:14px;border-radius:10px;min-height:88px;'>
          <div class='budget-metric-title' style='font-size:11px;color:#6b7280;text-transform:uppercase;letter-spacing:0.06em;'>%s</div>
          <div class='budget-metric-value' style='margin-top:8px;font-size:19px;font-weight:700;color:#0b2545;'>%s</div>
        </div>",
        bg, accent, html_escape(title), html_escape(value)
      )
    }

    html <- c("<div class='responsive-report-preview' style='font-family: Inter, Arial, Helvetica, sans-serif; padding: 20px; color: #0b2545; background: #ffffff;'>")
    html <- c(html, sprintf(
      "<div class='report-preview-header' style='display:flex;justify-content:space-between;align-items:flex-end;gap:12px;margin-bottom:18px;border-bottom:2px solid #e6eef8;padding-bottom:12px;'>
        <div>
          <div style='font-size:11px;letter-spacing:0.08em;color:#6b7280;text-transform:uppercase;'>Budget Management Report</div>
          <h2 class='report-preview-title' style='margin:4px 0 0 0;color:#0b2545;'>%s</h2>
          <div class='report-preview-scope-pill' style='margin-top:8px; display:inline-block; font-size:12px; font-weight:700; color:#143954; background:#eef4ff; border:1px solid #d6e4ff; border-radius:999px; padding:6px 12px;'>%s</div>
        </div>
        <div class='report-preview-generated' style='font-size:12px;color:#666;'>Generated %s</div>
      </div>",
      html_escape(ctx$project$name),
      html_escape(ctx$expense_scope_label),
      html_escape(generated_at)
    ))

    if (!is.null(watermark) && nzchar(as.character(watermark))) {
      html <- c(html, sprintf(
        "<div style='position:relative;top:-8px;font-size:58px;color:rgba(200,200,200,0.08);text-align:center;margin-bottom:-36px;pointer-events:none;'>%s</div>",
        html_escape(watermark)
      ))
    }

    html <- c(html, "<div class='report-metric-grid' style='display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:12px;margin-bottom:18px;'>")
    html <- c(html, card_template("Total Project Budget", format_currency(ctx$total_budget), "#2b7a2b", "#f5fbff"))
    html <- c(html, card_template("Total Spent (All Time)", format_currency(ctx$total_spent_all), "#c62828", "#fff3f2"))
    html <- c(html, card_template("Remaining Balance", format_currency(ctx$remaining_all), "#1d4ed8", "#eff6ff"))
    html <- c(html, card_template(report_total_label(ctx), format_currency(ctx$total_spent_period), "#d9822b", "#fff8eb"))
    html <- c(html, "</div>")

    html <- c(html, "<div class='report-project-details' style='background:#f8fbff;border:1px solid #e6eef8;border-radius:10px;padding:14px;margin-bottom:18px;'>")
    html <- c(html, sprintf("<div><strong>Project:</strong> %s</div>", html_escape(ctx$project$name)))
    html <- c(html, sprintf("<div><strong>Project ID:</strong> %s</div>", html_escape(ctx$project$id)))
    html <- c(html, sprintf("<div><strong>Project Status:</strong> %s</div>", html_escape(ctx$project$status)))
    html <- c(html, sprintf("<div><strong>Principle Investigator:</strong> %s</div>", html_escape(ctx$project$principal_investigator)))
    html <- c(html, sprintf("<div><strong>Team Members:</strong> %s</div>", html_escape(ctx$project$team_members)))
    if (!is.null(ctx$project$start_date) && nzchar(as.character(ctx$project$start_date %||% ""))) {
      html <- c(html, sprintf("<div><strong>Project Start Date:</strong> %s</div>", html_escape(ctx$project$start_date)))
    }
    if (!is.null(ctx$project$end_date) && nzchar(as.character(ctx$project$end_date %||% ""))) {
      html <- c(html, sprintf("<div><strong>Project End Date:</strong> %s</div>", html_escape(ctx$project$end_date)))
    }
    if (isTRUE(ctx$is_filtered)) {
      html <- c(html, sprintf("<div><strong>Report Period:</strong> %s to %s</div>", html_escape(ctx$start_date), html_escape(ctx$end_date)))
    } else {
      html <- c(html, "<div><strong>Report Scope:</strong> Full project history</div>")
    }
    html <- c(html, sprintf("<div style='margin-top:8px;font-size:12px;color:#6b7280;'>%s</div>", report_total_note(ctx)))
    html <- c(html, "</div>")

    html <- c(html, "<h3 class='report-section-title' style='color:#0b2545;margin:18px 0 10px 0;border-bottom:1px solid #e6eef8;padding-bottom:8px;'>Category Summary</h3>")
    if (nrow(ctx$category_summary) == 0) {
      html <- c(html, "<div style='padding:14px;background:#f5f5f5;border-radius:8px;color:#666;'>No expenses found for the selected criteria.</div>")
    } else {
      html <- c(html, "<table class='responsive-report-table' style='width:100%;border-collapse:collapse;margin-bottom:18px;'>")
      html <- c(html, "<thead><tr style='background:#f5f9ff;border-bottom:1px solid #dbe7f3;'><th style='text-align:left;padding:10px;'>Category</th><th style='text-align:right;padding:10px;'>Amount</th></tr></thead><tbody>")
      for (i in seq_len(nrow(ctx$category_summary))) {
        row <- ctx$category_summary[i, ]
        label <- if (identical(row$Level, "main")) {
          paste0("<strong>", html_escape(row$MainCategory), "</strong>")
        } else {
          paste0("<span style='padding-left:18px;color:#475569;'>", html_escape(row$Subcategory), "</span>")
        }
        bg <- if (identical(row$Level, "main")) "#ffffff" else "#fbfdff"
        html <- c(html, sprintf(
          "<tr style='border-bottom:1px solid #edf2f7;background:%s;'><td style='padding:9px;'>%s</td><td style='padding:9px;text-align:right;'>%s</td></tr>",
          bg, label, format_currency(row$Amount)
        ))
      }
      html <- c(html, "</tbody></table>")
    }

    html <- c(html, "<h3 class='report-section-title' style='color:#0b2545;margin:18px 0 10px 0;border-bottom:1px solid #e6eef8;padding-bottom:8px;'>Expense Details</h3>")
    if (nrow(ctx$detail_rows) == 0) {
      html <- c(html, "<div style='padding:14px;background:#f5f5f5;border-radius:8px;color:#666;'>No expenses found for the selected criteria.</div>")
    } else {
      html <- c(html, "<table class='responsive-report-table' style='width:100%;border-collapse:collapse;'>")
      html <- c(html, "<thead><tr style='background:#f5f9ff;border-bottom:1px solid #dbe7f3;'><th style='text-align:left;padding:10px;'>Date</th><th style='text-align:left;padding:10px;'>Category</th><th style='text-align:left;padding:10px;'>Subcategory</th><th style='text-align:left;padding:10px;'>Description</th><th style='text-align:right;padding:10px;'>Amount</th><th style='text-align:center;padding:10px;'>Receipt</th></tr></thead><tbody>")
      for (i in seq_len(nrow(ctx$detail_rows))) {
        row <- ctx$detail_rows[i, ]
        row_bg <- if (identical(row$RowType, "breakdown")) "#fafafa" else "#ffffff"
        row_color <- if (identical(row$RowType, "breakdown")) "#64748b" else "#0b2545"
        html <- c(html, sprintf(
          "<tr style='border-bottom:1px solid #edf2f7;background:%s;color:%s;'>
            <td style='padding:9px;'>%s</td>
            <td style='padding:9px;'>%s</td>
            <td style='padding:9px;'>%s</td>
            <td style='padding:9px;'>%s</td>
            <td style='padding:9px;text-align:right;'>%s</td>
            <td style='padding:9px;text-align:center;'>%s</td>
          </tr>",
          row_bg,
          row_color,
          html_escape(row$Date),
          html_escape(ifelse(identical(row$RowType, "breakdown"), "", row$MainCategory)),
          html_escape(ifelse(identical(row$RowType, "breakdown"), "", row$Subcategory)),
          html_escape(row$Description),
          format_currency(row$Amount),
          html_escape(row$Receipt)
        ))
      }
      html <- c(html, "</tbody></table>")
    }

    html <- c(html, sprintf(
      "<div style='background:#eaf5ff;border:1px solid #cfe4fb;border-radius:10px;padding:14px;margin-top:18px;'>
        <div class='report-summary-total-row' style='display:flex;justify-content:space-between;align-items:center;gap:12px;'>
          <div>
            <div style='font-size:11px;text-transform:uppercase;letter-spacing:0.06em;color:#6b7280;'>%s</div>
            <div style='margin-top:6px;font-size:12px;color:#52606d;'>%s</div>
          </div>
          <div class='report-summary-total-value' style='font-size:20px;font-weight:700;color:#0b2545;'>%s</div>
        </div>
      </div>",
      html_escape(report_total_label(ctx)),
      report_total_note(ctx),
      format_currency(ctx$total_spent_period)
    ))

    html <- c(html, "</div>")
    paste(html, collapse = "\n")
  }, error = function(e) {
    sprintf("<div style='padding: 20px; color: #c62828;'><strong>Error:</strong> %s</div>", html_escape(e$message))
  })
}


# ---------------------------
# Audit logging (and sync triggers)
# ---------------------------
log_audit <- function(user = "local_user", module, action, target_table = NA, target_id = NA, detail = list(), workspace_id = NA_character_, trigger_sync = TRUE) {
  if (is.null(module) || !nzchar(module)) module <- "Unknown"
  resolved_workspace <- workspace_id
  if (is.null(resolved_workspace) || identical(resolved_workspace, "") || is.na(resolved_workspace)) {
    resolved_workspace <- resolve_workspace_id(target_table = target_table, target_id = target_id, detail = detail)
  }
  resolved_workspace <- if (is.null(resolved_workspace) || is.na(resolved_workspace)) "" else as.character(resolved_workspace)
  try({
    con <- connect_db(); on.exit(dbDisconnect(con))
    entry <- data.frame(
      id = uuid("audit"),
      workspace_id = resolved_workspace,
      user = user,
      timestamp = now(),
      module = module,
      action = action,
      target_table = ifelse(is.na(target_table), "", target_table),
      target_id = ifelse(is.na(target_id), "", target_id),
      detail = json_stringify(detail, auto_unbox = TRUE),
      stringsAsFactors = FALSE
    )
    dbWriteTable(con, "audit", entry, append = TRUE, row.names = FALSE)
  }, silent = TRUE)
  
  try({
    if (!identical(module, "Google Drive") && nzchar(resolved_workspace)) {
      mark_drive_project_dirty(resolved_workspace)
    }
    if (isTRUE(trigger_sync) && !identical(user, "system") && nzchar(resolved_workspace)) {
      try(queue_project_workbook_sync(resolved_workspace, reason = paste0("audit:", as.character(action %||% "event"))), silent = TRUE)
    }
  }, silent = TRUE)
  invisible(TRUE)
}

# ---------------------------
# CRUD helpers
# ---------------------------
create_project <- function(id, name, description = "", budget_total = 0, start_date = NA, end_date = NA, status = "In Progress", budget_locked = 0, principal_investigator = NULL, team_members = "", access_key = NULL) {
  tryCatch({
    if (is.null(id) || !nzchar(id)) id <- uuid("proj")
    if (is.null(name) || !nzchar(trimws(as.character(name)))) stop("Project name is required.")
    principal_investigator <- trimws(as.character(principal_investigator %||% ""))
    if (!nzchar(principal_investigator)) stop("Principle Investigator is required.")
    status <- normalize_project_status(status)
    team_members <- normalize_team_members_text(team_members)
    con <- connect_db()
    on.exit({
      if (DBI::dbIsValid(con)) dbDisconnect(con)
    }, add = TRUE)
    ensure_projects_schema(con)
    nowt <- now()
    access_key <- normalize_project_access_key(access_key %||% "")
    if (!nzchar(access_key)) access_key <- generate_unique_project_access_key(con = con)
    df <- data.frame(id = id, name = name, description = description, principal_investigator = principal_investigator, team_members = team_members, budget_total = budget_total, start_date = ifelse(is.na(start_date), "", start_date), end_date = ifelse(is.na(end_date), "", end_date), status = status, access_key = access_key, budget_locked = as.integer(budget_locked), created_at = nowt, updated_at = nowt, is_trashed = 0, workbook_path = "", stringsAsFactors = FALSE)
    dbWriteTable(con, "projects", df, append = TRUE, row.names = FALSE)
    dbDisconnect(con)
    log_audit(module = "Projects", action = "create", target_table = "projects", target_id = id, detail = list(name = name, principal_investigator = principal_investigator, status = status, access_key = access_key, team_members = split_team_members(team_members)), trigger_sync = FALSE)
    try(queue_project_workbook_sync(id, reason = "project_created"), silent = TRUE)
    try(start_drive_sync_worker("project_created"), silent = TRUE)
    TRUE
  }, error = function(e) {
    message("create_project error: ", e$message)
    structure(FALSE, error = e$message)
  })
}

update_project <- function(id, fields) {
  tryCatch({
    if (!is.list(fields) || length(fields) == 0) stop("No project fields were supplied for update.")
    con <- connect_db()
    on.exit({
      if (DBI::dbIsValid(con)) dbDisconnect(con)
    }, add = TRUE)
    ensure_projects_schema(con)
    existing <- dbGetQuery(con, "SELECT COUNT(*) AS n FROM projects WHERE id = ? LIMIT 1;", params = list(id))
    if (nrow(existing) != 1 || is.na(existing$n[[1]]) || existing$n[[1]] < 1) stop("Project not found.")
    if ("name" %in% names(fields)) {
      fields$name <- trimws(as.character(as_db_scalar(fields$name, field_name = "Project name", default = "")))
      if (!nzchar(fields$name)) stop("Project name is required.")
    }
    if ("principal_investigator" %in% names(fields)) {
      fields$principal_investigator <- trimws(as.character(as_db_scalar(fields$principal_investigator, field_name = "Principle Investigator", default = "")))
      if (!nzchar(fields$principal_investigator)) stop("Principle Investigator is required.")
    }
    if ("access_key" %in% names(fields)) {
      fields$access_key <- normalize_project_access_key(as_db_scalar(fields$access_key, field_name = "Access Key", default = ""))
      if (!nzchar(fields$access_key)) stop("Access Key must be exactly three unique letters.")
      access_key_conflict <- dbGetQuery(
        con,
        "SELECT COUNT(*) AS n FROM projects WHERE id <> ? AND access_key = ? LIMIT 1;",
        params = list(as.character(id), as.character(fields$access_key))
      )
      if (nrow(access_key_conflict) == 1 && !is.na(access_key_conflict$n[[1]]) && access_key_conflict$n[[1]] > 0) {
        stop("Access Key is already assigned to another project.")
      }
    }
    if ("status" %in% names(fields)) {
      fields$status <- normalize_project_status(fields$status)
    }
    if ("team_members" %in% names(fields)) {
      fields$team_members <- normalize_team_members_text(fields$team_members)
    }
    if ("description" %in% names(fields)) {
      fields$description <- as.character(as_db_scalar(fields$description, field_name = "Description", default = ""))
    }
    if ("budget_total" %in% names(fields)) {
      fields$budget_total <- as.numeric(as_db_scalar(fields$budget_total, field_name = "Budget", default = 0))
      if (is.na(fields$budget_total)) stop("Budget must be a valid number.")
    }
    if ("budget_locked" %in% names(fields)) {
      fields$budget_locked <- as.integer(as_db_scalar(fields$budget_locked, field_name = "Lock Budget", default = 0))
    }
    if ("start_date" %in% names(fields)) {
      fields$start_date <- normalize_optional_date_value(fields$start_date, field_name = "Start Date")
    }
    if ("end_date" %in% names(fields)) {
      fields$end_date <- normalize_optional_date_value(fields$end_date, field_name = "End Date")
    }
    valid_columns <- setdiff(dbGetQuery(con, "PRAGMA table_info(projects);")$name, "id")
    fields <- fields[names(fields) %in% valid_columns]
    if (length(fields) == 0) stop("No valid project fields were supplied for update.")
    fields$updated_at <- now()
    set_sql <- paste0(names(fields), " = ?", collapse = ", ")
    params <- c(
      lapply(seq_along(fields), function(i) {
        as_db_scalar(fields[[i]], field_name = names(fields)[[i]], default = "")
      }),
      list(as.character(id))
    )
    sql <- paste0("UPDATE projects SET ", set_sql, " WHERE id = ?;")
    DBI::dbWithTransaction(con, {
      rows_changed <- dbExecute(con, sql, params = params)
      if (is.na(rows_changed)) stop("Project update did not complete.")
    })
    dbDisconnect(con)
    try(log_audit(module = "Projects", action = "update", target_table = "projects", target_id = id, detail = fields, trigger_sync = FALSE), silent = TRUE)
    try(queue_project_workbook_sync(id, reason = "project_updated"), silent = TRUE)
    TRUE
  }, error = function(e) {
    message("update_project error: ", e$message)
    structure(FALSE, error = e$message)
  })
}

soft_delete_project <- function(id) {
  tryCatch({
    con <- connect_db(); on.exit(dbDisconnect(con))
    dbExecute(con, "UPDATE projects SET is_trashed = 1, updated_at = ? WHERE id = ?;", params = list(now(), id))
    dbExecute(con, "UPDATE expenses SET is_trashed = 1, updated_at = ? WHERE project_id = ?;", params = list(now(), id))
    log_audit(module = "Projects", action = "trash", target_table = "projects", target_id = id, detail = list(), trigger_sync = FALSE)
    try(queue_project_workbook_sync(id, reason = "project_trashed"), silent = TRUE)
    TRUE
  }, error = function(e) { message("soft_delete_project error: ", e$message); FALSE })
}

restore_project <- function(id) {
  tryCatch({
    con <- connect_db(); on.exit(dbDisconnect(con))
    dbExecute(con, "UPDATE projects SET is_trashed = 0, updated_at = ? WHERE id = ?;", params = list(now(), id))
    dbExecute(con, "UPDATE expenses SET is_trashed = 0, updated_at = ? WHERE project_id = ?;", params = list(now(), id))
    log_audit(module = "Projects", action = "restore", target_table = "projects", target_id = id, detail = list(), trigger_sync = FALSE)
    try(queue_project_workbook_sync(id, reason = "project_restored"), silent = TRUE)
    TRUE
  }, error = function(e) { message("restore_project error: ", e$message); FALSE })
}

# ---------------------------
# Project contacts and scheduled email helpers
# ---------------------------
load_project_contacts <- function(project_id = NULL, include_trashed = FALSE) {
  con <- connect_db(); on.exit(dbDisconnect(con), add = TRUE)
  ensure_communications_schema(con)
  where <- character()
  params <- list()
  if (!is.null(project_id) && nzchar(as.character(project_id %||% ""))) {
    where <- c(where, "project_id = ?")
    params <- c(params, list(as.character(project_id)))
  }
  if (!isTRUE(include_trashed)) where <- c(where, "COALESCE(is_trashed,0) = 0")
  sql <- "SELECT * FROM project_contacts"
  if (length(where) > 0) sql <- paste(sql, "WHERE", paste(where, collapse = " AND "))
  sql <- paste(sql, "ORDER BY contact_name;")
  if (length(params) == 0) dbGetQuery(con, sql) else dbGetQuery(con, sql, params = params)
}

get_project_contact_by_id <- function(contact_id, include_trashed = TRUE) {
  con <- connect_db(); on.exit(dbDisconnect(con), add = TRUE)
  ensure_communications_schema(con)
  sql <- "SELECT * FROM project_contacts WHERE id = ?"
  if (!isTRUE(include_trashed)) sql <- paste0(sql, " AND COALESCE(is_trashed,0) = 0")
  sql <- paste0(sql, " LIMIT 1;")
  dbGetQuery(con, sql, params = list(as.character(contact_id %||% "")))
}

create_project_contact <- function(project_id, contact_name, role_position, email_address, phone_number) {
  tryCatch({
    project_id <- as.character(as_db_scalar(project_id, field_name = "Project Code", default = ""))
    if (!nzchar(project_id)) stop("Project Code is required.")
    project_row <- load_workspace_project(project_id, include_trashed = FALSE)
    if (nrow(project_row) != 1) stop("Project not found.")
    rec <- data.frame(
      id = uuid("pcon"),
      project_id = project_id,
      contact_name = normalize_contact_name(contact_name),
      role_position = normalize_contact_role(role_position),
      email_address = normalize_email_address(email_address),
      phone_number = normalize_phone_number(phone_number),
      created_at = now(),
      updated_at = now(),
      is_trashed = 0,
      stringsAsFactors = FALSE
    )
    con <- connect_db(); on.exit(dbDisconnect(con), add = TRUE)
    ensure_communications_schema(con)
    dbWriteTable(con, "project_contacts", rec, append = TRUE, row.names = FALSE)
    log_audit(module = "Contacts", action = "create", target_table = "project_contacts", target_id = rec$id, detail = as.list(rec[1, c("project_id", "contact_name", "role_position", "email_address", "phone_number")]), workspace_id = project_id, trigger_sync = FALSE)
    TRUE
  }, error = function(e) {
    message("create_project_contact error: ", e$message)
    structure(FALSE, error = e$message)
  })
}

update_project_contact <- function(contact_id, fields) {
  tryCatch({
    if (!is.list(fields) || length(fields) == 0) stop("No contact fields were supplied for update.")
    con <- connect_db(); on.exit(dbDisconnect(con), add = TRUE)
    ensure_communications_schema(con)
    existing <- dbGetQuery(con, "SELECT * FROM project_contacts WHERE id = ? LIMIT 1;", params = list(as.character(contact_id)))
    if (nrow(existing) != 1) stop("Contact not found.")
    if ("contact_name" %in% names(fields)) fields$contact_name <- normalize_contact_name(fields$contact_name)
    if ("role_position" %in% names(fields)) fields$role_position <- normalize_contact_role(fields$role_position)
    if ("email_address" %in% names(fields)) fields$email_address <- normalize_email_address(fields$email_address)
    if ("phone_number" %in% names(fields)) fields$phone_number <- normalize_phone_number(fields$phone_number)
    valid_columns <- setdiff(dbGetQuery(con, "PRAGMA table_info(project_contacts);")$name, "id")
    fields <- fields[names(fields) %in% valid_columns]
    if (length(fields) == 0) stop("No valid contact fields were supplied for update.")
    fields$updated_at <- now()
    set_sql <- paste0(names(fields), " = ?", collapse = ", ")
    params <- c(lapply(seq_along(fields), function(i) as_db_scalar(fields[[i]], field_name = names(fields)[[i]], default = "")), list(as.character(contact_id)))
    dbExecute(con, paste0("UPDATE project_contacts SET ", set_sql, " WHERE id = ?;"), params = params)
    log_audit(module = "Contacts", action = "update", target_table = "project_contacts", target_id = contact_id, detail = fields, workspace_id = as.character(existing$project_id[[1]] %||% ""), trigger_sync = FALSE)
    TRUE
  }, error = function(e) {
    message("update_project_contact error: ", e$message)
    structure(FALSE, error = e$message)
  })
}

delete_project_contact <- function(contact_id) {
  tryCatch({
    con <- connect_db(); on.exit(dbDisconnect(con), add = TRUE)
    ensure_communications_schema(con)
    contact_row <- dbGetQuery(con, "SELECT * FROM project_contacts WHERE id = ? LIMIT 1;", params = list(as.character(contact_id)))
    if (nrow(contact_row) != 1) stop("Contact not found.")
    active_refs <- dbGetQuery(con, "
      SELECT COUNT(*) AS n
      FROM scheduled_email_recipients r
      INNER JOIN scheduled_emails e ON e.id = r.email_id
      WHERE r.contact_id = ?
        AND e.status IN ('draft','scheduled','failed','sending')
        AND COALESCE(r.status,'pending') <> 'sent';
    ", params = list(as.character(contact_id)))
    if (nrow(active_refs) == 1 && !is.na(active_refs$n[[1]]) && active_refs$n[[1]] > 0) {
      stop("This contact is linked to an unsent scheduled email and cannot be deleted yet.")
    }
    dbExecute(con, "UPDATE project_contacts SET is_trashed = 1, updated_at = ? WHERE id = ?;", params = list(now(), as.character(contact_id)))
    log_audit(module = "Contacts", action = "delete", target_table = "project_contacts", target_id = contact_id, detail = list(project_id = as.character(contact_row$project_id[[1]] %||% "")), workspace_id = as.character(contact_row$project_id[[1]] %||% ""), trigger_sync = FALSE)
    TRUE
  }, error = function(e) {
    message("delete_project_contact error: ", e$message)
    structure(FALSE, error = e$message)
  })
}

load_project_scheduled_emails <- function(project_id = NULL, status_filter = NULL) {
  con <- connect_db(); on.exit(dbDisconnect(con), add = TRUE)
  ensure_communications_schema(con)
  where <- character()
  params <- list()
  if (!is.null(project_id) && nzchar(as.character(project_id %||% ""))) {
    where <- c(where, "project_id = ?")
    params <- c(params, list(as.character(project_id)))
  }
  if (!is.null(status_filter) && length(status_filter) > 0) {
    status_filter <- as.character(status_filter)
    where <- c(where, paste0("status IN (", paste(rep("?", length(status_filter)), collapse = ", "), ")"))
    params <- c(params, as.list(status_filter))
  }
  sql <- "SELECT * FROM scheduled_emails"
  if (length(where) > 0) sql <- paste(sql, "WHERE", paste(where, collapse = " AND "))
  sql <- paste(sql, "ORDER BY CASE status WHEN 'scheduled' THEN 1 WHEN 'draft' THEN 2 WHEN 'failed' THEN 3 WHEN 'partially_sent' THEN 4 WHEN 'sent' THEN 5 ELSE 6 END, scheduled_for DESC, created_at DESC;")
  if (length(params) == 0) dbGetQuery(con, sql) else dbGetQuery(con, sql, params = params)
}

