scheduled_email_attachment_storage_dir <- function(project_id, email_id) {
  target_dir <- file.path(
    scheduled_email_attachments_dir,
    sanitize_filename(as.character(project_id %||% "project")),
    sanitize_filename(as.character(email_id %||% "email"))
  )
