scheduled_email_attachment_remote_path <- function(attachment_row) {
  email_id <- as.character(attachment_row$email_id[[1]] %||% "")
  stored_name <- as.character(
    attachment_row$stored_filename[[1]] %||%
      basename(as.character(attachment_row$filepath[[1]] %||% attachment_row$attachment_name[[1]] %||% "attachment"))
  )
