}

load_project_email_attachment_sources <- function(project_id) {
  project_id <- as.character(project_id %||% "")
  if (!nzchar(project_id)) return(data.frame())
  con <- connect_db(); on.exit(dbDisconnect(con), add = TRUE)
  ensure_project_reports_schema(con)
  report_rows <- dbGetQuery(con, "
    SELECT *
    FROM project_reports
    WHERE project_id = ? AND COALESCE(is_trashed,0) = 0 AND status IN ('draft','submitted')
    ORDER BY updated_at DESC, created_at DESC;
  ", params = list(project_id))
  export_rows <- dbGetQuery(con, "
    SELECT *
    FROM exports_meta
    WHERE criteria = ? AND type IN ('excel','html','pdf')
    ORDER BY created_at DESC;
  ", params = list(project_id))

  rows <- list()
  add_choice <- function(choice_key, choice_label, source_type, source_key, attachment_name, filepath, mime_type) {
    rows[[length(rows) + 1]] <<- data.frame(
      choice_key = as.character(choice_key),
      choice_label = as.character(choice_label),
      source_type = as.character(source_type),
      source_key = as.character(source_key),
      attachment_name = as.character(attachment_name),
      filepath = as.character(filepath),
      mime_type = as.character(mime_type %||% ""),
      stringsAsFactors = FALSE
    )
  }

  if (nrow(report_rows) > 0) {
    for (i in seq_len(nrow(report_rows))) {
      report_row <- report_rows[i, , drop = FALSE]
      report_id <- as.character(report_row$id[[1]] %||% "")
      if (!nzchar(report_id)) next
      display_name <- project_report_display_name(report_row)
      attachment_name <- project_report_docx_filename(report_row)
      add_choice(
        choice_key = paste0("report::", report_id),
        choice_label = paste0("DOCX report | ", display_name, " | ", as.character(report_row$project_title[[1]] %||% project_id)),
        source_type = "project_report",
        source_key = report_id,
        attachment_name = attachment_name,
        filepath = as.character(report_row$docx_path[[1]] %||% file.path(project_reports_dir, project_id, attachment_name)),
        mime_type = guess_email_attachment_content_type(attachment_name)
      )
    }
  }

  if (nrow(export_rows) > 0) {
    for (i in seq_len(nrow(export_rows))) {
      export_row <- export_rows[i, , drop = FALSE]
      export_id <- as.character(export_row$id[[1]] %||% "")
      export_path <- as.character(export_row$filepath[[1]] %||% "")
      if (!nzchar(export_id) || !nzchar(export_path) || !file_exists(export_path)) next
      export_type <- toupper(as.character(export_row$type[[1]] %||% "FILE"))
      export_name <- basename(export_path)
      add_choice(
        choice_key = paste0("export::", export_id),
        choice_label = paste0(export_type, " export | ", export_name),
        source_type = "project_export",
        source_key = export_id,
        attachment_name = export_name,
        filepath = export_path,
        mime_type = guess_email_attachment_content_type(export_path)
      )
    }
  }

  if (length(rows) == 0) return(data.frame())
  do.call(rbind, rows)
}

resolve_project_email_attachment_source <- function(project_id, choice_key) {
  project_id <- as.character(project_id %||% "")
  choice_key <- as.character(choice_key %||% "")
  if (!nzchar(project_id) || !nzchar(choice_key)) stop("Project file selection is invalid.")

  if (startsWith(choice_key, "report::")) {
    report_id <- sub("^report::", "", choice_key)
    report_row <- get_project_report_by_id(report_id, include_trashed = FALSE)
    if (nrow(report_row) != 1) stop("Selected project report attachment was not found.")
    if (!identical(as.character(report_row$project_id[[1]] %||% ""), project_id)) stop("Selected project report belongs to a different project.")
    resolved_path <- ensure_project_report_docx_file(report_id)
    return(list(
      source_type = "project_report",
      source_key = report_id,
      attachment_name = project_report_docx_filename(report_row),
      filepath = resolved_path,
      mime_type = guess_email_attachment_content_type(resolved_path)
    ))
  }

  if (startsWith(choice_key, "export::")) {
    export_id <- sub("^export::", "", choice_key)
    con <- connect_db(); on.exit(dbDisconnect(con), add = TRUE)
    export_row <- dbGetQuery(con, "SELECT * FROM exports_meta WHERE id = ? AND criteria = ? LIMIT 1;", params = list(export_id, project_id))
    if (nrow(export_row) != 1) stop("Selected project export attachment was not found.")
    resolved_path <- as.character(export_row$filepath[[1]] %||% "")
    if (!nzchar(resolved_path) || !file_exists(resolved_path)) stop("Selected project export attachment file is missing.")
    return(list(
      source_type = "project_export",
      source_key = export_id,
      attachment_name = basename(resolved_path),
      filepath = normalizePath(resolved_path, winslash = "/", mustWork = FALSE),
      mime_type = guess_email_attachment_content_type(resolved_path)
    ))
  }

  stop("Unsupported project file attachment selection.")
}

build_scheduled_email_attachment_row <- function(project_id, email_id, src_path, attachment_name, source_type = "upload", source_key = "", mime_type = "") {
  src_path <- as.character(src_path %||% "")
  if (!nzchar(src_path) || !file_exists(src_path)) stop("Attachment source file could not be found.")
  if (safe_file_size(src_path) > max_upload_request_bytes) stop("Attachment exceeds the supported size limit for this server.")
  attachment_name <- as.character(attachment_name %||% basename(src_path))
  if (!nzchar(attachment_name)) attachment_name <- basename(src_path)
  attachment_id <- uuid("emla")
  ext <- tolower(fs::path_ext(attachment_name))
  stem <- sanitize_filename(tools::file_path_sans_ext(attachment_name))
  if (!nzchar(stem)) stem <- "attachment"
  stored_filename <- paste0(attachment_id, "__", stem, if (nzchar(ext)) paste0(".", ext) else "")
  dest_dir <- scheduled_email_attachment_storage_dir(project_id, email_id)
  dest_path <- file.path(dest_dir, stored_filename)
  dest_path <- copy_file_checked(src_path, dest_path, overwrite = TRUE)
  mime_value <- trimws(as.character(mime_type %||% ""))
  if (!nzchar(mime_value)) mime_value <- guess_email_attachment_content_type(attachment_name)
  data.frame(
    id = attachment_id,
    email_id = as.character(email_id %||% ""),
    project_id = as.character(project_id %||% ""),
    source_type = as.character(source_type %||% "upload"),
    source_key = as.character(source_key %||% ""),
    attachment_name = attachment_name,
    stored_filename = stored_filename,
    filepath = dest_path,
    mime_type = mime_value,
    size = safe_file_size(dest_path),
    checksum = file_checksum(dest_path),
    created_at = now(),
    updated_at = now(),
    stringsAsFactors = FALSE
  )
}

prepare_scheduled_email_attachment_rows <- function(email_id, project_id, uploaded_files = NULL, existing_file_keys = NULL, existing_rows = NULL) {
  project_id <- as.character(project_id %||% "")
  email_id <- as.character(email_id %||% "")
  if (is.null(existing_rows)) existing_rows <- load_scheduled_email_attachments(email_id)

  existing_source_type <- if (!is.null(existing_rows) && "source_type" %in% names(existing_rows)) as.character(existing_rows$source_type %||% character()) else character()
  existing_source_key <- if (!is.null(existing_rows) && "source_key" %in% names(existing_rows)) as.character(existing_rows$source_key %||% character()) else character()
  existing_attachment_name <- if (!is.null(existing_rows) && "attachment_name" %in% names(existing_rows)) as.character(existing_rows$attachment_name %||% character()) else character()
  existing_checksum <- if (!is.null(existing_rows) && "checksum" %in% names(existing_rows)) as.character(existing_rows$checksum %||% character()) else character()

  prepared_rows <- list()
  copied_paths <- character()
  staged_existing_sources <- character()
  staged_uploaded_keys <- character()

  append_row <- function(row) {
    prepared_rows[[length(prepared_rows) + 1]] <<- row
    copied_paths <<- c(copied_paths, as.character(row$filepath[[1]] %||% ""))
  }

  existing_file_keys <- unique(as.character(unlist(existing_file_keys %||% character(), use.names = FALSE)))
  existing_file_keys <- existing_file_keys[nzchar(existing_file_keys)]
  if (length(existing_file_keys) > 0) {
    for (choice_key in existing_file_keys) {
      source_meta <- resolve_project_email_attachment_source(project_id, choice_key)
      source_signature <- paste(source_meta$source_type, source_meta$source_key, sep = "::")
      already_saved <- length(existing_source_type) > 0 && any(existing_source_type == source_meta$source_type & existing_source_key == source_meta$source_key)
      if (already_saved || source_signature %in% staged_existing_sources) next
      row <- build_scheduled_email_attachment_row(
        project_id = project_id,
        email_id = email_id,
        src_path = source_meta$filepath,
        attachment_name = source_meta$attachment_name,
        source_type = source_meta$source_type,
        source_key = source_meta$source_key,
        mime_type = source_meta$mime_type
      )
      append_row(row)
      staged_existing_sources <- c(staged_existing_sources, source_signature)
    }
  }

  if (is.data.frame(uploaded_files) && nrow(uploaded_files) > 0) {
    for (i in seq_len(nrow(uploaded_files))) {
      src_path <- as.character(uploaded_files$datapath[[i]] %||% "")
      attachment_name <- as.character(uploaded_files$name[[i]] %||% basename(src_path))
      if (!nzchar(src_path) || !file_exists(src_path)) next
      upload_checksum <- tryCatch(file_checksum(src_path), error = function(e) "")
      upload_signature <- paste(attachment_name, upload_checksum, sep = "::")
      already_saved <- length(existing_attachment_name) > 0 && any(existing_attachment_name == attachment_name & existing_checksum == upload_checksum & existing_source_type == "upload")
      if (already_saved || upload_signature %in% staged_uploaded_keys) next
      row <- build_scheduled_email_attachment_row(
        project_id = project_id,
        email_id = email_id,
        src_path = src_path,
        attachment_name = attachment_name,
        source_type = "upload",
        source_key = "",
        mime_type = as.character(uploaded_files$type[[i]] %||% guess_email_attachment_content_type(attachment_name))
      )
      append_row(row)
      staged_uploaded_keys <- c(staged_uploaded_keys, upload_signature)
    }
  }

  out <- if (length(prepared_rows) == 0) data.frame() else do.call(rbind, prepared_rows)
  attr(out, "copied_paths") <- copied_paths[nzchar(copied_paths)]
  out
}

remove_scheduled_email_attachments <- function(attachment_ids, email_id = "", enforce_editable = TRUE) {
  tryCatch({
    attachment_ids <- unique(as.character(unlist(attachment_ids %||% character(), use.names = FALSE)))
    attachment_ids <- attachment_ids[nzchar(attachment_ids)]
    if (length(attachment_ids) == 0) stop("Select at least one attachment.")
    con <- connect_db(); on.exit(dbDisconnect(con), add = TRUE)
    ensure_communications_schema(con)
    rows <- do.call(rbind, lapply(attachment_ids, function(att_id) {
      dbGetQuery(con, "SELECT * FROM scheduled_email_attachments WHERE id = ? LIMIT 1;", params = list(att_id))
    }))
    if (is.null(rows) || nrow(rows) == 0) stop("Selected attachments were not found.")
    if (nzchar(as.character(email_id %||% ""))) {
      rows <- rows[as.character(rows$email_id %||% "") == as.character(email_id), , drop = FALSE]
    }
    if (nrow(rows) == 0) stop("Selected attachments do not belong to the current email.")
    email_ids <- unique(as.character(rows$email_id %||% ""))
    if (length(email_ids) != 1) stop("Attachments must belong to one email at a time.")
    email_row <- get_scheduled_email_by_id(email_ids[[1]])
    if (nrow(email_row) != 1) stop("Parent email record was not found.")
    email_status <- as.character(email_row$status[[1]] %||% "")
    if (isTRUE(enforce_editable) && email_status %in% c("sent", "sending", "partially_sent")) {
      stop("Attachments can only be removed from unsent emails.")
    }
    file_paths <- as.character(rows$filepath %||% character())
    for (att_id in attachment_ids) {
      dbExecute(con, "DELETE FROM scheduled_email_attachments WHERE id = ?;", params = list(att_id))
    }
    existing_mask <- nzchar(file_paths) & file_exists(file_paths)
    if (any(existing_mask)) try(file_delete(file_paths[existing_mask]), silent = TRUE)
    log_audit(
      module = "Communications",
      action = "remove_attachments",
      target_table = "scheduled_email_attachments",
      target_id = email_ids[[1]],
      detail = list(project_id = as.character(email_row$project_id[[1]] %||% ""), removed_count = nrow(rows), attachment_ids = attachment_ids),
      workspace_id = as.character(email_row$project_id[[1]] %||% ""),
      trigger_sync = FALSE
    )
    TRUE
  }, error = function(e) {
    message("remove_scheduled_email_attachments error: ", e$message)
    structure(FALSE, error = e$message)
  })
}

save_scheduled_email_job <- function(project_id, contact_ids, subject, message_body, scheduled_for = "", status = "draft", email_id = NULL, created_by_role = "Administrator", uploaded_files = NULL, existing_file_keys = NULL) {
  copied_paths <- character()
  tryCatch({
    schedule_tz <- email_schedule_timezone()
    status <- as.character(as_db_scalar(status, field_name = "Status", default = "draft"))
    if (!(status %in% c("draft", "scheduled"))) stop("Email status must be either draft or scheduled.")
    project_id <- as.character(as_db_scalar(project_id, field_name = "Project Code", default = ""))
    if (!nzchar(project_id)) stop("Project Code is required.")
    project_row <- load_workspace_project(project_id, include_trashed = FALSE)
    if (nrow(project_row) != 1) stop("Project not found.")
    subject <- trimws(as.character(as_db_scalar(subject, field_name = "Subject", default = "")))
    if (!nzchar(subject)) stop("Email subject is required.")
    message_body <- trimws(as.character(as_db_scalar(message_body, field_name = "Message Body", default = "")))
    if (!nzchar(message_body)) stop("Email message body is required.")
    contact_ids <- unique(as.character(unlist(contact_ids %||% character(), use.names = FALSE)))
    contact_ids <- contact_ids[nzchar(contact_ids)]
    if (length(contact_ids) == 0) stop("Select at least one recipient.")
    contacts <- load_project_contacts(project_id, include_trashed = FALSE)
    contacts <- contacts[contacts$id %in% contact_ids, , drop = FALSE]
    contacts <- contacts[nzchar(as.character(contacts$email_address %||% "")), , drop = FALSE]
    if (nrow(contacts) == 0) stop("Selected recipients were not found in the project contact list.")
    scheduled_for_value <- if (identical(status, "scheduled")) normalize_datetime_storage(scheduled_for, field_name = "Scheduled date/time", tz = schedule_tz) else if (nzchar(as.character(scheduled_for %||% ""))) normalize_datetime_storage(scheduled_for, field_name = "Scheduled date/time", tz = schedule_tz) else ""
    email_id <- trimws(as.character(email_id %||% ""))
    if (!nzchar(email_id)) email_id <- uuid("eml")
    con <- connect_db(); on.exit(dbDisconnect(con), add = TRUE)
    ensure_communications_schema(con)
    nowt <- scheduled_email_now()
    existing <- dbGetQuery(con, "SELECT * FROM scheduled_emails WHERE id = ? LIMIT 1;", params = list(email_id))
    existing_attachments <- dbGetQuery(con, "SELECT * FROM scheduled_email_attachments WHERE email_id = ? ORDER BY created_at, attachment_name;", params = list(email_id))
    prepared_attachment_rows <- prepare_scheduled_email_attachment_rows(
      email_id = email_id,
      project_id = project_id,
      uploaded_files = uploaded_files,
      existing_file_keys = existing_file_keys,
      existing_rows = existing_attachments
    )
    copied_paths <- as.character(attr(prepared_attachment_rows, "copied_paths") %||% character())
    recipient_rows <- do.call(rbind, lapply(seq_len(nrow(contacts)), function(i) {
      data.frame(
        id = uuid("emlr"),
        email_id = email_id,
        project_id = project_id,
        contact_id = as.character(contacts$id[[i]] %||% ""),
        recipient_name = as.character(contacts$contact_name[[i]] %||% ""),
        recipient_role = as.character(contacts$role_position[[i]] %||% ""),
        email_address = as.character(contacts$email_address[[i]] %||% ""),
        status = "pending",
        sent_at = "",
        last_error = "",
        created_at = nowt,
        updated_at = nowt,
        stringsAsFactors = FALSE
      )
    }))
    DBI::dbWithTransaction(con, {
      if (nrow(existing) == 1) {
        current_status <- as.character(existing$status[[1]] %||% "")
        if (current_status %in% c("sent", "sending", "partially_sent")) stop("This email can no longer be edited.")
        if (!identical(as.character(existing$project_id[[1]] %||% ""), project_id)) stop("Email belongs to a different project.")
        dbExecute(con, "
          UPDATE scheduled_emails
          SET project_code = ?, subject = ?, message_body = ?, status = ?, scheduled_for = ?, actual_sent_at = '',
              last_attempt_at = '', last_error = '', delivery_summary = '', cancelled_at = '', created_by_role = ?, updated_at = ?
          WHERE id = ?;
        ", params = list(project_id, subject, message_body, status, scheduled_for_value, as.character(created_by_role %||% ""), nowt, email_id))
        dbExecute(con, "DELETE FROM scheduled_email_recipients WHERE email_id = ?;", params = list(email_id))
      } else {
        rec <- data.frame(
          id = email_id,
          project_id = project_id,
          project_code = project_id,
          subject = subject,
          message_body = message_body,
          status = status,
          scheduled_for = scheduled_for_value,
          actual_sent_at = "",
          last_attempt_at = "",
          last_error = "",
          delivery_summary = "",
          created_by_role = as.character(created_by_role %||% ""),
          created_at = nowt,
          updated_at = nowt,
          cancelled_at = "",
          stringsAsFactors = FALSE
        )
        dbWriteTable(con, "scheduled_emails", rec, append = TRUE, row.names = FALSE)
      }
      dbWriteTable(con, "scheduled_email_recipients", recipient_rows, append = TRUE, row.names = FALSE)
      if (nrow(prepared_attachment_rows) > 0) {
        dbWriteTable(con, "scheduled_email_attachments", prepared_attachment_rows, append = TRUE, row.names = FALSE)
      }
    })
    total_attachment_count <- nrow(existing_attachments) + nrow(prepared_attachment_rows)
    try(mark_drive_project_dirty(project_id), silent = TRUE)
    log_audit(module = "Communications", action = if (identical(status, "draft")) "save_draft" else "schedule_email", target_table = "scheduled_emails", target_id = email_id, detail = list(project_id = project_id, recipient_count = nrow(recipient_rows), subject = subject, scheduled_for = scheduled_for_value, status = status, attachment_count = total_attachment_count), workspace_id = project_id, trigger_sync = FALSE)
    email_id
  }, error = function(e) {
    copied_paths <- tryCatch(as.character(copied_paths %||% character()), error = function(err) character())
    if (length(copied_paths) > 0) {
      stale_paths <- copied_paths[nzchar(copied_paths) & file_exists(copied_paths)]
      if (length(stale_paths) > 0) try(file_delete(stale_paths), silent = TRUE)
    }
    message("save_scheduled_email_job error: ", e$message)
    structure(FALSE, error = e$message)
  })
}

cancel_scheduled_email_job <- function(email_id) {
  tryCatch({
    nowt <- scheduled_email_now()
    con <- connect_db(); on.exit(dbDisconnect(con), add = TRUE)
    ensure_communications_schema(con)
    email_row <- dbGetQuery(con, "SELECT * FROM scheduled_emails WHERE id = ? LIMIT 1;", params = list(as.character(email_id)))
    if (nrow(email_row) != 1) stop("Scheduled email not found.")
    status <- as.character(email_row$status[[1]] %||% "")
    if (!(status %in% c("draft", "scheduled", "failed"))) stop("Only unsent emails can be cancelled.")
    dbExecute(con, "UPDATE scheduled_emails SET status = 'cancelled', cancelled_at = ?, updated_at = ? WHERE id = ?;", params = list(nowt, nowt, as.character(email_id)))
    dbExecute(con, "UPDATE scheduled_email_recipients SET status = 'cancelled', updated_at = ? WHERE email_id = ? AND COALESCE(status,'pending') <> 'sent';", params = list(nowt, as.character(email_id)))
    try(mark_drive_project_dirty(as.character(email_row$project_id[[1]] %||% "")), silent = TRUE)
    log_audit(module = "Communications", action = "cancel_email", target_table = "scheduled_emails", target_id = email_id, detail = list(project_id = as.character(email_row$project_id[[1]] %||% "")), workspace_id = as.character(email_row$project_id[[1]] %||% ""), trigger_sync = FALSE)
    TRUE
  }, error = function(e) {
    message("cancel_scheduled_email_job error: ", e$message)
    structure(FALSE, error = e$message)
  })
}

retry_scheduled_email_job <- function(email_id) {
  tryCatch({
    nowt <- scheduled_email_now()
    con <- connect_db(); on.exit(dbDisconnect(con), add = TRUE)
    ensure_communications_schema(con)
    email_row <- dbGetQuery(con, "SELECT * FROM scheduled_emails WHERE id = ? LIMIT 1;", params = list(as.character(email_id)))
    if (nrow(email_row) != 1) stop("Scheduled email not found.")
    status <- as.character(email_row$status[[1]] %||% "")
    if (!(status %in% c("failed", "partially_sent", "cancelled"))) stop("Only failed or incomplete emails can be retried.")
    retry_due_at <- format(time_in_timezone(email_schedule_timezone()) - 1, "%Y-%m-%d %H:%M:%S")
    dbExecute(con, "
      UPDATE scheduled_emails
      SET status = 'scheduled', scheduled_for = ?, last_error = '', cancelled_at = '', updated_at = ?
      WHERE id = ?;
    ", params = list(retry_due_at, nowt, as.character(email_id)))
    dbExecute(con, "
      UPDATE scheduled_email_recipients
      SET status = 'pending', sent_at = CASE WHEN status = 'sent' THEN sent_at ELSE '' END, last_error = '', updated_at = ?
      WHERE email_id = ? AND COALESCE(status,'pending') <> 'sent';
    ", params = list(nowt, as.character(email_id)))
    try(mark_drive_project_dirty(as.character(email_row$project_id[[1]] %||% "")), silent = TRUE)
    log_audit(module = "Communications", action = "retry_email", target_table = "scheduled_emails", target_id = email_id, detail = list(project_id = as.character(email_row$project_id[[1]] %||% "")), workspace_id = as.character(email_row$project_id[[1]] %||% ""), trigger_sync = FALSE)
    TRUE
  }, error = function(e) {
    message("retry_scheduled_email_job error: ", e$message)
    structure(FALSE, error = e$message)
  })
}

build_email_sender_header <- function(settings) {
  sender_name <- trimws(as.character(settings$from_name %||% ""))
  sender_address <- trimws(as.character(settings$from_address %||% ""))
  if (!nzchar(sender_name)) return(sender_address)
  escaped_name <- gsub('(["\\\\])', "\\\\\\1", sender_name, perl = TRUE)
  paste0("\"", escaped_name, "\" <", sender_address, ">")
}

email_sender_display_text <- function(settings) {
  sender_name <- trimws(as.character(settings$from_name %||% ""))
  sender_address <- trimws(as.character(settings$from_address %||% ""))
  if (nzchar(sender_name) && nzchar(sender_address)) {
    paste0(sender_name, " <", sender_address, ">")
  } else if (nzchar(sender_name)) {
    sender_name
  } else if (nzchar(sender_address)) {
    sender_address
  } else {
    "Project Communication"
  }
}

scheduled_email_summary_text <- function(delivery_summary = "", last_error = "") {
  summary <- trimws(as.character(delivery_summary %||% ""))
  error_text <- trimws(as.character(last_error %||% ""))
  if (nzchar(error_text) && nzchar(summary) && !grepl("Error:", summary, fixed = TRUE)) {
    return(paste0(summary, " | Error: ", error_text))
  }
  if (nzchar(error_text)) return(error_text)
  if (nzchar(summary)) return(summary)
  "-"
}

email_plain_text_body <- function(settings, subject, message_body) {
  subject_text <- trimws(as.character(subject %||% ""))
  sender_line <- email_sender_display_text(settings)
  paste(
    c(
      if (nzchar(subject_text)) subject_text else NULL,
      "",
      as.character(message_body %||% ""),
      "",
      paste0("Sent by: ", sender_line)
    ),
    collapse = "\n"
  )
}

email_message_body_html <- function(message_body) {
  text <- html_escape(message_body %||% "")
  text <- gsub("\r\n|\r|\n", "<br>", text, perl = TRUE)
  if (!nzchar(trimws(as.character(message_body %||% "")))) {
    return("<span style=\"color:#64748b;\">No message content provided.</span>")
  }
  text
}

build_branded_email_html <- function(settings, subject, message_body) {
  sender_display <- email_sender_display_text(settings)
  subject_text <- trimws(as.character(subject %||% ""))
  if (!nzchar(subject_text)) subject_text <- "Project Communication"
  has_logo <- nzchar(as.character(settings$logo_path %||% "")) && nzchar(as.character(settings$logo_content_type %||% ""))
  logo_cell_markup <- if (has_logo) {
    paste0(
      "<td width=\"118\" valign=\"middle\" style=\"padding:0 24px 0 0;\">",
      "<img src=\"cid:", email_logo_cid, "\" alt=\"", html_escape(sender_display),
      "\" style=\"display:block;max-width:96px;width:96px;height:auto;border:0;outline:none;text-decoration:none;\">",
      "</td>"
    )
  } else {
    ""
  }
  paste0(
    "<!DOCTYPE html>",
    "<html><head><meta charset=\"utf-8\"></head>",
    "<body style=\"margin:0;padding:0;background:#eef2f7;font-family:Segoe UI,Arial,Helvetica,sans-serif;color:#0f172a;\">",
    "<table role=\"presentation\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" style=\"background:#eef2f7;padding:32px 0;\">",
    "<tr><td align=\"center\">",
    "<table role=\"presentation\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\" style=\"max-width:760px;background:#ffffff;border:1px solid #dbe4ef;border-radius:18px;overflow:hidden;\">",
    "<tr><td style=\"padding:24px 32px;background:linear-gradient(135deg,#f8fbff 0%,#eef6ff 100%);border-bottom:1px solid #dbe4ef;\">",
    "<table role=\"presentation\" width=\"100%\" cellspacing=\"0\" cellpadding=\"0\">",
    "<tr>",
    logo_cell_markup,
    "<td valign=\"middle\" style=\"padding:0;\">",
    "<div style=\"font-size:30px;font-weight:700;line-height:1.18;color:#12395b;\">", html_escape(subject_text), "</div>",
    "<div style=\"margin-top:10px;font-size:14px;line-height:1.6;color:#526173;\">Official project communication.</div>",
    "</td>",
    "</tr>",
    "</table>",
    "</td></tr>",
    "<tr><td style=\"padding:34px 40px 40px 40px;\">",
    "<div style=\"font-size:15px;line-height:1.85;color:#1f2937;white-space:normal;\">", email_message_body_html(message_body), "</div>",
    "<div style=\"margin-top:30px;padding-top:18px;border-top:1px solid #e2e8f0;font-size:13px;line-height:1.7;color:#64748b;\">",
    "Sent by ", html_escape(sender_display), ".",
    "</div>",
    "</td></tr>",
    "</table>",
    "</td></tr></table>",
    "</body></html>"
  )
}

send_single_scheduled_email_message <- function(settings, to_email, to_name, subject, message_body, attachments = NULL) {
  smtp_username <- resolve_email_smtp_username(settings)
  smtp_password <- resolve_email_smtp_password(settings)
  transport_use_ssl <- resolve_email_smtp_transport_use_ssl(settings)
  to_header <- if (nzchar(as.character(to_name %||% ""))) paste0(as.character(to_name), " <", as.character(to_email), ">") else as.character(to_email)
  msg <- emayili::envelope(
    from = build_email_sender_header(settings),
    to = to_header,
    subject = as.character(subject %||% "")
  )
  msg <- emayili::text(msg, email_plain_text_body(settings, subject, message_body))
  msg <- emayili::html(msg, build_branded_email_html(settings, subject, message_body))
  if (nzchar(as.character(settings$logo_path %||% "")) && file_exists(as.character(settings$logo_path %||% "")) && nzchar(as.character(settings$logo_content_type %||% ""))) {
    msg <- emayili::attachment(
      msg,
      path = as.character(settings$logo_path),
      name = basename(as.character(settings$logo_path)),
      type = as.character(settings$logo_content_type),
      cid = email_logo_cid,
      disposition = "inline"
    )
  }
  if (is.data.frame(attachments) && nrow(attachments) > 0) {
    for (i in seq_len(nrow(attachments))) {
      attachment_row <- attachments[i, , drop = FALSE]
      attachment_path <- as.character(attachment_row$filepath[[1]] %||% "")
      attachment_name <- as.character(attachment_row$attachment_name[[1]] %||% basename(attachment_path))
      attachment_type <- trimws(as.character(attachment_row$mime_type[[1]] %||% ""))
      if (!nzchar(attachment_path) || !file_exists(attachment_path)) {
        stop(paste0("Attachment file is missing: ", attachment_name))
      }
      if (!nzchar(attachment_type)) attachment_type <- guess_email_attachment_content_type(attachment_name)
      msg <- emayili::attachment(
        msg,
        path = attachment_path,
        name = attachment_name,
        type = attachment_type,
        disposition = "attachment"
      )
    }
  }
  max_attempts <- 2L
  last_error <- ""
  for (attempt in seq_len(max_attempts)) {
    attempt_result <- tryCatch({
      smtp_server <- emayili::server(
        host = settings$smtp_host,
        port = settings$smtp_port,
        username = smtp_username,
        password = smtp_password,
        use_ssl = transport_use_ssl,
        insecure = isTRUE(settings$smtp_insecure_tls),
        reuse = TRUE,
        connecttimeout = as.integer(settings$smtp_connect_timeout_sec %||% 15L),
        timeout = as.integer(settings$smtp_total_timeout_sec %||% 60L),
        max_times = 1
      )
      smtp_server(msg)
      TRUE
    }, error = function(e) {
      last_error <<- describe_email_send_error(e)
      FALSE
    })
    if (isTRUE(attempt_result)) return(invisible(TRUE))
    if (attempt < max_attempts) Sys.sleep(min(1 * attempt, 2))
  }
  if (!nzchar(last_error)) last_error <- "Unknown email delivery error"
  stop(contextualize_email_send_error(last_error, settings, attempt_count = max_attempts), call. = FALSE)
  invisible(TRUE)
}

create_email_test_job <- function(recipient, subject, message_body) {
  job_id <- uuid("emailtest")
  write_email_test_job_state(job_id, list(
    status = "queued",
    recipient = as.character(recipient %||% ""),
    subject = as.character(subject %||% ""),
    message_body = as.character(message_body %||% ""),
    message = "",
    created_at = now(),
    started_at = "",
    completed_at = ""
  ))
  job_id
}

run_background_email_test_job <- function(job_id) {
  job_id <- as.character(job_id %||% "")
  state <- read_email_test_job_state(job_id)
  recipient <- trimws(as.character(state$recipient %||% ""))
  subject <- as.character(state$subject %||% "Budget Tracker Scheduled Email Test")
  message_body <- as.character(state$message_body %||% "")
  if (!nzchar(job_id) || !nzchar(recipient)) {
    append_scheduled_email_log("ERROR", "SMTP test email job is missing the required recipient.", detail = list(job_id = job_id))
    if (nzchar(job_id)) {
      write_email_test_job_state(job_id, modifyList(as.list(state), list(
        status = "failed",
        message = "Test email job is missing the required recipient.",
        completed_at = now()
      )))
    }
    return(FALSE)
  }
  tryCatch({
    write_email_test_job_state(job_id, modifyList(as.list(state), list(
      status = "sending",
      message = "",
      started_at = now()
    )))
    status <- email_delivery_status(get_email_delivery_settings(force = TRUE))
    if (!isTRUE(status$ok)) stop(status$reason)
    send_single_scheduled_email_message(
      settings = status$settings,
      to_email = recipient,
      to_name = "Test Recipient",
      subject = subject,
      message_body = message_body
    )
    append_scheduled_email_log("INFO", "SMTP test email sent.", detail = list(recipient = recipient, mode = "background_process", job_id = job_id))
    write_email_test_job_state(job_id, modifyList(as.list(state), list(
      status = "sent",
      message = "Test email sent successfully.",
      completed_at = now()
    )))
    TRUE
  }, error = function(e) {
    error_text <- as.character(conditionMessage(e) %||% "Unknown SMTP test email error")
    append_scheduled_email_log("ERROR", paste0("SMTP test email failed: ", error_text), detail = list(recipient = recipient, mode = "background_process", job_id = job_id))
    write_email_test_job_state(job_id, modifyList(as.list(state), list(
      status = "failed",
      message = error_text,
      completed_at = now()
    )))
    FALSE
  })
}

launch_background_email_test_job <- function(job_id) {
  expr <- paste0(
    "Sys.setenv(BUDGET_APP_MODE='worker', BUDGET_APP_ROOT=", r_string_literal(app_root), ");",
    "app_env <- new.env(parent = globalenv());",
    "source(", r_string_literal(file.path(startup_app_root, "app.R")), ", local = app_env, chdir = TRUE, encoding = 'UTF-8');",
    "result <- app_env$run_background_email_test_job(", r_string_literal(job_id), ");",
    "quit(save = 'no', status = if (isTRUE(result)) 0L else 1L)"
  )
  launch_detached_rscript(expr, log_path = scheduled_email_log_path, reason = "email_test")
}

run_scheduled_email_cycle <- function(lease_token = "", reason = "scheduled", force_settings_refresh = FALSE) {
  status <- email_delivery_status(get_email_delivery_settings(force = force_settings_refresh))
  schedule_tz <- if (isTRUE(force_settings_refresh)) normalize_timezone_value(status$settings$schedule_timezone %||% default_email_schedule_timezone(), field_name = "Email schedule time zone") else email_schedule_timezone()
  success <- TRUE
  final_error <- ""
  on.exit({
    if (nzchar(as.character(lease_token %||% ""))) {
      release_drive_sync_lease(lease_token, success = success, error_message = final_error)
    }
  }, add = TRUE)

  if (!isTRUE(status$ok)) {
    final_error <- status$reason
    append_scheduled_email_log("ERROR", status$reason, detail = list(reason = reason))
    return(FALSE)
  }

  settings <- status$settings
  append_scheduled_email_log("INFO", "Starting scheduled email cycle.", detail = list(reason = reason))
  tryCatch({
    con <- connect_db(); on.exit(dbDisconnect(con), add = TRUE)
    ensure_communications_schema(con)
    cycle_now <- scheduled_email_now()
    stale_cutoff <- format(time_in_timezone(schedule_tz) - 900, "%Y-%m-%d %H:%M:%S")
    dbExecute(con, "
      UPDATE scheduled_emails
      SET status = 'scheduled', last_error = CASE WHEN COALESCE(last_error,'') = '' THEN 'Recovered after interrupted send attempt.' ELSE last_error END, updated_at = ?
      WHERE status = 'sending' AND COALESCE(last_attempt_at,'') <> '' AND last_attempt_at < ?;
    ", params = list(cycle_now, stale_cutoff))
    jobs <- dbGetQuery(con, "
      SELECT *
      FROM scheduled_emails
      WHERE status = 'scheduled'
        AND COALESCE(scheduled_for,'') <> ''
        AND scheduled_for <= ?
      ORDER BY scheduled_for, created_at
      LIMIT 25;
    ", params = list(cycle_now))
    if (nrow(jobs) == 0) {
      append_scheduled_email_log("INFO", "No scheduled emails are due.")
      return(TRUE)
    }
    for (i in seq_len(nrow(jobs))) {
      if (nzchar(as.character(lease_token %||% ""))) heartbeat_drive_sync_lease(lease_token)
      job <- jobs[i, , drop = FALSE]
      email_id <- as.character(job$id[[1]] %||% "")
      project_id <- as.character(job$project_id[[1]] %||% "")
      tryCatch({
        attempt_now <- scheduled_email_now()
        dbExecute(con, "UPDATE scheduled_emails SET status = 'sending', last_attempt_at = ?, updated_at = ? WHERE id = ?;", params = list(attempt_now, attempt_now, email_id))
        recipients <- dbGetQuery(con, "SELECT * FROM scheduled_email_recipients WHERE email_id = ? AND COALESCE(status,'pending') <> 'sent' ORDER BY created_at;", params = list(email_id))
        attachments <- dbGetQuery(con, "SELECT * FROM scheduled_email_attachments WHERE email_id = ? ORDER BY created_at, attachment_name;", params = list(email_id))
        if (nrow(recipients) == 0) stop("No pending recipients remain for this scheduled email.")
        for (r in seq_len(nrow(recipients))) {
          recipient <- recipients[r, , drop = FALSE]
          recipient_id <- as.character(recipient$id[[1]] %||% "")
          tryCatch({
            send_single_scheduled_email_message(
              settings = settings,
              to_email = as.character(recipient$email_address[[1]] %||% ""),
              to_name = as.character(recipient$recipient_name[[1]] %||% ""),
              subject = as.character(job$subject[[1]] %||% ""),
              message_body = as.character(job$message_body[[1]] %||% ""),
              attachments = attachments
            )
            recipient_now <- scheduled_email_now()
            dbExecute(con, "UPDATE scheduled_email_recipients SET status = 'sent', sent_at = ?, last_error = '', updated_at = ? WHERE id = ?;", params = list(recipient_now, recipient_now, recipient_id))
          }, error = function(e) {
            recipient_error <- as.character(e$message %||% "Unknown email send error")
            dbExecute(con, "UPDATE scheduled_email_recipients SET status = 'failed', last_error = ?, updated_at = ? WHERE id = ?;", params = list(recipient_error, scheduled_email_now(), recipient_id))
            append_scheduled_email_log(
              "ERROR",
              paste0("Scheduled email recipient failed: ", recipient_error),
              email_id = email_id,
              project_id = project_id,
              detail = list(recipient = as.character(recipient$email_address[[1]] %||% ""), recipient_name = as.character(recipient$recipient_name[[1]] %||% ""))
            )
          })
        }
        final_rows <- dbGetQuery(con, "SELECT status FROM scheduled_email_recipients WHERE email_id = ?;", params = list(email_id))
        sent_count <- sum(as.character(final_rows$status %||% character()) == "sent", na.rm = TRUE)
        failed_count <- sum(as.character(final_rows$status %||% character()) == "failed", na.rm = TRUE)
        total_count <- nrow(final_rows)
        final_status <- if (sent_count > 0 && failed_count == 0) {
          "sent"
        } else if (sent_count > 0 && failed_count > 0) {
          "partially_sent"
        } else {
          "failed"
        }
        summary_text <- paste0("Sent: ", sent_count, " | Failed: ", failed_count, " | Total: ", total_count)
        latest_error <- ""
        if (identical(final_status, "failed") || identical(final_status, "partially_sent")) {
          error_rows <- dbGetQuery(con, "SELECT last_error FROM scheduled_email_recipients WHERE email_id = ? AND status = 'failed' ORDER BY updated_at DESC LIMIT 1;", params = list(email_id))
          if (nrow(error_rows) == 1) latest_error <- as.character(error_rows$last_error[[1]] %||% "")
        }
        summary_text <- scheduled_email_summary_text(summary_text, latest_error)
        if (!identical(final_status, "sent")) {
          success <<- FALSE
          if (!nzchar(as.character(final_error %||% ""))) {
            final_error <<- if (nzchar(latest_error)) latest_error else paste0("Scheduled email completed with status: ", final_status)
          }
        }
        dbExecute(con, "
          UPDATE scheduled_emails
          SET status = ?, actual_sent_at = ?, delivery_summary = ?, last_error = ?, updated_at = ?
          WHERE id = ?;
        ", params = list(final_status, if (identical(final_status, "sent")) scheduled_email_now() else as.character(job$actual_sent_at[[1]] %||% ""), summary_text, latest_error, scheduled_email_now(), email_id))
        try(mark_drive_project_dirty(project_id), silent = TRUE)
        append_scheduled_email_log(if (identical(final_status, "sent")) "INFO" else "ERROR", paste0("Scheduled email processed with status: ", final_status), email_id = email_id, project_id = project_id, detail = list(summary = summary_text))
        try(log_audit(module = "Communications", action = final_status, target_table = "scheduled_emails", target_id = email_id, detail = list(project_id = project_id, summary = summary_text), workspace_id = project_id, trigger_sync = FALSE), silent = TRUE)
      }, error = function(e) {
        success <<- FALSE
        final_error <<- as.character(e$message %||% "Unknown scheduled email error")
        dbExecute(con, "UPDATE scheduled_emails SET status = 'failed', last_error = ?, updated_at = ? WHERE id = ?;", params = list(final_error, scheduled_email_now(), email_id))
        try(mark_drive_project_dirty(project_id), silent = TRUE)
        append_scheduled_email_log("ERROR", paste0("Scheduled email failed: ", final_error), email_id = email_id, project_id = project_id)
      })
    }
    success
  }, error = function(e) {
    success <<- FALSE
    final_error <<- as.character(e$message %||% "Unknown scheduled email cycle error")
    append_scheduled_email_log("ERROR", paste0("Scheduled email cycle failed: ", final_error), detail = list(reason = reason))
    FALSE
  })
}

scheduled_email_runtime <- local({
  env <- new.env(parent = emptyenv())
  env$queued <- FALSE
  env$running <- FALSE
  env$active_lease_token <- ""
  env
})

cleanup_scheduled_email_future_job <- function() {
  if (isTRUE(scheduled_email_runtime$queued) && !isTRUE(scheduled_email_runtime$running)) {
    scheduled_email_runtime$queued <- FALSE
  }
  invisible(TRUE)
}

launch_background_scheduled_email_once_process <- function(reason = "scheduled") {
  expr <- paste0(
    "Sys.setenv(BUDGET_APP_MODE='worker', BUDGET_APP_ROOT=", r_string_literal(app_root), ");",
    "app_env <- new.env(parent = globalenv());",
    "source(", r_string_literal(file.path(startup_app_root, "app.R")), ", local = app_env, chdir = TRUE, encoding = 'UTF-8');",
    "result <- app_env$run_background_scheduled_email_once(reason = ", r_string_literal(as.character(reason %||% "scheduled")), ");",
    "quit(save = 'no', status = if (isTRUE(result)) 0L else 1L)"
  )
  launch_detached_rscript(expr, log_path = scheduled_email_log_path, reason = paste0("scheduled_email_once:", as.character(reason %||% "scheduled")))
}

start_scheduled_email_worker <- function(reason = "scheduled") {
  status <- email_delivery_status(get_email_delivery_settings(force = TRUE))
  if (isTRUE(status$settings$enabled) && !has_emayili) {
    install_ok <- tryCatch({
      ensure_email_packages_installed()
      TRUE
    }, error = function(e) {
      append_scheduled_email_log("ERROR", paste0("Unable to prepare scheduled email packages: ", e$message), detail = list(reason = reason))
      FALSE
    })
    if (!isTRUE(install_ok)) return(FALSE)
    status <- email_delivery_status(get_email_delivery_settings(force = TRUE))
  }
  if (!isTRUE(status$ok)) {
    if (isTRUE(status$settings$enabled)) append_scheduled_email_log("ERROR", status$reason, detail = list(reason = reason))
    return(FALSE)
  }
  if (can_launch_background_scheduler()) {
    launched <- isTRUE(launch_background_scheduled_email_once_process(reason = reason))
    if (launched) return(TRUE)
  }
  cleanup_scheduled_email_future_job()
  if (isTRUE(scheduled_email_runtime$queued) || isTRUE(scheduled_email_runtime$running)) {
    return(FALSE)
  }
  lease <- acquire_drive_sync_lease(lock_key = "scheduled_email_delivery", ttl_sec = max(300L, as.integer(status$settings$interval_sec) * 2L))
  if (!isTRUE(lease$acquired)) return(FALSE)
  scheduled_email_runtime$queued <- TRUE
  scheduled_email_runtime$active_lease_token <- as.character(lease$token %||% "")
  later::later(function() {
    scheduled_email_runtime$queued <- FALSE
    scheduled_email_runtime$running <- TRUE
    scheduled_email_runtime$active_lease_token <- as.character(lease$token %||% "")
    on.exit({
      scheduled_email_runtime$running <- FALSE
      scheduled_email_runtime$active_lease_token <- ""
    }, add = TRUE)
    tryCatch({
      run_scheduled_email_cycle(
        lease_token = as.character(lease$token %||% ""),
        reason = as.character(reason %||% "scheduled")
      )
    }, error = function(e) {
      append_scheduled_email_log("ERROR", paste0("Scheduled email runner crashed: ", e$message), detail = list(reason = reason))
      try(release_drive_sync_lease(as.character(lease$token %||% ""), success = FALSE, error_message = e$message), silent = TRUE)
      FALSE
    })
  }, delay = 0)
  TRUE
}

initialize_scheduled_email_scheduler <- local({
  scheduler_started <- FALSE
  function(force = FALSE) {
    if (!identical(app_mode, "app")) return(invisible(FALSE))
    if (scheduler_started && !isTRUE(force)) return(invisible(TRUE))
    scheduler_started <<- TRUE
    schedule_next <- function() {
      delay <- get_email_delivery_settings()$interval_sec
      later::later(function() {
        try(start_scheduled_email_worker("scheduled"), silent = TRUE)
        schedule_next()
      }, delay = delay)
    }
    later::later(function() {
      try(start_scheduled_email_worker("startup"), silent = TRUE)
      schedule_next()
    }, delay = 8)
    invisible(TRUE)
  }
})

initialize_background_scheduler_watchdog <- local({
  watchdog_started <- FALSE
  function(force = FALSE) {
    if (!can_launch_background_scheduler()) return(invisible(FALSE))
    if (watchdog_started && !isTRUE(force)) return(invisible(TRUE))
    watchdog_started <<- TRUE
    tick <- function() {
      later::later(function() {
        try(ensure_background_scheduler_service("watchdog"), silent = TRUE)
        tick()
      }, delay = 120)
    }
    later::later(function() {
      try(ensure_background_scheduler_service("watchdog"), silent = TRUE)
      tick()
    }, delay = 20)
    invisible(TRUE)
  }
})

append_background_scheduler_log <- function(level = "INFO", message, detail = list()) {
  timestamp <- format(Sys.time(), "%Y-%m-%d %H:%M:%S")
  payload <- if (!is.null(detail) && length(detail) > 0) {
    paste0(" ", json_stringify(detail, auto_unbox = TRUE, null = "null"))
  } else {
    ""
  }
  line <- paste0("[", timestamp, "] [", toupper(as.character(level %||% "INFO")), "] ", as.character(message %||% ""), payload)
  cat(line, "\n", file = background_scheduler_log_path, append = TRUE)
  invisible(line)
}

get_background_scheduler_lock <- function() {
  get_drive_sync_lock("background_scheduler")
}

background_scheduler_is_active <- function() {
  row <- get_background_scheduler_lock()
  if (nrow(row) != 1) return(FALSE)
  locked_until <- suppressWarnings(as.numeric(row$locked_until[[1]] %||% 0))
  !is.na(locked_until) && locked_until > as.numeric(Sys.time())
}

background_scheduler_status <- function() {
  row <- get_background_scheduler_lock()
  active <- FALSE
  heartbeat_at <- ""
  started_at <- ""
  last_success <- ""
  last_error <- ""
  if (nrow(row) == 1) {
    locked_until <- suppressWarnings(as.numeric(row$locked_until[[1]] %||% 0))
    active <- !is.na(locked_until) && locked_until > as.numeric(Sys.time())
    heartbeat_at <- as.character(row$updated_at[[1]] %||% "")
    started_at <- as.character(row$started_at[[1]] %||% "")
    last_success <- as.character(row$last_success_at[[1]] %||% "")
    last_error <- as.character(row$last_error[[1]] %||% "")
  }
  list(active = active, heartbeat_at = heartbeat_at, started_at = started_at, last_success = last_success, last_error = last_error)
}

can_launch_background_scheduler <- function() {
  identical(app_mode, "app") && !interactive()
}

run_background_drive_sync_once <- function(reason = "background_scheduler") {
  settings <- get_drive_sync_settings(force = TRUE)
  if (!isTRUE(settings$enabled)) return(FALSE)
  if (identical(settings$backend, "google_drive") && (!has_googledrive || !has_gargle)) {
    install_ok <- tryCatch({
      ensure_drive_packages_installed()
      TRUE
    }, error = function(e) {
      append_background_scheduler_log("ERROR", paste0("Unable to prepare Google Drive packages: ", e$message), detail = list(reason = reason))
      FALSE
    })
    if (!isTRUE(install_ok)) return(FALSE)
  }
  status <- drive_sync_status(settings)
  if (!isTRUE(status$ok)) return(FALSE)
  lease <- acquire_drive_sync_lease(lock_key = "google_drive_backup", ttl_sec = max(900L, as.integer(status$settings$interval_sec %||% 300L) * 2L))
  if (!isTRUE(lease$acquired)) return(FALSE)
  isTRUE(run_drive_sync_cycle(lease_token = as.character(lease$token %||% ""), reason = reason))
}

run_background_scheduled_email_once <- function(reason = "background_scheduler") {
  if (!has_emayili) {
    install_ok <- tryCatch({
      ensure_email_packages_installed()
      TRUE
    }, error = function(e) {
      append_background_scheduler_log("ERROR", paste0("Unable to prepare email packages: ", e$message), detail = list(reason = reason))
      FALSE
    })
    if (!isTRUE(install_ok)) return(FALSE)
  }
  status <- email_delivery_status(get_email_delivery_settings(force = TRUE))
  if (!isTRUE(status$ok)) return(FALSE)
  lease <- acquire_drive_sync_lease(lock_key = "scheduled_email_delivery", ttl_sec = max(300L, as.integer(status$settings$interval_sec %||% 60L) * 2L))
  if (!isTRUE(lease$acquired)) return(FALSE)
  isTRUE(run_scheduled_email_cycle(lease_token = as.character(lease$token %||% ""), reason = reason, force_settings_refresh = TRUE))
}

run_background_scheduler_loop <- function(run_once = identical(tolower(Sys.getenv("BUDGET_APP_HELPER_ONCE", unset = "false")), "true")) {
  helper_lease <- acquire_drive_sync_lease(lock_key = "background_scheduler", ttl_sec = 120L)
  if (!isTRUE(helper_lease$acquired)) {
    append_background_scheduler_log("INFO", "Background scheduler is already running. Exiting duplicate helper.")
    return(invisible(FALSE))
  }
  append_background_scheduler_log("INFO", "Background scheduler started.", detail = list(run_once = isTRUE(run_once)))
  on.exit({
    try(release_drive_sync_lease(as.character(helper_lease$token %||% ""), success = TRUE, error_message = ""), silent = TRUE)
    append_background_scheduler_log("INFO", "Background scheduler stopped.")
  }, add = TRUE)

  next_drive_run_at <- 0
  next_email_run_at <- 0
  repeat {
    heartbeat_drive_sync_lease(as.character(helper_lease$token %||% ""), extend_sec = 120L)
    now_epoch <- as.numeric(Sys.time())
    drive_interval <- max(300L, as.integer(get_drive_sync_settings(force = TRUE)$interval_sec %||% 300L))
    email_interval <- max(30L, as.integer(get_email_delivery_settings(force = TRUE)$interval_sec %||% 60L))

    if (now_epoch >= next_drive_run_at) {
      tryCatch({
        run_background_drive_sync_once(reason = "background_scheduler")
      }, error = function(e) {
        append_background_scheduler_log("ERROR", paste0("Background Drive sync iteration failed: ", e$message))
      })
      next_drive_run_at <- now_epoch + drive_interval
    }

    if (now_epoch >= next_email_run_at) {
      tryCatch({
        run_background_scheduled_email_once(reason = "background_scheduler")
      }, error = function(e) {
        append_background_scheduler_log("ERROR", paste0("Background email iteration failed: ", e$message))
      })
      next_email_run_at <- now_epoch + email_interval
    }

    if (isTRUE(run_once)) break
    Sys.sleep(5)
  }
  invisible(TRUE)
}

launch_background_scheduler_process <- function(reason = "startup") {
  expr <- paste0(
    "Sys.setenv(BUDGET_APP_MODE='worker', BUDGET_APP_ROOT=", r_string_literal(app_root), ");",
    "app_env <- new.env(parent = globalenv());",
    "source(", r_string_literal(file.path(startup_app_root, "app.R")), ", local = app_env, chdir = TRUE, encoding = 'UTF-8');",
    "app_env$run_background_scheduler_loop(run_once = FALSE)"
  )
  launch_detached_rscript(expr, log_path = background_scheduler_log_path, reason = paste0("background_scheduler:", as.character(reason %||% "startup")))
}

ensure_background_scheduler_service <- function(reason = "startup") {
  if (!can_launch_background_scheduler()) return(FALSE)
  if (background_scheduler_is_active()) return(TRUE)
  launched <- isTRUE(launch_background_scheduler_process(reason = reason))
  if (!launched) return(FALSE)
  TRUE
}

# ---------------------------
# create_expense extended to accept optional breakdowns (additive)
# - This does not break older callers; breakdowns default to NULL.
# ---------------------------
create_expense <- function(id, project_id, description, amount, category_main = NULL, category_sub = NULL, date = NULL, receipt_tmpfile = NULL, receipt_name = NULL, breakdowns = NULL, created_by_role = "Administrator") {
  tryCatch({
    if (is.null(project_id) || !nzchar(as.character(project_id))) stop("create_expense requires a valid project_id (enforced by UI).")
    con <- connect_db()
    on.exit({
      if (DBI::dbIsValid(con)) dbDisconnect(con)
    }, add = TRUE)
    ensure_expenses_schema(con)
    nowt <- now()
    receipt_path <- ""
    if (!is.null(receipt_tmpfile) && receipt_tmpfile != "" && !is.null(receipt_name)) {
      if (safe_file_size(receipt_tmpfile) > max_upload_request_bytes) stop("Receipt file exceeds the supported size limit for this server.")
      ext <- path_ext(receipt_name)
      fname <- paste0("receipt_", id, ifelse(ext == "", "", paste0(".", ext)))
      dest <- file.path(receipts_dir, fname)
      receipt_path <- copy_file_checked(receipt_tmpfile, dest, overwrite = TRUE)
      attach <- data.frame(id = uuid("att"), expense_id = id, filename = receipt_name, filepath = receipt_path, mimetype = "", size = safe_file_size(receipt_path), checksum = file_checksum(receipt_path), created_at = nowt, stringsAsFactors = FALSE)
      dbWriteTable(con, "attachments", attach, append = TRUE, row.names = FALSE)
    }
    
    # normalize category fields into the legacy 'category' for compatibility
    cat_main <- ifelse(is.null(category_main), "", as.character(category_main))
    cat_sub <- ifelse(is.null(category_sub), "", as.character(category_sub))
    combined_cat <- ifelse(nzchar(cat_sub), paste(cat_main, cat_sub, sep = " - ") , cat_main)
    source_role <- expense_scope_storage_role(default_expense_scope_for_role(created_by_role %||% "Administrator"))
    df <- data.frame(id = id, project_id = as.character(project_id), description = description, amount = amount, category = combined_cat, category_main = cat_main, category_sub = cat_sub, created_by_role = source_role, date = ifelse(is.null(date), "", date), receipt_path = receipt_path, created_at = nowt, updated_at = nowt, is_trashed = 0, stringsAsFactors = FALSE)
    dbWriteTable(con, "expenses", df, append = TRUE, row.names = FALSE)
    # NEW: store breakdowns if provided
    if (!is.null(breakdowns) && length(breakdowns) > 0) {
      create_breakdowns_for_expense(id, breakdowns)
    }
    dbDisconnect(con)
    log_audit(module = "Expenses", action = "create", target_table = "expenses", target_id = id, detail = list(amount = amount, project_id = project_id, category_main = cat_main, category_sub = cat_sub), trigger_sync = FALSE)
    try(queue_project_workbook_sync(project_id, reason = "expense_created"), silent = TRUE)
    TRUE
  }, error = function(e) { message("create_expense error: ", e$message); FALSE })
}

update_expense <- function(id, fields, acting_role = "Administrator") {
  tryCatch({
    if (!is.list(fields) || length(fields) == 0) stop("No expense fields were supplied for update.")
    con <- connect_db()
    on.exit({
      if (DBI::dbIsValid(con)) dbDisconnect(con)
    }, add = TRUE)
    ensure_expenses_schema(con)
    expense_row <- dbGetQuery(con, "SELECT project_id, category_main, category_sub, created_by_role FROM expenses WHERE id = ? LIMIT 1;", params = list(id))
    if (nrow(expense_row) != 1) stop("Expense not found.")
    if (identical(default_expense_scope_for_role(acting_role %||% "Administrator"), "scientist") &&
        !identical(normalize_expense_source_scope(expense_row$created_by_role[[1]] %||% ""), "scientist")) {
      stop("User/Scientist users cannot modify Admin expenses.")
    }
    # if updating category_main/sub, update combined category too
    if ("category_main" %in% names(fields)) {
      main <- as.character(as_db_scalar(fields$category_main, field_name = "Expense category", default = ""))
      sub <- ifelse("category_sub" %in% names(fields), as.character(as_db_scalar(fields$category_sub, field_name = "Expense subcategory", default = "")), expense_row$category_sub[[1]] %||% "")
      fields$category <- ifelse(nzchar(sub), paste(main, sub, sep = " - "), main)
    } else if ("category_sub" %in% names(fields) && !("category" %in% names(fields))) {
      sub <- as.character(as_db_scalar(fields$category_sub, field_name = "Expense subcategory", default = ""))
      main <- expense_row$category_main[[1]] %||% ""
      fields$category <- ifelse(nzchar(sub), paste(main, sub, sep = " - "), main)
    }
    if ("description" %in% names(fields)) {
      fields$description <- as.character(as_db_scalar(fields$description, field_name = "Expense description", default = ""))
    }
    if ("amount" %in% names(fields)) {
      fields$amount <- as.numeric(as_db_scalar(fields$amount, field_name = "Expense amount", default = 0))
      if (is.na(fields$amount)) stop("Expense amount must be a valid number.")
    }
    if ("date" %in% names(fields)) {
      fields$date <- normalize_optional_date_value(fields$date, field_name = "Expense date")
    }
    fields$updated_at <- now()
    set_sql <- paste0(names(fields), " = ?", collapse = ", ")
    params <- c(
      lapply(seq_along(fields), function(i) {
        as_db_scalar(fields[[i]], field_name = names(fields)[[i]], default = "")
      }),
      list(as.character(id))
    )
    sql <- paste0("UPDATE expenses SET ", set_sql, " WHERE id = ?;")
    DBI::dbWithTransaction(con, {
      rows_changed <- dbExecute(con, sql, params = params)
      if (is.na(rows_changed)) stop("Expense update did not complete.")
    })
    project_id <- as.character(expense_row$project_id[[1]] %||% "")
    dbDisconnect(con)
    try(log_audit(module = "Expenses", action = "update", target_table = "expenses", target_id = id, detail = fields, trigger_sync = FALSE), silent = TRUE)
    if (nzchar(project_id)) {
      try(queue_project_workbook_sync(project_id, reason = "expense_updated"), silent = TRUE)
    }
    TRUE
  }, error = function(e) { message("update_expense error: ", e$message); FALSE })
}

soft_delete_expense <- function(id, acting_role = "Administrator") {
  tryCatch({
    con <- connect_db(); on.exit(dbDisconnect(con))
    proj <- dbGetQuery(con, "SELECT project_id, created_by_role FROM expenses WHERE id = ?;", params = list(id))
    if (nrow(proj) != 1) stop("Expense not found.")
    if (identical(default_expense_scope_for_role(acting_role %||% "Administrator"), "scientist") &&
        !identical(normalize_expense_source_scope(proj$created_by_role[[1]] %||% ""), "scientist")) {
      stop("User/Scientist users cannot delete Admin expenses.")
    }
    dbExecute(con, "UPDATE expenses SET is_trashed = 1, updated_at = ? WHERE id = ?;", params = list(now(), id))
    log_audit(module = "Expenses", action = "trash", target_table = "expenses", target_id = id, detail = list(), trigger_sync = FALSE)
    if (nrow(proj) == 1 && nzchar(proj$project_id)) try(queue_project_workbook_sync(proj$project_id, reason = "expense_trashed"), silent = TRUE)
    TRUE
  }, error = function(e) { message("soft_delete_expense error: ", e$message); FALSE })
}

restore_expense <- function(id, acting_role = "Administrator") {
  tryCatch({
    con <- connect_db(); on.exit(dbDisconnect(con))
    proj <- dbGetQuery(con, "SELECT project_id, created_by_role FROM expenses WHERE id = ?;", params = list(id))
    if (nrow(proj) != 1) stop("Expense not found.")
    if (identical(default_expense_scope_for_role(acting_role %||% "Administrator"), "scientist") &&
        !identical(normalize_expense_source_scope(proj$created_by_role[[1]] %||% ""), "scientist")) {
      stop("User/Scientist users cannot restore Admin expenses.")
    }
    dbExecute(con, "UPDATE expenses SET is_trashed = 0, updated_at = ? WHERE id = ?;", params = list(now(), id))
    log_audit(module = "Expenses", action = "restore", target_table = "expenses", target_id = id, detail = list(), trigger_sync = FALSE)
    if (nrow(proj) == 1 && nzchar(proj$project_id)) try(queue_project_workbook_sync(proj$project_id, reason = "expense_restored"), silent = TRUE)
    TRUE
  }, error = function(e) { message("restore_expense error: ", e$message); FALSE })
}

# ---------------------------
# Reporting: Excel & HTML/PDF (project-only)
# Modified to include breakdowns under each expense in both Excel and HTML reports.
# PDF still excludes the audit trail.
# ---------------------------
write_excel_report <- function(project_id, watermark = NULL, start_date = NULL, end_date = NULL, password = NULL, output_dir = NULL, request_tag = NULL, expense_scope = "all") {
  if (is.null(project_id) || !nzchar(as.character(project_id))) {
    message("write_excel_report requires a valid project_id")
    return(NULL)
  }
  tryCatch({
    ctx <- build_report_context(project_id, start_date, end_date, expense_scope = expense_scope)
    export_dir <- output_dir %||% get_export_folder()
    dir_create(export_dir, recurse = TRUE)

    wb <- createWorkbook(creator = "Budget Tracker")
    modifyBaseFont(wb, fontName = "Calibri", fontSize = 11)

    title_style <- createStyle(fontSize = 16, textDecoration = "bold", fontColour = "#0b2545")
    subtitle_style <- createStyle(fontSize = 10, fontColour = "#6b7280")
    section_style <- createStyle(fontSize = 12, textDecoration = "bold", fgFill = "#eaf3ff", border = "Bottom", borderColour = "#dbe7f3")
    label_style <- createStyle(textDecoration = "bold", fontColour = "#334155")
    money_style <- createStyle(numFmt = excel_currency_numfmt(), halign = "right")
    main_row_style <- createStyle(textDecoration = "bold", fgFill = "#f5fbff", border = "Bottom", borderColour = "#dbe7f3")
    breakdown_style <- createStyle(fontColour = "#64748b", fgFill = "#fafafa")
    note_style <- createStyle(fontColour = "#52606d", wrapText = TRUE)

    addWorksheet(wb, "Overview", gridLines = FALSE)
    writeData(wb, "Overview", "Budget Tracker Report", startRow = 1, startCol = 1)
    addStyle(wb, "Overview", title_style, rows = 1, cols = 1)
    writeData(wb, "Overview", paste0("Generated ", format(Sys.time(), "%Y-%m-%d %H:%M:%S")), startRow = 2, startCol = 1)
    addStyle(wb, "Overview", subtitle_style, rows = 2, cols = 1)

    overview_info <- data.frame(
      Item = c("Project", "Project ID", "Project Status", "Expense Source", "Principle Investigator", "Team Members", "Project Start Date", "Project End Date", "Report Scope"),
      Value = c(
        ctx$project$name,
        ctx$project$id,
        ctx$project$status,
        ctx$expense_scope_label,
        ctx$project$principal_investigator,
        ctx$project$team_members,
        ctx$project$start_date %||% "",
        ctx$project$end_date %||% "",
        if (ctx$is_filtered) paste0(ctx$start_date, " to ", ctx$end_date) else "Full project history"
      ),
      stringsAsFactors = FALSE
    )
    overview_header_row <- 4
    overview_table_row <- overview_header_row + 1
    overview_first_data_row <- overview_table_row + 1
    overview_last_data_row <- overview_table_row + nrow(overview_info)
    writeData(wb, "Overview", "Project Details", startRow = overview_header_row, startCol = 1)
    addStyle(wb, "Overview", section_style, rows = overview_header_row, cols = 1:2, gridExpand = TRUE)
    writeData(wb, "Overview", overview_info, startRow = overview_table_row, startCol = 1, colNames = TRUE)
    addStyle(wb, "Overview", label_style, rows = overview_first_data_row:overview_last_data_row, cols = 1, gridExpand = TRUE)

    summary_df <- data.frame(
      Metric = c("Total Project Budget", "Total Project Spent (All Time)", "Remaining Balance", report_total_label(ctx)),
      Amount = c(ctx$total_budget, ctx$total_spent_all, ctx$remaining_all, ctx$total_spent_period),
      stringsAsFactors = FALSE
    )
    summary_header_row <- overview_last_data_row + 2
    summary_table_row <- summary_header_row + 1
    summary_first_data_row <- summary_table_row + 1
    summary_last_data_row <- summary_table_row + nrow(summary_df)
    note_row <- summary_last_data_row + 2
    writeData(wb, "Overview", "Financial Summary", startRow = summary_header_row, startCol = 1)
    addStyle(wb, "Overview", section_style, rows = summary_header_row, cols = 1:2, gridExpand = TRUE)
    writeDataTable(wb, "Overview", summary_df, startRow = summary_table_row, startCol = 1, tableStyle = "TableStyleMedium2")
    addStyle(wb, "Overview", money_style, rows = summary_first_data_row:summary_last_data_row, cols = 2, gridExpand = TRUE)
    writeData(wb, "Overview", report_total_note(ctx), startRow = note_row, startCol = 1)
    addStyle(wb, "Overview", note_style, rows = note_row, cols = 1)
    setColWidths(wb, "Overview", cols = 1:2, widths = c(28, 28))

    addWorksheet(wb, "Category Summary", gridLines = FALSE)
    writeData(wb, "Category Summary", "Category Summary", startRow = 1, startCol = 1)
    addStyle(wb, "Category Summary", title_style, rows = 1, cols = 1)
    if (nrow(ctx$category_summary) == 0) {
      writeData(wb, "Category Summary", data.frame(Message = "No expenses found for the selected criteria."), startRow = 3, startCol = 1)
    } else {
      summary_sheet <- ctx$category_summary %>%
        mutate(
          Category = ifelse(Level == "main", MainCategory, paste0("  - ", Subcategory))
        ) %>%
        select(Category, Amount)
      writeDataTable(wb, "Category Summary", summary_sheet, startRow = 3, startCol = 1, tableStyle = "TableStyleMedium9")
      addStyle(wb, "Category Summary", money_style, rows = 4:(nrow(summary_sheet) + 3), cols = 2, gridExpand = TRUE)
      main_rows <- which(ctx$category_summary$Level == "main") + 3
      if (length(main_rows) > 0) {
        addStyle(wb, "Category Summary", main_row_style, rows = main_rows, cols = 1:2, gridExpand = TRUE)
      }
      freezePane(wb, "Category Summary", firstActiveRow = 4)
      setColWidths(wb, "Category Summary", cols = 1:2, widths = c(42, 18))
    }

    addWorksheet(wb, "Expense Details", gridLines = FALSE)
    writeData(wb, "Expense Details", "Expense Details", startRow = 1, startCol = 1)
    addStyle(wb, "Expense Details", title_style, rows = 1, cols = 1)
    if (nrow(ctx$detail_rows) == 0) {
      writeData(wb, "Expense Details", data.frame(Message = "No expenses found for the selected criteria."), startRow = 3, startCol = 1)
    } else {
      detail_sheet <- ctx$detail_rows %>%
        transmute(
          Date = Date,
          Category = ifelse(RowType == "breakdown", "", MainCategory),
          Subcategory = ifelse(RowType == "breakdown", "", Subcategory),
          Description = Description,
          Amount = Amount,
          Receipt = Receipt
        )
      writeDataTable(wb, "Expense Details", detail_sheet, startRow = 3, startCol = 1, tableStyle = "TableStyleLight9")
      addStyle(wb, "Expense Details", money_style, rows = 4:(nrow(detail_sheet) + 3), cols = 5, gridExpand = TRUE)
      breakdown_rows <- which(ctx$detail_rows$RowType == "breakdown") + 3
      if (length(breakdown_rows) > 0) {
        addStyle(wb, "Expense Details", breakdown_style, rows = breakdown_rows, cols = 1:ncol(detail_sheet), gridExpand = TRUE)
      }
      total_row <- nrow(detail_sheet) + 5
      writeData(wb, "Expense Details", data.frame(Label = report_total_label(ctx), Amount = ctx$total_spent_period), startRow = total_row, startCol = 4, colNames = TRUE)
      addStyle(wb, "Expense Details", label_style, rows = total_row + 1, cols = 4)
      addStyle(wb, "Expense Details", money_style, rows = total_row + 1, cols = 5)
      freezePane(wb, "Expense Details", firstActiveRow = 4)
      setColWidths(wb, "Expense Details", cols = 1:6, widths = c(12, 20, 20, 42, 16, 12))
    }

    workbook_password <- password %||% get_setting("excel_password") %||% ""
    if (!is.null(watermark) && nzchar(as.character(watermark))) {
      for (sheet_name in names(wb)) {
        try(setHeaderFooter(wb, sheet = sheet_name, header = c("", as.character(watermark), "")), silent = TRUE)
      }
    }
    if (nzchar(workbook_password)) {
      for (sheet_name in names(wb)) {
        try(protectWorksheet(wb, sheet = sheet_name, protect = TRUE, password = workbook_password), silent = TRUE)
      }
    }

    file_stem <- build_report_file_stem(ctx$project$name, request_tag = request_tag)
    wb_path <- file.path(export_dir, paste0(file_stem, ".xlsx"))
    saveWorkbook(wb, wb_path, overwrite = TRUE)
    register_export(wb_path, "excel", project_id, detail = list(filtered = ctx$is_filtered, expense_scope = ctx$expense_scope))
  }, error = function(e) {
    message("write_excel_report error: ", e$message); NULL
  })
}


# ---------------------------
# Reporting: HTML/PDF Report Generation (project-only)
# STRUCTURE:
# Section 1: Project Financial Summary
#   - Total Project Budget (all-time)
#   - Total Project Spent (all-time)
#   - Remaining Balance (all-time)
# Section 2: Filtered Expense Details
#   - Only expenses within selected date range (if filtering enabled)
#   - Categories and subcategories with breakdowns
# Section 3: Period Expense Total
#   - Sum of expenses within selected date range
#   - Clearly labeled and distinguished from project totals
# 
# When date filtering is NOT enabled:
#   - Sections 2 and 3 show all project expenses
#   - The "selected period" label does not appear
#
# When date filtering IS enabled:
#   - Sections 2 and 3 show only filtered expenses
#   - A filter notice appears below project summary
#   - Period total is clearly marked as period-specific
# 
# Audit data is NEVER included in reports (per requirements)
# ---------------------------

# CORRECTED: write_html_pdf_report function
write_html_pdf_report <- function(project_id, pdf = FALSE, watermark = NULL, start_date = NULL, end_date = NULL, output_dir = NULL, work_dir = NULL, request_tag = NULL, expense_scope = "all") {
  if (is.null(project_id) || !nzchar(as.character(project_id))) {
    message("write_html_pdf_report requires a valid project_id")
    return(NULL)
  }
  tryCatch({
    ctx <- build_report_context(project_id, start_date, end_date, expense_scope = expense_scope)
    generated_at <- format(Sys.time(), "%Y-%m-%d %H:%M:%S")
    title <- paste0("Budget Tracker - Project Report: ", ctx$project$name)
    body_html <- generate_report_preview_html(project_id, start_date, end_date, watermark, expense_scope = expense_scope)
    html_doc <- paste0(
      "<!doctype html><html><head><meta charset='utf-8'><meta name='viewport' content='width=device-width, initial-scale=1'>",
      sprintf("<title>%s</title>", html_escape(title)),
      "<style>body{margin:0;background:#ffffff;} footer{padding:0 20px 20px;color:#666;font-size:11px;font-family:Arial,Helvetica,sans-serif;}</style>",
      "</head><body>",
      body_html,
      sprintf("<footer>Generated: %s</footer>", html_escape(generated_at)),
      "</body></html>"
    )

    final_dir <- output_dir %||% get_export_folder()
    temp_dir <- work_dir %||% final_dir
    dir_create(final_dir, recurse = TRUE)
    dir_create(temp_dir, recurse = TRUE)

    base_name <- build_report_file_stem(ctx$project$name, request_tag = request_tag)
    temp_html_path <- file.path(temp_dir, paste0(base_name, ".html"))
    writeLines(enc2utf8(html_doc), temp_html_path, useBytes = TRUE)

    if (isTRUE(pdf)) {
      final_pdf_path <- file.path(final_dir, paste0(base_name, ".pdf"))
      pdf_written <- FALSE

      if (can_render_pdf()) {
        chrome_bin <- find_browser_binary()
        old_browser <- Sys.getenv("PAGEDOWN_CHROME", unset = "")
        on.exit({
          if (nzchar(old_browser)) {
            Sys.setenv(PAGEDOWN_CHROME = old_browser)
          } else {
            Sys.unsetenv("PAGEDOWN_CHROME")
          }
        }, add = TRUE)

        pdf_written <- isTRUE(tryCatch({
          Sys.setenv(PAGEDOWN_CHROME = chrome_bin)
          pagedown::chrome_print(
            input = normalizePath(temp_html_path, winslash = "/", mustWork = TRUE),
            output = final_pdf_path
          )
          file.exists(final_pdf_path)
        }, error = function(e) {
          message("Browser PDF generation failed, using fallback PDF writer: ", e$message)
          FALSE
        }))
      }

      if (!pdf_written) {
        write_pdf_report_fallback(
          ctx = ctx,
          output_file = final_pdf_path,
          watermark = watermark,
          generated_at = generated_at
        )
      }

      return(register_export(
        final_pdf_path,
        "pdf",
        project_id,
        detail = list(filtered = ctx$is_filtered, renderer = if (pdf_written) "browser" else "fallback", expense_scope = ctx$expense_scope)
      ))
    }

    final_html_path <- file.path(final_dir, paste0(base_name, ".html"))
    if (!identical(normalizePath(temp_html_path, winslash = "/", mustWork = FALSE), normalizePath(final_html_path, winslash = "/", mustWork = FALSE))) {
      final_html_path <- copy_file_checked(temp_html_path, final_html_path, overwrite = TRUE)
    }
    register_export(final_html_path, "html", project_id, detail = list(filtered = ctx$is_filtered, expense_scope = ctx$expense_scope))
  }, error = function(e) {
    message("write_html_pdf_report error: ", e$message)
    return(NULL)
  })
}

# ---------------------------
# LOAD APPLICATION DATA (REPLACEMENT FOR DEV-ONLY load_all())
# This function centralizes reading DB tables into R objects for the app.
# ---------------------------
normalize_projects_frame <- function(projects) {
  if (is.null(projects) || !is.data.frame(projects)) {
    projects <- data.frame(stringsAsFactors = FALSE)
  }
  ensure_chr_col <- function(df, col_name, default = "") {
    if (!(col_name %in% names(df))) {
      df[[col_name]] <- rep(default, nrow(df))
    } else {
      df[[col_name]] <- as.character(df[[col_name]] %||% rep(default, nrow(df)))
    }
    df
  }
  ensure_num_col <- function(df, col_name, default = 0) {
    if (!(col_name %in% names(df))) {
      df[[col_name]] <- rep(default, nrow(df))
    } else {
      df[[col_name]] <- suppressWarnings(as.numeric(df[[col_name]]))
      df[[col_name]][is.na(df[[col_name]])] <- default
    }
    df
  }
  ensure_int_col <- function(df, col_name, default = 0L) {
    if (!(col_name %in% names(df))) {
      df[[col_name]] <- rep(default, nrow(df))
    } else {
      df[[col_name]] <- suppressWarnings(as.integer(df[[col_name]]))
      df[[col_name]][is.na(df[[col_name]])] <- default
    }
    df
  }
  for (col_name in c("id", "name", "description", "principal_investigator", "team_members", "status", "access_key", "created_at", "updated_at", "start_date", "end_date")) {
    projects <- ensure_chr_col(projects, col_name, "")
  }
  projects <- ensure_num_col(projects, "budget_total", 0)
  projects <- ensure_int_col(projects, "is_trashed", 0L)
  projects <- ensure_int_col(projects, "budget_locked", 0L)
  if (nrow(projects) == 0) return(projects)
  for (col_name in intersect(c("created_at", "updated_at", "start_date", "end_date"), names(projects))) {
    projects[[col_name]] <- ifelse(as.character(projects[[col_name]] %||% "") == "", NA, as.character(projects[[col_name]]))
  }
  if (nrow(projects) > 0) {
    projects$status <- vapply(projects$status, normalize_project_status, character(1))
    projects$team_members <- vapply(projects$team_members, normalize_team_members_text, character(1))
    projects$principal_investigator <- ifelse(is.na(projects$principal_investigator), "", as.character(projects$principal_investigator))
  }
  projects
}

normalize_expenses_frame <- function(expenses) {
  if (is.null(expenses) || !is.data.frame(expenses)) expenses <- data.frame(stringsAsFactors = FALSE)
  ensure_chr_col <- function(df, col_name, default = "") {
    if (!(col_name %in% names(df))) {
      df[[col_name]] <- rep(default, nrow(df))
    } else {
      df[[col_name]] <- as.character(df[[col_name]] %||% rep(default, nrow(df)))
    }
    df
  }
  ensure_num_col <- function(df, col_name, default = 0) {
    if (!(col_name %in% names(df))) {
      df[[col_name]] <- rep(default, nrow(df))
    } else {
      df[[col_name]] <- suppressWarnings(as.numeric(df[[col_name]]))
      df[[col_name]][is.na(df[[col_name]])] <- default
    }
    df
  }
  ensure_int_col <- function(df, col_name, default = 0L) {
    if (!(col_name %in% names(df))) {
      df[[col_name]] <- rep(default, nrow(df))
    } else {
      df[[col_name]] <- suppressWarnings(as.integer(df[[col_name]]))
      df[[col_name]][is.na(df[[col_name]])] <- default
    }
    df
  }
  for (col_name in c("id", "project_id", "description", "category", "category_main", "category_sub", "receipt_path", "created_at", "updated_at", "date", "created_by_role")) {
    expenses <- ensure_chr_col(expenses, col_name, if (identical(col_name, "created_by_role")) "Administrator" else "")
  }
  expenses <- ensure_num_col(expenses, "amount", 0)
  expenses <- ensure_int_col(expenses, "is_trashed", 0L)
  role_values <- if (nrow(expenses) > 0) as.character(expenses$created_by_role %||% rep("Administrator", nrow(expenses))) else character()
  scope_values <- if (length(role_values) > 0) vapply(role_values, normalize_expense_source_scope, character(1)) else character()
  expenses$expense_source_scope <- scope_values
  expenses$created_by_role <- if (length(scope_values) > 0) vapply(scope_values, expense_scope_storage_role, character(1)) else character()
  expenses$expense_source_label <- if (length(scope_values) > 0) vapply(scope_values, expense_scope_view_label, character(1)) else character()
  if (nrow(expenses) == 0) return(expenses)
  for (col_name in intersect(c("created_at", "updated_at", "date"), names(expenses))) {
    expenses[[col_name]] <- ifelse(as.character(expenses[[col_name]] %||% "") == "", NA, as.character(expenses[[col_name]]))
  }
  expenses
}

load_projects_expenses_bundle <- function(workspace_id = NULL, con = NULL, expense_scope = "all", busy_timeout_ms = 60000L, retries = 5L, base_delay = 0.2) {
  project_scope <- if (is.null(workspace_id) || !nzchar(as.character(workspace_id))) NULL else as.character(workspace_id)
  close_con <- FALSE
  if (is.null(con)) {
    con <- connect_db(busy_timeout_ms = busy_timeout_ms, retries = retries, base_delay = base_delay)
    close_con <- TRUE
  }
  if (isTRUE(close_con)) on.exit(dbDisconnect(con), add = TRUE)
  try(ensure_expenses_schema(con), silent = TRUE)
  if (is.null(project_scope)) {
    projects <- dbGetQuery(con, "SELECT * FROM projects ORDER BY created_at DESC;")
    expense_sql <- "SELECT * FROM expenses"
    expense_params <- list()
  } else {
    projects <- dbGetQuery(con, "SELECT * FROM projects WHERE id = ? ORDER BY created_at DESC;", params = list(project_scope))
    expense_sql <- "SELECT * FROM expenses WHERE project_id = ?"
    expense_params <- list(project_scope)
  }
  expense_aliases <- expense_scope_sql_aliases(expense_scope)
  if (length(expense_aliases) > 0) {
    placeholders <- paste(rep("?", length(expense_aliases)), collapse = ", ")
    clause <- paste0("LOWER(TRIM(COALESCE(created_by_role,''))) IN (", placeholders, ")")
    expense_sql <- if (grepl("\\bWHERE\\b", expense_sql, ignore.case = TRUE)) {
      paste(expense_sql, "AND", clause)
    } else {
      paste(expense_sql, "WHERE", clause)
    }
    expense_params <- c(expense_params, as.list(expense_aliases))
  }
  expense_sql <- paste(expense_sql, "ORDER BY created_at DESC;")
  expenses <- if (length(expense_params) == 0) dbGetQuery(con, expense_sql) else dbGetQuery(con, expense_sql, params = expense_params)
  list(
    projects = normalize_projects_frame(projects),
    expenses = normalize_expenses_frame(expenses)
  )
}

