}

load_project_attachments_for_expense_ids <- function(expense_ids) {
  expense_ids <- unique(as.character(expense_ids %||% character()))
  expense_ids <- expense_ids[nzchar(expense_ids)]
  if (length(expense_ids) == 0) return(data.frame())
  con <- connect_db(); on.exit(dbDisconnect(con), add = TRUE)
  placeholders <- paste(rep("?", length(expense_ids)), collapse = ", ")
  dbGetQuery(con, paste0("SELECT * FROM attachments WHERE expense_id IN (", placeholders, ") ORDER BY created_at DESC;"), params = as.list(expense_ids))
}

load_runtime_core_data <- function(workspace_id = NULL, expense_scope = "all", busy_timeout_ms = 60000L, retries = 5L, base_delay = 0.2) {
  bundle <- load_projects_expenses_bundle(
    workspace_id,
    expense_scope = expense_scope,
    busy_timeout_ms = busy_timeout_ms,
    retries = retries,
    base_delay = base_delay
  )
  bundle
}

empty_runtime_core_data <- function() {
  list(
    projects = normalize_projects_frame(data.frame(stringsAsFactors = FALSE)),
    expenses = normalize_expenses_frame(data.frame(stringsAsFactors = FALSE))
  )
}

load_app_data <- function(workspace_id = NULL) {
  con <- connect_db(); on.exit(dbDisconnect(con))
  try(ensure_project_reports_schema(con), silent = TRUE)
  try(ensure_project_report_supporting_docs_schema(con), silent = TRUE)
  try(ensure_communications_schema(con), silent = TRUE)
  try(ensure_archive_schema(con), silent = TRUE)
  project_scope <- if (is.null(workspace_id) || !nzchar(as.character(workspace_id))) NULL else as.character(workspace_id)
  core_bundle <- load_projects_expenses_bundle(project_scope, con = con)
  projects <- core_bundle$projects
  expenses <- core_bundle$expenses
  if (is.null(project_scope)) {
    attachments <- dbGetQuery(con, "SELECT * FROM attachments ORDER BY created_at DESC;")
    audit <- dbGetQuery(con, "SELECT * FROM audit ORDER BY timestamp DESC LIMIT 2000;")
    exports_meta <- dbGetQuery(con, "SELECT * FROM exports_meta ORDER BY created_at DESC LIMIT 200;")
    project_reports <- dbGetQuery(con, "SELECT * FROM project_reports ORDER BY COALESCE(is_trashed,0), updated_at DESC;")
    project_report_supporting_docs <- dbGetQuery(con, "SELECT * FROM project_report_supporting_docs ORDER BY COALESCE(is_trashed,0), updated_at DESC, created_at DESC;")
    breakdowns <- dbGetQuery(con, "SELECT * FROM expense_breakdowns ORDER BY created_at;")
    backups <- dbGetQuery(con, "SELECT * FROM backups ORDER BY created_at DESC;")
    project_contacts <- dbGetQuery(con, "SELECT * FROM project_contacts WHERE COALESCE(is_trashed,0) = 0 ORDER BY contact_name;")
    scheduled_emails <- dbGetQuery(con, "SELECT * FROM scheduled_emails ORDER BY updated_at DESC, created_at DESC;")
    scheduled_email_recipients <- dbGetQuery(con, "SELECT * FROM scheduled_email_recipients ORDER BY created_at;")
    scheduled_email_attachments <- dbGetQuery(con, "SELECT * FROM scheduled_email_attachments ORDER BY created_at, attachment_name;")
    archive_groups <- dbGetQuery(con, "SELECT * FROM archive_groups ORDER BY updated_at DESC, name;")
  } else {
    attachments <- dbGetQuery(con, "
      SELECT a.*
      FROM attachments a
      INNER JOIN expenses e ON e.id = a.expense_id
      WHERE e.project_id = ?
      ORDER BY a.created_at DESC;
    ", params = list(project_scope))
    audit <- dbGetQuery(con, "SELECT * FROM audit WHERE workspace_id = ? ORDER BY timestamp DESC LIMIT 2000;", params = list(project_scope))
    exports_meta <- dbGetQuery(con, "SELECT * FROM exports_meta WHERE criteria = ? ORDER BY created_at DESC LIMIT 200;", params = list(project_scope))
    project_reports <- dbGetQuery(con, "SELECT * FROM project_reports WHERE project_id = ? ORDER BY COALESCE(is_trashed,0), updated_at DESC;", params = list(project_scope))
    project_report_supporting_docs <- dbGetQuery(con, "SELECT * FROM project_report_supporting_docs WHERE project_id = ? ORDER BY COALESCE(is_trashed,0), updated_at DESC, created_at DESC;", params = list(project_scope))
    breakdowns <- dbGetQuery(con, "
      SELECT b.*
      FROM expense_breakdowns b
      INNER JOIN expenses e ON e.id = b.expense_id
      WHERE e.project_id = ?
      ORDER BY b.created_at;
    ", params = list(project_scope))
    backups <- dbGetQuery(con, "SELECT * FROM backups WHERE workspace_id = ? ORDER BY created_at DESC;", params = list(project_scope))
    project_contacts <- dbGetQuery(con, "SELECT * FROM project_contacts WHERE project_id = ? AND COALESCE(is_trashed,0) = 0 ORDER BY contact_name;", params = list(project_scope))
    scheduled_emails <- dbGetQuery(con, "SELECT * FROM scheduled_emails WHERE project_id = ? ORDER BY updated_at DESC, created_at DESC;", params = list(project_scope))
    scheduled_email_recipients <- dbGetQuery(con, "SELECT * FROM scheduled_email_recipients WHERE project_id = ? ORDER BY created_at;", params = list(project_scope))
    scheduled_email_attachments <- dbGetQuery(con, "SELECT * FROM scheduled_email_attachments WHERE project_id = ? ORDER BY created_at, attachment_name;", params = list(project_scope))
    archive_groups <- dbGetQuery(con, "
      SELECT DISTINCT g.*
      FROM archive_groups g
      LEFT JOIN project_reports r ON r.archive_group_id = g.id AND r.project_id = ?
      LEFT JOIN project_report_supporting_docs d ON d.archive_group_id = g.id AND d.project_id = ?
      WHERE r.id IS NOT NULL OR d.id IS NOT NULL
      ORDER BY g.updated_at DESC, g.name;
    ", params = list(project_scope, project_scope))
  }
  settings <- dbGetQuery(con, "SELECT * FROM settings;")
  categories <- dbGetQuery(con, "SELECT * FROM categories ORDER BY main, sub;")
  list(
    projects = projects,
    expenses = expenses,
    attachments = attachments,
    settings = settings,
    audit = audit,
    exports_meta = exports_meta,
    project_reports = project_reports,
    project_report_supporting_docs = project_report_supporting_docs,
    categories = categories,
    breakdowns = breakdowns,
    backups = backups,
    archive_groups = archive_groups,
    project_contacts = project_contacts,
    scheduled_emails = scheduled_emails,
    scheduled_email_recipients = scheduled_email_recipients,
    scheduled_email_attachments = scheduled_email_attachments
  )
}

load_backups_data <- function(workspace_id) {
  con <- connect_db(); on.exit(dbDisconnect(con))
  dbGetQuery(con, "SELECT * FROM backups WHERE workspace_id = ? ORDER BY created_at DESC;", params = list(as.character(workspace_id)))
}

write_backup_table_csv <- function(df, path) {
  if (is.null(df) || !is.data.frame(df) || ncol(df) == 0) {
    writeLines(character(), path, useBytes = TRUE)
    return(invisible(path))
  }
  utils::write.csv(df, path, row.names = FALSE, na = "")
  invisible(path)
}

read_backup_table_csv <- function(path) {
  if (!file_exists(path)) return(data.frame())
  info <- tryCatch(file_info(path), error = function(e) NULL)
  if (is.null(info) || isTRUE(is.na(info$size[[1]])) || as.numeric(info$size[[1]]) <= 0) return(data.frame())
  preview_lines <- tryCatch(readLines(path, n = 5, warn = FALSE, encoding = "UTF-8"), error = function(e) character())
  if (length(preview_lines) == 0 || !any(nzchar(trimws(preview_lines)))) return(data.frame())
  tryCatch(
    utils::read.csv(path, stringsAsFactors = FALSE, check.names = FALSE),
    error = function(e) {
      if (grepl("first five rows are empty|no lines available", e$message, ignore.case = TRUE)) return(data.frame())
      stop(e)
    }
  )
}

create_backup_archive <- function(workspace_id, note = "") {
  tryCatch({
    if (is.null(workspace_id) || !nzchar(as.character(workspace_id))) stop("Project ID is required.")
    workspace_id <- as.character(workspace_id)
    scoped <- load_app_data(workspace_id)
    project_row <- scoped$projects %>% filter(id == workspace_id) %>% slice_head(n = 1)
    if (nrow(project_row) == 0) stop("Project not found.")

    timestamp <- format(Sys.time(), "%Y%m%d_%H%M%S")
    fname <- paste0("backup_", sanitize_filename(project_row$name[[1]]), "_", workspace_id, "_", timestamp, ".zip")
    backup_path <- file.path(get_backup_folder(), fname)
    dir_create(dirname(backup_path), recurse = TRUE)

    stage_dir <- file.path(tempdir(), paste0("budget_backup_", digest::digest(paste(workspace_id, timestamp, Sys.getpid(), sep = "_"))))
    csv_dir <- file.path(stage_dir, "csv")
    stage_receipts <- file.path(stage_dir, "receipts")
    stage_exports <- file.path(stage_dir, "exports")
    stage_reports <- file.path(stage_dir, "project_reports")
    stage_supporting_docs <- file.path(stage_dir, "project_report_supporting_docs")
    stage_email_attachments <- file.path(stage_dir, "scheduled_email_attachments")
    stage_archive_groups <- file.path(stage_dir, "archive_groups")
    dir_create(csv_dir, recurse = TRUE)
    dir_create(stage_receipts, recurse = TRUE)
    dir_create(stage_exports, recurse = TRUE)
    dir_create(stage_reports, recurse = TRUE)
    dir_create(stage_supporting_docs, recurse = TRUE)
    dir_create(stage_email_attachments, recurse = TRUE)
    dir_create(stage_archive_groups, recurse = TRUE)
    on.exit(if (dir_exists(stage_dir)) try(dir_delete(stage_dir), silent = TRUE), add = TRUE)

    con_stage <- connect_db(); on.exit(dbDisconnect(con_stage), add = TRUE)
    ensure_projects_schema(con_stage)
    ensure_expenses_schema(con_stage)
    ensure_project_reports_schema(con_stage)
    ensure_project_report_supporting_docs_schema(con_stage)
    ensure_communications_schema(con_stage)
    ensure_archive_schema(con_stage)

    projects_backup <- align_restore_table(con_stage, "projects", scoped$projects)
    expenses_backup <- align_restore_table(con_stage, "expenses", scoped$expenses)
    audit_backup <- align_restore_table(con_stage, "audit", scoped$audit)
    breakdowns_backup <- align_restore_table(con_stage, "expense_breakdowns", scoped$breakdowns)
    contacts_backup <- align_restore_table(con_stage, "project_contacts", scoped$project_contacts)
    scheduled_emails_backup <- align_restore_table(con_stage, "scheduled_emails", scoped$scheduled_emails)
    scheduled_email_recipients_backup <- align_restore_table(con_stage, "scheduled_email_recipients", scoped$scheduled_email_recipients)
    archive_groups_backup <- align_restore_table(con_stage, "archive_groups", scoped$archive_groups %||% data.frame())

    attachments_backup <- align_restore_table(con_stage, "attachments", scoped$attachments)
    if (nrow(attachments_backup) > 0) {
      attachments_backup$backup_relpath <- ""
      for (i in seq_len(nrow(attachments_backup))) {
        src <- as.character(attachments_backup$filepath[[i]] %||% "")
        if (nzchar(src) && file_exists(src)) {
          ext <- fs::path_ext(attachments_backup$filename[[i]] %||% src)
          staged_name <- paste0(attachments_backup$id[[i]], if (nzchar(ext)) paste0(".", ext) else "")
          dest <- file.path(stage_receipts, staged_name)
          file_copy(src, dest, overwrite = TRUE)
          attachments_backup$backup_relpath[[i]] <- file.path("receipts", staged_name)
        }
      }
    }

    exports_backup <- align_restore_table(con_stage, "exports_meta", scoped$exports_meta)
    if (nrow(exports_backup) > 0) {
      exports_backup$backup_relpath <- ""
      for (i in seq_len(nrow(exports_backup))) {
        src <- as.character(exports_backup$filepath[[i]] %||% "")
        if (nzchar(src) && file_exists(src)) {
          ext <- fs::path_ext(exports_backup$filename[[i]] %||% src)
          staged_name <- paste0(exports_backup$id[[i]], if (nzchar(ext)) paste0(".", ext) else "")
          dest <- file.path(stage_exports, staged_name)
          file_copy(src, dest, overwrite = TRUE)
          exports_backup$backup_relpath[[i]] <- file.path("exports", staged_name)
        }
      }
    }

    project_reports_backup <- align_restore_table(con_stage, "project_reports", scoped$project_reports)
    if (!is.null(project_reports_backup) && nrow(project_reports_backup) > 0) {
      project_reports_backup$backup_relpath <- ""
      for (i in seq_len(nrow(project_reports_backup))) {
        src <- as.character(project_reports_backup$docx_path[[i]] %||% "")
        if (nzchar(src) && file_exists(src) && identical(tolower(fs::path_ext(src)), "docx")) {
          staged_name <- paste0(project_reports_backup$id[[i]], ".docx")
          dest <- file.path(stage_reports, staged_name)
          file_copy(src, dest, overwrite = TRUE)
          project_reports_backup$backup_relpath[[i]] <- file.path("project_reports", staged_name)
        }
      }
    }

    supporting_docs_backup <- align_restore_table(con_stage, "project_report_supporting_docs", scoped$project_report_supporting_docs)
    if (!is.null(supporting_docs_backup) && nrow(supporting_docs_backup) > 0) {
      supporting_docs_backup$backup_relpath <- ""
      for (i in seq_len(nrow(supporting_docs_backup))) {
        src <- as.character(supporting_docs_backup$filepath[[i]] %||% "")
        stored_name <- as.character(supporting_docs_backup$stored_filename[[i]] %||% "")
        if (nzchar(src) && file_exists(src) && nzchar(stored_name)) {
          dest <- file.path(stage_supporting_docs, stored_name)
          file_copy(src, dest, overwrite = TRUE)
          supporting_docs_backup$backup_relpath[[i]] <- file.path("project_report_supporting_docs", stored_name)
        }
      }
    }

    scheduled_email_attachments_backup <- align_restore_table(con_stage, "scheduled_email_attachments", scoped$scheduled_email_attachments)
    if (!is.null(scheduled_email_attachments_backup) && nrow(scheduled_email_attachments_backup) > 0) {
      scheduled_email_attachments_backup$backup_relpath <- ""
      for (i in seq_len(nrow(scheduled_email_attachments_backup))) {
        src <- as.character(scheduled_email_attachments_backup$filepath[[i]] %||% "")
        stored_name <- as.character(scheduled_email_attachments_backup$stored_filename[[i]] %||% "")
        email_id <- as.character(scheduled_email_attachments_backup$email_id[[i]] %||% "")
        if (nzchar(src) && file_exists(src) && nzchar(email_id) && nzchar(stored_name)) {
          target_dir <- file.path(stage_email_attachments, sanitize_filename(email_id))
          dir_create(target_dir, recurse = TRUE)
          dest <- file.path(target_dir, stored_name)
          file_copy(src, dest, overwrite = TRUE)
          scheduled_email_attachments_backup$backup_relpath[[i]] <- file.path("scheduled_email_attachments", sanitize_filename(email_id), stored_name)
        }
      }
    }

    write_backup_table_csv(projects_backup, file.path(csv_dir, "projects.csv"))
    write_backup_table_csv(expenses_backup, file.path(csv_dir, "expenses.csv"))
    write_backup_table_csv(attachments_backup, file.path(csv_dir, "attachments.csv"))
    write_backup_table_csv(exports_backup, file.path(csv_dir, "exports_meta.csv"))
    write_backup_table_csv(project_reports_backup, file.path(csv_dir, "project_reports.csv"))
    write_backup_table_csv(supporting_docs_backup, file.path(csv_dir, "project_report_supporting_docs.csv"))
    write_backup_table_csv(archive_groups_backup, file.path(csv_dir, "archive_groups.csv"))
    write_backup_table_csv(audit_backup, file.path(csv_dir, "audit.csv"))
    write_backup_table_csv(breakdowns_backup, file.path(csv_dir, "expense_breakdowns.csv"))
    write_backup_table_csv(contacts_backup, file.path(csv_dir, "project_contacts.csv"))
    write_backup_table_csv(scheduled_emails_backup, file.path(csv_dir, "scheduled_emails.csv"))
    write_backup_table_csv(scheduled_email_recipients_backup, file.path(csv_dir, "scheduled_email_recipients.csv"))
    write_backup_table_csv(scheduled_email_attachments_backup, file.path(csv_dir, "scheduled_email_attachments.csv"))
    jsonlite::write_json(
      list(
        workspace_id = workspace_id,
        workspace_name = project_row$name[[1]],
        created_at = now(),
        format = "budget-workspace-backup-v1"
      ),
      path = file.path(stage_dir, "manifest.json"),
      auto_unbox = TRUE,
      pretty = TRUE
    )

    stage_files <- dir_ls(stage_dir, recurse = TRUE, type = "file")
    zip::zipr(
      zipfile = backup_path,
      files = stage_files,
      root = stage_dir
    )

    con <- connect_db(); on.exit(dbDisconnect(con), add = TRUE)
    info <- file_info(backup_path)
    rec <- data.frame(
      id = uuid("bk"),
      workspace_id = workspace_id,
      filename = basename(backup_path),
      filepath = normalizePath(backup_path, winslash = "/", mustWork = FALSE),
      created_at = now(),
      size = info$size,
      checksum = file_checksum(backup_path),
      notes = note,
      stringsAsFactors = FALSE
    )
    dbWriteTable(con, "backups", rec, append = TRUE, row.names = FALSE)
    log_audit(
      module = "Backups",
      action = "create",
      target_table = "backups",
      target_id = rec$id,
      detail = list(filename = rec$filename, workspace_id = workspace_id),
      workspace_id = workspace_id,
      trigger_sync = FALSE
    )
    rec
  }, error = function(e) {
    message("create_backup_archive error: ", e$message)
    NULL
  })
}

restore_backup_archive <- function(backup_path, workspace_id) {
  tryCatch({
    if (is.null(workspace_id) || !nzchar(as.character(workspace_id))) stop("Project ID is required.")
    workspace_id <- as.character(workspace_id)
    if (!file_exists(backup_path)) stop("Backup file not found.")

    restore_dir <- file.path(tempdir(), paste0("budget_restore_", digest::digest(paste(backup_path, workspace_id, Sys.getpid(), sep = "_"))))
    dir_create(restore_dir, recurse = TRUE)
    on.exit(if (dir_exists(restore_dir)) try(dir_delete(restore_dir), silent = TRUE), add = TRUE)
    utils::unzip(backup_path, exdir = restore_dir)

    manifest_path <- file.path(restore_dir, "manifest.json")
    if (!file_exists(manifest_path)) stop("Backup manifest is missing.")
    manifest <- jsonlite::read_json(manifest_path, simplifyVector = TRUE)
    if (!identical(as.character(manifest$workspace_id %||% ""), workspace_id)) stop("Backup belongs to a different project.")

    find_restore_file <- function(rel_path) {
      preferred <- file.path(restore_dir, rel_path)
      if (file_exists(preferred)) return(preferred)
      candidates <- dir_ls(restore_dir, recurse = TRUE, type = "file")
      matches <- candidates[basename(candidates) == basename(rel_path)]
      if (length(matches) > 0) return(matches[[1]])
      ""
    }
    csv_file <- function(name) find_restore_file(file.path("csv", paste0(name, ".csv")))

    projects_restore <- read_backup_table_csv(csv_file("projects"))
    expenses_restore <- read_backup_table_csv(csv_file("expenses"))
    attachments_restore <- read_backup_table_csv(csv_file("attachments"))
    exports_restore <- read_backup_table_csv(csv_file("exports_meta"))
    project_reports_restore <- read_backup_table_csv(csv_file("project_reports"))
    project_report_supporting_docs_restore <- read_backup_table_csv(csv_file("project_report_supporting_docs"))
    archive_groups_restore <- read_backup_table_csv(csv_file("archive_groups"))
    audit_restore <- read_backup_table_csv(csv_file("audit"))
    breakdowns_restore <- read_backup_table_csv(csv_file("expense_breakdowns"))
    contacts_restore <- read_backup_table_csv(csv_file("project_contacts"))
    scheduled_emails_restore <- read_backup_table_csv(csv_file("scheduled_emails"))
    scheduled_email_recipients_restore <- read_backup_table_csv(csv_file("scheduled_email_recipients"))
    scheduled_email_attachments_restore <- read_backup_table_csv(csv_file("scheduled_email_attachments"))

    if (nrow(projects_restore) > 0 && any(as.character(projects_restore$id) != workspace_id)) stop("Backup project scope does not match the requested project.")
    if (nrow(expenses_restore) > 0 && any(as.character(expenses_restore$project_id) != workspace_id)) stop("Backup expense scope does not match the requested project.")
    if (nrow(project_reports_restore) > 0 && "project_id" %in% names(project_reports_restore) && any(as.character(project_reports_restore$project_id) != workspace_id)) stop("Backup report scope does not match the requested project.")
    if (nrow(project_report_supporting_docs_restore) > 0 && "project_id" %in% names(project_report_supporting_docs_restore) && any(as.character(project_report_supporting_docs_restore$project_id) != workspace_id)) stop("Backup uploaded file scope does not match the requested project.")
    if (nrow(contacts_restore) > 0 && "project_id" %in% names(contacts_restore) && any(as.character(contacts_restore$project_id) != workspace_id)) stop("Backup contact scope does not match the requested project.")
    if (nrow(scheduled_emails_restore) > 0 && "project_id" %in% names(scheduled_emails_restore) && any(as.character(scheduled_emails_restore$project_id) != workspace_id)) stop("Backup scheduled email scope does not match the requested project.")
    if (nrow(scheduled_email_recipients_restore) > 0 && "project_id" %in% names(scheduled_email_recipients_restore) && any(as.character(scheduled_email_recipients_restore$project_id) != workspace_id)) stop("Backup scheduled email recipient scope does not match the requested project.")
    if (nrow(scheduled_email_attachments_restore) > 0 && "project_id" %in% names(scheduled_email_attachments_restore) && any(as.character(scheduled_email_attachments_restore$project_id) != workspace_id)) stop("Backup scheduled email attachment scope does not match the requested project.")

    if (nrow(attachments_restore) > 0 && "backup_relpath" %in% names(attachments_restore)) {
      for (i in seq_len(nrow(attachments_restore))) {
        rel_path <- as.character(attachments_restore$backup_relpath[[i]] %||% "")
        if (nzchar(rel_path)) {
          src <- find_restore_file(rel_path)
          if (file_exists(src)) {
            dest <- file.path(receipts_dir, basename(rel_path))
            dir_create(dirname(dest), recurse = TRUE)
            file_copy(src, dest, overwrite = TRUE)
            attachments_restore$filepath[[i]] <- normalizePath(dest, winslash = "/", mustWork = FALSE)
            attachments_restore$size[[i]] <- file_info(dest)$size
          }
        }
      }
      attachments_restore$backup_relpath <- NULL
    }

    if (nrow(exports_restore) > 0 && "backup_relpath" %in% names(exports_restore)) {
      for (i in seq_len(nrow(exports_restore))) {
        rel_path <- as.character(exports_restore$backup_relpath[[i]] %||% "")
        if (nzchar(rel_path)) {
          src <- find_restore_file(rel_path)
          if (file_exists(src)) {
            dest <- file.path(internal_exports_dir, basename(rel_path))
            dir_create(dirname(dest), recurse = TRUE)
            file_copy(src, dest, overwrite = TRUE)
            exports_restore$filepath[[i]] <- normalizePath(dest, winslash = "/", mustWork = FALSE)
          }
        }
      }
      exports_restore$backup_relpath <- NULL
    }

    if (nrow(project_reports_restore) > 0 && "backup_relpath" %in% names(project_reports_restore)) {
      target_report_dir <- file.path(project_reports_dir, workspace_id)
      dir_create(target_report_dir, recurse = TRUE)
      for (i in seq_len(nrow(project_reports_restore))) {
        rel_path <- as.character(project_reports_restore$backup_relpath[[i]] %||% "")
        if (nzchar(rel_path)) {
          src <- find_restore_file(rel_path)
          if (file_exists(src)) {
            dest <- file.path(target_report_dir, basename(rel_path))
            file_copy(src, dest, overwrite = TRUE)
            project_reports_restore$docx_path[[i]] <- normalizePath(dest, winslash = "/", mustWork = FALSE)
          }
        }
      }
      project_reports_restore$backup_relpath <- NULL
    }

    if (nrow(project_report_supporting_docs_restore) > 0 && "backup_relpath" %in% names(project_report_supporting_docs_restore)) {
      if (!("filepath" %in% names(project_report_supporting_docs_restore))) project_report_supporting_docs_restore$filepath <- ""
      if (!("size" %in% names(project_report_supporting_docs_restore))) project_report_supporting_docs_restore$size <- 0
      if (!("checksum" %in% names(project_report_supporting_docs_restore))) project_report_supporting_docs_restore$checksum <- ""
      if (!("stored_filename" %in% names(project_report_supporting_docs_restore))) project_report_supporting_docs_restore$stored_filename <- ""
      target_supporting_dir <- project_report_supporting_doc_storage_dir(workspace_id)
      for (i in seq_len(nrow(project_report_supporting_docs_restore))) {
        rel_path <- as.character(project_report_supporting_docs_restore$backup_relpath[[i]] %||% "")
        stored_name <- as.character(project_report_supporting_docs_restore$stored_filename[[i]] %||% "")
        if (nzchar(rel_path)) {
          src <- find_restore_file(rel_path)
          if (file_exists(src)) {
            if (!nzchar(stored_name)) stored_name <- basename(rel_path)
            dest <- file.path(target_supporting_dir, stored_name)
            file_copy(src, dest, overwrite = TRUE)
            dest_abs <- normalizePath(dest, winslash = "/", mustWork = FALSE)
            project_report_supporting_docs_restore$filepath[[i]] <- dest_abs
            project_report_supporting_docs_restore$size[[i]] <- file_info(dest_abs)$size
            project_report_supporting_docs_restore$checksum[[i]] <- file_checksum(dest_abs)
            project_report_supporting_docs_restore$stored_filename[[i]] <- stored_name
          }
        }
      }
      project_report_supporting_docs_restore$backup_relpath <- NULL
    }

    if (nrow(scheduled_email_attachments_restore) > 0 && "backup_relpath" %in% names(scheduled_email_attachments_restore)) {
      if (!("filepath" %in% names(scheduled_email_attachments_restore))) scheduled_email_attachments_restore$filepath <- ""
      if (!("size" %in% names(scheduled_email_attachments_restore))) scheduled_email_attachments_restore$size <- 0
      if (!("checksum" %in% names(scheduled_email_attachments_restore))) scheduled_email_attachments_restore$checksum <- ""
      if (!("stored_filename" %in% names(scheduled_email_attachments_restore))) scheduled_email_attachments_restore$stored_filename <- ""
      if (!("email_id" %in% names(scheduled_email_attachments_restore))) scheduled_email_attachments_restore$email_id <- ""
      for (i in seq_len(nrow(scheduled_email_attachments_restore))) {
        rel_path <- as.character(scheduled_email_attachments_restore$backup_relpath[[i]] %||% "")
        email_id <- as.character(scheduled_email_attachments_restore$email_id[[i]] %||% "")
        stored_name <- as.character(scheduled_email_attachments_restore$stored_filename[[i]] %||% "")
        if (nzchar(rel_path) && nzchar(email_id) && nzchar(stored_name)) {
          src <- find_restore_file(rel_path)
          if (file_exists(src)) {
            target_dir <- scheduled_email_attachment_storage_dir(workspace_id, email_id)
            dest <- file.path(target_dir, stored_name)
            file_copy(src, dest, overwrite = TRUE)
            dest_abs <- normalizePath(dest, winslash = "/", mustWork = FALSE)
            scheduled_email_attachments_restore$filepath[[i]] <- dest_abs
            scheduled_email_attachments_restore$size[[i]] <- file_info(dest_abs)$size
            scheduled_email_attachments_restore$checksum[[i]] <- file_checksum(dest_abs)
          }
        }
      }
      scheduled_email_attachments_restore$backup_relpath <- NULL
    }

    if (nrow(projects_restore) > 0 && "workbook_path" %in% names(projects_restore)) projects_restore$workbook_path <- ""
    if (nrow(audit_restore) > 0 && "workspace_id" %in% names(audit_restore)) audit_restore$workspace_id <- workspace_id
    if (nrow(exports_restore) > 0 && "criteria" %in% names(exports_restore)) exports_restore$criteria <- workspace_id

    con <- connect_db(); on.exit(dbDisconnect(con), add = TRUE)
    ensure_projects_schema(con)
    ensure_expenses_schema(con)
    ensure_project_reports_schema(con)
    ensure_project_report_supporting_docs_schema(con)
    ensure_communications_schema(con)
    ensure_archive_schema(con)
    projects_restore <- align_restore_table(con, "projects", projects_restore)
    projects_restore <- prepare_projects_access_keys_for_restore(projects_restore, con, exclude_project_ids = workspace_id)
    expenses_restore <- align_restore_table(con, "expenses", expenses_restore)
    attachments_restore <- align_restore_table(con, "attachments", attachments_restore)
    exports_restore <- align_restore_table(con, "exports_meta", exports_restore)
    audit_restore <- align_restore_table(con, "audit", audit_restore)
    breakdowns_restore <- align_restore_table(con, "expense_breakdowns", breakdowns_restore)
    project_reports_restore <- align_restore_table(con, "project_reports", project_reports_restore)
    project_report_supporting_docs_restore <- align_restore_table(con, "project_report_supporting_docs", project_report_supporting_docs_restore)
    contacts_restore <- align_restore_table(con, "project_contacts", contacts_restore)
    scheduled_emails_restore <- align_restore_table(con, "scheduled_emails", scheduled_emails_restore)
    scheduled_email_recipients_restore <- align_restore_table(con, "scheduled_email_recipients", scheduled_email_recipients_restore)
    scheduled_email_attachments_restore <- align_restore_table(con, "scheduled_email_attachments", scheduled_email_attachments_restore)
    dbBegin(con)
    committed <- FALSE
    on.exit(if (!committed) try(dbRollback(con), silent = TRUE), add = TRUE)
    dbExecute(con, "DELETE FROM attachments WHERE expense_id IN (SELECT id FROM expenses WHERE project_id = ?);", params = list(workspace_id))
    dbExecute(con, "DELETE FROM expense_breakdowns WHERE expense_id IN (SELECT id FROM expenses WHERE project_id = ?);", params = list(workspace_id))
    dbExecute(con, "DELETE FROM exports_meta WHERE criteria = ?;", params = list(workspace_id))
    dbExecute(con, "DELETE FROM project_reports WHERE project_id = ?;", params = list(workspace_id))
    dbExecute(con, "DELETE FROM project_report_supporting_docs WHERE project_id = ?;", params = list(workspace_id))
    dbExecute(con, "DELETE FROM scheduled_email_attachments WHERE project_id = ?;", params = list(workspace_id))
    dbExecute(con, "DELETE FROM scheduled_email_recipients WHERE project_id = ?;", params = list(workspace_id))
    dbExecute(con, "DELETE FROM scheduled_emails WHERE project_id = ?;", params = list(workspace_id))
    dbExecute(con, "DELETE FROM project_contacts WHERE project_id = ?;", params = list(workspace_id))
    dbExecute(con, "DELETE FROM audit WHERE workspace_id = ?;", params = list(workspace_id))
    dbExecute(con, "DELETE FROM expenses WHERE project_id = ?;", params = list(workspace_id))
    dbExecute(con, "DELETE FROM projects WHERE id = ?;", params = list(workspace_id))

    upsert_archive_groups_restore(con, archive_groups_restore)

    if (nrow(projects_restore) > 0) dbWriteTable(con, "projects", projects_restore, append = TRUE, row.names = FALSE)
    if (nrow(expenses_restore) > 0) dbWriteTable(con, "expenses", expenses_restore, append = TRUE, row.names = FALSE)
    if (nrow(attachments_restore) > 0) dbWriteTable(con, "attachments", attachments_restore, append = TRUE, row.names = FALSE)
    if (nrow(exports_restore) > 0) dbWriteTable(con, "exports_meta", exports_restore, append = TRUE, row.names = FALSE)
    if (nrow(project_reports_restore) > 0) dbWriteTable(con, "project_reports", project_reports_restore, append = TRUE, row.names = FALSE)
    if (nrow(project_report_supporting_docs_restore) > 0) dbWriteTable(con, "project_report_supporting_docs", project_report_supporting_docs_restore, append = TRUE, row.names = FALSE)
    if (nrow(contacts_restore) > 0) dbWriteTable(con, "project_contacts", contacts_restore, append = TRUE, row.names = FALSE)
    if (nrow(scheduled_emails_restore) > 0) dbWriteTable(con, "scheduled_emails", scheduled_emails_restore, append = TRUE, row.names = FALSE)
    if (nrow(scheduled_email_recipients_restore) > 0) dbWriteTable(con, "scheduled_email_recipients", scheduled_email_recipients_restore, append = TRUE, row.names = FALSE)
    if (nrow(scheduled_email_attachments_restore) > 0) dbWriteTable(con, "scheduled_email_attachments", scheduled_email_attachments_restore, append = TRUE, row.names = FALSE)
    if (nrow(audit_restore) > 0) dbWriteTable(con, "audit", audit_restore, append = TRUE, row.names = FALSE)
    if (nrow(breakdowns_restore) > 0) dbWriteTable(con, "expense_breakdowns", breakdowns_restore, append = TRUE, row.names = FALSE)
    dbCommit(con)
    committed <- TRUE

    try(queue_project_workbook_sync(workspace_id, reason = "backup_restored"), silent = TRUE)
    log_audit(
      module = "Backups",
      action = "restore",
      target_table = "backups",
      target_id = NA,
      detail = list(filepath = backup_path, workspace_id = workspace_id),
      workspace_id = workspace_id,
      trigger_sync = FALSE
    )
    TRUE
  }, error = function(e) {
    message("restore_backup_archive error: ", e$message)
    FALSE
  })
}

run_integrity_check <- function(workspace_id) {
  con <- connect_db(); on.exit(dbDisconnect(con))
  try(ensure_project_report_supporting_docs_schema(con), silent = TRUE)
  if (is.null(workspace_id) || !nzchar(as.character(workspace_id))) return("Project ID is required.")
  workspace_id <- as.character(workspace_id)
  msgs <- character()

  project_row <- dbGetQuery(con, "SELECT id, workbook_path FROM projects WHERE id = ? LIMIT 1;", params = list(workspace_id))
  if (nrow(project_row) == 0) msgs <- c(msgs, "Project record is missing.")

  atts <- dbGetQuery(con, "
    SELECT a.id, a.filepath
    FROM attachments a
    INNER JOIN expenses e ON e.id = a.expense_id
    WHERE e.project_id = ?;
  ", params = list(workspace_id))
  missing_files <- atts$filepath[!file_exists(atts$filepath)]
  if (length(missing_files) > 0) msgs <- c(msgs, paste0("Missing attachment files: ", paste(missing_files, collapse = ", ")))

  if (nrow(project_row) == 1 && nzchar(project_row$workbook_path[[1]]) && !file_exists(project_row$workbook_path[[1]])) {
    msgs <- c(msgs, paste0("Missing project workbook: ", workspace_id))
  }

  email_atts <- dbGetQuery(con, "
    SELECT id, attachment_name, filepath
    FROM scheduled_email_attachments
    WHERE project_id = ?;
  ", params = list(workspace_id))
  if (nrow(email_atts) > 0) {
    missing_email_files <- email_atts[!file_exists(as.character(email_atts$filepath %||% "")), , drop = FALSE]
    if (nrow(missing_email_files) > 0) {
      labels <- ifelse(nzchar(as.character(missing_email_files$attachment_name %||% "")), as.character(missing_email_files$attachment_name), as.character(missing_email_files$filepath %||% ""))
      msgs <- c(msgs, paste0("Missing scheduled email attachment files: ", paste(labels, collapse = ", ")))
    }
  }

  supporting_docs <- dbGetQuery(con, "
    SELECT id, original_filename, filepath
    FROM project_report_supporting_docs
    WHERE project_id = ? AND COALESCE(is_trashed,0) = 0;
  ", params = list(workspace_id))
  if (nrow(supporting_docs) > 0) {
    missing_supporting <- supporting_docs[!file_exists(as.character(supporting_docs$filepath %||% "")), , drop = FALSE]
    if (nrow(missing_supporting) > 0) {
      labels <- ifelse(nzchar(as.character(missing_supporting$original_filename %||% "")), as.character(missing_supporting$original_filename), as.character(missing_supporting$filepath %||% ""))
      msgs <- c(msgs, paste0("Missing uploaded project files: ", paste(labels, collapse = ", ")))
    }
  }

  if (length(msgs) == 0) msgs <- "No issues found."
  msgs
}

