              var workspaces = document.querySelectorAll('.progress-report-workspace');
              workspaces.forEach(function(workspace) {
                var dialog = workspace.closest('.modal-dialog');
                var modal = workspace.closest('.modal');
                if (dialog) dialog.classList.add('progress-report-modal-dialog');
                if (modal) modal.classList.add('progress-report-modal');
              });
              var textareas = document.querySelectorAll('.progress-report-workspace textarea.form-control');
              textareas.forEach(function(textarea) {
                textarea.classList.add('progress-report-autogrow-textarea');
                var resizeTextarea = function() {
                  textarea.style.height = 'auto';
                  var minHeight = parseInt(textarea.getAttribute('data-min-height') || '140', 10);
                  textarea.style.height = Math.max(minHeight, textarea.scrollHeight + 6) + 'px';
                };
                if (!textarea.dataset.reportAutosizeBound) {
                  textarea.dataset.reportAutosizeBound = '1';
                  textarea.addEventListener('input', resizeTextarea);
                  textarea.addEventListener('change', resizeTextarea);
                }
                resizeTextarea();
              });
            } catch (e) {
              if (window.console && console.warn) console.warn('Report workspace enhancement error', e);
            }
