          window.budgetTrackerFitTextElement = function(el) {
            try {
              if (!el) return;
              var rect = el.getBoundingClientRect();
              if (!rect || rect.width <= 0 || rect.height <= 0) return;
              var baseSize = parseFloat(el.dataset.fitBaseSize || window.getComputedStyle(el).fontSize || '16');
              var minSize = parseFloat(el.dataset.fitMinSize || '14');
              if (!el.dataset.fitBaseSize) el.dataset.fitBaseSize = String(baseSize);
              el.style.fontSize = el.dataset.fitBaseSize + 'px';
              el.style.maxWidth = '100%';
              if (el.classList && el.classList.contains('dashboard-money-value')) {
                el.style.whiteSpace = 'nowrap';
                el.style.overflowWrap = 'normal';
                el.style.wordBreak = 'normal';
              } else {
                el.style.whiteSpace = 'normal';
                el.style.overflowWrap = 'anywhere';
                el.style.wordBreak = 'break-word';
              }
              var currentSize = parseFloat(el.dataset.fitBaseSize);
              var attempts = 0;
              while (attempts < 24 && (el.scrollWidth > el.clientWidth + 1 || el.scrollHeight > el.clientHeight + 1)) {
                currentSize = currentSize - 1;
                if (currentSize <= minSize) break;
                el.style.fontSize = currentSize + 'px';
                attempts += 1;
              }
            } catch (e) {}
          };
          window.budgetTrackerEnhanceResponsiveLayout = function() {
            try {
              var fitTargets = document.querySelectorAll('.dashboard-money-value, .budget-metric-value, .report-summary-total-value, .info-box-number');
              fitTargets.forEach(function(el) {
                if (!el.dataset.fitMinSize) {
                  if (el.matches('.dashboard-money-value')) {
                    el.dataset.fitMinSize = '15';
                  } else if (el.matches('.info-box-number')) {
                    el.dataset.fitMinSize = '16';
                  } else {
                    el.dataset.fitMinSize = '14';
                  }
                }
                window.budgetTrackerFitTextElement(el);
              });
            } catch (e) {
              if (window.console && console.warn) console.warn('Responsive layout enhancement error', e);
            }
          };
          window.budgetTrackerQueueResponsiveLayout = function() {
            try {
              clearTimeout(window.__budgetTrackerResponsiveTimer);
              window.__budgetTrackerResponsiveTimer = setTimeout(function() {
                if (window.budgetTrackerEnhanceResponsiveLayout) window.budgetTrackerEnhanceResponsiveLayout();
              }, 40);
            } catch (e) {}
          };
          function budgetTrackerInitUiGate() {
            window.budgetTrackerSetAuthReady(window.__budgetTrackerAuthState === true);
            window.budgetTrackerRegisterAuthHandler();
            window.budgetTrackerEnhanceReportWorkspace();
            window.budgetTrackerQueueResponsiveLayout();
