            setTimeout(window.budgetTrackerQueueResponsiveLayout, 1200);
            setTimeout(window.budgetTrackerHideSplash, 2500);
            setTimeout(window.budgetTrackerHideSplash, 5000);
          }
          if (document.readyState === 'loading') {
            document.addEventListener('DOMContentLoaded', budgetTrackerInitUiGate);
          } else {
            budgetTrackerInitUiGate();
          }
          document.addEventListener('shiny:connected', window.budgetTrackerRegisterAuthHandler);
          document.addEventListener('shiny:bound', window.budgetTrackerEnhanceReportWorkspace);
          document.addEventListener('shiny:bound', window.budgetTrackerQueueResponsiveLayout);
          document.addEventListener('shiny:value', window.budgetTrackerQueueResponsiveLayout);
          window.addEventListener('resize', window.budgetTrackerQueueResponsiveLayout);
          if (window.jQuery) {
            window.jQuery(document).on('shown.bs.modal', window.budgetTrackerEnhanceReportWorkspace);
            window.jQuery(document).on('shown.bs.modal', window.budgetTrackerQueueResponsiveLayout);
          }
          setTimeout(window.budgetTrackerRegisterAuthHandler, 0);
          setTimeout(window.budgetTrackerRegisterAuthHandler, 1000);
          setTimeout(window.budgetTrackerQueueResponsiveLayout, 0);
          setTimeout(window.budgetTrackerQueueResponsiveLayout, 1000);
        })();
