# Debug logging for downloads
log_download <- function(msg) {
  timestamp <- format(Sys.time(), "%Y-%m-%d %H:%M:%S")
  message(paste0("[DOWNLOAD LOG ", timestamp, "] ", msg))
}

server <- function(input, output, session) {
  # shinyFiles roots
  roots <- c(Home = fs::path_home(), `App Data` = normalizePath(data_dir, winslash = "/"))
  shinyDirChoose(input, "choose_export_folder", roots = roots, session = session)
  shinyDirChoose(input, "choose_backup_folder", roots = roots, session = session)

  rv <- reactiveValues(
    data = NULL,
    proj_obs_created = character(),
    user_role = NULL,
    allowed_project = NULL,
    pending_breakdowns_create = list(),
    pending_breakdowns_edit = list(),
    bk_new_obs_created = character(),
    bk_edit_obs_created = character(),
    editing_contact_id = NULL,
    editing_email_id = NULL,
    comm_upload_token = 1L,
    comm_attachment_refresh_token = 0L,
    submission_project_id = NULL,
    submission_project_code = NULL,
    submission_report_id = NULL,
    submission_docx_path = NULL,
    submission_mode = NULL,
    submission_supporting_refresh_token = 0L,
    supporting_doc_id = NULL,
    file_manager_item_key = NULL,
    file_manager_archive_group_id = NULL,
    file_manager_pending_keys = character(),
    file_manager_refresh_token = 0L
  )
  session_state <- new.env(parent = emptyenv())
  session_state$user_role <- ""
  session_state$allowed_project <- ""
  session_state$data <- NULL
  settings_version <- reactiveVal(0)
  settings_cache <- reactiveVal(list())
  email_test_inflight <- reactiveVal(FALSE)
  login_in_progress <- reactiveVal(FALSE)
  expense_message <- reactiveVal("")
  integrity_report_text <- reactiveVal('Click "Run Consistency Check" to inspect the selected project.')
  pi_bulk_email_preview_state <- reactiveVal(list(
    display = data.frame(),
    jobs = list(),
    action = "",
    generated_at = ""
  ))
  set_session_auth_state <- function(role = NULL, allowed_project = NULL) {
    role_value <- trimws(as.character(role %||% ""))
    allowed_project_value <- trimws(as.character(allowed_project %||% ""))
    session_state$user_role <- role_value
    session_state$allowed_project <- allowed_project_value
    rv$user_role <- if (nzchar(role_value)) role_value else NULL
    rv$allowed_project <- if (nzchar(allowed_project_value)) allowed_project_value else NULL
    invisible(TRUE)
  }
  set_runtime_data_state <- function(value) {
    session_state$data <- value
    rv$data <- value
    invisible(value)
  }
  current_user_role <- function() {
    as.character(session_state$user_role %||% "")
  }
  current_allowed_project <- function() {
    as.character(session_state$allowed_project %||% "")
  }
  authenticated_state <- function() {
    nzchar(trimws(current_user_role()))
  }
  is_authenticated <- reactive({
    !is.null(rv$user_role) && nzchar(trimws(as.character(rv$user_role %||% "")))
  })
  showNotification <- local({
    base_show_notification <- shiny::showNotification
    function(ui, action = NULL, duration = 5, closeButton = TRUE, id = NULL, type = c("default", "message", "warning", "error"), session = shiny::getDefaultReactiveDomain()) {
      type <- match.arg(type)
      notification_preview <- tryCatch({
        ui_text <- paste(as.character(ui), collapse = " ")
        if (!nzchar(trimws(ui_text))) "<notification>" else substr(trimws(ui_text), 1, 300)
      }, error = function(e) "<notification>")
      target_session <- session
      if (is.null(target_session) || !is.function(target_session$sendNotification)) {
        target_session <- tryCatch(shiny::getDefaultReactiveDomain(), error = function(e) NULL)
      }
      if (is.null(target_session) || !is.function(target_session$sendNotification)) {
        append_app_runtime_log(
          "WARN",
          "Notification suppressed because no valid Shiny notification session was available.",
          detail = list(type = type, text = notification_preview)
        )
        return(invisible(NULL))
      }
      tryCatch(
        base_show_notification(
          ui = ui,
          action = action,
          duration = duration,
          closeButton = closeButton,
          id = id,
          type = type,
          session = target_session
        ),
        error = function(e) {
          append_app_runtime_log(
            "ERROR",
            paste0("Notification failed: ", e$message),
            detail = list(type = type, text = notification_preview)
          )
          invisible(NULL)
        }
      )
    }
  })
  require_authenticated <- function(notify = TRUE) {
    ok <- isTRUE(authenticated_state())
    if (!ok && isTRUE(notify)) {
      showNotification("Login required.", type = "error")
    }
    ok
  }
  set_expense_message <- function(value = "") {
    expense_message(as.character(value %||% ""))
    invisible(TRUE)
  }
  set_integrity_report_text <- function(value = "") {
    integrity_report_text(as.character(value %||% ""))
    invisible(TRUE)
  }
  output$exp_msg <- renderText({
    expense_message()
  })
  output$integrity_report <- renderText({
    integrity_report_text()
  })
  refresh_settings_cache <- function() {
    values <- read_settings_map(force = TRUE)
    pick_setting <- function(key, default = NULL) values[[key]] %||% default
    current <- list(
      theme = pick_setting("theme", "Light"),
      custom_accent = pick_setting("custom_accent", "#2B84D8"),
      export_folder = pick_setting("export_folder", internal_exports_dir),
      backup_folder = pick_setting("backup_folder", internal_backups_dir),
      excel_password = pick_setting("excel_password", ""),
      watermark_text = pick_setting("watermark_text", "CONFIDENTIAL"),
      progress_report_as_at_date = pick_setting("progress_report_as_at_date", project_progress_report_default_as_at_date),
      protect_other_sheets = pick_setting("protect_other_sheets", "false"),
      use_working_dir = pick_setting("use_working_dir", "true"),
      currency = pick_setting("currency", "KES"),
      drive_backup_enabled = pick_setting("drive_backup_enabled", "false"),
      drive_account_email = pick_setting("drive_account_email", ""),
      drive_root_folder_name = pick_setting("drive_root_folder_name", "Budget App Backups"),
      drive_root_folder_id = pick_setting("drive_root_folder_id", ""),
      drive_sync_interval_sec = pick_setting("drive_sync_interval_sec", "300"),
      email_delivery_enabled = pick_setting("email_delivery_enabled", "false"),
      email_from_name = pick_setting("email_from_name", ""),
      email_from_address = pick_setting("email_from_address", ""),
      email_smtp_host = pick_setting("email_smtp_host", ""),
      email_smtp_port = pick_setting("email_smtp_port", "587"),
      email_smtp_username = pick_setting("email_smtp_username", ""),
      email_smtp_password = pick_setting("email_smtp_password", ""),
      email_smtp_use_ssl = pick_setting("email_smtp_use_ssl", "true"),
      email_smtp_insecure_tls = pick_setting("email_smtp_insecure_tls", "false"),
      email_scheduler_interval_sec = pick_setting("email_scheduler_interval_sec", "60"),
      email_schedule_timezone = pick_setting("email_schedule_timezone", default_email_schedule_timezone()),
      email_smtp_connect_timeout_sec = pick_setting("email_smtp_connect_timeout_sec", "15"),
      email_smtp_total_timeout_sec = pick_setting("email_smtp_total_timeout_sec", "60")
    )
    settings_cache(current)
    settings_version(isolate(settings_version()) + 1)
    invisible(current)
  }
