    updateSelectInput(session, "setting_theme", selected = current$theme %||% "Light")
    updateTextInput(session, "custom_accent_hex", value = current$custom_accent %||% "#2B84D8")
    updateCheckboxInput(session, "setting_use_working_dir", value = tolower(as.character(current$use_working_dir %||% "true")) == "true")
