    updateTextInput(session, "setting_email_from_name", value = current$email_from_name %||% "")
    updateTextInput(session, "setting_email_from_address", value = current$email_from_address %||% "")
    updateTextInput(session, "setting_email_smtp_host", value = current$email_smtp_host %||% "")
    updateTextInput(session, "setting_email_smtp_port", value = current$email_smtp_port %||% "587")
    updateTextInput(session, "setting_email_smtp_username", value = current$email_smtp_username %||% "")
    updateTextInput(session, "setting_email_smtp_password", value = current$email_smtp_password %||% "")
    updateCheckboxInput(session, "setting_email_smtp_use_ssl", value = tolower(as.character(current$email_smtp_use_ssl %||% "true")) == "true")
    updateCheckboxInput(session, "setting_email_smtp_insecure_tls", value = tolower(as.character(current$email_smtp_insecure_tls %||% "false")) == "true")
