  log_login_stage <- function(stage, level = "INFO", detail = list()) {
    stage_detail <- list(
      session_token = substr(as.character(session$token %||% ""), 1, 12),
      authenticated = isTRUE(authenticated_state()),
      user_role = current_user_role(),
      allowed_project = current_allowed_project()
    )
    if (is.list(detail) && length(detail) > 0) {
      stage_detail <- c(stage_detail, detail)
    }
    append_app_runtime_log(level, paste0("login::", stage), detail = stage_detail)
  }

  complete_login_transition <- function(role, allowed_project = NULL, success_message = "", notification_duration = 6) {
    role_value <- as.character(role %||% "")
    allowed_project_value <- if (is.null(allowed_project) || !nzchar(as.character(allowed_project %||% ""))) "" else as.character(allowed_project)
    set_session_auth_state(role = role_value, allowed_project = allowed_project_value)
    if (is.null(session_state$data)) set_runtime_data_state(empty_runtime_core_data())
    log_login_stage("session_state_updated", detail = list(role = role_value, resolved_project = allowed_project_value))
    session$sendCustomMessage("auth-ui", list(authenticated = TRUE))
    updateTabItems(session, "main_nav", "dashboard")
    log_login_stage("login_ui_hidden", detail = list(role = role_value, resolved_project = allowed_project_value))
    showNotification(success_message, type = "message", duration = notification_duration)
  }

  schedule_post_login_initialization <- function(role, allowed_project = NULL, busy_timeout_ms = 5000L, retries = 2L, base_delay = 0.05) {
    role_value <- as.character(role %||% "")
    project_value <- as.character(allowed_project %||% "")
    session$onFlushed(function() {
      log_login_stage("application_ui_displayed", detail = list(role = role_value, resolved_project = project_value))
      later::later(function() {
        started_at <- Sys.time()
        log_login_stage("dashboard_initialization_started", detail = list(role = role_value, resolved_project = project_value))
        tryCatch({
          reload_data(busy_timeout_ms = busy_timeout_ms, retries = retries, base_delay = base_delay)
          elapsed_ms <- round(as.numeric(difftime(Sys.time(), started_at, units = "secs")) * 1000)
          loaded_projects <- if (!is.null(rv$data) && is.list(rv$data) && is.data.frame(rv$data$projects)) nrow(rv$data$projects) else 0L
          loaded_expenses <- if (!is.null(rv$data) && is.list(rv$data) && is.data.frame(rv$data$expenses)) nrow(rv$data$expenses) else 0L
          log_login_stage(
            "dashboard_initialization_completed",
            detail = list(
              role = role_value,
              resolved_project = project_value,
              elapsed_ms = elapsed_ms,
              projects_loaded = loaded_projects,
              expenses_loaded = loaded_expenses
            )
          )
        }, error = function(e) {
          elapsed_ms <- round(as.numeric(difftime(Sys.time(), started_at, units = "secs")) * 1000)
          log_login_stage(
            "dashboard_initialization_failed",
            level = "ERROR",
            detail = list(
              role = role_value,
              resolved_project = project_value,
              elapsed_ms = elapsed_ms,
              error = as.character(e$message %||% "")
            )
          )
          showNotification(
            "Login succeeded, but dashboard data is still loading. Please wait a moment and retry if the data does not appear.",
            type = "warning",
            duration = 10
          )
        })
      }, delay = 0)
    }, once = TRUE)
  }

