  show_report_submission_modal <- function(project_code, project_row = NULL) {
    project <- if (is.data.frame(project_row) && nrow(project_row) == 1) project_row else lookup_project_by_code(project_code)
    if (nrow(project) != 1) {
      session$sendCustomMessage("report-submission-ui", list(active = FALSE))
      showNotification("Invalid Project Code. No active project found.", type = "error")
      return(FALSE)
    }
    project_id <- as.character(project$id[[1]])
    draft <- get_latest_project_report_draft(project_id)
    draft_value <- function(field, default = "") {
      if (nrow(draft) == 1 && field %in% names(draft)) as.character(draft[[field]][[1]] %||% default) else default
    }
    values <- list(
      project_team_leader = draft_value("project_team_leader"),
      team_members = draft_value("team_members"),
      form_project_title = draft_value("form_project_title"),
      project_objectives = draft_value("project_objectives"),
      nature_of_project = draft_value("nature_of_project"),
      ethical_approval_number = draft_value("ethical_approval_number"),
      nacosti_approval_number = draft_value("nacosti_approval_number"),
      other_approval_provided = draft_value("other_approval_provided"),
      date_project_commenced = draft_value("date_project_commenced"),
      progress_activities_done = draft_value("progress_activities_done"),
      progress_pending_activities = draft_value("progress_pending_activities"),
      completion_date = draft_value("completion_date"),
      other_comment = draft_value("other_comment")
    )
    project_team_leader <- as.character(project$principal_investigator[[1]] %||% "")
    project_team_members <- normalize_team_members_text(project$team_members[[1]] %||% "")
    if (!nzchar(trimws(as.character(values$project_team_leader %||% "")))) values$project_team_leader <- project_team_leader
    if (!nzchar(trimws(as.character(values$team_members %||% "")))) values$team_members <- project_team_members
    rv$submission_project_id <- project_id
    rv$submission_project_code <- project_id
    rv$submission_report_id <- if (nrow(draft) == 1) as.character(draft$id[[1]]) else NULL
    rv$submission_docx_path <- if (nrow(draft) == 1) as.character(draft$docx_path[[1]] %||% "") else NULL
    rv$submission_mode <- "structured"

    removeModal()
    session$sendCustomMessage("report-submission-ui", list(active = TRUE))
    showModal(modalDialog(
      title = "Project Report Submission",
      size = "l",
      easyClose = TRUE,
      footer = tagList(
        downloadButton("download_submission_report_docx", "Download DOCX"),
        modalButton("Close"),
        actionButton("submit_report_save_draft", "Save Draft", class = "btn-warning"),
        actionButton("submit_report_send", "Submit/Send", class = "btn-success")
      ),
      tagList(
        tags$div(
          class = "progress-report-workspace progress-report-edit-workspace",
          tags$div(
            class = "progress-report-workspace-header",
            tags$h3(class = "progress-report-workspace-title", project_progress_report_title()),
            tags$div(
              class = "progress-report-workspace-meta",
              tags$div(tags$strong("Report: "), project_report_display_name(data.frame(project_code = project_id, project_id = project_id, id = rv$submission_report_id %||% "", stringsAsFactors = FALSE))),
              tags$div(tags$strong("Project Code: "), project_id),
              tags$div(tags$strong("Mode: "), if (nrow(draft) == 1) "Editing draft" else "New draft")
            )
          ),
          tags$p(class = "settings-hint", "Project team leader, Other project team members, Date funding awarded, and Grant code are filled automatically by the system. All other fields are entered by the user."),
          tags$div(
            class = "progress-report-table-wrap",
            tags$table(
              class = "table table-bordered progress-report-form-table",
              tags$colgroup(
                tags$col(class = "progress-report-item-col"),
                tags$col(class = "progress-report-description-col")
              ),
              tags$thead(tags$tr(tags$th("Item"), tags$th("Description"))),
              tags$tbody(
                report_form_row("1", "Project team leader", report_short_text_input("submission_project_team_leader", values$project_team_leader)),
                report_form_row("2", "Other project team members", report_long_text_input("submission_team_members", values$team_members, rows = 5)),
                report_form_row("3", "Project Title (Final project title as approved by ethical committee)", report_short_text_input("submission_form_project_title", values$form_project_title)),
                report_form_row("4", "Project objectives", report_long_text_input("submission_project_objectives", values$project_objectives, rows = 6)),
                report_form_row("", "Nature of project (field based only, lab-based only or both)", report_short_text_input("submission_nature_of_project", values$nature_of_project)),
                report_form_row("", "Date funding awarded", readonly_report_field(NULL, project_progress_report_funding_awarded)),
                report_form_row("5", "Grant code", readonly_report_field(NULL, project_id)),
                report_form_row("6", "Ethical approval number (if not approved, indicate so and state status and challenges if any)", report_long_text_input("submission_ethical_approval_number", values$ethical_approval_number, rows = 5)),
                report_form_row("7", "NACOSTI approval number (if not approved, indicate so and state status and challenges if any)", report_long_text_input("submission_nacosti_approval_number", values$nacosti_approval_number, rows = 5)),
                report_form_row("8", "Please indicated any other approval provided", report_long_text_input("submission_other_approval_provided", values$other_approval_provided, rows = 5)),
                report_form_row("9", "Date project commenced (if you have not started work, please indicate so and give details on challenges encountered. Also state when you will commence work)", report_long_text_input("submission_date_project_commenced", values$date_project_commenced, rows = 5)),
                report_form_row("10", c("Progress report:", "(i) Indicate activities already done", "(ii) Indicate pending activities"), tagList(
                  report_progress_subfield("submission_progress_activities_done", "(i) Indicate activities already done", values$progress_activities_done),
                  report_progress_subfield("submission_progress_pending_activities", "(ii) Indicate pending activities", values$progress_pending_activities)
                )),
                report_form_row("11", "Completion date (Indicate projected date for completion of the project)", report_short_text_input("submission_completion_date", values$completion_date)),
                report_form_row("12", "Any other comment (are you on track on your project? Are there challenges that may make your project difficult to complete? How can the Director of Research & Product Development help you to complete your research)", report_long_text_input("submission_other_comment", values$other_comment, rows = 7))
              )
            )
          ),
          tags$div(
            class = "progress-report-supporting-section",
            tags$h4("Supporting Files"),
            tags$p(class = "settings-hint", "Optional. Upload supporting documents linked strictly to this Project and report."),
            fileInput("submission_supporting_docs", "Upload supporting files", multiple = TRUE, accept = email_attachment_accept_types),
            uiOutput("submission_supporting_docs_ui")
          )
        ),
        progress_report_workspace_script()
      )
    ))
    TRUE
  }

