  output$submission_supporting_docs_ui <- renderUI({
    rv$submission_supporting_refresh_token
    project_id <- as.character(rv$submission_project_id %||% "")
    if (!nzchar(project_id)) return(NULL)
    mode <- as.character(rv$submission_mode %||% "")
    report_id <- as.character(rv$submission_report_id %||% "")
    docs <- load_project_report_supporting_docs(
      project_id = project_id,
      report_id = if (identical(mode, "structured") && nzchar(report_id)) report_id else NULL,
      include_trashed = FALSE
    )
    if (nrow(docs) == 0) {
      return(tags$div(class = "settings-hint", "No supporting files saved yet."))
    }
    if (identical(mode, "upload_only")) {
      docs <- docs[as.character(docs$submission_type %||% "") == "upload_only", , drop = FALSE]
    } else if (identical(mode, "structured") && nzchar(report_id)) {
      docs <- docs[as.character(docs$report_id %||% "") == report_id, , drop = FALSE]
    }
    if (nrow(docs) == 0) {
      return(tags$div(class = "settings-hint", "No supporting files saved yet."))
    }
    tags$div(
      class = "report-supporting-doc-list",
      tags$h5("Saved files"),
      lapply(seq_len(nrow(docs)), function(i) {
        doc <- docs[i, , drop = FALSE]
        tags$div(
          class = "report-supporting-doc-item",
          tags$div(tags$strong(project_report_supporting_doc_display_name(doc))),
          tags$div(class = "settings-hint", paste0(
            toupper(as.character(doc$submission_type[[1]] %||% "supporting")),
            " | ",
            format_file_size_text(doc$size[[1]] %||% 0),
            " | Uploaded ",
            as.character(doc$created_at[[1]] %||% "")
          ))
        )
      })
    )
  })
