  observeEvent(input$submit_report_save_draft, {
    project_id <- as.character(rv$submission_project_id %||% "")
    if (!nzchar(project_id)) { showNotification("Project Code is required before saving.", type = "error"); return() }
    tryCatch({
      report <- save_project_report_submission(project_id, status = "draft", values = report_submission_values_from_input(), report_id = rv$submission_report_id)
      rv$submission_report_id <- as.character(report$id[[1]])
      rv$submission_docx_path <- as.character(report$docx_path[[1]] %||% "")
      supporting_files <- tryCatch(input$submission_supporting_docs, error = function(e) NULL)
      if (is.data.frame(supporting_files) && nrow(supporting_files) > 0) {
        save_project_report_supporting_docs(
          project_id = project_id,
          uploaded_files = supporting_files,
          report_id = rv$submission_report_id,
          submission_type = "structured_supporting",
          uploaded_by_role = "Public Submitter",
          uploaded_by_name = ""
        )
      }
      rv$submission_supporting_refresh_token <- isolate(rv$submission_supporting_refresh_token %||% 0L) + 1L
      rv$submission_project_id <- NULL
      rv$submission_project_code <- NULL
      rv$submission_report_id <- NULL
      rv$submission_docx_path <- NULL
