  reload_data <- function(busy_timeout_ms = 60000L, retries = 5L, base_delay = 0.2) {
    reload_started_at <- Sys.time()
    previous_data <- session_state$data
    current_role <- current_user_role()
    current_project <- current_allowed_project()
    next_data <- tryCatch({
      if (identical(current_role, "Administrator")) {
        load_runtime_core_data(expense_scope = "all", busy_timeout_ms = busy_timeout_ms, retries = retries, base_delay = base_delay)
      } else {
        allowed_project <- trimws(as.character(current_project %||% ""))
        if (!nzchar(allowed_project)) stop("Allowed project is not set for the current session.")
        load_runtime_core_data(
          allowed_project,
          expense_scope = default_expense_scope_for_role(current_role),
          busy_timeout_ms = busy_timeout_ms,
          retries = retries,
          base_delay = base_delay
        )
      }
    }, error = function(e) {
      append_app_runtime_log(
        "ERROR",
        paste0("reload_data failed: ", e$message),
        detail = list(
          user_role = current_role,
          allowed_project = current_project
        )
      )
      NULL
    })
    if (is.null(next_data)) {
      append_app_runtime_log(
        "WARN",
        "reload_data returned previous or empty runtime data.",
        detail = list(
          user_role = current_role,
          allowed_project = current_project,
          elapsed_ms = round(as.numeric(difftime(Sys.time(), reload_started_at, units = "secs")) * 1000)
        )
      )
      if (!is.null(previous_data)) return(invisible(previous_data))
      set_runtime_data_state(empty_runtime_core_data())
      return(invisible(session_state$data))
    }
    set_runtime_data_state(next_data)
    tryCatch(
      refresh_settings_cache(),
      error = function(e) {
        append_app_runtime_log("ERROR", paste0("refresh_settings_cache failed: ", e$message))
      }
    )
    append_app_runtime_log(
      "INFO",
      "reload_data completed.",
      detail = list(
        user_role = current_role,
        allowed_project = current_project,
        elapsed_ms = round(as.numeric(difftime(Sys.time(), reload_started_at, units = "secs")) * 1000),
        projects_loaded = if (is.data.frame(session_state$data$projects)) nrow(session_state$data$projects) else 0L,
        expenses_loaded = if (is.data.frame(session_state$data$expenses)) nrow(session_state$data$expenses) else 0L
      )
    )
    invisible(session_state$data)
  }

