  project_health <- function(pid, expense_scope = default_expense_scope_for_role(isolate(rv$user_role %||% ""))) {
    p <- active_projects_data() %>% filter(id == pid)
    if (nrow(p) == 0) return(list(health_status = "unknown", pct = 0, spent = 0, budget = 0))
    ex_scope <- expense_rows_for_scope(pid, expense_scope = expense_scope, include_trashed = FALSE)
    spent <- sum(as.numeric(ex_scope$amount %||% 0), na.rm = TRUE)
    if (is.na(spent)) spent <- 0
    budget <- as.numeric(p$budget_total)
    pct <- ifelse(budget == 0, 0, round(100 * spent / budget, 1))
    health_status <- ifelse(pct >= 100, "over", ifelse(pct >= 75, "warning", "ok"))
    list(health_status = health_status, status = health_status, pct = pct, spent = spent, budget = budget)
  }

