  # Handle login confirm
  observeEvent(input$login_confirm_request, {
    if (isTRUE(is_authenticated())) return()
    if (isTRUE(login_in_progress())) return()
    login_in_progress(TRUE)
    on.exit(login_in_progress(FALSE), add = TRUE)
    login_request <- input$login_confirm_request %||% list()
    role <- as.character(login_request$role %||% input$login_role %||% "Scientist")
    log_login_stage(
      "attempt_received",
      detail = list(
        requested_role = role,
        scientist_action = as.character(login_request$scientist_action %||% input$scientist_action %||% ""),
        requested_project = as.character(login_request$sc_open_workspace_id %||% input$sc_open_workspace_id %||% "")
      )
    )
    tryCatch({
      if (identical(role, "Scientist")) {
        action <- login_request$scientist_action %||% input$scientist_action %||% "open"
        if (identical(action, "create")) {
          new_name <- as.character(login_request$sc_new_name %||% input$sc_new_name %||% "")
          new_pi <- trimws(as.character(login_request$sc_new_pi %||% input$sc_new_pi %||% ""))
          new_status <- normalize_project_status(login_request$sc_new_status %||% input$sc_new_status %||% "In Progress")
          new_team_members <- normalize_team_members_text(login_request$sc_new_team %||% input$sc_new_team %||% "")
          new_desc <- as.character(login_request$sc_new_desc %||% input$sc_new_desc %||% "")
          new_id <- as.character(login_request$sc_new_id %||% input$sc_new_id %||% "")
          new_budget <- suppressWarnings(as.numeric(login_request$sc_new_budget %||% input$sc_new_budget %||% 0))
          if (!is.finite(new_budget)) new_budget <- 0
          if (!nzchar(trimws(new_name))) {
            log_login_stage("credentials_rejected", level = "WARN", detail = list(role = role, reason = "missing_project_name"))
            showNotification("Project name is required.", type = "error")
            return()
          }
          if (!nzchar(new_pi)) {
            log_login_stage("credentials_rejected", level = "WARN", detail = list(role = role, reason = "missing_principle_investigator"))
            showNotification("Principle Investigator is required.", type = "error")
            return()
          }
          if (!nzchar(new_id)) {
            log_login_stage("credentials_rejected", level = "WARN", detail = list(role = role, reason = "missing_project_id"))
            showNotification("Project ID is required and must be unique. Please enter a valid Project ID.", type = "error")
            return()
          }
          con <- connect_db_for_login()
          on.exit({
            if (exists("con", inherits = FALSE) && DBI::dbIsValid(con)) dbDisconnect(con)
          }, add = TRUE)
          exists <- dbGetQuery(con, "SELECT COUNT(*) as n FROM projects WHERE id = ?;", params = list(new_id))$n
          if (exists > 0) {
            log_login_stage("credentials_rejected", level = "WARN", detail = list(role = role, reason = "duplicate_project_id", project_id = new_id))
            showNotification("Project ID already exists. Choose a different unique ID.", type = "error")
            return()
          }
          ok <- create_project(
            id = new_id,
            name = new_name,
            description = new_desc,
            budget_total = new_budget,
            start_date = as.character(Sys.Date()),
            end_date = as.character(NA),
            status = new_status,
            principal_investigator = new_pi,
            team_members = new_team_members
          )
          if (!isTRUE(ok)) {
            log_login_stage("credentials_rejected", level = "ERROR", detail = list(role = role, reason = "project_creation_failed", project_id = new_id))
            showNotification("Failed to create project. See logs.", type = "error")
            return()
          }
          access_key <- get_project_access_key(new_id)
          log_login_stage("credentials_validated", detail = list(role = role, action = "create", project_id = new_id))
          updateSelectInput(session, "exp_project_select", choices = setNames(new_id, new_name), selected = new_id)
          updateSelectInput(session, "report_project", choices = setNames(new_id, new_name), selected = new_id)
          log_login_stage("role_resolved", detail = list(role = "Scientist", resolved_project = new_id))
          complete_login_transition(
            role = "Scientist",
            allowed_project = new_id,
            success_message = paste0("Project created and Scientist access granted for project: ", new_name, ". Access Key: ", access_key),
            notification_duration = 10
          )
          schedule_post_login_initialization(role = "Scientist", allowed_project = new_id)
          return()
        }
        workspace_id <- as.character(login_request$sc_open_workspace_id %||% input$sc_open_workspace_id %||% "")
        if (!nzchar(workspace_id)) {
          log_login_stage("credentials_rejected", level = "WARN", detail = list(role = role, reason = "missing_project_id"))
          showNotification("Project ID is required.", type = "error")
          return()
        }
        entered_access_key <- normalize_project_access_key(login_request$sc_open_access_key %||% input$sc_open_access_key %||% "")
        if (!nzchar(entered_access_key)) {
          log_login_stage("credentials_rejected", level = "WARN", detail = list(role = role, reason = "missing_access_key", project_id = workspace_id))
          showNotification("Enter the project Access Key using three unique letters.", type = "error")
          return()
        }
        pr <- load_workspace_project(
          workspace_id,
          include_trashed = FALSE,
          busy_timeout_ms = 1500L,
          retries = 2L,
          base_delay = 0.05
        )
        if (nrow(pr) != 1) {
          log_login_stage("credentials_rejected", level = "WARN", detail = list(role = role, reason = "project_not_found", project_id = workspace_id))
          showNotification("Selected project not available.", type = "error")
          return()
        }
        stored_access_key <- normalize_project_access_key(pr$access_key[[1]] %||% "")
        if (!nzchar(stored_access_key) || !identical(entered_access_key, stored_access_key)) {
          log_login_stage("credentials_rejected", level = "WARN", detail = list(role = role, reason = "access_key_mismatch", project_id = workspace_id))
          showNotification("Project Code and Access Key do not match. Access denied.", type = "error")
          return()
        }
        log_login_stage("credentials_validated", detail = list(role = role, action = "open", project_id = workspace_id))
        updateSelectInput(session, "exp_project_select", choices = setNames(pr$id, pr$name), selected = pr$id)
        updateSelectInput(session, "report_project", choices = setNames(pr$id, pr$name), selected = pr$id)
        log_login_stage("role_resolved", detail = list(role = "Scientist", resolved_project = workspace_id))
        complete_login_transition(
          role = "Scientist",
          allowed_project = workspace_id,
          success_message = paste0("Scientist access granted for project: ", pr$name)
        )
        schedule_post_login_initialization(role = "Scientist", allowed_project = workspace_id)
        return()
      }
      if (identical(role, "Administrator")) {
        pwd <- as.character(login_request$login_admin_password %||% input$login_admin_password %||% "")
        if (!nzchar(pwd)) {
          log_login_stage("credentials_rejected", level = "WARN", detail = list(role = role, reason = "missing_password"))
          showNotification("Administrator password required.", type = "error")
          return()
        }
        if (!check_admin_password(pwd)) {
          log_login_stage("credentials_rejected", level = "WARN", detail = list(role = role, reason = "invalid_password"))
          showNotification("Incorrect administrator password.", type = "error")
          return()
        }
        log_login_stage("credentials_validated", detail = list(role = role))
        log_login_stage("role_resolved", detail = list(role = "Administrator", resolved_project = ""))
        complete_login_transition(
          role = "Administrator",
          allowed_project = NULL,
          success_message = "Administrator access granted."
        )
        schedule_post_login_initialization(role = "Administrator", allowed_project = NULL)
        return()
      }
      log_login_stage("credentials_rejected", level = "WARN", detail = list(role = role, reason = "unknown_role"))
      showNotification("Unknown role selection.", type = "error")
    }, error = function(e) {
      log_login_stage(
        "failed",
        level = "ERROR",
        detail = list(
          requested_role = role,
          error = as.character(e$message %||% "")
        )
      )
      showNotification(paste0("Login failed: ", e$message), type = "error", duration = 10)
    })
  })

