  # Live report preview rendering
  report_controls_box_ui <- function() {
    project_rows <- data.frame()
    if (!is.null(rv$data) && "projects" %in% names(rv$data)) {
      project_rows <- rv$data$projects %>% filter(is_trashed == 0)
      if (identical(rv$user_role, "Scientist") && nzchar(as.character(rv$allowed_project %||% ""))) {
        project_rows <- project_rows %>% filter(id == as.character(rv$allowed_project))
      }
    }
    project_choices <- if (nrow(project_rows) > 0) setNames(project_rows$id, project_rows$name) else c()
    selected_project <- if (length(project_choices) > 0) {
      current_project <- isolate(input$report_project %||% "")
      if (nzchar(current_project) && current_project %in% unname(project_choices)) current_project else unname(project_choices)[[1]]
    } else NULL
    report_scope_choices <- if (identical(rv$user_role, "Administrator")) {
      c("Admin Expense Report" = "administrator", "User/Scientist Expense Report" = "scientist")
    } else {
      c("User/Scientist Expense Report" = "scientist")
    }
    selected_scope <- isolate(input$report_expense_scope %||% report_scope_choices[[1]])
    if (!selected_scope %in% unname(report_scope_choices)) selected_scope <- report_scope_choices[[1]]
    current_date_range <- isolate(input$report_date_range)
    default_date_range <- c(Sys.Date() - 90, Sys.Date())
    if (length(current_date_range) != 2 || any(is.na(current_date_range))) current_date_range <- default_date_range
    compare_enabled <- isTRUE(isolate(input$report_compare_side_by_side %||% FALSE))
    use_date_filter <- isTRUE(isolate(input$report_use_date_filter %||% FALSE))
    watermark_enabled <- isTRUE(isolate(input$report_watermark %||% TRUE))
    watermark_text <- isolate(input$report_watermark_text %||% get_setting("watermark_text") %||% "CONFIDENTIAL")
    excel_password <- isolate(input$report_excel_password %||% get_setting("excel_password") %||% "")
    box(
      title = "Export Options",
      width = NULL,
      status = "primary",
      selectInput("report_project", "Select Project (required)", choices = project_choices, selected = selected_project),
      selectInput("report_expense_scope", "Expense report type", choices = report_scope_choices, selected = selected_scope),
      if (identical(rv$user_role, "Administrator")) checkboxInput("report_compare_side_by_side", "Compare Admin and Scientist expense reports side by side in preview", value = compare_enabled),
      dateRangeInput("report_date_range", "Date Range (optional)",
        start = current_date_range[[1]],
        end = current_date_range[[2]],
        format = "yyyy-mm-dd"
      ),
      checkboxInput("report_use_date_filter", "Apply date range filter", value = use_date_filter),
      tags$p(
        style = "font-size: 12px; color: #666; margin-top: 12px;",
        "When enabled, the report will show expenses only within the selected date range and display a period total. Overall project financial status will always reflect all-time spending."
      ),
      checkboxInput("report_watermark", "Apply Watermark", value = watermark_enabled),
      textInput("report_watermark_text", "Watermark text", value = watermark_text),
      div(
        class = "report-help",
        "Report preview, Excel, and PDF use the same filtered dataset. PDF uses browser rendering when available and a server-safe fallback renderer otherwise."
      ),
      textInput("report_excel_password", "Excel password (optional)", value = excel_password),
      div(
        class = "report-actions",
        downloadButton("download_excel_report", "Download Excel", class = "btn-primary"),
        downloadButton("download_pdf_report", "Download PDF", class = "btn-success"),
        downloadButton("download_html_report", "Download HTML", class = "btn-default")
      )
    )
  }

