  output$report_preview_container <- renderUI({
    tryCatch({
      pid <- input$report_project
      
      if (is.null(pid) || !nzchar(pid)) {
        return(tags$div(
          style = "padding: 20px; text-align: center; color: #999; background: #f5f5f5; border-radius: 4px; min-height: 400px; display: flex; align-items: center; justify-content: center;",
          "Select a project to preview the report."
        ))
      }
      
      if (!can_access_project(pid)) {
        return(tags$div(
          style = "padding: 20px; color: #c62828; background: #ffe8e8; border-radius: 4px;",
