        ))
      }
      
      # Determine date range
      use_filter <- input$report_use_date_filter %||% FALSE
      start_date <- if (isTRUE(use_filter)) input$report_date_range[[1]] else NULL
      end_date <- if (isTRUE(use_filter)) input$report_date_range[[2]] else NULL
      
      # Generate preview HTML
