  output$drive_sync_status <- renderText({
    settings_version()
    status <- drive_sync_status()
    lock_row <- get_drive_sync_lock()
    helper_status <- background_scheduler_status()
    service_account_connected <- isTRUE(status$settings$has_service_account) && nzchar(status$settings$connected_email %||% "")
    lines <- c(
      paste0("Status: ", if (isTRUE(status$ok)) "Ready" else "Not Ready"),
      paste0("Backend: ", status$settings$backend %||% "google_drive"),
      paste0("Account: ", status$settings$account_email %||% ""),
      paste0("Auth Mode: ", if (isTRUE(status$settings$has_service_account)) "Service Account JSON" else "Cached OAuth Token"),
      paste0("Service Account JSON: ", if (isTRUE(status$settings$has_service_account)) "Uploaded" else "Not Uploaded"),
      paste0("Connected: ", if (isTRUE(service_account_connected) || drive_has_cached_token()) "Yes" else "No"),
      paste0("Connected Account: ", status$settings$connected_email %||% ""),
      paste0("Interval: ", as.integer(status$settings$interval_sec %||% 300), " seconds"),
      paste0("Hosted Background Helper: ", if (isTRUE(helper_status$active)) "Running" else if (can_launch_background_scheduler()) "Not Running" else "Not Required"),
      paste0("Root Folder Name: ", status$settings$root_folder_name %||% "Budget App Backups"),
      paste0("Root Folder ID: ", status$settings$root_folder_id %||% "")
    )
    if (!isTRUE(status$ok)) {
      lines <- c(lines, paste0("Issue: ", status$reason))
    }
    if (nrow(lock_row) == 1) {
      lines <- c(
        lines,
        paste0("Last Success: ", as.character(lock_row$last_success_at[[1]] %||% "")),
        paste0("Last Error: ", as.character(lock_row$last_error[[1]] %||% ""))
      )
    }
    if (nzchar(helper_status$heartbeat_at %||% "")) {
      lines <- c(lines, paste0("Helper Heartbeat: ", helper_status$heartbeat_at %||% ""))
    }
    paste(lines, collapse = "\n")
  })
  output$dt_project_access_keys <- renderDT({
    req(rv$data)
    if (!identical(rv$user_role, "Administrator")) {
      return(DT::datatable(data.frame(Message = "Administrator access only"), options = list(dom = "t")))
    }
    project_rows <- rv$data$projects %>%
      filter(is_trashed == 0) %>%
      transmute(
        `Project Code` = id,
        `Project Name` = name,
        `Access Key` = vapply(access_key, normalize_project_access_key, character(1)),
        `Principle Investigator` = ifelse(nzchar(trimws(as.character(principal_investigator %||% ""))), principal_investigator, "Not set"),
        `Status` = vapply(status, normalize_project_status, character(1))
      )
    if (nrow(project_rows) == 0) {
      return(DT::datatable(data.frame(Message = "No active projects"), options = list(dom = "t")))
    }
    DT::datatable(project_rows, rownames = FALSE, options = list(pageLength = 10, autoWidth = TRUE))
  }, server = TRUE)
  
  # Persist theme setting (anyone can change theme; but saving settings is restricted later)
  observeEvent(input$setting_theme, {
    if (!require_authenticated(FALSE)) return()
    if (!is.null(input$setting_theme)) {
      ok_theme <- set_setting("theme", input$setting_theme)
      ok_accent <- TRUE
      if (identical(input$setting_theme, "Custom Accent")) ok_accent <- set_setting("custom_accent", input$custom_accent_hex %||% "#2B84D8")
      if (!isTRUE(ok_theme) || !isTRUE(ok_accent)) {
        showNotification("Theme change could not be saved.", type = "error")
        return()
      }
      refresh_settings_cache()
    }
  }, ignoreInit = TRUE)

  observeEvent(input$btn_drive_connect, {
    if (!require_authenticated()) return()
    if (identical(rv$user_role, "Scientist")) {
      showNotification("Scientist role cannot configure Google Drive backup.", type = "error")
      return()
    }
    account_email <- trimws(as.character(input$setting_drive_account_email %||% ""))
    root_folder_name <- trimws(as.character(input$setting_drive_root_folder_name %||% "Budget App Backups"))
    root_folder_id <- trimws(as.character(input$setting_drive_root_folder_id %||% ""))
    tryCatch({
      ensure_drive_packages_installed()
      current_drive_settings <- get_drive_sync_settings(force = TRUE)
      uploaded_service_account <- !is.null(input$setting_drive_service_account_json$datapath) && nzchar(as.character(input$setting_drive_service_account_json$datapath %||% ""))
      using_service_account <- isTRUE(current_drive_settings$has_service_account) || uploaded_service_account
      if (!nzchar(root_folder_id)) {
        root_folder_id <- trimws(as.character(current_drive_settings$root_folder_id %||% ""))
      }
      if (!nzchar(account_email) && !using_service_account) {
        stop("Google account email is required unless a Google service account JSON is uploaded.", call. = FALSE)
      }
      if (!nzchar(root_folder_name)) root_folder_name <- "Budget App Backups"
      if (using_service_account && !nzchar(root_folder_id)) {
        stop(
          paste(
            "Service account mode requires a Shared Drive folder ID.",
            "Create or choose a folder inside a Google Shared Drive, add the service account as a Content manager or Manager, paste that folder ID into Settings, then click Connect Google Drive again."
          ),
          call. = FALSE
        )
      }
      if (uploaded_service_account) {
        store_drive_service_account_json(input$setting_drive_service_account_json$datapath)
      }
      if (!using_service_account && !identical(tolower(account_email), tolower(as.character(current_drive_settings$account_email %||% "")))) {
        clear_drive_cached_tokens()
      }
      set_setting("drive_account_email", account_email)
      set_setting("drive_root_folder_name", root_folder_name)
      set_setting("drive_root_folder_id", root_folder_id)
      set_setting("drive_connected_email", "")
      auth_result <- drive_authenticate_interactive(account_email)
      set_setting("drive_connected_email", auth_result$connected_email %||% account_email)
      root_id <- ensure_drive_root_folder(get_drive_sync_settings())
      set_setting("drive_root_folder_id", root_id)
      mark_all_projects_drive_dirty()
      refresh_settings_cache()
      showNotification(
        if (identical(auth_result$mode %||% "", "service_account")) {
          "Google Drive service account connected, permissions verified, and root backup folder prepared."
        } else {
          "Google Drive account connected, permissions verified, and root backup folder prepared."
        },
        type = "message"
      )
      later::later(function() {
        if (can_launch_background_scheduler()) try(ensure_background_scheduler_service("drive_connected"), silent = TRUE)
        try(start_drive_sync_worker("drive_connected"), silent = TRUE)
      }, delay = 0)
    }, error = function(e) {
      set_setting("drive_connected_email", "")
      refresh_settings_cache()
      showNotification(paste0("Google Drive connection failed: ", format_drive_error(e)), type = "error")
    })
  }, ignoreInit = TRUE)

  observeEvent(input$btn_drive_disconnect, {
    if (!require_authenticated()) return()
    if (identical(rv$user_role, "Scientist")) {
      showNotification("Scientist role cannot configure Google Drive backup.", type = "error")
      return()
    }
    tryCatch({
      clear_drive_cached_tokens()
      set_setting("drive_connected_email", "")
      refresh_settings_cache()
      showNotification("Google Drive connection cleared. The configured backup folder remains saved for the next reconnect.", type = "warning")
    }, error = function(e) {
      showNotification(paste0("Failed to clear Google Drive connection: ", e$message), type = "error")
    })
  }, ignoreInit = TRUE)

