  observeEvent(input$btn_drive_restore, {
    if (!require_authenticated()) return()
    if (identical(rv$user_role, "Scientist")) {
      showNotification("Scientist role cannot restore from Google Drive.", type = "error")
      return()
    }
    showModal(modalDialog(
      title = "Restore from Google Drive",
      easyClose = TRUE,
      footer = tagList(
        modalButton("Cancel"),
        actionButton("confirm_drive_restore", "Restore Now", class = "btn-warning")
      ),
      tagList(
        p("This will scan the configured Google Drive backup folder and restore all Project snapshots found there."),
        p("Existing local records for matching Projects will be replaced with the Drive snapshot data, and attachments/reports will be downloaded back into this app."),
        tags$strong("Only continue if this server should be restored from the connected Google Drive backup.")
      )
    ))
  }, ignoreInit = TRUE)

  observeEvent(input$confirm_drive_restore, {
    if (!require_authenticated()) return()
    if (identical(rv$user_role, "Scientist")) {
      showNotification("Scientist role cannot restore from Google Drive.", type = "error")
      return()
    }
    removeModal()
    tryCatch({
      res <- withProgress(message = "Restoring from Google Drive...", value = 0.2, {
        restore_from_google_drive()
      })
      reload_data()
      refresh_settings_cache()
      restored <- as.integer(res$restored_projects %||% 0L)
      skipped <- as.integer(res$skipped_projects %||% 0L)
      if (restored > 0) {
        showNotification(paste0("Google Drive restore completed. Restored ", restored, " Project(s). Skipped ", skipped, "."), type = "message", duration = 8)
      } else {
        showNotification("Google Drive restore completed, but no restorable Project snapshots were found.", type = "warning", duration = 8)
      }
    }, error = function(e) {
      showNotification(paste0("Google Drive restore failed: ", format_drive_error(e)), type = "error", duration = 12)
    })
  }, ignoreInit = TRUE)
  # Save settings handler (resyncs projects). Protect settings changes from Scientist role.
  observeEvent(input$btn_save_settings, {
    if (!require_authenticated()) return()
    tryCatch({
      save_or_stop <- function(ok, label) {
        if (!isTRUE(ok)) stop(paste0("Failed to save ", label, "."))
      }
      # Restrict settings changes if Scientist
      if (identical(rv$user_role, "Scientist")) {
        showNotification("Scientist role cannot change system settings.", type = "error")
        return()
      }
      current_settings_map <- read_settings_map(force = TRUE)
      # Persist currency selection (ADD)
      current_drive_settings <- get_drive_sync_settings(force = TRUE)
      uploaded_service_account <- !is.null(input$setting_drive_service_account_json$datapath) && nzchar(as.character(input$setting_drive_service_account_json$datapath %||% ""))
      using_service_account <- isTRUE(current_drive_settings$has_service_account) || uploaded_service_account
      settings_updates <- list()
      if (!is.null(input$setting_currency)) settings_updates$currency <- as.character(input$setting_currency)
      if (!is.null(input$choose_export_folder)) {
        path <- tryCatch(parseDirPath(roots, input$choose_export_folder), error = function(e) "")
        if (length(path) && nzchar(path)) settings_updates$export_folder <- as.character(path)
      }
      if (!is.null(input$choose_backup_folder)) {
        pathb <- tryCatch(parseDirPath(roots, input$choose_backup_folder), error = function(e) "")
        if (length(pathb) && nzchar(pathb)) settings_updates$backup_folder <- as.character(pathb)
      }
      if (!is.null(input$setting_drive_service_account_json$datapath) && nzchar(as.character(input$setting_drive_service_account_json$datapath %||% ""))) {
        store_drive_service_account_json(input$setting_drive_service_account_json$datapath)
      }
      settings_updates$excel_password <- as.character(input$setting_excel_password %||% "")
      settings_updates$watermark_text <- as.character(input$setting_watermark_text %||% "CONFIDENTIAL")
      settings_updates$progress_report_as_at_date <- trimws(as.character(input$setting_progress_report_as_at_date %||% project_progress_report_default_as_at_date))
      settings_updates$protect_other_sheets <- tolower(as.character(input$setting_protect_other))
      if (!is.null(input$setting_theme)) settings_updates$theme <- as.character(input$setting_theme)
      settings_updates$use_working_dir <- tolower(as.character(input$setting_use_working_dir))
      if (!is.null(input$setting_theme) && input$setting_theme == "Custom Accent") settings_updates$custom_accent <- as.character(input$custom_accent_hex %||% "#2B84D8")
      settings_updates$drive_backup_enabled <- tolower(as.character(input$setting_drive_backup_enabled %||% FALSE))
      new_drive_email <- trimws(as.character(input$setting_drive_account_email %||% ""))
      new_root_folder_name <- trimws(as.character(input$setting_drive_root_folder_name %||% "Budget App Backups"))
      new_root_folder_id <- trimws(as.character(input$setting_drive_root_folder_id %||% ""))
      settings_updates$drive_account_email <- new_drive_email
      settings_updates$drive_root_folder_name <- new_root_folder_name
      settings_updates$drive_root_folder_id <- new_root_folder_id
      if (!using_service_account && !identical(tolower(new_drive_email), tolower(as.character(current_drive_settings$account_email %||% "")))) {
        clear_drive_cached_tokens()
        settings_updates$drive_connected_email <- ""
        settings_updates$drive_root_folder_id <- ""
      }
      if (!nzchar(new_root_folder_id) && !identical(trimws(as.character(input$setting_drive_root_folder_name %||% "Budget App Backups")), trimws(as.character(current_drive_settings$root_folder_name %||% "Budget App Backups")))) {
        settings_updates$drive_root_folder_id <- ""
      }
      settings_updates$drive_sync_interval_sec <- "300"
      email_port <- suppressWarnings(as.integer(input$setting_email_smtp_port %||% "587"))
      if (is.na(email_port) || email_port <= 0) stop("SMTP port must be a valid positive number.")
      email_interval <- suppressWarnings(as.integer(input$setting_email_scheduler_interval_sec %||% "60"))
      if (is.na(email_interval) || email_interval < 30) stop("Email scheduler interval must be at least 30 seconds.")
      email_schedule_tz <- normalize_timezone_value(input$setting_email_schedule_timezone %||% default_email_schedule_timezone(), field_name = "Scheduled email time zone")
      email_connect_timeout <- suppressWarnings(as.integer(input$setting_email_smtp_connect_timeout_sec %||% "15"))
      if (is.na(email_connect_timeout) || email_connect_timeout < 5) stop("SMTP connect timeout must be at least 5 seconds.")
      email_total_timeout <- suppressWarnings(as.integer(input$setting_email_smtp_total_timeout_sec %||% "60"))
      if (is.na(email_total_timeout) || email_total_timeout < email_connect_timeout) stop("SMTP total timeout must be greater than or equal to the SMTP connect timeout.")
      settings_updates$email_delivery_enabled <- tolower(as.character(input$setting_email_delivery_enabled %||% FALSE))
      settings_updates$email_from_name <- trimws(as.character(input$setting_email_from_name %||% ""))
      settings_updates$email_from_address <- trimws(as.character(input$setting_email_from_address %||% ""))
      settings_updates$email_smtp_host <- trimws(as.character(input$setting_email_smtp_host %||% ""))
      settings_updates$email_smtp_port <- as.character(email_port)
      settings_updates$email_smtp_username <- trimws(as.character(input$setting_email_smtp_username %||% ""))
      settings_updates$email_smtp_password <- as.character(input$setting_email_smtp_password %||% "")
      if (grepl("gmail", tolower(settings_updates$email_smtp_host %||% ""), fixed = TRUE)) {
        if (nzchar(settings_updates$email_from_address %||% "") && !grepl("@", settings_updates$email_smtp_username %||% "", fixed = TRUE)) {
          settings_updates$email_smtp_username <- settings_updates$email_from_address
        }
        settings_updates$email_smtp_password <- gsub("\\s+", "", settings_updates$email_smtp_password %||% "", perl = TRUE)
      }
      settings_updates$email_smtp_use_ssl <- tolower(as.character(input$setting_email_smtp_use_ssl %||% TRUE))
      settings_updates$email_smtp_insecure_tls <- tolower(as.character(input$setting_email_smtp_insecure_tls %||% FALSE))
      settings_updates$email_scheduler_interval_sec <- as.character(email_interval)
      settings_updates$email_schedule_timezone <- email_schedule_tz
      settings_updates$email_smtp_connect_timeout_sec <- as.character(email_connect_timeout)
      settings_updates$email_smtp_total_timeout_sec <- as.character(email_total_timeout)
      uploaded_email_logo <- !is.null(input$setting_email_logo$datapath) && nzchar(as.character(input$setting_email_logo$datapath %||% ""))
      if (uploaded_email_logo) {
        store_email_logo_asset(input$setting_email_logo$datapath)
      }
      # Admin password change (if provided)
      new_admin_pwd <- input$setting_admin_password %||% ""
      admin_password_changed <- FALSE
      if (nzchar(new_admin_pwd)) {
        settings_updates$admin_password_hash <- digest::digest(as.character(new_admin_pwd), algo = "sha256")
        admin_password_changed <- TRUE
      }
      changed_keys <- names(settings_updates)[vapply(names(settings_updates), function(key) {
        !identical(as.character(settings_updates[[key]] %||% ""), as.character(current_settings_map[[key]] %||% ""))
      }, logical(1))]
      settings_updates <- settings_updates[changed_keys]
      if (length(settings_updates) == 0 && !uploaded_email_logo && !uploaded_service_account && !admin_password_changed) {
        refresh_settings_cache()
        refresh_setting_inputs()
        updateTextInput(session, "setting_admin_password", value = "")
        showNotification("No settings changes detected.", type = "message")
        return()
      }
      save_or_stop(
        set_settings_batch(
          settings_updates,
          audit_action = "save_settings",
          detail = list(admin_password_changed = admin_password_changed, changed_keys = unname(changed_keys))
        ),
        "settings"
      )
      refresh_settings_cache()
      refresh_setting_inputs()
      updateTextInput(session, "setting_admin_password", value = "")
      later::later(function() {
        if (can_launch_background_scheduler() && (length(changed_keys) > 0 || uploaded_email_logo || uploaded_service_account)) {
          try(ensure_background_scheduler_service("settings_saved"), silent = TRUE)
        }
      }, delay = 0)
      showNotification("Settings saved and applied immediately.", type = "message")
    }, error = function(e) {
      showNotification(paste0("Failed to save settings: ", e$message), type = "error")
    })
  }, ignoreInit = TRUE)
  
