  normalize_contact_match_key <- function(x) {
    value <- trimws(tolower(as.character(x %||% "")))
    gsub("[^a-z0-9]+", "", value)
  }

  resolve_project_pi_contact <- function(project_row) {
    project_id <- as.character(project_row$id[[1]] %||% "")
    pi_name <- trimws(as.character(project_row$principal_investigator[[1]] %||% ""))
    contacts <- tryCatch(load_project_contacts(project_id, include_trashed = FALSE), error = function(e) data.frame())
    if (!is.data.frame(contacts) || nrow(contacts) == 0) {
      return(list(
        ok = FALSE,
        contact_id = "",
        pi_name = if (nzchar(pi_name)) pi_name else "Not set",
        pi_email = "",
        status = "PI email not found in project contacts."
      ))
    }
    contacts <- contacts[as.character(contacts$project_id %||% "") == project_id, , drop = FALSE]
    if ("is_trashed" %in% names(contacts)) {
      trashed <- suppressWarnings(as.integer(contacts$is_trashed %||% 0L))
      contacts <- contacts[is.na(trashed) | trashed == 0L, , drop = FALSE]
    }
    if (nrow(contacts) == 0) {
      return(list(
        ok = FALSE,
        contact_id = "",
        pi_name = if (nzchar(pi_name)) pi_name else "Not set",
        pi_email = "",
        status = "PI email not found in project contacts."
      ))
    }
    contacts$email_address <- trimws(as.character(contacts$email_address %||% ""))
    contacts$contact_name <- trimws(as.character(contacts$contact_name %||% ""))
    contacts$role_position <- trimws(as.character(contacts$role_position %||% ""))
    contacts <- contacts[nzchar(contacts$email_address), , drop = FALSE]
    if (nrow(contacts) == 0) {
      return(list(
        ok = FALSE,
        contact_id = "",
        pi_name = if (nzchar(pi_name)) pi_name else "Not set",
        pi_email = "",
        status = "PI email is blank in the project contacts."
      ))
    }
    pi_key <- normalize_contact_match_key(pi_name)
    name_keys <- vapply(contacts$contact_name, normalize_contact_match_key, character(1))
    role_values <- tolower(as.character(contacts$role_position %||% ""))
    role_match <- grepl("principal investigator|principle investigator|project team leader|\\bpi\\b", role_values, perl = TRUE)
    exact_name_match <- nzchar(pi_key) & name_keys == pi_key
    preferred <- which(exact_name_match & role_match)
    if (length(preferred) == 0) preferred <- which(exact_name_match)
    if (length(preferred) == 0) preferred <- which(role_match)
    if (length(preferred) == 0 && nrow(contacts) == 1 && !nzchar(pi_key)) preferred <- 1L
    if (length(preferred) == 0) {
      return(list(
        ok = FALSE,
        contact_id = "",
        pi_name = if (nzchar(pi_name)) pi_name else "Not set",
        pi_email = "",
        status = "No project contact matches the Principal Investigator."
      ))
    }
    row <- contacts[preferred[[1]], , drop = FALSE]
    resolved_name <- trimws(as.character(row$contact_name[[1]] %||% pi_name))
    if (!nzchar(resolved_name)) resolved_name <- if (nzchar(pi_name)) pi_name else "Not set"
    list(
      ok = TRUE,
      contact_id = as.character(row$id[[1]] %||% ""),
      pi_name = resolved_name,
      pi_email = as.character(row$email_address[[1]] %||% ""),
      status = "Ready"
    )
  }

