  render_pi_bulk_email_tokens <- function(text, project_row, pi_contact, access_key) {
    out <- as.character(text %||% "")
    replacements <- list(
      "{{PI_NAME}}" = as.character(pi_contact$pi_name %||% ""),
      "{{PI_EMAIL}}" = as.character(pi_contact$pi_email %||% ""),
      "{{PROJECT_CODE}}" = as.character(project_row$id[[1]] %||% ""),
      "{{PROJECT_TITLE}}" = as.character(project_row$name[[1]] %||% ""),
      "{{ACCESS_KEY}}" = as.character(access_key %||% ""),
      "{{PROJECT_STATUS}}" = as.character(project_row$status[[1]] %||% ""),
      "{{TEAM_MEMBERS}}" = format_team_members_inline(project_row$team_members[[1]] %||% "", empty = "Not provided")
    )
    for (token in names(replacements)) {
      out <- gsub(token, replacements[[token]] %||% "", out, fixed = TRUE)
    }
    out
  }

  project_submitted_report_attachment_keys <- function(project_id) {
    reports <- tryCatch(load_project_reports_for_file_manager(project_id, include_trashed = FALSE), error = function(e) data.frame())
    if (!is.data.frame(reports) || nrow(reports) == 0) return(character())
    reports <- reports[tolower(as.character(reports$status %||% "")) == "submitted", , drop = FALSE]
    unique(paste0("report::", as.character(reports$id %||% character())))
  }

  build_pi_bulk_email_job <- function(project_row, action_type, custom_subject = "", custom_message = "") {
    project_id <- as.character(project_row$id[[1]] %||% "")
    project_title <- as.character(project_row$name[[1]] %||% "")
    access_key <- normalize_project_access_key(project_row$access_key[[1]] %||% "")
    pi_contact <- resolve_project_pi_contact(project_row)
    sender_label <- trimws(as.character(get_setting("email_from_name") %||% ""))
    if (!nzchar(sender_label)) sender_label <- "the project management system"
    issues <- character()
    subject <- ""
    message_body <- ""
    attachment_keys <- character()

    if (!nzchar(project_id)) {
      issues <- c(issues, "Project Code is missing.")
    }
    if (!isTRUE(pi_contact$ok)) {
      issues <- c(issues, as.character(pi_contact$status %||% "PI email not found."))
    }

    if (identical(action_type, "access_keys")) {
      if (!nzchar(access_key)) issues <- c(issues, "Access Key is missing for this project.")
      subject <- paste0("Project Access Details: ", project_title, " (", project_id, ")")
      message_body <- paste(
        c(
          paste0("Dear ", pi_contact$pi_name %||% "Principal Investigator", ","),
          "",
          "The system has prepared your project access details below.",
          paste0("Project Title: ", project_title),
          paste0("Project Code: ", project_id),
          paste0("Access Key: ", access_key),
          "",
          "Please keep this access key confidential and use it together with your Project Code when accessing the project workspace.",
          "",
          "Thank you."
        ),
        collapse = "\n"
      )
    } else if (identical(action_type, "report_reminder")) {
      subject <- paste0("Report Reminder: ", project_title, " (", project_id, ")")
      message_body <- paste(
        c(
          paste0("Dear ", pi_contact$pi_name %||% "Principal Investigator", ","),
          "",
          paste0("This is a reminder to submit the required project report through ", sender_label, "."),
          paste0("Project Title: ", project_title),
          paste0("Project Code: ", project_id),
          paste0("Access Key: ", access_key),
          "",
          "Please review the current reporting requirements and complete the submission within the expected timeline.",
          "",
          "Thank you."
        ),
        collapse = "\n"
      )
    } else if (identical(action_type, "submitted_reports")) {
      attachment_keys <- project_submitted_report_attachment_keys(project_id)
      if (length(attachment_keys) == 0) {
        issues <- c(issues, "No submitted reports are available for this project.")
      }
      subject <- paste0("Submitted Reports: ", project_title, " (", project_id, ")")
      message_body <- paste(
        c(
          paste0("Dear ", pi_contact$pi_name %||% "Principal Investigator", ","),
          "",
          "Please find attached the submitted project report document(s) currently stored in the system for your project.",
          paste0("Project Title: ", project_title),
          paste0("Project Code: ", project_id),
          "",
          "Thank you."
        ),
        collapse = "\n"
      )
    } else if (identical(action_type, "status_update")) {
      project_status <- normalize_project_status(project_row$status[[1]] %||% "")
      subject <- paste0("Project Status Update: ", project_title, " (", project_id, ")")
      message_body <- paste(
        c(
          paste0("Dear ", pi_contact$pi_name %||% "Principal Investigator", ","),
          "",
          "This is an update on the current project status recorded in the system.",
          paste0("Project Title: ", project_title),
          paste0("Project Code: ", project_id),
          paste0("Current Status: ", project_status),
          "",
          "If this status needs to be changed, please contact the system administrator.",
          "",
          "Thank you."
        ),
        collapse = "\n"
      )
    } else {
      subject <- trimws(as.character(custom_subject %||% ""))
      message_body <- trimws(as.character(custom_message %||% ""))
      if (!nzchar(subject)) {
        issues <- c(issues, "Custom email subject is required.")
      }
      if (!nzchar(message_body)) {
        issues <- c(issues, "Custom email message is required.")
      } else {
        subject <- render_pi_bulk_email_tokens(subject, project_row, pi_contact, access_key)
        message_body <- render_pi_bulk_email_tokens(message_body, project_row, pi_contact, access_key)
      }
    }

    status_text <- if (length(issues) == 0) "Ready" else paste(unique(issues[nzchar(issues)]), collapse = " | ")

    list(
      project_id = project_id,
      project_title = project_title,
      access_key = access_key,
      pi_name = as.character(pi_contact$pi_name %||% "Not set"),
      pi_email = as.character(pi_contact$pi_email %||% ""),
      contact_id = as.character(pi_contact$contact_id %||% ""),
      subject = subject,
      message_body = message_body,
      attachment_keys = attachment_keys,
      ready = identical(status_text, "Ready"),
      status = status_text
    )
  }

  build_pi_bulk_email_preview_state <- function(action_type, custom_subject = "", custom_message = "") {
    projects <- active_projects_for_pi_bulk()
    selected_ids <- selected_pi_bulk_project_ids()
    if (nrow(projects) == 0) stop("No active projects are available.")
    if (length(selected_ids) == 0) stop("Select at least one project.")
    projects <- projects[as.character(projects$id %||% "") %in% selected_ids, , drop = FALSE]
    if (nrow(projects) == 0) stop("No active projects matched the selected scope.")
    jobs <- lapply(seq_len(nrow(projects)), function(i) build_pi_bulk_email_job(projects[i, , drop = FALSE], action_type, custom_subject, custom_message))
    display <- do.call(rbind, lapply(jobs, function(job) {
      data.frame(
        project_title = as.character(job$project_title %||% ""),
        project_code = as.character(job$project_id %||% ""),
        pi_name = as.character(job$pi_name %||% ""),
        pi_email = if (nzchar(as.character(job$pi_email %||% ""))) as.character(job$pi_email) else "Not found",
        access_key = if (nzchar(as.character(job$access_key %||% ""))) as.character(job$access_key) else "Not set",
        send_status = as.character(job$status %||% "Ready"),
        ready = isTRUE(job$ready),
        stringsAsFactors = FALSE
      )
    }))
    list(
      display = display,
      jobs = jobs,
      action = action_type,
      generated_at = now()
    )
  }

  selected_pi_bulk_preview_jobs <- function(ready_only = TRUE) {
    state <- pi_bulk_email_preview_state()
    display <- state$display %||% data.frame()
    jobs <- state$jobs %||% list()
    if (!is.data.frame(display) || nrow(display) == 0 || length(jobs) == 0) return(list())
    selected_rows <- as.integer(input$dt_pi_bulk_email_preview_rows_selected %||% integer())
    if (length(selected_rows) == 0) {
      selected_rows <- seq_len(nrow(display))
    } else {
      selected_rows <- selected_rows[selected_rows >= 1 & selected_rows <= nrow(display)]
    }
    picked_jobs <- jobs[selected_rows]
    if (!isTRUE(ready_only)) return(picked_jobs)
    Filter(function(job) isTRUE(job$ready), picked_jobs)
  }

  update_pi_bulk_preview_status <- function(status_map) {
    state <- pi_bulk_email_preview_state()
    display <- state$display %||% data.frame()
    jobs <- state$jobs %||% list()
    if (!is.data.frame(display) || nrow(display) == 0 || length(jobs) == 0 || length(status_map) == 0) return(invisible(FALSE))
    for (i in seq_along(jobs)) {
      key <- as.character(jobs[[i]]$project_id %||% "")
      if (nzchar(key) && !is.null(status_map[[key]])) {
        display$send_status[[i]] <- as.character(status_map[[key]])
        jobs[[i]]$status <- as.character(status_map[[key]])
      }
    }
    state$display <- display
    state$jobs <- jobs
    pi_bulk_email_preview_state(state)
    invisible(TRUE)
  }

