  show_contact_modal <- function(contact_id = NULL) {
    pid <- communication_project_id()
    if (!nzchar(pid) || !can_access_project(pid)) {
      showNotification("Select an authorized project first.", type = "error")
      return(invisible(FALSE))
    }
    contact_row <- if (!is.null(contact_id) && nzchar(as.character(contact_id %||% ""))) get_project_contact_by_id(contact_id) else data.frame()
    rv$editing_contact_id <- if (nrow(contact_row) == 1) as.character(contact_row$id[[1]]) else NULL
    showModal(modalDialog(
      title = if (nrow(contact_row) == 1) "Edit Project Contact" else "Add Project Contact",
      textInput("contact_name_modal", "Name", value = if (nrow(contact_row) == 1) as.character(contact_row$contact_name[[1]] %||% "") else ""),
      textInput("contact_role_modal", "Role/Position", value = if (nrow(contact_row) == 1) as.character(contact_row$role_position[[1]] %||% "") else ""),
      textInput("contact_email_modal", "Email Address", value = if (nrow(contact_row) == 1) as.character(contact_row$email_address[[1]] %||% "") else ""),
      textInput("contact_phone_modal", "Phone Number", value = if (nrow(contact_row) == 1) as.character(contact_row$phone_number[[1]] %||% "") else ""),
      footer = tagList(modalButton("Cancel"), actionButton("confirm_save_contact", "Save Contact", class = "btn-primary")),
      easyClose = TRUE
    ))
  }

  observeEvent(input$btn_new_contact, {
    if (!require_authenticated()) return()
    if (!can_access_project(communication_project_id())) { showNotification("Access denied.", type = "error"); return() }
    show_contact_modal()
  }, ignoreInit = TRUE)

  observeEvent(input$btn_edit_contact, {
    if (!require_authenticated()) return()
    contacts <- project_contacts_scoped()
    sel <- input$dt_project_contacts_rows_selected
    if (length(sel) != 1 || nrow(contacts) < sel) { showNotification("Select a contact first.", type = "warning"); return() }
    show_contact_modal(contacts$id[[sel]])
  }, ignoreInit = TRUE)

  observeEvent(input$confirm_save_contact, {
    if (!require_authenticated()) return()
    pid <- communication_project_id()
    if (!can_access_project(pid)) { showNotification("Access denied.", type = "error"); return() }
    ok <- if (nzchar(as.character(rv$editing_contact_id %||% ""))) {
      update_project_contact(rv$editing_contact_id, list(
        contact_name = input$contact_name_modal,
        role_position = input$contact_role_modal,
        email_address = input$contact_email_modal,
        phone_number = input$contact_phone_modal
      ))
    } else {
      create_project_contact(
        project_id = pid,
        contact_name = input$contact_name_modal,
        role_position = input$contact_role_modal,
        email_address = input$contact_email_modal,
        phone_number = input$contact_phone_modal
      )
    }
    if (isTRUE(ok)) {
      removeModal()
      rv$editing_contact_id <- NULL
      reload_data()
      showNotification("Contact saved.", type = "message")
    } else {
      showNotification(attr(ok, "error") %||% "Failed to save contact.", type = "error")
    }
  }, ignoreInit = TRUE)

  observeEvent(input$btn_delete_contact, {
    if (!require_authenticated()) return()
    contacts <- project_contacts_scoped()
    sel <- input$dt_project_contacts_rows_selected
    if (length(sel) != 1 || nrow(contacts) < sel) { showNotification("Select a contact first.", type = "warning"); return() }
    row <- contacts[sel, , drop = FALSE]
    showModal(modalDialog(
      title = "Delete Contact",
      p(paste0("Delete contact ", as.character(row$contact_name[[1]]), "?")),
      footer = tagList(modalButton("Cancel"), actionButton("confirm_delete_contact", "Delete", class = "btn-danger")),
      easyClose = TRUE
    ))
    observeEvent(input$confirm_delete_contact, {
      result <- delete_project_contact(row$id[[1]])
      if (isTRUE(result)) {
        removeModal()
        reload_data()
        showNotification("Contact deleted.", type = "message")
      } else {
        showNotification(attr(result, "error") %||% "Failed to delete contact.", type = "error")
      }
    }, once = TRUE, ignoreInit = TRUE)
  }, ignoreInit = TRUE)

  observeEvent(input$btn_pi_bulk_clear, {
    if (!require_authenticated()) return()
    if (!identical(rv$user_role, "Administrator")) { showNotification("Administrator access is required.", type = "error"); return() }
    pi_bulk_email_preview_state(list(display = data.frame(), jobs = list(), action = "", generated_at = ""))
    try(updateCheckboxInput(session, "pi_bulk_all_projects", value = TRUE), silent = TRUE)
    try(shinyWidgets::updatePickerInput(session, "pi_bulk_project_ids", selected = character()), silent = TRUE)
    try(updateTextInput(session, "pi_bulk_custom_subject", value = ""), silent = TRUE)
    try(updateTextAreaInput(session, "pi_bulk_custom_message", value = ""), silent = TRUE)
    try(updateDateInput(session, "pi_bulk_schedule_date", value = as.Date(format(time_in_timezone(email_schedule_timezone()), "%Y-%m-%d"))), silent = TRUE)
    try(updateTextInput(session, "pi_bulk_schedule_time", value = default_email_schedule_time()), silent = TRUE)
  }, ignoreInit = TRUE)

  observeEvent(input$btn_pi_bulk_preview, {
    if (!require_authenticated()) return()
    if (!identical(rv$user_role, "Administrator")) { showNotification("Administrator access is required.", type = "error"); return() }
    action_type <- as.character(input$pi_bulk_action %||% "access_keys")
    preview_state <- tryCatch(
      build_pi_bulk_email_preview_state(
        action_type = action_type,
        custom_subject = input$pi_bulk_custom_subject %||% "",
        custom_message = input$pi_bulk_custom_message %||% ""
      ),
      error = function(e) e
    )
    if (inherits(preview_state, "error")) {
      showNotification(as.character(preview_state$message %||% "Failed to build the PI email preview."), type = "error", duration = 8)
      return()
    }
    pi_bulk_email_preview_state(preview_state)
    ready_n <- if (is.data.frame(preview_state$display) && "ready" %in% names(preview_state$display)) {
      sum(as.logical(preview_state$display$ready), na.rm = TRUE)
    } else {
      0L
    }
    showNotification(paste0("PI email preview generated. Ready rows: ", ready_n, " of ", nrow(preview_state$display %||% data.frame()), "."), type = "message")
  }, ignoreInit = TRUE)

  queue_pi_bulk_email_jobs <- function(schedule_mode = c("send_now", "schedule")) {
    schedule_mode <- match.arg(schedule_mode)
    if (!require_authenticated()) return(invisible(FALSE))
    if (!identical(rv$user_role, "Administrator")) {
      showNotification("Administrator access is required.", type = "error")
      return(invisible(FALSE))
    }
    delivery_ready <- email_delivery_status(get_email_delivery_settings(force = TRUE))
    if (!isTRUE(delivery_ready$ok)) {
      showNotification(paste0("Email delivery is not ready: ", delivery_ready$reason), type = "error", duration = 8)
      return(invisible(FALSE))
    }
    jobs <- selected_pi_bulk_preview_jobs(ready_only = TRUE)
    if (length(jobs) == 0) {
      showNotification("No ready PI email rows were selected.", type = "warning")
      return(invisible(FALSE))
    }
    scheduled_for <- if (identical(schedule_mode, "send_now")) {
      format(time_in_timezone(email_schedule_timezone()) - 1, "%Y-%m-%d %H:%M:%S")
    } else {
      compose_scheduled_datetime(input$pi_bulk_schedule_date, input$pi_bulk_schedule_time)
    }
    status_map <- list()
    queued_ids <- character()
    failure_messages <- character()
    for (job in jobs) {
      result <- save_scheduled_email_job(
        project_id = job$project_id,
        contact_ids = job$contact_id,
        subject = job$subject,
        message_body = job$message_body,
        scheduled_for = scheduled_for,
        status = "scheduled",
        created_by_role = rv$user_role %||% "Administrator",
        existing_file_keys = job$attachment_keys
      )
      if (identical(result, FALSE)) {
        err <- attr(result, "error") %||% "Failed to queue email."
        failure_messages <- c(failure_messages, paste0(job$project_id, ": ", err))
        status_map[[as.character(job$project_id)]] <- paste0("Failed: ", err)
      } else {
        queued_ids <- c(queued_ids, as.character(result))
        status_map[[as.character(job$project_id)]] <- if (identical(schedule_mode, "send_now")) "Queued for sending" else paste0("Scheduled for ", format_datetime_display(scheduled_for, tz = email_schedule_timezone()))
      }
    }
    update_pi_bulk_preview_status(status_map)
    reload_data()
    later::later(function() {
      if (can_launch_background_scheduler()) try(ensure_background_scheduler_service(if (identical(schedule_mode, "send_now")) "pi_bulk_send" else "pi_bulk_schedule"), silent = TRUE)
      try(start_scheduled_email_worker(if (identical(schedule_mode, "send_now")) "pi_bulk_send" else "pi_bulk_schedule"), silent = TRUE)
    }, delay = 0)
    if (length(queued_ids) > 0) {
      try(log_audit(
        module = "Communications",
        action = if (identical(schedule_mode, "send_now")) "email_to_pis_now" else "email_to_pis_scheduled",
        target_table = "scheduled_emails",
        target_id = paste(queued_ids, collapse = ","),
        detail = list(
          action_type = as.character(pi_bulk_email_preview_state()$action %||% input$pi_bulk_action %||% ""),
          queued_count = length(queued_ids),
          selected_projects = vapply(jobs, function(job) as.character(job$project_id %||% ""), character(1))
        ),
        trigger_sync = FALSE
      ), silent = TRUE)
    }
    if (length(failure_messages) > 0 && length(queued_ids) == 0) {
      showNotification(paste0("PI emails could not be queued: ", paste(failure_messages, collapse = " | ")), type = "error", duration = 10)
      return(invisible(FALSE))
    }
    if (length(failure_messages) > 0) {
      showNotification(
        paste0(
          if (identical(schedule_mode, "send_now")) "Queued " else "Scheduled ",
          length(queued_ids),
          " PI emails. Some rows failed: ",
          paste(failure_messages, collapse = " | ")
        ),
        type = "warning",
        duration = 10
      )
    } else {
      showNotification(
        paste0(if (identical(schedule_mode, "send_now")) "Queued " else "Scheduled ", length(queued_ids), " PI emails successfully."),
        type = "message"
      )
    }
    invisible(length(queued_ids) > 0)
  }

