  observeEvent(input$btn_test_email_settings, {
    if (!require_authenticated()) return()
    if (!identical(rv$user_role, "Administrator")) { showNotification("Administrator access is required.", type = "error"); return() }
    if (isTRUE(email_test_inflight())) {
      showNotification("A test email is already being sent by the server. Please wait for the current attempt to finish.", type = "warning", duration = 6)
      return()
    }
    status <- email_delivery_status(get_email_delivery_settings(force = TRUE))
    if (!isTRUE(status$ok)) {
      showNotification(paste0("Email delivery is not ready: ", status$reason), type = "error", duration = 8)
      return()
    }
    recipient <- trimws(as.character(input$setting_email_test_recipient %||% ""))
    recipient <- if (nzchar(recipient)) recipient else status$settings$from_address
    recipient <- normalize_email_address(recipient, field_name = "Test recipient")
    tryCatch({
      subject_text <- "Budget Tracker Scheduled Email Test"
      body_text <- paste0(
        "This is a test email sent on ",
        format(time_in_timezone(status$settings$schedule_timezone %||% default_email_schedule_timezone()), "%Y-%m-%d %H:%M:%S %Z"),
        "."
      )
      job_id <- create_email_test_job(recipient = recipient, subject = subject_text, message_body = body_text)
      launched <- isTRUE(launch_background_email_test_job(job_id))
      if (!launched) {
        send_single_scheduled_email_message(
          settings = status$settings,
          to_email = recipient,
          to_name = "Test Recipient",
          subject = subject_text,
          message_body = body_text
        )
        append_scheduled_email_log("INFO", "SMTP test email sent.", detail = list(recipient = recipient, mode = "inline_fallback", job_id = job_id))
        write_email_test_job_state(job_id, modifyList(as.list(read_email_test_job_state(job_id)), list(
          status = "sent",
          message = "Test email sent successfully.",
          completed_at = now()
        )))
        showNotification("Test email sent successfully.", type = "message")
        return()
      }

      email_test_inflight(TRUE)
      session_token <- session$token
      poll_test_email_job <- NULL
      poll_test_email_job <- function() {
        if (!identical(session$token, session_token)) {
          email_test_inflight(FALSE)
          return(invisible(FALSE))
        }
        state <- read_email_test_job_state(job_id)
        job_status <- as.character(state$status %||% "")
        created_at <- suppressWarnings(as.POSIXct(as.character(state$created_at %||% ""), tz = status$settings$schedule_timezone %||% default_email_schedule_timezone()))
        if (job_status %in% c("", "queued", "sending")) {
          if (!is.na(created_at)) {
            age_sec <- as.numeric(difftime(Sys.time(), created_at, units = "secs"))
            if (!is.na(age_sec) && age_sec > max(45, as.numeric(status$settings$smtp_total_timeout_sec %||% 60L) + 20)) {
              write_email_test_job_state(job_id, modifyList(as.list(state), list(
                status = "failed",
                message = "The background test email worker timed out before reporting completion.",
                completed_at = now()
              )))
              job_status <- "failed"
              state <- read_email_test_job_state(job_id)
            }
          }
        }
        if (!(job_status %in% c("sent", "failed"))) {
          later::later(poll_test_email_job, delay = 0.7)
          return(invisible(FALSE))
        }
        email_test_inflight(FALSE)
        if (identical(job_status, "sent")) {
          try(showNotification("Test email sent successfully.", type = "message"), silent = TRUE)
        } else {
          try(showNotification(paste0("Test email failed: ", as.character(state$message %||% "Unknown SMTP error")), type = "error", duration = 8), silent = TRUE)
        }
        invisible(TRUE)
      }
      later::later(poll_test_email_job, delay = 0.7)
      showNotification("Test email queued. The hosted server is sending it in the background.", type = "message", duration = 6)
    }, error = function(e) {
      email_test_inflight(FALSE)
      append_scheduled_email_log("ERROR", paste0("SMTP test email failed: ", e$message), detail = list(recipient = recipient))
      showNotification(paste0("Test email failed: ", e$message), type = "error", duration = 8)
    })
  }, ignoreInit = TRUE)

