  output$vb_total_projects <- renderValueBox({ req(compute_totals()); valueBox(value = compute_totals()$project_name, subtitle = "Project", icon = icon("folder-open"), color = "aqua") })
  output$vb_total_budget <- renderValueBox({ req(compute_totals()); valueBox(value = tags$span(class = "dashboard-money-value", format_currency(compute_totals()$total_budget)), subtitle = "Project Budget", icon = icon("coins"), color = "green") })
  output$vb_total_spent <- renderValueBox({ req(compute_totals()); valueBox(value = tags$span(class = "dashboard-money-value", format_currency(compute_totals()$total_spent)), subtitle = "Project Spent", icon = icon("credit-card"), color = "red") })
  output$vb_remaining <- renderValueBox({ req(compute_totals()); valueBox(value = tags$span(class = "dashboard-money-value", format_currency(compute_totals()$remaining)), subtitle = "Remaining Balance", icon = icon("wallet"), color = ifelse(compute_totals()$remaining >= 0, "blue", "red")) })
  # Project cards (respect role-based visibility)
  output$project_cards <- renderUI({
    req(rv$data)
    pr_all <- rv$data$projects %>% filter(is_trashed == 0)
    pr <- pr_all %>% filter(id == dashboard_project_id())
    if (nrow(pr) == 0) return(tags$p("No projects yet."))
    cards <- lapply(seq_len(nrow(pr)), function(i) {
      p <- pr[i, ]
      ph <- project_health(p$id, expense_scope = dashboard_expense_scope())
      health_color <- switch(ph$health_status, ok = "#2b7a2b", warning = "#d9822b", over = "#c62828", "#666666")
      project_status <- normalize_project_status(p$status)
      project_status_color <- switch(project_status, "Not Started" = "#6b7280", "In Progress" = "#1d4ed8", "Paused" = "#d9822b", "Ended" = "#6b7280", "#1d4ed8")
      viewId <- paste0("view_proj__", p$id)
      editId <- paste0("edit_proj__", p$id)
      trashId <- paste0("trash_proj__", p$id)
      box(width = 12, status = "info", solidHeader = FALSE,
          div(class = "project-card",
              div(class = "title", paste0(p$name, " - ", p$id)),
              div(tags$span(class = "small-muted", paste0("Budget: ", format_currency(p$budget_total), " | Spent: ", format_currency(ph$spent), " | Usage: ", ph$pct, "% | Team Members: ", count_team_members(p$team_members)))),
              br(),
              div(strong("Principle Investigator: "), ifelse(nzchar(trimws(as.character(p$principal_investigator %||% ""))), as.character(p$principal_investigator), "Not provided")),
              br(),
              div(strong("Team Members: "), format_team_members_inline(p$team_members %||% "", empty = "Not provided")),
              br(),
              div(strong("Last update: "), ifelse(is.na(p$updated_at) || p$updated_at == "", "-", p$updated_at)),
              br(),
              fluidRow(
                column(4, actionButton(inputId = viewId, label = "View", class = "btn-block btn-info")),
                column(4, actionButton(inputId = editId, label = "Edit", class = "btn-block btn-primary")),
                column(4, actionButton(inputId = trashId, label = "Delete", class = "btn-block btn-danger"))
              ),
              tags$div(style = paste0("margin-top:8px; color:", project_status_color, "; font-weight:700;"), paste0("Project Status: ", project_status)),
              tags$div(style = paste0("margin-top:4px; color:", health_color, "; font-weight:700;"), paste0("Budget Health: ", format_budget_health_label(ph$health_status)))
          )
      )
    })
    do.call(tagList, cards)
  })
  
  # Dynamic observers for card buttons
  observe({
    if (is.null(rv$data)) return()
    pr_all <- rv$data$projects %>% filter(is_trashed == 0)
    pr <- pr_all %>% filter(id == dashboard_project_id())
    for (i in seq_len(nrow(pr))) {
      pid <- pr$id[i]
      viewId <- paste0("view_proj__", pid)
      editId <- paste0("edit_proj__", pid)
      trashId <- paste0("trash_proj__", pid)
      
      if (!(viewId %in% rv$proj_obs_created)) {
        local({
          mypid <- pid; myView <- viewId
          observeEvent(input[[myView]], {
            updateTabItems(session, "main_nav", "projects")
            pr_df <- rv$data$projects %>% filter(is_trashed == 0)
            idx <- which(pr_df$id == mypid)
            if (length(idx) == 1) {
              proxy <- dataTableProxy("dt_projects")
              selectRows(proxy, idx)
            }
            show_project_detail(mypid)
          }, ignoreInit = TRUE)
        })
        rv$proj_obs_created <- c(rv$proj_obs_created, viewId)
      }
      
      if (!(editId %in% rv$proj_obs_created)) {
        local({
          mypid <- pid; myEdit <- editId
          observeEvent(input[[myEdit]], { show_edit_project_modal(mypid) }, ignoreInit = TRUE)
        })
        rv$proj_obs_created <- c(rv$proj_obs_created, editId)
      }
      
      if (!(trashId %in% rv$proj_obs_created)) {
        local({
          mypid <- pid; myTrash <- trashId
          observeEvent(input[[myTrash]], {
            showModal(modalDialog(title = "Confirm Delete", paste0("Move project '", rv$data$projects %>% filter(id == mypid) %>% pull(name), "' to Recycle Bin? This will soft-delete associated expenses."), footer = tagList(modalButton("Cancel"), actionButton(paste0("confirm_trash_proj__", mypid), "Move to Recycle Bin", class = "btn-danger"))))
            observeEvent(input[[paste0("confirm_trash_proj__", mypid)]], {
              soft_delete_project(mypid); reload_data(); removeModal(); showNotification("Project moved to Recycle Bin", type = "warning")
            }, once = TRUE, ignoreInit = TRUE)
          }, ignoreInit = TRUE)
        })
        rv$proj_obs_created <- c(rv$proj_obs_created, trashId)
      }
    }
  })
  
  # Project detail modal
  show_project_detail <- function(pid) {
    # Enforce access control
    if (!can_access_project(pid)) {
      showNotification("Access denied to selected project.", type = "error")
      return()
    }
    data <- rv$data
    p <- data$projects %>% filter(id == pid)
    if (nrow(p) == 0) { showNotification("Project not found", type = "error"); return() }
    detail_scope <- if (identical(isolate(input$main_nav %||% ""), "dashboard")) dashboard_expense_scope() else default_viewer_expense_scope()
    ex <- expense_rows_for_scope(pid, expense_scope = detail_scope, include_trashed = FALSE)
    if (nrow(ex) > 0) ex <- ex %>% mutate(category_main = ifelse(is.na(category_main) | category_main == "", (ifelse(is.na(category) | category == "", "Uncategorized", sub(" -.*$", "", category))), category_main), category_sub = ifelse(is.na(category_sub) | category_sub == "", (ifelse(grepl(" - ", category), sub("^.* - ", "", category), "")), category_sub))
    attachments <- load_project_attachments_for_expense_ids(ex$id)
    audit_rel <- load_audit_log_data(pid) %>% filter(target_id == pid | target_id %in% ex$id | grepl(pid, detail, fixed = TRUE))
    if (!identical(rv$user_role, "Administrator") && nrow(audit_rel) > 0) {
      visible_expense_ids <- as.character(ex$id %||% character())
      audit_rel <- audit_rel %>%
        filter(!(as.character(target_table %||% "") == "expenses" & !(as.character(target_id %||% "") %in% visible_expense_ids)))
    }
    ph <- project_health(pid, expense_scope = detail_scope)
    
    showModal(modalDialog(
      title = paste0("Project Detail - ", p$name),
      size = "l",
      easyClose = TRUE,
      footer = modalButton("Close"),
      tagList(
        tags$div(class = "section-sep"),
        fluidRow(
          column(6, tags$div(h4("Financial Summary"), tags$p(strong("View: "), expense_scope_view_label(detail_scope)), tags$p(strong("Budget: "), format_currency(p$budget_total)), tags$p(strong("Total Spent: "), format_currency(ph$spent)), tags$p(strong("Remaining: "), format_currency(ph$budget - ph$spent)))),
          column(6, tags$div(h4("Project Information"), tags$p(strong("Project ID: "), p$id), if (identical(rv$user_role, "Administrator")) tags$p(strong("Access Key: "), normalize_project_access_key(p$access_key %||% "")), tags$p(strong("Project Status: "), normalize_project_status(p$status)), tags$p(strong("Principle Investigator: "), ifelse(nzchar(trimws(as.character(p$principal_investigator %||% ""))), p$principal_investigator, "Not provided")), tags$p(strong("Team Members: "), format_team_members_inline(p$team_members %||% "", empty = "Not provided"))))
        ),
        tags$hr(),
        tabsetPanel(
          tabPanel("Overview",
                   fluidRow(column(12, tags$h4("Description"), tags$p(ifelse(is.null(p$description) || p$description == "", "-", p$description))))),
          tabPanel("Expenses", DT::dataTableOutput(paste0("proj_expenses_dt_", pid))),
          tabPanel("Attachments", DT::dataTableOutput(paste0("proj_attachments_dt_", pid))),
          tabPanel("Audit", DT::dataTableOutput(paste0("proj_audit_dt_", pid)))
        )
      )
    ))
    
    # Tables
    output[[paste0("proj_expenses_dt_", pid)]] <- DT::renderDataTable({
      if (nrow(ex) == 0) return(DT::datatable(data.frame(Message = "No expenses for this project"), options = list(dom = 't')))
      df <- ex %>% transmute(ID = id, Description = description, Amount = amount, Category = category_main, Subcategory = category_sub, Date = date, Receipt = ifelse(receipt_path == "", "", "Has Receipt"), Created = created_at)
      DT::datatable(df, options = list(pageLength = 10))
    })
    
    output[[paste0("proj_attachments_dt_", pid)]] <- DT::renderDataTable({
      if (nrow(attachments) == 0) return(DT::datatable(data.frame(Message = "No attachments"), options = list(dom = 't')))
      df <- attachments %>% transmute(ID = id, Expense = expense_id, Filename = filename, Path = filepath, Size = size, Created = created_at)
      DT::datatable(df, options = list(pageLength = 10))
    })
    
    output[[paste0("proj_audit_dt_", pid)]] <- DT::renderDataTable({
      if (nrow(audit_rel) == 0) return(DT::datatable(data.frame(Message = "No audit entries"), options = list(dom = 't')))
      df <- audit_rel %>% transmute(Time = timestamp, User = user, Module = module, Action = action, Detail = detail)
      DT::datatable(df, options = list(pageLength = 10))
    })
  }
  
  # Edit modal (project)
  show_edit_project_modal <- function(pid) {
    # Enforce access
    if (!can_access_project(pid)) {
      showNotification("Access denied to edit this project.", type = "error"); return(NULL)
    }
    p <- rv$data$projects %>% filter(id == pid)
    if (nrow(p) == 0) { showNotification("Project not found", type = "error"); return(NULL) }
    showModal(modalDialog(
      title = paste0("Edit Project: ", p$name),
      textInput("edit_name_modal", "Name", value = p$name),
      textInput("edit_pi_modal", "Principle Investigator", value = p$principal_investigator %||% ""),
      if (identical(rv$user_role, "Administrator")) textInput("edit_access_key_modal", "Access Key", value = normalize_project_access_key(p$access_key %||% ""), placeholder = "Three unique letters"),
      selectInput("edit_status_modal", "Project Status", choices = project_status_choices, selected = normalize_project_status(p$status %||% "In Progress")),
      textAreaInput("edit_team_modal", "Add team members", value = p$team_members %||% "", placeholder = "Enter one name per line or separate names with commas"),
      textAreaInput("edit_desc_modal", "Description", value = p$description),
      numericInput("edit_budget_modal", "Budget", value = as.numeric(p$budget_total)),
      dateInput("edit_start_modal", "Start Date", value = ifelse(is.na(p$start_date) || p$start_date == "", NA, as.Date(p$start_date))),
      dateInput("edit_end_modal", "End Date", value = ifelse(is.na(p$end_date) || p$end_date == "", NA, as.Date(p$end_date))),
      checkboxInput("edit_locked_modal", "Lock Budget", value = as.logical(p$budget_locked)),
      footer = tagList(modalButton("Cancel"), actionButton(paste0("confirm_edit_project_modal__", pid), "Save", class = "btn-primary"))
    ))
    observeEvent(input[[paste0("confirm_edit_project_modal__", pid)]], {
      # Enforce access for scientist (cannot change project id here; only allowed_project scientist can edit their project)
      if (identical(rv$user_role, "Scientist") && !isTRUE(rv$allowed_project == pid)) {
        showNotification("Scientist cannot edit this project.", type = "error"); removeModal(); return()
      }
      if (!nzchar(trimws(as.character(input$edit_pi_modal %||% "")))) {
        showNotification("Principle Investigator is required.", type = "error")
        return()
      }
      update_fields <- list(name = input$edit_name_modal, principal_investigator = input$edit_pi_modal, status = input$edit_status_modal, team_members = input$edit_team_modal, description = input$edit_desc_modal, budget_total = as.numeric(input$edit_budget_modal), start_date = as.character(input$edit_start_modal), end_date = as.character(input$edit_end_modal), budget_locked = as.integer(input$edit_locked_modal))
      if (identical(rv$user_role, "Administrator")) update_fields$access_key <- input$edit_access_key_modal
      ok <- update_project(pid, update_fields)
      if (isTRUE(ok)) {
        reload_data()
        removeModal()
        showNotification("Project updated", type = "message")
      } else {
        showNotification(paste0("Failed to update project", if (!is.null(attr(ok, "error")) && nzchar(as.character(attr(ok, "error")))) paste0(": ", attr(ok, "error")) else ""), type = "error")
      }
    }, once = TRUE, ignoreInit = TRUE)
  }
  
  # Projects table outputs
  output$dt_projects <- renderDT({
    req(rv$data)
    pr_all <- rv$data$projects
    pr <- pr_all %>% filter(is_trashed == 0)
    # Scientist sees only allowed project
    if (identical(rv$user_role, "Scientist") && !is.null(rv$allowed_project)) pr <- pr %>% filter(id == rv$allowed_project)
    df <- pr %>% transmute(`Project ID` = id, `Project Name` = name, `Principle Investigator` = ifelse(nzchar(trimws(as.character(principal_investigator %||% ""))), principal_investigator, "Not set"), `Team Members` = ifelse(vapply(team_members, count_team_members, integer(1)) == 0, "Not set", vapply(team_members, format_team_members_inline, character(1), empty = "Not set")), `Budget` = budget_total, `Start Date` = start_date, `End Date` = end_date, `Status` = vapply(status, normalize_project_status, character(1)))
    DT::datatable(
      df,
      selection = "single",
      options = list(
        pageLength = 10,
        autoWidth = TRUE,
        scrollX = TRUE,
        columnDefs = list(
          list(width = "110px", targets = c(0, 5, 6, 7)),
          list(width = "220px", targets = c(1, 2)),
          list(width = "260px", targets = 3)
        )
      )
    )
  }, server = TRUE)
  output$dt_recycle_projects <- renderDT({
    req(rv$data)
    pr_all <- rv$data$projects
    pr <- pr_all %>% filter(is_trashed == 1)
    # Scientist should not see recycle bin entries
    if (identical(rv$user_role, "Scientist")) pr <- pr %>% filter(FALSE)
    df <- pr %>% transmute(`Project ID` = id, `Project Name` = name, `Deleted At` = updated_at)
    DT::datatable(df, selection = "single", options = list(pageLength = 5, dom = 't'))
  }, server = TRUE)
  
  # New project wizard (button)
  observeEvent(input$btn_new_project, {
    if (!require_authenticated()) return()
    # Prevent scientist creating projects if they already have one? Requirement allowed scientist to create new project at login only.
    if (identical(rv$user_role, "Scientist")) {
      showNotification("Scientists must create projects at login. Use Administrator to create additional projects.", type = "error")
      return()
    }
    showModal(modalDialog(
      title = "New Project - Wizard",
      size = "l",
      footer = NULL,
      easyClose = TRUE,
      fluidPage(
        tabsetPanel(id = "proj_wizard",
                    tabPanel("Basic Info", textInput("w_name", "Name"), textInput("w_pi", "Principle Investigator"), selectInput("w_status", "Project Status", choices = project_status_choices, selected = "In Progress"), textAreaInput("w_team_members", "Add team members", "", placeholder = "Enter one name per line or separate names with commas"), textInput("w_id", "ID (optional; will be generated if blank)"), textAreaInput("w_desc", "Description", "")),
                    tabPanel("Budget", numericInput("w_budget", "Total allocation", value = 0, min = 0, step = 0.01)),
                    tabPanel("Timeline", dateInput("w_start", "Start Date", value = Sys.Date()), dateInput("w_end", "End Date", value = Sys.Date() + 30)),
                    tabPanel("Categories", textInput("w_cats", "Default categories (comma-separated)", value = "General,Travel,Supplies")),
                    tabPanel("Confirm", verbatimTextOutput("proj_wizard_summary"), actionButton("proj_wizard_create", "Create Project", class = "btn-success"))
        )
      )
    ))
  })
  
  output$proj_wizard_summary <- renderPrint({
    cat("Name:", input$w_name, "\n")
    cat("Principle Investigator:", input$w_pi, "\n")
    cat("Project Status:", normalize_project_status(input$w_status %||% "In Progress"), "\n")
    cat("Team Members:", format_team_members_inline(input$w_team_members %||% "", empty = "Not set"), "\n")
    cat("ID:", ifelse(nzchar(input$w_id), input$w_id, "(will be generated)"), "\n")
    cat("Access Key:", "(generated automatically)", "\n")
    cat("Budget:", input$w_budget, "\n")
    cat("Start:", as.character(input$w_start), "\n")
    cat("End:", as.character(input$w_end), "\n")
    cat("Categories:", input$w_cats, "\n")
  })
  
  observeEvent(input$proj_wizard_create, {
    if (!require_authenticated()) return()
    id <- ifelse(nzchar(input$w_id), input$w_id, uuid("proj"))
    if (!nzchar(trimws(input$w_name %||% ""))) { showNotification("Project name is required.", type = "error"); return() }
    if (!nzchar(trimws(input$w_pi %||% ""))) { showNotification("Principle Investigator is required.", type = "error"); return() }
    # Ensure uniqueness
    con <- connect_db(); on.exit(dbDisconnect(con))
    exists <- dbGetQuery(con, "SELECT COUNT(*) as n FROM projects WHERE id = ?;", params = list(id))$n
    if (exists > 0) { showNotification("Project ID already exists. Choose a different ID.", type = "error"); return() }
    create_project(id = id, name = input$w_name, description = input$w_desc, budget_total = as.numeric(input$w_budget), start_date = as.character(input$w_start), end_date = as.character(input$w_end), status = input$w_status, principal_investigator = input$w_pi, team_members = input$w_team_members)
    access_key <- get_project_access_key(id)
    removeModal()
    reload_data()
    showNotification(paste0("Project created and workbook generated. Access Key: ", access_key), type = "message", duration = 8)
  })
  
  # Table-level actions for edit/delete/view
  observeEvent(input$btn_edit_project, {
    if (!require_authenticated()) return()
    sel <- input$dt_projects_rows_selected
    if (length(sel) != 1) { showNotification("Select a project to edit", type = "warning"); return() }
    pr <- rv$data$projects %>% filter(is_trashed == 0)
    # restrict list for scientist
    if (identical(rv$user_role, "Scientist") && !is.null(rv$allowed_project)) pr <- pr %>% filter(id == rv$allowed_project)
    row <- pr[sel, ]
    show_edit_project_modal(row$id)
  })
  observeEvent(input$btn_delete_project, {
    if (!require_authenticated()) return()
    # protect: only admin can delete
    if (identical(rv$user_role, "Scientist")) { showNotification("Scientist cannot delete projects.", type = "error"); return() }
    sel <- input$dt_projects_rows_selected
    if (length(sel) != 1) { showNotification("Select a project to delete", type = "warning"); return() }
    pr <- rv$data$projects %>% filter(is_trashed == 0)
    row <- pr[sel, ]
    showModal(modalDialog(title = "Confirm Delete", paste0("Move project '", row$name, "' to Recycle Bin? This will soft-delete associated expenses."), footer = tagList(modalButton("Cancel"), actionButton("confirm_delete_project_modal_table", "Move to Recycle Bin", class = "btn-danger"))))
    observeEvent(input$confirm_delete_project_modal_table, { soft_delete_project(row$id); reload_data(); removeModal(); showNotification("Project moved to Recycle Bin", type = "warning") }, once = TRUE)
  })
  observeEvent(input$btn_view_project, {
    if (!require_authenticated()) return()
    sel <- input$dt_projects_rows_selected
    if (length(sel) != 1) { showNotification("Select a project to view", type = "warning"); return() }
    pr_all <- rv$data$projects %>% filter(is_trashed == 0)
    if (identical(rv$user_role, "Scientist") && !is.null(rv$allowed_project)) pr_all <- pr_all %>% filter(id == rv$allowed_project)
    row <- pr_all[sel, ]
    show_project_detail(row$id)
  })
  
  observeEvent(input$btn_restore_project, {
    if (!require_authenticated()) return()
    # only admin
    if (identical(rv$user_role, "Scientist")) { showNotification("Scientist cannot restore projects.", type = "error"); return() }
    sel <- input$dt_recycle_projects_rows_selected
    if (length(sel) != 1) { showNotification("Select a trashed project to restore", type = "warning"); return() }
    pr <- rv$data$projects %>% filter(is_trashed == 1); row <- pr[sel, ]; restore_project(row$id); reload_data(); showNotification("Project restored", type = "message")
  })
  
  observeEvent(input$btn_purge_projects, {
    if (!require_authenticated()) return()
    # only admin
    if (identical(rv$user_role, "Scientist")) { showNotification("Scientist cannot purge Recycle Bin.", type = "error"); return() }
    showModal(modalDialog(title = "Empty Recycle Bin", "This will permanently delete all trashed projects and their expenses. This action cannot be undone.", footer = tagList(modalButton("Cancel"), actionButton("confirm_purge", "Purge Now", class = "btn-danger"))))
    observeEvent(input$confirm_purge, {
      con <- connect_db(); on.exit(dbDisconnect(con))
      trashed_expenses <- dbGetQuery(con, "SELECT id, receipt_path FROM expenses WHERE is_trashed = 1;")
      for (i in seq_len(nrow(trashed_expenses))) {
        pth <- trashed_expenses$receipt_path[i]
        if (nzchar(pth) && file_exists(pth)) file_move(pth, file.path(trash_dir, path_file(pth)))
      }
      dbExecute(con, "DELETE FROM attachments WHERE expense_id IN (SELECT id FROM expenses WHERE is_trashed = 1);")
      dbExecute(con, "DELETE FROM scheduled_email_recipients WHERE project_id IN (SELECT id FROM projects WHERE is_trashed = 1);")
      dbExecute(con, "DELETE FROM scheduled_email_attachments WHERE project_id IN (SELECT id FROM projects WHERE is_trashed = 1);")
      dbExecute(con, "DELETE FROM scheduled_emails WHERE project_id IN (SELECT id FROM projects WHERE is_trashed = 1);")
      dbExecute(con, "DELETE FROM project_contacts WHERE project_id IN (SELECT id FROM projects WHERE is_trashed = 1);")
      dbExecute(con, "DELETE FROM expenses WHERE is_trashed = 1;")
      dbExecute(con, "DELETE FROM projects WHERE is_trashed = 1;")
      log_audit(module = "Projects", action = "purge_recycle_bin", target_table = "projects", target_id = NA, detail = list())
      reload_data(); removeModal(); showNotification("Recycle Bin emptied", type = "message")
    }, once = TRUE)
  })
  
  # Expenses UI & actions: require selecting a project first (and enforce access)
  output$expense_view_controls_ui <- renderUI({
    if (!identical(rv$user_role, "Administrator")) return(NULL)
    selectInput(
      "exp_financial_view",
      "Financial view",
      choices = c(
        "Admin Expense View" = "administrator",
        "User/Scientist Expense View" = "scientist",
        "Compare Admin and User/Scientist" = "compare"
      ),
      selected = expense_module_view_mode()
    )
  })

  output$expense_entry_scope_hint_ui <- renderUI({
    if (identical(rv$user_role, "Administrator")) {
      mode <- expense_module_view_mode()
      if (identical(mode, "administrator")) {
        return(tags$div(class = "settings-hint", "New expenses entered by Admin are stored only in the Admin financial view for this project."))
      }
      if (identical(mode, "scientist")) {
        return(tags$div(class = "settings-hint", "You are viewing User/Scientist financial data. New Admin expenses are disabled until you switch back to Admin Expense View."))
      }
      return(tags$div(class = "settings-hint", "Compare mode is view-only. Switch to Admin Expense View to add new Admin expenses."))
    }
    tags$div(class = "settings-hint", "Expenses entered here are stored only in the User/Scientist financial view for this project.")
  })

  render_budget_bar_for_scope <- function(pid, expense_scope, title = NULL) {
    ph <- project_health(pid, expense_scope = expense_scope)
    pct <- ph$pct
    color <- ifelse(ph$health_status == "over", "danger", ifelse(ph$health_status == "warning", "warning", "success"))
    tagList(
      if (nzchar(as.character(title %||% ""))) tags$div(style = "font-weight:700; margin:0 0 4px 0;", as.character(title)),
      tags$div(
        style = "margin-bottom:6px;",
        paste0(
          expense_scope_view_label(expense_scope), ": Budget ", format_currency(ph$budget),
          " | Spent ", format_currency(ph$spent),
          " | Remaining ", format_currency(ph$budget - ph$spent)
        )
      ),
      progressBar(
        id = paste0("proj_budget_bar_", sanitize_filename(pid), "_", sanitize_filename(expense_scope)),
        value = min(100, round(pct)),
        total = 100,
        display_pct = TRUE,
        status = color
      )
    )
  }

