  observeEvent(input$exp_save, {
    if (!require_authenticated()) return()
    pid <- input$exp_project_select
    if (is.null(pid) || !nzchar(pid)) { set_expense_message("Please select a project before adding an expense."); showNotification("Select a project first", type = "warning"); return() }
    if (!can_access_project(pid)) { showNotification("Access denied to add expense for selected project.", type = "error"); return() }
    if (!isTRUE(can_create_admin_expense_in_current_view())) {
      set_expense_message("Switch to Admin Expense View before adding a new Admin expense.")
      showNotification("Switch to Admin Expense View before adding a new Admin expense.", type = "warning")
      return()
    }
    pr_check <- rv$data$projects %>% filter(id == pid & is_trashed == 0)
    if (nrow(pr_check) != 1) { set_expense_message("Selected project is invalid or deleted."); showNotification("Invalid project selected", type = "error"); return() }
    amt <- as.numeric(input$exp_amount)
    if (is.na(amt) || amt <= 0) { set_expense_message("Enter a valid amount > 0"); return() }
    if (pr_check$budget_locked == 1) { set_expense_message("Project budget is locked. Cannot add expenses."); showNotification("Budget locked", type = "error"); return() }
    
    # Determine category main/sub (respect "Other" custom inputs)
    main_cat <- input$exp_main_category %||% ""
    if (identical(main_cat, "Other")) main_cat <- input$exp_custom_main %||% ""
    sub_cat <- input$exp_sub_category %||% ""
    if (identical(sub_cat, "(none)")) sub_cat <- ""
    if (identical(sub_cat, "Other")) sub_cat <- input$exp_custom_sub %||% ""
    
    ph <- project_health(pid, expense_scope = expense_module_single_scope())
    if (ph$spent + amt > ph$budget) {
      showModal(modalDialog(title = "Budget Exceeded", paste0("This expense will exceed the project's budget (Current spent: ", format_currency(ph$spent), ", Budget: ", format_currency(ph$budget), "). Do you want to continue?"), footer = tagList(modalButton("Cancel"), actionButton("confirm_force_save", "Add Expense Anyway", class = "btn-danger"))))
      observeEvent(input$confirm_force_save, {
        if (!isTRUE(can_create_admin_expense_in_current_view())) {
          removeModal()
          set_expense_message("Switch to Admin Expense View before adding a new Admin expense.")
          showNotification("Switch to Admin Expense View before adding a new Admin expense.", type = "warning")
          return()
        }
        id <- uuid("exp"); receipt <- NULL; rname <- NULL
        if (!is.null(input$exp_receipt) && !is.null(input$exp_receipt$datapath)) { receipt <- input$exp_receipt$datapath; rname <- input$exp_receipt$name }
        # include pending breakdowns
        bkd <- rv$pending_breakdowns_create %||% list()
        ok <- create_expense(id = id, project_id = pid, description = input$exp_desc, amount = amt, category_main = main_cat, category_sub = sub_cat, date = as.character(input$exp_date), receipt_tmpfile = receipt, receipt_name = rname, breakdowns = bkd, created_by_role = rv$user_role %||% "Administrator")
        if (isTRUE(ok)) {
          rv$pending_breakdowns_create <- list()
          reload_data(); removeModal(); set_expense_message("Expense added (budget exceeded)."); showNotification("Expense added", type = "message")
        } else { removeModal(); showNotification("Failed to add expense", type = "error") }
      }, once = TRUE)
      return()
    }
    id <- uuid("exp"); receipt <- NULL; rname <- NULL
    if (!is.null(input$exp_receipt) && !is.null(input$exp_receipt$datapath)) { receipt <- input$exp_receipt$datapath; rname <- input$exp_receipt$name }
    bkd <- rv$pending_breakdowns_create %||% list()
    ok <- create_expense(id = id, project_id = pid, description = input$exp_desc, amount = amt, category_main = main_cat, category_sub = sub_cat, date = as.character(input$exp_date), receipt_tmpfile = receipt, receipt_name = rname, breakdowns = bkd, created_by_role = rv$user_role %||% "Administrator")
    if (isTRUE(ok)) {
      rv$pending_breakdowns_create <- list()
      reload_data(); set_expense_message("Expense saved.")
      # reset category selectors and custom inputs (do not change global categories table)
      mains <- get_main_categories()
      default_main <- ifelse(length(mains) > 0, mains[[1]], "Other")
      updateSelectInput(session, "exp_main_category", selected = default_main)
      updateSelectInput(session, "exp_sub_category", selected = "(none)")
      updateTextInput(session, "exp_custom_main", value = "")
      updateTextInput(session, "exp_custom_sub", value = "")
      updateTextInput(session, "exp_desc", value = "")
      updateNumericInput(session, "exp_amount", value = 0)
      updateDateInput(session, "exp_date", value = Sys.Date())
    } else {
      set_expense_message("Failed to save expense. See server logs."); showNotification("Failed to save expense", type = "error")
    }
  })
  
  observeEvent(input$exp_duplicate, {
    if (!require_authenticated()) return()
    if (is.null(rv$data)) return()
    if (!isTRUE(can_create_admin_expense_in_current_view())) {
      showNotification("Switch to Admin Expense View before duplicating an expense.", type = "warning")
      return()
    }
    target_project_id <- isolate(as.character(input$exp_project_select %||% selected_project_context()))
    if (!nzchar(target_project_id)) { showNotification("Select a project first.", type = "warning"); return() }
    ex <- expense_rows_for_scope(target_project_id, expense_scope = expense_module_single_scope(), include_trashed = FALSE) %>%
      slice_head(n = 1)
    if (nrow(ex) == 0) { showNotification("No expense to duplicate", type = "warning"); return() }
    if (is.null(ex$project_id) || !nzchar(ex$project_id)) { showNotification("Last expense is unassigned and cannot be duplicated into a project.", type = "warning"); return() }
    # enforce access
    if (!can_access_project(ex$project_id)) { showNotification("Access denied to duplicate this expense.", type = "error"); return() }
    new_id <- uuid("exp")
    # duplicate breakdowns as well
    bks <- get_breakdowns(ex$id)
    bkd_list <- if (nrow(bks) > 0) lapply(seq_len(nrow(bks)), function(i) list(label = bks$label[i], amount = bks$amount[i])) else NULL
    ok <- create_expense(id = new_id, project_id = ex$project_id, description = paste0("(dup) ", ex$description), amount = ex$amount, category_main = ex$category_main, category_sub = ex$category_sub, date = as.character(Sys.Date()), breakdowns = bkd_list, created_by_role = rv$user_role %||% "Administrator")
    if (isTRUE(ok)) { reload_data(); showNotification("Expense duplicated", type = "message") } else { showNotification("Failed to duplicate expense", type = "error") }
  })
  
