  render_project_expense_datatable <- function(pid, expense_scope, selection = "single") {
    if (is.null(pid) || !nzchar(pid)) {
      return(DT::datatable(data.frame(Message = "Select a project to view its expenses"), options = list(dom = "t")))
    }
    if (!can_access_project(pid)) {
      return(DT::datatable(data.frame(Message = "Access denied for selected project"), options = list(dom = "t")))
    }
    ex <- expense_rows_for_scope(pid, expense_scope = expense_scope, include_trashed = FALSE)
    if (nrow(ex) == 0) {
      return(DT::datatable(
        data.frame(Message = paste0("No expenses found for ", expense_scope_view_label(expense_scope), ".")),
        options = list(dom = "t")
      ))
    }
    df <- ex %>%
      transmute(
        ID = id,
        Description = description,
        Amount = amount,
        Category = category_main,
        Subcategory = category_sub,
        Date = date,
        Receipt = ifelse(receipt_path == "", "", "Has Receipt")
      )
    DT::datatable(
      df,
      selection = selection,
      extensions = if (identical(selection, "single")) "Buttons" else NULL,
      options = if (identical(selection, "single")) {
        list(pageLength = 10, dom = "Bfrtip", buttons = c("copy", "csv", "excel"), scrollX = TRUE)
      } else {
        list(pageLength = 10, scrollX = TRUE)
      }
    )
  }

