  observeEvent(input$dt_expenses_rows_selected, {
    if (!require_authenticated()) return()
    if (identical(rv$user_role, "Administrator") && identical(expense_module_view_mode(), "compare")) return()
    sel <- input$dt_expenses_rows_selected; if (length(sel) != 1) return()
    pid <- input$exp_project_select
    if (is.null(pid) || !nzchar(pid)) return()
    if (!can_access_project(pid)) { showNotification("Access denied.", type = "error"); return() }
    destroy_expense_modal_observers()
    ex <- expense_rows_for_scope(pid, expense_scope = expense_module_single_scope(), include_trashed = FALSE)
    if (nrow(ex) == 0 || sel > nrow(ex)) return()
    row <- ex[sel, ]
    # Load breakdowns for edit
    rv$bk_edit_obs_created <- character()
    rv$pending_breakdowns_edit <- lapply(seq_len(nrow(get_breakdowns(row$id))), function(i) NULL) # initialize
    bkdf <- get_breakdowns(row$id)
    if (nrow(bkdf) > 0) rv$pending_breakdowns_edit <- lapply(seq_len(nrow(bkdf)), function(i) list(label = bkdf$label[i], amount = bkdf$amount[i]))
    showModal(modalDialog(
      title = paste0("Expense: ", row$description),
      textInput("edit_exp_desc", "Description", value = row$description),
      numericInput("edit_exp_amount", "Amount", value = as.numeric(row$amount), step = 0.01),
      selectInput("edit_exp_main", "Category (main)", choices = c(get_main_categories(), "Other"), selected = ifelse(nzchar(row$category_main), row$category_main, ifelse(nzchar(row$category), sub(" -.*$", "", row$category), ""))),
      uiOutput("edit_exp_sub_ui"),
      conditionalPanel("input.edit_exp_main == 'Other'", textInput("edit_exp_custom_main", "Custom main category")),
      actionButton("edit_manage_breakdown", "Manage Breakdown", icon = icon("th-list")),
      dateInput("edit_exp_date", "Date", value = ifelse(is.na(row$date) || row$date == "", Sys.Date(), as.Date(row$date))),
      if (nzchar(row$receipt_path) && file_exists(row$receipt_path)) tagList(tags$a(href = paste0("file://", row$receipt_path), target = "_blank", "Open Receipt"), br()) else tags$div("No receipt"),
      footer = tagList(modalButton("Cancel"), actionButton("confirm_update_expense", "Save"), actionButton("confirm_delete_expense", "Delete", class = "btn-danger")),
      size = "m"
    ))
    
    # render sub UI for edit modal
    output$edit_exp_sub_ui <- renderUI({
      main <- isolate(ifelse(nzchar(row$category_main), row$category_main, sub(" -.*$", "", row$category)))
      if (!is.null(input$edit_exp_main)) main <- input$edit_exp_main
      if (is.null(main) || main == "" || identical(main, "Other")) {
        tagList(
          selectInput("edit_exp_sub", "Subcategory", choices = c("(none)", "Other"), selected = ifelse(nzchar(row$category_sub), row$category_sub, "(none)")),
          conditionalPanel("input.edit_exp_sub == 'Other'", textInput("edit_exp_custom_sub", "Custom subcategory"))
        )
      } else {
        subs <- get_subcategories(main)
        choices <- unique(c("(none)", subs, "Other"))
        selected_sub <- if (!is.null(input$edit_exp_sub)) input$edit_exp_sub else if (nzchar(row$category_sub)) row$category_sub else if (length(subs)>0) subs[[1]] else "(none)"
        tagList(
          selectInput("edit_exp_sub", "Subcategory", choices = choices, selected = selected_sub),
          conditionalPanel("input.edit_exp_sub == 'Other'", textInput("edit_exp_custom_sub", "Custom subcategory"))
        )
      }
    })
    
    # Manage breakdowns in edit modal
    expense_modal_runtime$observers$edit_manage_breakdown <- observeEvent(input$edit_manage_breakdown, {
      # build modal similar to create but based on rv$pending_breakdowns_edit
      showModal(modalDialog(
        title = "Manage Breakdown (Edit Expense)",
        easyClose = TRUE,
        footer = tagList(modalButton("Close"), actionButton("save_breakdowns_edit", "Save breakdowns", class = "btn-primary")),
        tagList(
          textInput("bk_label_edit", "Category / Subcategory name", value = ""),
          numericInput("bk_amount_edit", "Amount", value = 0, min = 0, step = 0.01),
          actionButton("bk_add_row_edit", "Add row", icon = icon("plus")),
          br(), br(),
          uiOutput("bk_list_edit")
        )
      ))
    })
    
    output$bk_list_edit <- renderUI({
      rows <- rv$pending_breakdowns_edit %||% list()
      if (length(rows) == 0) return(tags$p("No breakdown items added yet."))
      items <- lapply(seq_along(rows), function(i) {
        r <- rows[[i]]
        fluidRow(column(8, tags$div(paste0(r$label, " - ", format_currency(r$amount)))), column(4, actionButton(paste0("bk_remove_edit_", i), "Remove", class = "btn-danger btn-sm")))
      })
      do.call(tagList, items)
    })
    expense_modal_runtime$observers$bk_add_row_edit <- observeEvent(input$bk_add_row_edit, {
      label <- as.character(input$bk_label_edit %||% "")
      amt <- as.numeric(input$bk_amount_edit %||% 0)
      if (!nzchar(label) || is.na(amt) || amt <= 0) {
        showNotification("Enter valid breakdown label and amount > 0", type = "error"); return()
      }
      rows <- rv$pending_breakdowns_edit %||% list()
      rows[[length(rows) + 1]] <- list(label = label, amount = amt)
      rv$pending_breakdowns_edit <- rows
      updateTextInput(session, "bk_label_edit", value = "")
      updateNumericInput(session, "bk_amount_edit", value = 0)
    })
    expense_modal_runtime$observers$bk_remove_registry <- observe({
      rows <- rv$pending_breakdowns_edit %||% list()
      obs_ids <- paste0("bk_remove_edit_", seq_along(rows))
      new_ids <- setdiff(obs_ids, rv$bk_edit_obs_created %||% character())
      if (length(new_ids) == 0) return()
      for (obs_id in new_ids) {
        local({
          my_id <- obs_id
          expense_modal_runtime$observers[[my_id]] <- observeEvent(input[[my_id]], {
            idx <- suppressWarnings(as.integer(sub("^bk_remove_edit_", "", my_id)))
            rows2 <- rv$pending_breakdowns_edit %||% list()
            if (!is.na(idx) && length(rows2) >= idx) rows2 <- rows2[-idx]
            rv$pending_breakdowns_edit <- rows2
          }, ignoreInit = TRUE)
        })
      }
      rv$bk_edit_obs_created <- unique(c(rv$bk_edit_obs_created %||% character(), new_ids))
    })
    expense_modal_runtime$observers$save_breakdowns_edit <- observeEvent(input$save_breakdowns_edit, {
      removeModal()
      showNotification("Breakdown entries saved to pending edits. They will be stored when you save the expense.", type = "message")
    })
    
    expense_modal_runtime$observers$confirm_update_expense <- observeEvent(input$confirm_update_expense, {
      # enforce access
      if (!isTRUE(expense_record_can_be_modified_by_viewer(row))) {
        showNotification("You are not allowed to edit this expense record.", type = "error")
        removeModal()
        return()
      }
      main_sel <- input$edit_exp_main
      if (identical(main_sel, "Other")) main_sel <- input$edit_exp_custom_main %||% ""
      sub_sel <- input$edit_exp_sub
      if (identical(sub_sel, "(none)")) sub_sel <- ""
      if (identical(sub_sel, "Other")) sub_sel <- input$edit_exp_custom_sub %||% ""
      ok <- update_expense(row$id, list(description = input$edit_exp_desc, amount = as.numeric(input$edit_exp_amount), category_main = main_sel, category_sub = sub_sel, date = as.character(input$edit_exp_date)), acting_role = rv$user_role %||% "Administrator")
      if (isTRUE(ok)) {
        # save pending breakdown edits
        bkd <- rv$pending_breakdowns_edit %||% list()
        create_breakdowns_for_expense(row$id, bkd)
        rv$pending_breakdowns_edit <- list()
        reload_data(); removeModal(); showNotification("Expense updated", type = "message")
      } else {
        showNotification("Failed to update expense", type = "error")
      }
    }, once = TRUE, ignoreInit = TRUE)
    
    expense_modal_runtime$observers$confirm_delete_expense <- observeEvent(input$confirm_delete_expense, {
      if (!isTRUE(expense_record_can_be_modified_by_viewer(row))) {
        showNotification("You are not allowed to delete this expense record.", type = "error")
        removeModal()
        return()
      }
      ok <- soft_delete_expense(row$id, acting_role = rv$user_role %||% "Administrator")
      if (isTRUE(ok)) { reload_data(); removeModal(); showNotification("Expense moved to Recycle Bin", type = "warning") } else { showNotification("Failed to delete expense", type = "error") }
    }, once = TRUE, ignoreInit = TRUE)
  })
  
