  report_project_name <- function(proj_id) {
    project_name <- "report"
    if (!is.null(rv$data) && nzchar(proj_id)) {
      project_row <- rv$data$projects %>% filter(id == proj_id) %>% slice_head(n = 1)
      if (nrow(project_row) == 1) project_name <- project_row$name[[1]]
    }
    project_name
  }
  report_date_params <- function() {
    use_filter <- isolate(input$report_use_date_filter %||% FALSE)
    start_d <- isolate(input$report_date_range[1])
    end_d <- isolate(input$report_date_range[2])
    list(
      start_date = if (isTRUE(use_filter) && !is.null(start_d)) start_d else NULL,
      end_date = if (isTRUE(use_filter) && !is.null(end_d)) end_d else NULL
    )
  }
  report_watermark_param <- function() {
    watermark_txt <- isolate(input$report_watermark_text %||% "")
    apply_watermark <- isolate(input$report_watermark %||% FALSE)
    if (isTRUE(apply_watermark) && nzchar(watermark_txt)) watermark_txt else NULL
  }
  copy_generated_report <- function(source, target) {
    tryCatch({
      copy_file_checked(source, target, overwrite = TRUE)
      TRUE
    }, error = function(e) {
      append_app_runtime_log(
        "ERROR",
        paste0("Failed to prepare generated report download: ", e$message),
        detail = list(source = as.character(source %||% ""), target = as.character(target %||% ""))
      )
      FALSE
    })
  }

  output$download_excel_report <- downloadHandler(
    filename = function() {
      proj_id <- isolate(input$report_project %||% "")
      project_name <- report_project_name(proj_id)
      paste0("budget_report_", sanitize_filename(project_name), "_", format(Sys.time(), "%Y%m%d_%H%M%S"), ".xlsx")
    },
    content = function(file) {
      proj_id <- isolate(input$report_project %||% "")
      if (!nzchar(proj_id)) {
        stop("No project selected")
      }
      if (!can_access_project(proj_id)) {
        stop("Access denied for selected project")
      }

      date_params <- report_date_params()
      expense_scope <- isolate(input$report_expense_scope %||% if (identical(rv$user_role, "Administrator")) "administrator" else "scientist")
      report_path <- tryCatch({
        write_excel_report(
          project_id = proj_id,
          watermark = report_watermark_param(),
          start_date = date_params$start_date,
          end_date = date_params$end_date,
          password = isolate(input$report_excel_password %||% settings_cache()[["excel_password"]] %||% ""),
          output_dir = get_export_folder(),
          request_tag = paste(session$token, "xlsx", sep = "_"),
          expense_scope = expense_scope
        )
      }, error = function(e) {
        message("Error generating Excel report: ", e$message)
        NULL
      })

      if (is.null(report_path) || !file.exists(report_path)) {
        stop("Failed to generate Excel report")
      }

      if (!copy_generated_report(report_path, file)) {
        stop("Failed to prepare file for download")
      }
    }
  )

  output$download_pdf_report <- downloadHandler(
    filename = function() {
      proj_id <- isolate(input$report_project %||% "")
      project_name <- report_project_name(proj_id)
      paste0("budget_report_", sanitize_filename(project_name), "_", format(Sys.time(), "%Y%m%d_%H%M%S"), ".pdf")
    },
    content = function(file) {
      proj_id <- isolate(input$report_project %||% "")
      if (!nzchar(proj_id)) {
        stop("No project selected")
      }
      if (!can_access_project(proj_id)) {
        stop("Access denied for selected project")
      }

      date_params <- report_date_params()
      expense_scope <- isolate(input$report_expense_scope %||% if (identical(rv$user_role, "Administrator")) "administrator" else "scientist")
      report_path <- tryCatch({
        write_html_pdf_report(
          project_id = proj_id,
          pdf = TRUE,
          watermark = report_watermark_param(),
          start_date = date_params$start_date,
          end_date = date_params$end_date,
          output_dir = get_export_folder(),
          work_dir = session_work_dir,
          request_tag = paste(session$token, "pdf", sep = "_"),
          expense_scope = expense_scope
        )
      }, error = function(e) {
        message("Error generating PDF report: ", e$message)
        NULL
      })

      if (is.null(report_path) || !file.exists(report_path)) {
        stop("Failed to generate PDF report")
      }

      if (!copy_generated_report(report_path, file)) {
        stop("Failed to prepare file for download")
      }
    }
  )

