  file_manager_result_error <- function(ok, default = "The requested File Manager action failed.") {
    msg <- trimws(as.character(attr(ok, "error") %||% ""))
    if (nzchar(msg)) msg else default
  }

  file_manager_date_mask <- function(values, range_values, enabled = FALSE) {
    values <- as.character(values %||% "")
    keep <- rep(TRUE, length(values))
    if (!isTRUE(enabled) || length(range_values) != 2) return(keep)
    start_date <- suppressWarnings(as.Date(range_values[[1]]))
    end_date <- suppressWarnings(as.Date(range_values[[2]]))
    parsed <- suppressWarnings(as.Date(substr(values, 1, 10)))
    keep <- !is.na(parsed)
    if (!is.na(start_date)) keep <- keep & parsed >= start_date
    if (!is.na(end_date)) keep <- keep & parsed <= end_date
    keep
  }

