  file_manager_registry <- reactive({
    req(rv$data)
    rv$file_manager_refresh_token
    rv$submission_supporting_refresh_token
    if (!isTRUE(file_manager_is_admin())) return(data.frame())
    items <- load_file_manager_registry(include_trashed = TRUE, include_archived = TRUE)
    if (!is.data.frame(items) || nrow(items) == 0) return(data.frame())
    items$is_trashed <- suppressWarnings(as.integer(items$is_trashed %||% 0L))
    items$is_trashed[is.na(items$is_trashed)] <- 0L
    items$file_location <- vapply(items$file_location %||% "active", normalize_file_location, character(1))
    items$project_code <- as.character(items$project_code %||% "")
    items$project_title <- as.character(items$project_title %||% "")
    items$display_name <- as.character(items$display_name %||% "")
    items$archive_group_id <- as.character(items$archive_group_id %||% "")
    items$archive_group_name <- as.character(items$archive_group_name %||% "")
    items$uploaded_by <- as.character(items$uploaded_by %||% "")
    items
  })

  file_manager_active_registry <- reactive({
    items <- file_manager_registry()
    if (!is.data.frame(items) || nrow(items) == 0) return(data.frame())
    items <- items[items$is_trashed == 0L & items$file_location == "active", , drop = FALSE]
    if (nrow(items) == 0) return(data.frame())
    items %>% arrange(desc(last_modified), project_title, display_name)
  })

  file_manager_archived_registry_raw <- reactive({
    items <- file_manager_registry()
    if (!is.data.frame(items) || nrow(items) == 0) return(data.frame())
    items <- items[items$is_trashed == 0L & items$file_location == "archive", , drop = FALSE]
    if (nrow(items) == 0) return(data.frame())
    items %>% arrange(archive_group_name, desc(archived_at), project_title, display_name)
  })

  file_manager_archived_registry <- reactive({
    items <- file_manager_archived_registry_raw()
    if (!is.data.frame(items) || nrow(items) == 0) return(data.frame())
    selected_project <- as.character(input$archive_filter_project %||% "")
    if (nzchar(selected_project)) {
      items <- items[as.character(items$project_id %||% "") == selected_project, , drop = FALSE]
    }
    selected_group <- as.character(input$archive_filter_group %||% "")
    if (nzchar(selected_group)) {
      items <- items[as.character(items$archive_group_id %||% "") == selected_group, , drop = FALSE]
    }
    selected_type <- tolower(as.character(input$archive_filter_type %||% ""))
    if (nzchar(selected_type)) {
      items <- items[tolower(as.character(items$file_ext %||% "")) == selected_type, , drop = FALSE]
    }
    selected_uploaded_by <- as.character(input$archive_filter_uploaded_by %||% "")
    if (nzchar(selected_uploaded_by)) {
      items <- items[as.character(items$uploaded_by %||% "") == selected_uploaded_by, , drop = FALSE]
    }
    upload_mask <- file_manager_date_mask(items$upload_date, input$archive_filter_upload_date, enabled = isTRUE(input$archive_use_upload_date_filter %||% FALSE))
    items <- items[upload_mask, , drop = FALSE]
    archive_mask <- file_manager_date_mask(items$archived_at, input$archive_filter_archive_date, enabled = isTRUE(input$archive_use_archive_date_filter %||% FALSE))
    items <- items[archive_mask, , drop = FALSE]
    search_text <- trimws(tolower(as.character(input$archive_file_search %||% "")))
    if (nzchar(search_text) && nrow(items) > 0) {
      haystack <- paste(
        tolower(as.character(items$project_code %||% "")),
        tolower(as.character(items$project_title %||% "")),
        tolower(as.character(items$display_name %||% "")),
        tolower(as.character(items$archive_group_name %||% "")),
        tolower(as.character(items$uploaded_by %||% "")),
        tolower(as.character(items$source_label %||% "")),
        sep = " | "
      )
      items <- items[grepl(search_text, haystack, fixed = TRUE), , drop = FALSE]
    }
    items
  })

  file_manager_recycle_registry <- reactive({
    items <- file_manager_registry()
    if (!is.data.frame(items) || nrow(items) == 0) return(data.frame())
    items <- items[items$is_trashed == 1L, , drop = FALSE]
