  observe({
    if (!isTRUE(file_manager_is_admin())) return()
    groups <- archive_group_rows()
    archived_items <- file_manager_archived_registry_raw()
    project_choices <- c("All Projects" = "")
    if (is.data.frame(archived_items) && nrow(archived_items) > 0) {
      project_df <- archived_items %>%
        distinct(project_id, project_code, project_title) %>%
        arrange(project_title, project_code)
      project_labels <- ifelse(
        nzchar(as.character(project_df$project_title %||% "")),
        paste0(project_df$project_code, " - ", project_df$project_title),
        as.character(project_df$project_code %||% "")
      )
      project_choices <- c(project_choices, stats::setNames(as.character(project_df$project_id), project_labels))
    }
    updateSelectInput(session, "archive_filter_project", choices = project_choices, selected = if (isolate(input$archive_filter_project %||% "") %in% unname(project_choices)) isolate(input$archive_filter_project %||% "") else "")

    group_choices <- c("All Groups" = "")
    if (is.data.frame(groups) && nrow(groups) > 0) {
      group_choices <- c(group_choices, stats::setNames(as.character(groups$id), as.character(groups$name)))
    }
    updateSelectInput(session, "archive_filter_group", choices = group_choices, selected = if (isolate(input$archive_filter_group %||% "") %in% unname(group_choices)) isolate(input$archive_filter_group %||% "") else "")

    type_choices <- c("All Types" = "")
    if (is.data.frame(archived_items) && nrow(archived_items) > 0) {
      types <- sort(unique(tolower(as.character(archived_items$file_ext %||% ""))))
      types <- types[nzchar(types)]
      if (length(types) > 0) type_choices <- c(type_choices, stats::setNames(types, toupper(types)))
    }
    updateSelectInput(session, "archive_filter_type", choices = type_choices, selected = if (isolate(input$archive_filter_type %||% "") %in% unname(type_choices)) isolate(input$archive_filter_type %||% "") else "")

    uploaded_by_choices <- c("All Uploaders" = "")
    if (is.data.frame(archived_items) && nrow(archived_items) > 0) {
      uploaders <- sort(unique(as.character(archived_items$uploaded_by %||% "")))
      uploaders <- uploaders[nzchar(uploaders)]
      if (length(uploaders) > 0) uploaded_by_choices <- c(uploaded_by_choices, stats::setNames(uploaders, uploaders))
    }
    updateSelectInput(session, "archive_filter_uploaded_by", choices = uploaded_by_choices, selected = if (isolate(input$archive_filter_uploaded_by %||% "") %in% unname(uploaded_by_choices)) isolate(input$archive_filter_uploaded_by %||% "") else "")
  })

