  file_manager_reports <- reactive({
    req(rv$data)
    rv$file_manager_refresh_token
    if (!isTRUE(file_manager_is_admin())) return(data.frame())
    deleted_only <- isTRUE(input$show_deleted_project_reports %||% FALSE)
    reports <- load_project_reports_for_file_manager(project_id = "", include_trashed = TRUE)
    if (is.null(reports) || nrow(reports) == 0) return(data.frame())
    trashed <- suppressWarnings(as.integer(reports$is_trashed %||% 0))
    trashed[is.na(trashed)] <- 0L
    locations <- vapply(reports$file_location %||% "active", normalize_file_location, character(1))
    deleted_from <- as.character(reports$deleted_from_location %||% "")
    keep <- if (isTRUE(deleted_only)) {
      trashed == 1L & deleted_from != "archive"
    } else {
      trashed == 0L & locations == "active"
    }
    reports <- reports[keep, , drop = FALSE]
    if (nrow(reports) == 0) return(data.frame())
    reports$expected_docx <- vapply(seq_len(nrow(reports)), function(i) project_report_docx_filename(reports[i, , drop = FALSE]), character(1))
    reports$report_identifier <- vapply(seq_len(nrow(reports)), function(i) project_report_display_name(reports[i, , drop = FALSE]), character(1))
    reports %>% arrange(desc(updated_at), project_title, project_code)
  })

