      Status = ifelse(suppressWarnings(as.integer(is_trashed)) == 1, "DELETED", toupper(status)),
      `DOCX File` = expected_docx,
      `Updated At` = updated_at
    )
    DT::datatable(df, selection = "single", options = list(pageLength = 10, autoWidth = TRUE, scrollX = TRUE))
  }, server = TRUE)

  output$dt_project_report_supporting_docs <- renderDT({
    if (!isTRUE(file_manager_is_admin())) {
      return(DT::datatable(data.frame(Message = "Administrator access is required for Uploaded Project Files."), options = list(dom = "t")))
    }
    docs <- file_manager_supporting_docs()
    if (nrow(docs) == 0) {
      return(DT::datatable(data.frame(Message = "No uploaded project files are available in the active File Manager view."), options = list(dom = "t")))
    }
    df <- docs %>% transmute(
      `Project Code` = project_code,
      `File Name` = display_name,
      Type = toupper(ifelse(nzchar(file_ext), file_ext, fs::path_ext(original_filename))),
      `Submission Workflow` = ifelse(as.character(submission_type %||% "") == "upload_only", "Upload Files Only", "Structured Report"),
      `Report Link` = ifelse(nzchar(as.character(report_id %||% "")), as.character(report_id), "-"),
      Size = size_label,
      `Uploaded By` = ifelse(nzchar(as.character(uploaded_by_name %||% "")), paste0(as.character(uploaded_by_role %||% ""), " | ", as.character(uploaded_by_name %||% "")), as.character(uploaded_by_role %||% "")),
      Status = ifelse(suppressWarnings(as.integer(is_trashed)) == 1, "DELETED", "ACTIVE"),
      `Updated At` = updated_at
    )
    DT::datatable(df, selection = "single", options = list(pageLength = 10, autoWidth = TRUE, scrollX = TRUE))
  }, server = TRUE)

