  output$download_file_manager_item <- downloadHandler(
    filename = function() {
      item <- get_file_manager_item_by_key(rv$file_manager_item_key %||% "", include_trashed = TRUE)
      if (nrow(item) == 1) file_manager_item_download_name(item) else "project_file"
    },
    content = function(file) {
      if (!isTRUE(file_manager_is_admin())) stop("Administrator access is required.")
      item <- get_file_manager_item_by_key(rv$file_manager_item_key %||% "", include_trashed = TRUE)
      if (nrow(item) != 1) stop("Select a file first.")
      src <- as.character(item$file_path[[1]] %||% "")
      if (!nzchar(src) || !file_exists(src)) stop("The selected file was not found.")
      copy_file_checked(src, file, overwrite = TRUE)
      log_file_manager_download_action(
        item,
        action = "download_file",
        acting_user = file_manager_actor(),
        acting_role = rv$user_role %||% "Administrator",
        bundle_name = basename(file)
      )
    }
  )

