  output$download_archive_group_bundle <- downloadHandler(
    filename = function() {
      group_id <- as.character(input$archive_filter_group %||% "")
      if (!nzchar(group_id)) {
        group_row <- selected_archive_group_row()
        group_id <- as.character(group_row$id[[1]] %||% "")
      }
      group_row <- get_archive_group_by_id(group_id)
      group_name <- if (nrow(group_row) == 1) sanitize_filename(as.character(group_row$name[[1]] %||% "archive_group")) else "archive_group"
      paste0(group_name, "_", format(Sys.time(), "%Y%m%d_%H%M%S"), ".zip")
    },
    content = function(file) {
      if (!isTRUE(file_manager_is_admin())) stop("Administrator access is required.")
      group_id <- as.character(input$archive_filter_group %||% "")
      if (!nzchar(group_id)) {
        group_row <- selected_archive_group_row()
        group_id <- as.character(group_row$id[[1]] %||% "")
      }
      if (!nzchar(group_id)) stop("Select an Archive Group first.")
      group_row <- get_archive_group_by_id(group_id)
      group_name <- if (nrow(group_row) == 1) as.character(group_row$name[[1]] %||% "Archive Group") else "Archive Group"
      items <- file_manager_archived_registry_raw()
      items <- items[as.character(items$archive_group_id %||% "") == group_id, , drop = FALSE]
      if (nrow(items) == 0) stop("No files were found in the selected Archive Group.")
      zip_path <- build_file_manager_zip(items, zip_prefix = paste0("archive_group_", group_id), top_folder = group_name)
      copy_file_checked(zip_path, file, overwrite = TRUE)
      log_file_manager_download_action(
        items,
        action = "download_archive_group_bundle",
        acting_user = file_manager_actor(),
        acting_role = rv$user_role %||% "Administrator",
        bundle_name = basename(file),
        archive_group = group_name
      )
    }
  )

