    items <- selected_recycle_file_manager_items()
    if (nrow(items) == 0) {
      showNotification("Select one or more deleted files to permanently remove.", type = "warning")
      return()
    }
    rv$file_manager_pending_keys <- as.character(items$file_key %||% character())
    showModal(modalDialog(
      title = "Permanently Delete Files",
      tags$p("This action cannot be undone."),
      tags$p("The selected records, file references, and physical files will be removed permanently."),
      footer = tagList(modalButton("Cancel"), actionButton("confirm_permanently_delete_file", "Permanently Delete", class = "btn-danger"))
    ))
  }, ignoreInit = TRUE)

  observeEvent(input$confirm_permanently_delete_file, {
    if (!require_file_manager_admin()) return()
    ok <- permanently_delete_file_manager_items(
      rv$file_manager_pending_keys %||% character(),
      acting_user = file_manager_actor(),
      acting_role = rv$user_role %||% "Administrator"
    )
    if (isTRUE(ok)) {
      rv$file_manager_pending_keys <- character()
      removeModal()
      refresh_file_manager_state()
      showNotification("Selected files were permanently deleted.", type = "message")
    } else {
      showNotification(file_manager_result_error(ok, "Failed to permanently delete the selected files."), type = "error")
    }
  }, ignoreInit = TRUE)

  observeEvent(input$dt_project_reports_rows_selected, {
    if (!require_file_manager_admin()) return()
    row <- selected_file_manager_report()
    if (nrow(row) != 1) return()
    rv$file_manager_report_id <- as.character(row$id[[1]])
    is_deleted <- suppressWarnings(as.integer(row$is_trashed[[1]] %||% 0)) == 1
    showModal(modalDialog(
      title = paste0("DOCX Report: ", as.character(row$report_identifier[[1]] %||% project_report_display_name(row))),
      size = "l",
      easyClose = TRUE,
      project_report_view_ui(row),
      footer = tagList(
        if (!is_deleted) downloadButton("download_project_report_docx", "Download DOCX"),
        if (!is_deleted) actionButton("btn_delete_project_report_modal", "Delete Report", icon = icon("trash"), class = "btn-danger"),
        if (is_deleted) actionButton("btn_restore_project_report_modal", "Restore Report", icon = icon("undo"), class = "btn-success"),
        modalButton("Close")
      )
    ))
  }, ignoreInit = TRUE)

  observeEvent(input$btn_delete_project_report, {
    if (!require_file_manager_admin()) return()
