    if (nrow(row) != 1) { showNotification("Select a report to delete.", type = "error"); return() }
    if (suppressWarnings(as.integer(row$is_trashed[[1]] %||% 0)) == 1) { showNotification("Selected report is already deleted.", type = "warning"); return() }
    show_project_report_delete_confirm(row)
  }, ignoreInit = TRUE)

  observeEvent(input$btn_delete_project_report_modal, {
    if (!require_file_manager_admin()) return()
    report <- get_project_report_by_id(rv$file_manager_report_id %||% "", include_trashed = TRUE)
    if (nrow(report) != 1) { showNotification("Select a report to delete.", type = "error"); return() }
    show_project_report_delete_confirm(report)
  }, ignoreInit = TRUE)

  observeEvent(input$confirm_delete_project_report, {
    if (!require_file_manager_admin()) return()
    report <- get_project_report_by_id(rv$file_manager_report_id %||% "", include_trashed = TRUE)
    if (nrow(report) != 1) { showNotification("Report not found.", type = "error"); return() }
    ok <- soft_delete_project_report(as.character(report$id[[1]]))
    removeModal()
    if (isTRUE(ok)) {
      refresh_file_manager_state()
      rv$file_manager_report_id <- NULL
      showNotification("Report deleted successfully and moved to the Recycle Bin.", type = "message")
    } else {
      showNotification("Failed to delete report.", type = "error")
    }
  }, ignoreInit = TRUE)

  observeEvent(input$btn_restore_project_report, {
    if (!require_file_manager_admin()) return()
    row <- selected_file_manager_report()
    if (nrow(row) != 1) { showNotification("Select a deleted report to restore.", type = "error"); return() }
    if (suppressWarnings(as.integer(row$is_trashed[[1]] %||% 0)) != 1) { showNotification("Selected report is not deleted.", type = "warning"); return() }
    show_project_report_restore_confirm(row)
  }, ignoreInit = TRUE)

  observeEvent(input$btn_restore_project_report_modal, {
    if (!require_file_manager_admin()) return()
