    if (nrow(report) != 1) { showNotification("Select a deleted report to restore.", type = "error"); return() }
    show_project_report_restore_confirm(report)
  }, ignoreInit = TRUE)

  observeEvent(input$confirm_restore_project_report, {
    if (!require_file_manager_admin()) return()
    report <- get_project_report_by_id(rv$file_manager_report_id %||% "", include_trashed = TRUE)
    if (nrow(report) != 1) { showNotification("Report not found.", type = "error"); return() }
    ok <- restore_project_report(as.character(report$id[[1]]))
    removeModal()
    if (isTRUE(ok)) {
      refresh_file_manager_state()
      showNotification("Report restored.", type = "message")
    } else {
      showNotification("Failed to restore report.", type = "error")
    }
  }, ignoreInit = TRUE)

