    removeModal()
    if (isTRUE(ok)) {
      rv$submission_supporting_refresh_token <- isolate(rv$submission_supporting_refresh_token %||% 0L) + 1L
      refresh_file_manager_state()
      showNotification("File restored.", type = "message")
    } else {
      showNotification("Failed to restore file.", type = "error")
    }
  }, ignoreInit = TRUE)

  render_backups_table <- function() {
    bk <- backups_rows()
    if (nrow(bk) == 0) return(DT::datatable(data.frame(Message = "No backups"), options = list(dom = 't')))
    df <- bk %>% transmute(`Project ID` = workspace_id, ID = id, Name = filename, Path = filepath, Created = created_at, Size = size)
    DT::datatable(df, selection = "single", options = list(pageLength = 10))
  }
  output$dt_backups <- renderDT({ render_backups_table() })
    # Backups & integrity
  observeEvent(input$btn_create_backup, {
    if (!require_authenticated()) return()
    if (identical(rv$user_role, "Scientist")) { showNotification("Scientist cannot create system backups.", type = "error"); return() }
    project_id <- isolate(selected_project_context())
    if (!nzchar(project_id)) { showNotification("Select a project first.", type = "warning"); return() }
    res <- create_backup_archive(project_id)
    reload_data()
    if (!is.null(res)) showNotification("Backup created", type = "message") else showNotification("Backup failed", type = "error")
  })
  
  observeEvent(input$btn_restore_selected_backup, {
    if (!require_authenticated()) return()
    if (identical(rv$user_role, "Scientist")) { showNotification("Scientist cannot restore backups.", type = "error"); return() }
    sel <- input$dt_backups_rows_selected
    if (length(sel) != 1) { showNotification("Select a backup to restore", type = "warning"); return() }
    bk <- backups_rows()
    row <- bk[sel, ]
    showModal(modalDialog(title = "Restore Backup", paste0("This will restore backup: ", row$filename, ". Proceed?"), footer = tagList(modalButton("Cancel"), actionButton("confirm_restore_backup", "Restore", class = "btn-warning"))))
    observeEvent(input$confirm_restore_backup, {
      tryCatch({
        project_id <- as.character(row$workspace_id %||% "")
        if (!nzchar(project_id)) stop("Select a project first.")
        ok <- restore_backup_archive(row$filepath, project_id)
        if (!isTRUE(ok)) stop("Restore archive failed.")
        reload_data()
        removeModal()
        showNotification("Backup restored.", type = "message")
      }, error = function(e) { showNotification(paste0("Restore failed: ", e$message), type = "error") })
    }, once = TRUE, ignoreInit = TRUE)
  })
  
  observeEvent(input$btn_run_integrity, {
    if (!require_authenticated()) return()
    project_id <- isolate(selected_project_context())
    if (!nzchar(project_id)) {
      set_integrity_report_text("Select a project first.")
      return()
    }
    tryCatch({
      msgs <- run_integrity_check(project_id)
      if (length(msgs) == 0) msgs <- "No integrity issues detected."
      set_integrity_report_text(paste(msgs, collapse = "\n"))
    }, error = function(e) {
      set_integrity_report_text(paste0("Integrity check failed: ", e$message))
      showNotification(paste0("Integrity check failed: ", e$message), type = "error")
    })
  })
  
  # Exit app
  observeEvent(input$btn_exit_app, {
    if (!require_authenticated()) return()
    showModal(modalDialog(title = "Exit Application", "Save state and close application?", footer = tagList(modalButton("Cancel"), actionButton("confirm_exit", "Exit", class = "btn-danger"))))
    observeEvent(input$confirm_exit, {
      # perform a final reload to persist state
      try({ reload_data() }, silent = TRUE)
      stopApp()
    }, once = TRUE, ignoreInit = TRUE)
  })
  
} # end server

if (identical(app_mode, "app")) {
  helper_ready <- FALSE
  if (can_launch_background_scheduler()) {
    helper_ready <- isTRUE(ensure_background_scheduler_service("startup"))
    initialize_background_scheduler_watchdog()
  }
  if (!can_launch_background_scheduler() && !isTRUE(helper_ready)) {
    initialize_drive_sync_scheduler()
    initialize_scheduled_email_scheduler()
  }
  shinyApp(ui = ui, server = server)
} else if (identical(app_mode, "scheduler")) {
  run_background_scheduler_loop()
}
